setCloudWalletBridge({
  async signMessage(message, summary) {
    const result = await signWalletProofMessageWithToast(message, summary, state.cluster, {
      message: `${summary}: approve this wallet proof. No transaction will be submitted.`,
    });
    return {
      signature: result.signature,
      encoding: 'base58',
      proofEncoding: result.proofEncoding,
      proofTxBase64: result.proofTxBase64,
      proofMemoText: result.proofMemoText,
    };
  },
  cloudRequest(path, init) {
    return cloudRequest(path, init);
  },
});

const LEDGER_DEVICE_APPROVAL_TOAST_KEY = 'ledger-device-approval';
// Shared key so the cloud sign-in proof toast ("Waiting for signature" → "Signature approved /
// Verifying…") and the terminal "Cloud workspace signed in" toast collapse into ONE toast:
// pushToast drops any existing same-key toast, so the final push replaces the intermediate.
const CLOUD_SIGN_IN_TOAST_KEY = 'cloud-sign-in';
let proofSigningToastDepth = 0;

function isLedgerWalletSelected(): boolean {
  return state.selectedWalletName === LEDGER_WALLET_NAME;
}

function ledgerApprovalMessage(): string {
  return 'Review and approve this request on your Ledger device.';
}

function beginLedgerDeviceApprovalToast(
  message = ledgerApprovalMessage(),
  options: { force?: boolean } = {},
): number | undefined {
  if (!options.force && !isLedgerWalletSelected()) return undefined;
  dismissToastByKey(LEDGER_DEVICE_APPROVAL_TOAST_KEY);
  const toastId = pushToast('pending', t('Approve on Ledger'), message, {
    key: LEDGER_DEVICE_APPROVAL_TOAST_KEY,
  });
  render();
  return toastId;
}

function normalizeLedgerSigningError(err: unknown, options: { force?: boolean } = {}): unknown {
  if (!options.force && !isLedgerWalletSelected()) return err;
  const message = err instanceof Error ? err.message : String(err);
  if (/user rejected|rejected on device|wallet rejected/i.test(message)) {
    return new Error('Ledger rejected the request.');
  }
  return err;
}

async function waitForLedgerPromptPaint(): Promise<void> {
  await new Promise<void>((resolve) => {
    if (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function') {
      window.requestAnimationFrame(() => resolve());
      return;
    }
    globalThis.setTimeout(resolve, 0);
  });
}

function completeLedgerDeviceApprovalToast(
  toastId: number | undefined,
  kind: ToastKind,
  title: string,
  message: string,
): void {
  if (toastId === undefined) return;
  replaceToast(toastId, kind, title, message, {
    key: LEDGER_DEVICE_APPROVAL_TOAST_KEY,
  });
}

function dismissLedgerDeviceApprovalToast(toastId: number | undefined): void {
  if (toastId !== undefined) {
    dismissToast(toastId);
  }
}

function beginProofSigningToast(options: { title?: string; message?: string; key?: string } = {}): number {
  const title = options.title ?? (isLedgerWalletSelected() ? t('Approve on Ledger') : t('Waiting for signature'));
  const message = options.message ?? (isLedgerWalletSelected()
    ? t('Review and approve this proof request on your Ledger device.')
    : t('Approve the proof in your wallet. No transaction will be submitted.'));
  const toastOptions = options.key ? { key: options.key } : {};
  const toastId = pushToast(
    'pending',
    title,
    jupiterIosManualToastMessage(message),
    withJupiterIosManualApprovalToast(toastOptions),
  );
  proofSigningToastDepth += 1;
  render();
  return toastId;
}

interface ProofSigningToastOptions {
  title?: string;
  message?: string;
  key?: string;
  successTitle?: string;
  successMessage?: string;
  errorTitle?: string;
  showLedgerDeviceToast?: boolean;
}

function completeProofSigningToast(
  toastId: number | undefined,
  kind: ToastKind,
  title: string,
  message: string,
  options: ToastOptions = {},
): void {
  if (toastId === undefined) {
    pushToast(kind, title, message, options);
    render();
    return;
  }
  proofSigningToastDepth = Math.max(0, proofSigningToastDepth - 1);
  replaceToast(toastId, kind, title, message, options);
}

function markToastShown(err: unknown): unknown {
  if (err && typeof err === 'object') {
    (err as { toastShown?: boolean }).toastShown = true;
    return err;
  }
  const wrapped = new Error(String(err));
  (wrapped as Error & { toastShown?: boolean }).toastShown = true;
  return wrapped;
}

async function signWalletProofMessageWithToast(
  message: string,
  summary: string,
  cluster: Cluster,
  options: ProofSigningToastOptions = {},
) {
  const toastId = beginProofSigningToast({
    title: options.title,
    message: options.message,
    key: options.key,
  });
  try {
    const result = await signWalletProofMessage(message, summary, cluster, {
      showLedgerDeviceToast: options.showLedgerDeviceToast,
    });
    completeProofSigningToast(
      toastId,
      'success',
      options.successTitle ?? t('Signature approved'),
      options.successMessage ?? t('Wallet signature received.'),
      options.key ? { key: options.key } : {},
    );
    return result;
  } catch (err) {
    completeProofSigningToast(
      toastId,
      'error',
      options.errorTitle ?? t('Sign proof failed'),
      redactSecrets(err instanceof Error ? err.message : String(err)),
      options.key ? { key: options.key } : {},
    );
    throw markToastShown(err);
  }
}

function ledgerConnectApprovalMessage(): string {
  return 'Confirm the address on your Ledger device.';
}

function ledgerErrorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

async function withLedgerDeviceApproval<T>(
  message: string,
  task: () => Promise<T>,
  options: { force?: boolean } = {},
): Promise<T> {
  const toastId = beginLedgerDeviceApprovalToast(message, options);
  try {
    if (toastId !== undefined) {
      await waitForLedgerPromptPaint();
    }
    return await task();
  } catch (err) {
    throw normalizeLedgerSigningError(err, options);
  } finally {
    dismissLedgerDeviceApprovalToast(toastId);
  }
}

async function signWalletProofMessage(
  message: string,
  summary: string,
  cluster: Cluster,
  options: { showLedgerDeviceToast?: boolean } = {},
) {
  const toastId = options.showLedgerDeviceToast === false || proofSigningToastDepth > 0
    ? undefined
    : beginLedgerDeviceApprovalToast('Review and approve this proof request on your Ledger device.');
  try {
    if (toastId !== undefined) {
      await waitForLedgerPromptPaint();
    }
    assertConnectedWalletMatchesSavedPath(cluster);
    return await signWalletProofMessageRaw(message, summary, cluster);
  } catch (err) {
    throw normalizeLedgerSigningError(err);
  } finally {
    dismissLedgerDeviceApprovalToast(toastId);
  }
}

