interface ChatMessage {
  id: string;
  role: ChatMessageRole;
  content: string;
  createdAt: string;
  status?: 'streaming' | 'done' | 'error';
  proposal?: ChatActionProposal;     // pending proposal, not yet promoted
  preparedActionId?: string;         // set once promoted; SAME id as state.preparedActions[]
  toolEvidence?: ChatToolEvidence[];
  error?: string;
  txReceipt?: { txid: string; cluster: Cluster }; // inline Solscan receipt after a chat-signed action
  // Client-only "Receive" accessory card: the connected address shown as a QR + copyable
  // pill. Only the address is persisted; the QR data URL is regenerated on render
  // (chatReceiveQrFor) so the large base64 PNG never bloats localStorage / the cloud blob.
  receiveCard?: { address: string };
  // Client-only "Recurring/DCA" card: id of the created RecurringPayment in
  // state.recurringPayments. The compact card is rendered live by id (regenerated on render),
  // so nothing heavy is persisted on the message — just the id.
  recurringCardId?: string;
  // Live Active-Positions card: renders the current positions of one category (limit/dca/lend/…) from
  // state.positionsLive, so the cards stay monitored and their manage actions run inline in chat.
  positionsCard?: { category: ActionCategory };
  // Client-only deterministic Research card: compact read-only facts generated from
  // existing chat read tools. Never creates a PreparedAction or approval receipt.
  researchCard?: ChatResearchCard;
  // One-shot decision planner card from Chat. It runs the same review engine as
  // New Request/Repeat, but never creates a durable request or wallet action.
  decisionCheckCard?: ChatDecisionCheckCard;
  // Token usage for this answer (summed across the loop's turns) + web sources the
  // model cited (Anthropic native web_search). Rendered as a subtle footer.
  usage?: ChatUsage;
  citations?: ChatCitation[];
  // UI-only synthetic marker (e.g. the "earlier messages were trimmed" notice). Not
  // persisted, not synced to cloud, not counted toward the per-session message cap.
  ephemeral?: boolean;
}

interface ChatSession {
  id: string;
  title: string;
  createdAt: string;
  updatedAt: string;
  walletAddress: string;
  cluster: Cluster;
  messages: ChatMessage[];
  // Cloud-sync bookkeeping (signed-in only). `cloudMessageCount` is set on a
  // metadata-only stub whose messages haven't been lazily loaded yet, so the
  // history list can show it before its compressed blob is fetched. `cloudVersion`
  // is the last server version this client observed (informational).
  cloudMessageCount?: number;
  cloudVersion?: number;
  // Transient (not persisted): the last lazy stub fetch failed (decompress failure,
  // 5xx, or offline). Drives the in-transcript error/retry state instead of an
  // endless "Loading conversation…" spinner. Cleared on a successful load or retry.
  cloudLoadError?: 'failed' | 'offline';
}

