type DebugLogSource = 'rpc' | 'ai' | 'wallet' | 'ledger' | 'ui' | 'health' | 'preflight' | 'device-agent';

interface DebugLogEvent {
  ts: string;
  level: DebugLogLevel;
  source: DebugLogSource;
  message: string;
  code?: string;
  actionId?: string;
  txid?: string;
  requestId?: string;
}

interface NotificationSettingsState {
  permission: NotificationPermission | 'unsupported';
  browser: boolean;
  due: boolean;
  pending: boolean;
  confirmed: boolean;
  failed: boolean;
  // New push-capable categories (server-sourced; reach a closed app). Absent on old persisted state.
  limitFilled: boolean;
  dcaFilled: boolean;
  borrowAtRisk: boolean;
}

type SafetyRailsMode = 'warn' | 'block';

interface ProgramRulesState {
  enabled: boolean;
  mode: SafetyRailsMode;
  allowlist: string[];
  blocklist: string[];
}

interface TokenRulesState {
  enabled: boolean;
  mode: SafetyRailsMode;
  allowlist: string[];
  blocklist: string[];
}

interface SpendCapEntry {
  token: string;
  maxPerDay?: number;
  maxPerWeek?: number;
  maxPerMonth?: number;
}

interface SpendCapsState {
  enabled: boolean;
  mode: SafetyRailsMode;
  caps: SpendCapEntry[];
}

interface SlippageCapState {
  enabled: boolean;
  mode: SafetyRailsMode;
  maxBps: number;
}

interface SafetyRailsState {
  programs: ProgramRulesState;
  tokens: TokenRulesState;
  spend: SpendCapsState;
  slippage: SlippageCapState;
}

interface TemplateFieldOptionCacheEntry {
  options: ConnectorOption[];
  fetchedAt: number;
  ttlMs: number;
  error?: string;
}

interface TemplateFieldPairPreview {
  templateId: string;
  pairLabel: string;
  amountSide: 'tokenA' | 'tokenB';
  pairedSide: 'tokenA' | 'tokenB';
  pairedSymbol: string;
  pairedAmount: string;
  pairedMaxAmount?: string;
  fetchedAt: number;
  estimateNote: string;
  error?: string;
}

type WalletBalanceLoadStatus = 'idle' | 'loading' | 'ready' | 'error';

interface WalletBalanceViewState {
  scopeKey: string;
  summaryStatus: WalletBalanceLoadStatus;
  fullStatus: WalletBalanceLoadStatus;
  overlayOpen: boolean;
  summary: WalletBalanceSnapshot | null;
  full: WalletBalanceSnapshot | null;
  summaryError: string;
  fullError: string;
}

function emptyWalletBalanceViewState(): WalletBalanceViewState {
  return {
    scopeKey: '',
    summaryStatus: 'idle',
    fullStatus: 'idle',
    overlayOpen: false,
    summary: null,
    full: null,
    summaryError: '',
    fullError: '',
  };
}

