type BrowserDeviceAgentModule = typeof import('./deviceAgent/index.js');
let browserDeviceAgentModule: BrowserDeviceAgentModule | null = null;
let browserDeviceAgentModulePromise: Promise<BrowserDeviceAgentModule> | null = null;

async function loadBrowserDeviceAgentModule(): Promise<BrowserDeviceAgentModule> {
  if (browserDeviceAgentModule) return browserDeviceAgentModule;
  browserDeviceAgentModulePromise ??= import('./deviceAgent/index.js').then((mod) => {
    browserDeviceAgentModule = mod;
    return mod;
  }).catch((err) => {
    browserDeviceAgentModulePromise = null;
    throw err;
  });
  return browserDeviceAgentModulePromise;
}

function isBrowserDeviceAgentSecretStoreMode(value: unknown): value is SecretStoreMode {
  return value === 'encrypted-indexeddb' || value === 'session-memory';
}

function readBrowserDeviceAgentSecretStoreMode(): SecretStoreMode {
  // Secret-store mode is pinned to encrypted-indexeddb: the provider key is always
  // remembered securely on this device (WebCrypto ciphertext in IndexedDB). The
  // user-facing picker was removed for being developer jargon; any lingering
  // 'session-memory' preference is migrated to the persistent default.
  return 'encrypted-indexeddb';
}

function persistBrowserDeviceAgentSecretStoreMode(mode: SecretStoreMode): void {
  if (!isBrowserDeviceAgentSecretStoreMode(mode)) return;
  try {
    window.localStorage.setItem(DEVICE_AGENT_SECRET_STORE_MODE_KEY, mode);
  } catch {
    // Best-effort preference persistence.
  }
}

function currentDeviceAgentWalletAddress(): string | undefined {
  return state.address || state.cloudSession.walletAddress || undefined;
}

interface PersistedDeviceAgentStatusV1 {
  v: 1;
  walletAddress: string;
  mode: AiSettings['mode'];
  savedAt: number;
  status: DeviceAgentStatus;
}

interface PersistedDeviceAgentStatusV2 {
  v: 2;
  scope: 'app' | 'wallet';
  walletAddress?: string;
  mode: AiSettings['mode'];
  savedAt: number;
  status: DeviceAgentStatus;
}

type PersistedDeviceAgentStatus = PersistedDeviceAgentStatusV1 | PersistedDeviceAgentStatusV2;

function deviceAgentStatusCacheScope(status: DeviceAgentStatus): 'app' | 'wallet' {
  const apiFormat = status.apiFormat as string | undefined;
  if (
    state.aiSettings.pairedBridge ||
    status.provider === 'paired-bridge' ||
    apiFormat === 'paired-bridge'
  ) {
    return 'wallet';
  }
  return 'app';
}

function saveDeviceAgentStatusCache(status: DeviceAgentStatus | null): void {
  if (!status) return;
  // An explicitly-unconfigured status is also "known truth" — clear the cache
  // so a later refresh doesn't resurrect an older configured snapshot.
  if (!status.configured) {
    clearDeviceAgentStatusCache();
    return;
  }
  const scope = deviceAgentStatusCacheScope(status);
  const walletAddress = currentDeviceAgentWalletAddress();
  if (scope === 'wallet' && !walletAddress) return;
  try {
    const payload: PersistedDeviceAgentStatus = {
      v: 2,
      scope,
      ...(scope === 'wallet' && walletAddress ? { walletAddress } : {}),
      mode: 'device-agent',
      savedAt: Date.now(),
      status,
    };
    window.localStorage.setItem(DEVICE_AGENT_STATUS_STORAGE_KEY, JSON.stringify(payload));
  } catch {
    // Best-effort cache; persistence failures shouldn't break UX.
  }
}

function loadDeviceAgentStatusCache(): DeviceAgentStatus | null {
  let raw: string | null;
  try {
    raw = window.localStorage.getItem(DEVICE_AGENT_STATUS_STORAGE_KEY);
  } catch {
    return null;
  }
  if (!raw) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    clearDeviceAgentStatusCache();
    return null;
  }
  if (
    !parsed
    || typeof parsed !== 'object'
    || ((parsed as { v?: unknown }).v !== 1 && (parsed as { v?: unknown }).v !== 2)
  ) {
    clearDeviceAgentStatusCache();
    return null;
  }
  const entry = parsed as Partial<PersistedDeviceAgentStatus>;
  const walletAddress = currentDeviceAgentWalletAddress();
  if (
    entry.mode !== 'device-agent'
    || typeof entry.savedAt !== 'number'
    || Date.now() - entry.savedAt > DEVICE_AGENT_STATUS_CACHE_MAX_AGE_MS
  ) {
    return null;
  }
  if (entry.v === 1) {
    const legacyEntry = entry as Partial<PersistedDeviceAgentStatusV1>;
    if (!walletAddress || legacyEntry.walletAddress !== walletAddress) return null;
  } else {
    const scopedEntry = entry as Partial<PersistedDeviceAgentStatusV2>;
    if (scopedEntry.scope === 'wallet') {
      if (!walletAddress || scopedEntry.walletAddress !== walletAddress) return null;
    } else if (scopedEntry.scope !== 'app') {
      clearDeviceAgentStatusCache();
      return null;
    }
  }
  try {
    return parseDeviceAgentStatus(entry.status);
  } catch {
    return null;
  }
}

function clearDeviceAgentStatusCache(): void {
  try {
    window.localStorage.removeItem(DEVICE_AGENT_STATUS_STORAGE_KEY);
  } catch {
    // Best-effort.
  }
}

async function hydrateIosNativeLayoutContract(): Promise<void> {
  if (!state.iosNativeEnvironment.isIosNative) {
    state.iosLayoutContract = 'legacy-auto-inset';
    return;
  }
  const iosSystem = agenticIosSystemBridge();
  if (!iosSystem?.systemInfo) {
    state.iosLayoutContract = 'legacy-auto-inset';
    return;
  }
  try {
    const info = await iosSystem.systemInfo();
    state.iosLayoutContract =
      info?.layoutContract === 'ios-css-safe-area-v1' && info.webViewContentInset === 'never'
        ? 'css-safe-area-v1'
        : 'legacy-auto-inset';
  } catch (err) {
    console.warn('[bootstrap] iOS layout contract probe failed', err);
    state.iosLayoutContract = 'legacy-auto-inset';
  }
}

function currentBrowserNativeRuntimeEligible(): boolean {
  return browserNativeRuntimeEligibleForSurface({
    deviceAgentEnabled: DEVICE_AGENT_ENABLED,
    browserDeviceAgentEnabled: BROWSER_DEVICE_AGENT_ENABLED,
    walletAddress: currentDeviceAgentWalletAddress(),
    isAndroidApp: IS_ANDROID_APP,
    isIosApp: state.iosNativeEnvironment.isIosNative,
    showDevControls: SHOW_DEV_CONTROLS,
  });
}

let browserDeviceAgentStatusUnsubscribe: (() => void) | null = null;

async function ensureBrowserDeviceAgentInitialized(): Promise<BrowserDeviceAgentModule | null> {
  if (!currentBrowserNativeRuntimeEligible()) return null;
  const mod = await loadBrowserDeviceAgentModule();
  if (!mod.isBrowserDeviceAgentInitialized()) {
    mod.initBrowserDeviceAgent({
      secretStoreMode: readBrowserDeviceAgentSecretStoreMode(),
      walletAddress: currentDeviceAgentWalletAddress(),
    });
    attachBrowserDeviceAgentStatusListener(mod);
    return mod;
  }
  syncBrowserDeviceAgentWalletAddress(mod);
  attachBrowserDeviceAgentStatusListener(mod);
  return mod;
}

function attachBrowserDeviceAgentStatusListener(mod: BrowserDeviceAgentModule): void {
  if (browserDeviceAgentStatusUnsubscribe) return;
  browserDeviceAgentStatusUnsubscribe = mod.subscribeBrowserDeviceAgentStatus((nextStatus) => {
    // Only update the visible status while the user is on the device-agent
    // path. Other AI modes shouldn't redraw on background runtime transitions.
    if (state.aiSettings.mode !== 'device-agent') return;
    try {
      state.deviceAgentStatus = parseDeviceAgentStatus(nextStatus);
    } catch {
      state.deviceAgentStatus = nextStatus;
    }
    saveDeviceAgentStatusCache(state.deviceAgentStatus);
    render();
  });
}

function warmBrowserDeviceAgent(): void {
  void ensureBrowserDeviceAgentInitialized();
}

function syncBrowserDeviceAgentWalletAddress(mod = browserDeviceAgentModule): void {
  if (!mod?.isBrowserDeviceAgentInitialized()) return;
  mod.setBrowserDeviceAgentWalletAddress(currentDeviceAgentWalletAddress());
}

function notifyCompletedCloudWorkspaceDeleteFromLaunch(): void {
  if (!completedCloudWorkspaceDeleteNotice) return;
  const count = completedCloudWorkspaceDeleteNotice.deletedCount;
  pushToast(
    'success',
    t('Cloud workspace deleted'),
    count === 1
      ? tf('{count} cloud record removed. This device\'s app storage was cleared.', { count })
      : tf('{count} cloud records removed. This device\'s app storage was cleared.', { count }),
    { dismissAfterMs: 10_000 },
  );
}

// Open/closed state for presentational <details> keyed by a stable derived id.
// Persists across render()'s wholesale innerHTML replacement so a disclosure the
// user opened stays open across re-renders. See ./webViewControlFix.ts.
const disclosureOpenState = new Map<string, boolean>();

async function startApp(): Promise<void> {
  try {
    if (!appRoot) {
      throw new Error('Missing #app');
    }
    bindWalletBalanceLogoFallback();
    // Tag the GA session with the runtime surface so the single Web stream can segment
    // web vs in-app (android/ios) vs desktop traffic. IS_* constants resolve at module load.
    initializeAnalytics(
      IS_TAURI_APP ? 'desktop' : IS_IOS_APP ? 'ios' : IS_ANDROID_APP ? 'android' : 'web',
    );
    warmBrowserDeviceAgent();
    normalizeInitialRoute();
    hydrateGeneratedPlansForStartup();
    notifyCompletedCloudWorkspaceDeleteFromLaunch();
    installSpendBridgeHandlers();
    const cachedDeviceAgentStatus = loadDeviceAgentStatusCache();
    if (cachedDeviceAgentStatus) {
      state.deviceAgentStatus = cachedDeviceAgentStatus;
    }
    render();
    scheduleConnectorSecretsRefresh();
    if (SHOW_DEV_CONTROLS) {
      startSystemHealthPolling();
    }
    startNotificationTicker();
    initPushTapRouting();
    // A device already opted into push (has a saved token) should re-attest on launch, since the
    // 7-day session expires but push must outlive it. No-op when nothing is registered.
    if (rememberedPushDevice()) void syncPushDeviceRegistration();
    startAgentBackgroundWatch();
    startRelayPresenceWatch();
    window.addEventListener('popstate', () => render());
    window.addEventListener('keydown', handleGlobalKeydown);
    if (!IS_ANDROID_APP) {
      installNativeLiveUpdateWatcher();
    }
    installWebViewControlDelegates(disclosureOpenState);
    installPayOutApprovalCreatedListener();
    reportOrphanedCloudSignInOnBoot();
    if (!IS_ANDROID_APP && await runNativeLiveUpdateCheck('startup') === 'reloading') return;
    await bootstrap();
    if (IS_ANDROID_APP) {
      installNativeLiveUpdateWatcher();
      void runNativeLiveUpdateCheck('startup-after-android-restore');
    }
  } catch (err) {
    renderStartupFailure(err);
  }
}

function installNativeLiveUpdateWatcher(): void {
  if (!nativeLiveUpdateEnabled()) return;
  window.addEventListener('focus', () => {
    void runNativeLiveUpdateCheck('focus');
  });
  window.addEventListener('online', () => {
    void runNativeLiveUpdateCheck('online');
  });
  window.addEventListener('pageshow', () => {
    void runNativeLiveUpdateCheck('pageshow');
  });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      void runNativeLiveUpdateCheck('visible');
    }
  });
  window.setInterval(() => {
    if (document.visibilityState !== 'hidden') {
      void runNativeLiveUpdateCheck('visible-interval');
    }
  }, NATIVE_LIVE_UPDATE_VISIBLE_INTERVAL_MS);
}

async function runNativeLiveUpdateCheck(trigger: string): Promise<'skipped' | 'current' | 'reloading' | 'error'> {
  const result = await checkNativeLiveUpdate({
    enabled: nativeLiveUpdateEnabled(),
    currentBuildCommit: __AGENTIC_BROWSER_BUILD_COMMIT__,
    liveOrigin: androidCloudApiBaseUrl(),
    fetch: window.fetch.bind(window),
    storage: window.localStorage,
    location: window.location,
    nowMs: () => Date.now(),
    walletRequestActive: nativeLiveUpdateRequestActive,
    logger: console,
  });
  lastNativeLiveUpdateResult = result;
  lastNativeLiveUpdateTrigger = trigger;
  lastNativeLiveUpdateCheckedAt = new Date().toISOString();
  if (result === 'reloading') {
    console.info('[native-live-update] reload scheduled', { trigger });
  }
  return result;
}

function nativeLiveUpdateEnabled(): boolean {
  return IS_ANDROID_APP || IS_IOS_APP || IS_TAURI_APP;
}

function nativeLiveUpdateRequestActive(): boolean {
  // Never reload the page (live-update) while a sensitive op is in flight: a busy
  // wallet flow, a pending CLI sign, a proof-signing toast, OR an active chat
  // stream — reloading mid-stream aborts the answer the user is watching.
  return Boolean(
    state.busy || state.pendingCliSignRequest || proofSigningToastDepth > 0 || chatStreamActive(),
  );
}

if (nativeLiveUpdateEnabled() && typeof window !== 'undefined') {
  (window as Window & {
    __agenticNativeLiveUpdateRequestActive?: () => boolean;
  }).__agenticNativeLiveUpdateRequestActive = nativeLiveUpdateRequestActive;
}

function installPayOutApprovalCreatedListener(): void {
  addPayOutApprovalCreatedListener((detail) => {
    void handlePayOutApprovalCreated(detail);
  });
  addAp2InboundDemoCreatedListener((detail) => {
    handleAp2InboundDemoCreated(detail);
  });
  addStreamingApprovalRequestedListener((detail) => {
    handleStreamingApprovalRequested(detail);
  });
  addStreamingApprovalExecuteRequestedListener((detail) => {
    void handleStreamingApprovalExecuteRequested(detail);
  });
  addCloudSignInRequestedListener(() => {
    void runCloudSignIn();
  });
}

function handleAp2InboundDemoCreated(detail: Ap2InboundDemoCreatedDetail): void {
  const action = cloudApprovalToPreparedAction(detail.approval);
  if (!action) {
    state.error = t('The local AP2 demo did not return a valid approval card.');
    pushToast('error', t('Incoming request failed'), state.error);
    render();
    return;
  }
  const walletAddress = state.address || action.walletAddress;
  if (!walletAddress) {
    state.error = t('Connect a wallet before creating an incoming request demo.');
    pushToast('error', t('Incoming request failed'), state.error);
    render();
    return;
  }
  const localAction: PreparedAction = {
    ...action,
    walletAddress,
    workflowSource: 'browser',
    metadata: {
      ...(action.metadata ?? {}),
      source: 'ap2_inbound',
      actionSource: 'ap2_inbound',
      devLocal: true,
    },
  };
  state.preparedActions = mergePreparedActions([localAction], state.preparedActions);
  state.materializedActions = state.preparedActions;
  saveBrowserWorkflowState();
  pushToast('success', t('Incoming request ready'), t('Open it from Incoming Requests, then approve in Sign Approval.'));
  render();
}

async function handlePayOutApprovalCreated(detail: PayOutApprovalCreatedDetail): Promise<void> {
  state.activeTab = 'inbox';
  state.inboxFilter = 'all';
  state.error = '';
  state.steps.inbox = 'active';
  if (state.workflowModePreference === 'local-bridge') {
    state.workflowModePreference = 'auto';
    savePersistedState();
  }
  render();

  if (detail.localOnly) {
    try {
      const action = materializeLocalPayOutApproval(detail);
      state.steps.inbox = 'done';
      state.error = '';
      pushToast('success', t('Approval added to Sign Approval'), tf('{cartId} is saved on this device.', { cartId: detail.cartId }));
      render();
      focusInboxApprovalCard(action.id);
    } catch (err) {
      state.steps.inbox = 'error';
      state.error = redactSecrets(err instanceof Error ? err.message : String(err));
      pushToast('error', t('Local approval failed'), state.error);
      render();
    }
    return;
  }

  try {
    await refreshCloudSession(false);
    if (!cloudSessionMatchesWallet()) {
      throw new Error(t('Connect the signed-in Agentic Cloud wallet to view the Pay Merchant approval.'));
    }
    await refreshCloudWorkspaceData();
    state.steps.inbox = 'done';
    state.error = '';
    render();
    focusInboxApprovalCard(detail.approvalId);
  } catch (err) {
    state.steps.inbox = 'error';
    state.error = redactSecrets(err instanceof Error ? err.message : String(err));
    render();
    pushToast(
      'error',
      t('Approval created, inbox refresh failed'),
      tf('{cartId} is saved in Agentic Cloud. {error}', { cartId: detail.cartId, error: state.error }),
    );
  }
}

function materializeLocalPayOutApproval(detail: PayOutApprovalCreatedDetail): PreparedAction {
  if (!state.address) {
    throw new Error(t('Connect a wallet before adding the Pay Merchant approval to Sign Approval.'));
  }
  const action = cloudApprovalToPreparedAction(detail.approval);
  if (!action) {
    throw new Error(t('The local ACP dev route did not return a valid approval card.'));
  }
  const localAction: PreparedAction = {
    ...action,
    walletAddress: state.address,
    workflowSource: 'browser',
    metadata: {
      ...(action.metadata ?? {}),
      source: 'acp_outbound',
      actionSource: 'acp_outbound',
      devLocal: true,
    },
  };
  state.preparedActions = mergePreparedActions([localAction], state.preparedActions);
  state.materializedActions = state.preparedActions;
  saveBrowserWorkflowState();
  return localAction;
}

function handleStreamingApprovalRequested(detail: StreamingApprovalRequestedDetail): void {
  try {
    const action = materializeLocalStreamingApproval(detail);
    state.activeTab = 'inbox';
    state.inboxFilter = 'all';
    state.error = '';
    state.steps.inbox = 'done';
    pushToast('success', t('Streaming approval ready'), tf('{operation} is in Sign Approval.', { operation: streamingOperationLabel(detail.operation) }));
    render();
    focusInboxApprovalCard(action.id);
    dispatchStreamingApprovalCompleted({
      source: 'streaming_session',
      operation: detail.operation,
      sessionId: detail.sessionId,
      approvalId: action.id,
      status: 'queued',
    });
  } catch (err) {
    const message = redactSecrets(err instanceof Error ? err.message : String(err));
    state.error = message;
    pushToast('error', t('Streaming approval failed'), message);
    render();
    dispatchStreamingApprovalCompleted({
      source: 'streaming_session',
      operation: detail.operation,
      sessionId: detail.sessionId,
      approvalId: detail.sessionId,
      status: 'failed',
      error: message,
    });
  }
}

async function handleStreamingApprovalExecuteRequested(detail: StreamingApprovalExecuteRequestedDetail): Promise<void> {
  let action: PreparedAction | undefined;
  let toastId: number | undefined;
  try {
    action = materializeInlineStreamingApproval(detail);
    const summary = detail.summary || streamingApprovalSummary(detail.operation, detail.sessionId);
    const submittedTxid = detail.txid?.trim();
    toastId = pushToast('pending', submittedTxid ? t('Checking session transaction') : t('Opening wallet'), summary);
    const toastContext: TransactionToastContext = { toastId, actionId: action.id, cluster: action.cluster };
    const execution = submittedTxid
      ? await checkInlineStreamingTransaction(action, submittedTxid, toastContext)
      : await executeInlineStreamingTransaction(action, detail, summary, toastContext);
    const status = execution.txStatus === 'confirmed' ? 'confirmed' : 'submitted';
    if (execution.txStatus === 'confirmed') {
      const ledger = findPendingTransactionByAction(action.id);
      if (ledger) {
        removePendingTransaction(ledger.id);
        syncPendingTransactionsFromLedger();
      }
    }
    dispatchStreamingApprovalCompleted({
      source: 'streaming_session',
      operation: detail.operation,
      sessionId: detail.sessionId,
      approvalId: action.id,
      status,
      txid: execution.txid,
    });
    replaceToast(
      toastId,
      status === 'confirmed' ? 'success' : 'pending',
      status === 'confirmed' ? t('Session transaction confirmed') : t('Session transaction submitted'),
      short(execution.txid),
      {
        linkHref: execution.explorerUrl,
        linkLabel: t('Open Solscan'),
      },
    );
    render();
  } catch (err) {
    const message = redactSecrets(err instanceof Error ? err.message : String(err));
    if (toastId !== undefined) {
      replaceToast(toastId, 'error', t('Streaming transaction failed'), message);
    } else {
      pushToast('error', t('Streaming transaction failed'), message);
    }
    dispatchStreamingApprovalCompleted({
      source: 'streaming_session',
      operation: detail.operation,
      sessionId: detail.sessionId,
      approvalId: action?.id || detail.approvalId || detail.sessionId,
      status: 'failed',
      ...(detail.txid ? { txid: detail.txid } : {}),
      error: message,
    });
    render();
  }
}

function materializeInlineStreamingApproval(detail: StreamingApprovalExecuteRequestedDetail): PreparedAction {
  if (!state.address) {
    throw new Error(t('Connect a wallet before signing the streaming session transaction.'));
  }
  const walletAddress = detail.walletAddress?.trim() || state.address;
  if (walletAddress !== state.address) {
    throw new Error(tf('Connect {wallet} before signing this streaming session transaction.', { wallet: short(walletAddress) }));
  }
  const cluster = streamingApprovalCluster(detail);
  const now = new Date().toISOString();
  return {
    id: detail.approvalId?.trim() || newId('browser-streaming-inline'),
    kind: 'custom_transaction',
    status: 'ready',
    walletAddress,
    cluster,
    summary: detail.summary || streamingApprovalSummary(detail.operation, detail.sessionId),
    params: {
      transactionBase64: detail.tx.txBase64,
      reason: detail.summary || streamingApprovalSummary(detail.operation, detail.sessionId),
      streamingSessionId: detail.sessionId,
      streamingOperation: detail.operation,
      ...(detail.tx.tokenMint ? { tokenMint: detail.tx.tokenMint, token: detail.tx.tokenMint } : {}),
      ...(detail.tx.totalAmount ? { amount: detail.tx.totalAmount } : {}),
      ...(detail.tx.description ? { description: detail.tx.description } : {}),
      ...(detail.tx.kind ? { delegateTxKind: detail.tx.kind } : {}),
      ...(detail.tx.sourceAta ? { sourceAta: detail.tx.sourceAta } : {}),
    },
    metadata: {
      source: 'streaming_session',
      actionSource: 'streaming_session',
      connectorId: 'streaming',
      connectorName: 'Streaming Sessions',
      operation: detail.operation,
      sessionId: detail.sessionId,
      walletAddress,
      callbackPath: detail.callbackPath,
      streamingCallbackStatus: 'pending',
      ...(detail.tx.tokenMint ? { tokenMint: detail.tx.tokenMint } : {}),
      ...(detail.tx.totalAmount ? { capAmount: detail.tx.totalAmount } : {}),
      ...(detail.tx.description ? { delegateTxDescription: detail.tx.description } : {}),
    },
    dueAt: now,
    createdAt: now,
    updatedAt: now,
    note: detail.tx.description || 'Streaming session delegate transaction.',
    workflowSource: 'browser',
  };
}

async function executeInlineStreamingTransaction(
  action: PreparedAction,
  detail: StreamingApprovalExecuteRequestedDetail,
  summary: string,
  toastContext: TransactionToastContext,
): Promise<BrowserTransactionExecution> {
  if (!detail.tx.txBase64) {
    throw new Error(t('Streaming transaction bytes are missing.'));
  }
  const execution = await signAndBroadcastBrowserTransactionBase64(action, detail.tx.txBase64, summary, toastContext);
  const txid = execution.txid;
  const txStatus = await resolveSubmittedTransactionStatus(action.cluster, txid, toastContext);
  return {
    txid,
    txStatus,
    explorerUrl: explorerUrl(txid, action.cluster),
    messageHash: execution.messageHash,
  };
}

async function checkInlineStreamingTransaction(
  action: PreparedAction,
  txid: string,
  toastContext: TransactionToastContext,
): Promise<BrowserTransactionExecution> {
  const status = await resolveSubmittedTransactionStatusResult(action.cluster, txid, toastContext);
  return {
    txid,
    txStatus: status.txStatus === 'confirmed' ? 'confirmed' : 'pending',
    explorerUrl: explorerUrl(txid, action.cluster),
  };
}

function materializeLocalStreamingApproval(detail: StreamingApprovalRequestedDetail): PreparedAction {
  if (!state.address) {
    throw new Error(t('Connect a wallet before adding the streaming session approval to Sign Approval.'));
  }
  const walletAddress = detail.walletAddress?.trim() || state.address;
  if (walletAddress !== state.address) {
    throw new Error(tf('Connect {wallet} before adding this streaming session approval to Sign Approval.', { wallet: short(walletAddress) }));
  }
  const cluster = streamingApprovalCluster(detail);
  const now = new Date().toISOString();
  const action: PreparedAction = {
    id: newId('browser-streaming'),
    kind: 'custom_transaction',
    status: 'ready',
    walletAddress,
    cluster,
    summary: detail.summary || streamingApprovalSummary(detail.operation, detail.sessionId),
    params: {
      transactionBase64: detail.tx.txBase64,
      reason: detail.summary || streamingApprovalSummary(detail.operation, detail.sessionId),
      streamingSessionId: detail.sessionId,
      streamingOperation: detail.operation,
      ...(detail.tx.tokenMint ? { tokenMint: detail.tx.tokenMint, token: detail.tx.tokenMint } : {}),
      ...(detail.tx.totalAmount ? { amount: detail.tx.totalAmount } : {}),
      ...(detail.tx.description ? { description: detail.tx.description } : {}),
      ...(detail.tx.kind ? { delegateTxKind: detail.tx.kind } : {}),
      ...(detail.tx.sourceAta ? { sourceAta: detail.tx.sourceAta } : {}),
    },
    metadata: {
      source: 'streaming_session',
      actionSource: 'streaming_session',
      connectorId: 'streaming',
      connectorName: 'Streaming Sessions',
      operation: detail.operation,
      sessionId: detail.sessionId,
      walletAddress,
      callbackPath: detail.callbackPath,
      streamingCallbackStatus: 'pending',
      ...(detail.tx.tokenMint ? { tokenMint: detail.tx.tokenMint } : {}),
      ...(detail.tx.totalAmount ? { capAmount: detail.tx.totalAmount } : {}),
      ...(detail.tx.description ? { delegateTxDescription: detail.tx.description } : {}),
    },
    dueAt: now,
    createdAt: now,
    updatedAt: now,
    note: detail.tx.description || 'Streaming session delegate transaction.',
    workflowSource: 'browser',
  };
  state.preparedActions = mergePreparedActions([action], state.preparedActions);
  state.materializedActions = state.preparedActions;
  saveBrowserWorkflowState();
  return action;
}

function streamingApprovalCluster(detail: StreamingApprovalRequestedDetail): Cluster {
  const cluster = detail.cluster ?? detail.tx.cluster;
  if (cluster === 'mainnet-beta' || cluster === 'devnet' || cluster === 'testnet' || cluster === 'localnet') {
    return cluster;
  }
  return state.cluster;
}

function streamingOperationLabel(operation: StreamingApprovalOperation): string {
  return operation === 'grant' ? t('Session grant') : t('Session revoke');
}

function streamingApprovalSummary(operation: StreamingApprovalOperation, sessionId: string): string {
  return operation === 'grant'
    ? tf('Grant streaming session {id}', { id: short(sessionId) })
    : tf('Revoke streaming session {id}', { id: short(sessionId) });
}

function focusInboxApprovalCard(approvalId: string): void {
  if (!approvalId || typeof document === 'undefined') return;
  requestAnimationFrame(() =>
    requestAnimationFrame(() => {
      const escaped = typeof CSS !== 'undefined' && CSS.escape
        ? CSS.escape(approvalId)
        : approvalId.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
      const anchor = document.querySelector(`[data-action-id="${escaped}"]`);
      const article = anchor?.closest('article');
      if (article instanceof HTMLElement) {
        article.scrollIntoView({ behavior: 'smooth', block: 'center' });
        article.classList.add('inbox-approval-created-flash');
        window.setTimeout(() => article.classList.remove('inbox-approval-created-flash'), 1600);
      }
    }),
  );
}

function handleGlobalKeydown(event: KeyboardEvent): void {
  // Chat: Escape closes an open menu first, then aborts an in-flight stream,
  // before any other handler — mirrors the Android back-button expectation.
  if (event.key === 'Escape' && state.connectorConnect) {
    event.preventDefault();
    closeConnectorConnect();
    return;
  }
  // Escape first disarms an armed delete-confirm without closing the whole menu;
  // a second Escape then closes the menu via the block below.
  if (event.key === 'Escape' && state.chatDeleteConfirmId) {
    event.preventDefault();
    const disarmedId = state.chatDeleteConfirmId;
    state.chatDeleteConfirmId = '';
    render();
    // Return focus to the restored × for that row (the Cancel button it was on is now gone).
    (document.querySelector<HTMLButtonElement>(`[data-chat-del="${disarmedId}"]`)
      ?? document.querySelector<HTMLButtonElement>('[data-chat-history-trigger]'))?.focus();
    return;
  }
  if (event.key === 'Escape' && (state.chatHistoryOpen || state.chatComposerOpen || state.chatPendingOpen)) {
    event.preventDefault();
    const restoreHistoryFocus = state.chatHistoryOpen;
    state.chatHistoryOpen = false;
    state.chatDeleteConfirmId = '';
    state.chatComposerOpen = false;
    state.chatPendingOpen = false;
    state.chatPendingSelectedId = null;
    render();
    // Return focus to the trigger that opened the menu (keyboard a11y).
    if (restoreHistoryFocus) {
      document.querySelector<HTMLButtonElement>('[data-chat-history-trigger]')?.focus();
    }
    return;
  }
  if (event.key === 'Escape' && state.activeTab === 'chat' && chatStreamActive()) {
    event.preventDefault();
    cancelChatStream();
    render();
    return;
  }
  if (event.key === 'Escape' && state.cloudWorkspaceDeleteModalOpen) {
    event.preventDefault();
    closeCloudWorkspaceDeleteModal();
    return;
  }
  if (event.key === 'Escape' && state.completedDeleteModalId) {
    event.preventDefault();
    closeCompletedDeleteModal();
    return;
  }
  if (event.key === 'Escape' && state.generatedPlanDeleteModalId) {
    event.preventDefault();
    closeGeneratedPlanDeleteModal();
    return;
  }
  if (event.key === 'Escape' && state.inboxDeleteModalId) {
    event.preventDefault();
    closeInboxDeleteModal();
    return;
  }
  if (event.key === 'Escape' && state.deleteAllInboxModalOpen) {
    event.preventDefault();
    closeDeleteAllInboxModal();
    return;
  }
  if (event.key === 'Escape' && state.deleteAllCheckModalOpen) {
    event.preventDefault();
    closeDeleteAllCheckModal();
    return;
  }
  if (event.key === 'Escape' && state.deleteAllRepeatsModalOpen) {
    event.preventDefault();
    closeDeleteAllRepeatsModal();
    return;
  }
  if (event.key === 'Escape' && state.deleteAllDoneModalOpen) {
    event.preventDefault();
    closeDeleteAllDoneModal();
    return;
  }
  if (event.key === 'Escape' && state.generatedPlanAuditId) {
    event.preventDefault();
    closeGeneratedPlanAuditModal();
    return;
  }
  if (event.key === 'Escape' && state.walletBalance.overlayOpen) {
    event.preventDefault();
    closeWalletBalanceOverlay();
    return;
  }
  // Wallet overlays (Slice R.5). We close the overlay unconditionally on
  // Escape — any in-flight IPC continues and will dispatch back into a
  // closed overlay, which the reducers handle as a no-op (or, in the
  // create-success path, re-opens to show the recovery phrase, which is
  // the desired UX). For the Ledger overlay we also stop the device-scan
  // poll, mirroring `closeSiblingOverlays`.
  if (event.key === 'Escape' && embeddedWallet.overlay.mode !== 'closed') {
    if (!embeddedWallet.overlay.busy) {
      event.preventDefault();
      dispatchEmbeddedWalletOverlay({ type: 'close' });
    }
    return;
  }
  if (event.key === 'Escape' && walletConnect.overlay.mode !== 'closed') {
    event.preventDefault();
    cancelWalletConnectPairing();
    return;
  }
  if (event.key === 'Escape' && ledger.overlay.mode !== 'closed') {
    event.preventDefault();
    stopLedgerPoll();
    ledger.pairingToken += 1;
    dispatchLedgerOverlay({ type: 'close' });
    return;
  }
}

function hydrateGeneratedPlansForStartup(): void {
  try {
    const plans = loadGeneratedPlans();
    const recovered = recoverInterruptedAgentReviews(plans, { staleAfterMs: 0 });
    state.generatedPlans = recovered.records;
    state.selectedGeneratedPlanId = recovered.records.find((record) => record.status !== 'archived')?.id ?? recovered.records[0]?.id ?? '';
    if (recovered.changed) saveGeneratedPlans();
  } catch (err) {
    state.generatedPlans = [];
    state.selectedGeneratedPlanId = '';
    console.warn('Generated plan storage could not be loaded.', err);
  }
}

function hydrateLocalWorkspaceForWallet(): void {
  if (!state.address) return;
  const cloudPlans = state.generatedPlans.filter((record) => record.workflowSource === 'cloud');
  const localPlans = loadGeneratedPlans(state.address);
  const recovered = recoverInterruptedAgentReviews(mergeGeneratedPlans(cloudPlans, localPlans), { staleAfterMs: 0 });
  state.generatedPlans = recovered.records;
  state.localCompletedPlans = loadLocalCompletedPlans(state.address);
  state.positions = loadPositions(state.address);
  state.positionsClosed = loadPositionsClosed(state.address);
  state.positionsLive = {}; // old wallet's live data must not bleed across a switch
  state.positionsPrefetched = false;
  ensurePositionSettleInterval(); // a manage action still settling when the app reloaded resumes here
  refreshBrowserWorkflowData();
  if (recovered.changed) saveGeneratedPlans();
  selectFallbackGeneratedPlan();
}

function renderStartupFailure(err: unknown): void {
  const message = err instanceof Error ? err.message : String(err);
  const escaped = escapeHtml(message || 'Unknown startup error.');
  const target = appRoot ?? document.body;
  target.innerHTML = `
    <section data-agentic-startup-failure style="
      min-height: 100vh;
      box-sizing: border-box;
      display: grid;
      place-items: center;
      padding: 24px;
      background: #020504;
      color: #eef8f2;
      font-family: Space Grotesk, Inter, system-ui, sans-serif;
    ">
      <div style="
        max-width: 620px;
        border: 1px solid rgba(94, 231, 158, 0.35);
        border-radius: 12px;
        background: rgba(9, 18, 15, 0.94);
        box-shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
        padding: 22px;
      ">
        <p style="
          margin: 0 0 8px;
          color: #8bcdaa;
          font-size: 0.75rem;
          font-weight: 900;
          letter-spacing: 0.08em;
          text-transform: uppercase;
        ">${escapeHtml(t('Agentic startup failed'))}</p>
        <h1 style="margin: 0 0 10px; font-size: 1.35rem; line-height: 1.2;">${escapeHtml(t('Refresh loaded the shell, but the app could not start.'))}</h1>
        <p style="margin: 0; color: rgba(218, 229, 224, 0.84); line-height: 1.5;">${escaped}</p>
      </div>
    </section>
  `;
  console.error('Agentic startup failed.', err);
}

async function bootstrap(): Promise<void> {
  // Cloud sign-in diagnostic: a fresh "app-bootstrap" line after a sign attempt (with DevTools
  // "Preserve log" on) means the webview actually reloaded; absence means it was only a re-render.
  cloudSignInDiag('app-bootstrap', { path: typeof window !== 'undefined' ? window.location.pathname : '' });
  state.mwaRegistration = await registerAgentMobileWalletAdapter({
    appIdentity: {
      name: 'Agentic',
      uri: window.location.origin,
    },
    chains: ['solana:devnet', 'solana:mainnet-beta'],
    logLevel: 'info',
  });
  state.mwaEnvironment = state.mwaRegistration.environment;
  state.androidNativeEnvironment = detectAndroidNativeEnvironment();
  if (state.androidNativeEnvironment.isAndroidNative && state.cluster !== 'mainnet-beta') {
    state.cluster = 'mainnet-beta';
    savePersistedState();
  }
  await refreshAndroidNativeCacheState();
  if (state.androidNativeEnvironment.isAndroidNative) {
    const restored = await restoreAndroidNativeSession().catch((err) => {
      console.warn('[bootstrap] restoreAndroidNativeSession failed', err);
      state.androidNativeStatus = 'Could not restore the cached Android MWA authorization. Tap Discover to reconnect.';
      return false;
    });
    if (restored) await afterWalletConnected();
    if (restored) {
      logAndroidNativeRestore('WEB_RESTORE_AFTER_WALLET_CONNECTED', 'SUCCESS', {
        route: typeof window !== 'undefined' ? window.location.pathname : '',
        address: state.address,
        selectedWalletName: state.selectedWalletName,
        cacheCount: state.androidAuthCacheCount,
      });
      routeAndroidNativeAfterCachedRestore();
    }
  }
  state.tauriNativeEnvironment = detectTauriNativeEnvironment();
  if (state.tauriNativeEnvironment.isTauriNative) {
    // Expose the embedded Agentic Wallet to the Wallet Standard registry so
    // the existing picker discovers it alongside Phantom/Backpack/Solflare.
    // No-op outside Tauri; safe to call unconditionally but cheap to gate.
    registerAgenticWallet();
    // Hydrate the per-brand picker preference (Slice D) from localStorage so
    // the "Show external browser fallback" toggle persists across launches.
    hydrateDesktopBrandPanelsPrefs();
    // Wire the Tauri IPC for the create/import/unlock overlay (Slice C) and
    // start polling so the UI notices when the Rust-side auto-lock timer
    // fires (idle timeout). Polling errors are swallowed; the UI tolerates
    // null status without breaking.
    const invoke = detectTauriInvoke();
    if (invoke) {
      embeddedWallet.ipc = createTauriWalletIpc(invoke);
      embeddedWallet.pollHandle = startWalletStatusPoll(embeddedWallet.ipc, {
        // Skip the IPC call entirely when Agentic isn't the active wallet.
        // The interval keeps ticking, so we pick up status as soon as the
        // user selects Agentic again.
        shouldPoll: () => state.selectedWalletName === AGENTIC_WALLET_NAME,
        onStatus: (status) => {
          // shouldPoll already ensured Agentic is selected; cache directly.
          embeddedWallet.status = status;
        },
        onAutoLocked: () => {
          traceWalletCleared('embedded-wallet-auto-locked');
          state.address = '';
          pushToast(
            'pending',
            t('Agentic Wallet locked'),
            t('Idle timeout reached. Connect again to unlock.'),
          );
          render();
        },
      });
    }
    // Listen for bridge-status updates from the Local-runtime panel polling +
    // user actions, so device-agent routing stays current. Registered BEFORE
    // the first fetch so we never miss an emission.
    window.addEventListener(TAURI_BRIDGE_STATUS_EVENT, (event) => {
      const detail = (event as CustomEvent<TauriBridgeStatus | null>).detail;
      state.tauriBridgeStatus = detail ?? null;
      syncBridgeConfigFromTauriStatus(detail ?? null);
    });
    // Prime the cloud-session-token cache. The Phase-3 file-backed secure store
    // hydrates asynchronously on first read; if hydration finds a newer token
    // than what localStorage held, tauriNative dispatches the rehydrated event
    // below so we re-validate the cloud session.
    void tauriNativeCloudSessionToken();
    window.addEventListener(CLOUD_SESSION_REHYDRATED_EVENT, () => {
      void refreshCloudSessionAfterNativeTokenRehydrated()
        .then(() => render())
        .catch((err) => {
          console.warn('[bootstrap] refreshCloudSession after rehydrate failed', err);
        });
    });
    // Snapshot the current bridge status synchronously so device-agent routing
    // has a value to consult immediately.
    state.tauriBridgeStatus = await tauriNativeBridgeStatus();
    syncBridgeConfigFromTauriStatus(state.tauriBridgeStatus);
    // Best-effort: spawn the local bridge sidecar in the background so the user
    // can immediately use "Local Bridge" AI mode and local connector reads
    // without having to manually start it. Idempotent on the Rust side —
    // start_bridge is a no-op when the bridge is already reachable. Fired
    // non-blocking; subsequent polling in the Local-runtime panel keeps
    // `state.tauriBridgeStatus` fresh via TAURI_BRIDGE_STATUS_EVENT.
    void tauriNativeStartBridge().then((status) => {
      if (status) {
        state.tauriBridgeStatus = status;
        syncBridgeConfigFromTauriStatus(status);
      }
    }).catch((err) => {
      console.warn('[bootstrap] tauriNativeStartBridge failed', err);
    });
    // Relay the Tauri-side `agentic://deep-link` event to a window CustomEvent
    // so future deep-link consumers (e.g. the planned wallet-return relay) can
    // subscribe via DOM-native APIs without depending on @tauri-apps/api.
    void tauriListenEvent<string[]>('agentic://deep-link', (urls) => {
      try {
        window.dispatchEvent(new CustomEvent(TAURI_DEEP_LINK_EVENT, { detail: urls }));
      } catch (err) {
        console.warn('[bootstrap] deep-link relay dispatch failed', err);
      }
    }).catch((err) => {
      console.warn('[bootstrap] tauriListenEvent(agentic://deep-link) failed', err);
    });
  }
  state.iosNativeEnvironment = detectIosNativeEnvironment();
  if (state.iosNativeEnvironment.isIosNative) {
    const previousLayoutContract = state.iosLayoutContract;
    await hydrateIosNativeLayoutContract();
    if (state.iosLayoutContract !== previousLayoutContract) {
      render();
    }
    void iosNativeCloudSessionToken();
    window.addEventListener(IOS_CLOUD_SESSION_REHYDRATED_EVENT, () => {
      void refreshCloudSessionAfterNativeTokenRehydrated()
        .then(() => render())
        .catch((err) => {
          console.warn('[bootstrap] refreshCloudSession after iOS rehydrate failed', err);
        });
    });
  }
  await refreshIosNativeCacheState();
  if (state.iosNativeEnvironment.isIosNative) {
    const restored = await restoreIosNativeSession().catch((err) => {
      console.warn('[bootstrap] restoreIosNativeSession failed', err);
      return false;
    });
    if (restored) await afterWalletConnected();
  }
  if (multiPathWalletFlowAvailable()) {
    // Restore any previously-paired WalletConnect sessions. Lazy — skips if
    // no project ID is configured. This used to be desktop-only; the website
    // now exposes the same QR path.
    void restoreWalletConnectSessions();
  }
  if (!state.androidNativeEnvironment.isAndroidNative && !state.iosNativeEnvironment.isIosNative) {
    await restoreBrowserWalletSession();
    await hydrateCliSignInBridgeWallet();
    subscribeToWalletRegistration(() => {
      const next = visibleBrowserWallets(listAvailableWallets());
      if (next.length === state.wallets.length) return;
      state.wallets = next;
      state.selectedWalletName = reconcileBrowserWalletSelection(state.wallets, state.selectedWalletName);
      if (!cliView && !state.address && state.wallets.length > 0 && !state.selectedWalletName) {
        state.browserWalletPickerOpen = true;
      }
      render();
    });
  }
  if (nativeCloudApiSurfaceActive()) {
    await ensureNativeCloudTokenReady(2500);
  }
  await refreshCloudSessionWithWalletBoundary(false);
  reconcileAiModeForSurface();
  const walletBoundDeviceAgentStatus = loadDeviceAgentStatusCache();
  if (walletBoundDeviceAgentStatus) {
    state.deviceAgentStatus = walletBoundDeviceAgentStatus;
  }
  await hydrateLabArtifactArchive();
  if (cloudSessionMatchesWallet()) {
    await refreshCloudWorkspaceData().catch(() => undefined);
  }
  warmBrowserDeviceAgent();
  if (shouldProbeBridgeOnStartup()) {
    await loadBridgeConfig(false);
    if (shouldReconnectBridgeOnStartup()) {
      await reconnectBridgeOnStartup();
    }
    if (state.aiSettings.mode === 'bridge') {
      await refreshBridgeAiStatus(false);
      await resyncConnectorEngineWithBridge();
    }
  }
  if (state.aiSettings.mode === 'device-agent') {
    state.deviceAgentStatusLoading = true;
    void refreshDeviceAgentStatus(false).finally(() => {
      state.deviceAgentStatusLoading = false;
      render();
    });
  }
  render();
  void reconcilePendingTransactions({ trigger: 'bootstrap' });
  if (
    cliView?.intent === 'connect' &&
    !state.address &&
    !state.androidNativeEnvironment.isAndroidNative &&
    !state.iosNativeEnvironment.isIosNative &&
    !state.tauriNativeEnvironment.isTauriNative
  ) {
    if (cliView.surface === 'desktop' && launchParams.walletBrand) {
      void runWalletHostBrandAutoConnect(launchParams.walletBrand);
    } else {
      void runDiscover().finally(() => {
        state.browserWalletPickerOpen = false;
        render();
      });
    }
  }
  // Wallet-host auto-connect for `?wallet=<brandId>` (desktop browser-extension
  // connect/sign passes this when opening the wallet host in the system browser).
  if (
    launchParams.walletBrand &&
    (!cliView || cliView.surface === 'desktop') &&
    cliView?.intent !== 'connect' &&
    !state.address &&
    !state.androidNativeEnvironment.isAndroidNative &&
    !state.iosNativeEnvironment.isIosNative &&
    !state.tauriNativeEnvironment.isTauriNative
  ) {
    void runWalletHostBrandAutoConnect(launchParams.walletBrand);
  }
}

const WALLET_HOST_AUTOCONNECT_TIMEOUT_MS = 5000;

/** Wait up to `timeoutMs` for a Wallet-Standard wallet matching the brand
 *  to appear in `state.wallets`. Extensions inject asynchronously after
 *  page load via `wallet-standard:register-wallet` window events; the
 *  single-snapshot check we used to do here would race against the
 *  injection and false-negative for cold-start browsers. We subscribe to
 *  the registration stream and re-snapshot on each event. */
async function waitForWalletByBrand(
  brandId: string,
  timeoutMs: number,
): Promise<DiscoveredWallet | null> {
  const names = DESKTOP_BRAND_WALLET_NAMES[brandId];
  if (!names) return null;
  const match = (): DiscoveredWallet | undefined =>
    state.wallets.find((w) => names.some((n) => w.name.toLowerCase() === n.toLowerCase()));
  const initial = match();
  if (initial) return initial;
  return new Promise((resolve) => {
    let settled = false;
    const finish = (w: DiscoveredWallet | null) => {
      if (settled) return;
      settled = true;
      unsubscribe();
      window.clearTimeout(timer);
      resolve(w);
    };
    const unsubscribe = subscribeToWalletRegistration(() => {
      // Re-snapshot — the subscriber doesn't auto-refresh state.wallets.
      state.wallets = visibleBrowserWallets(listAvailableWallets());
      const w = match();
      if (w) finish(w);
    });
    const timer = window.setTimeout(() => finish(null), timeoutMs);
  });
}

async function runWalletHostBrandAutoConnect(brandId: string): Promise<void> {
  const brandLabel =
    DESKTOP_BRAND_PANELS.find((b) => b.id === brandId)?.name ?? brandId;
  // Surface the "Opening <Brand>…" splash immediately so the user sees
  // something happening instead of a blank/landing page.
  state.walletHostOpening = { brandId, brandLabel, status: 'waiting' };
  render();
  try {
    await runDiscover();
  } catch (err) {
    pushToast(
      'error',
      t('Discovery failed'),
      err instanceof Error ? err.message : String(err),
    );
    state.walletHostOpening = null;
    clearWalletBrandLaunchParam();
    render();
    return;
  }
  const candidate = await waitForWalletByBrand(brandId, WALLET_HOST_AUTOCONNECT_TIMEOUT_MS);
  if (!candidate) {
    // Stay on the splash with status='error' + Retry button. Don't clear
    // the launch param here so a hard reload still re-triggers the
    // auto-connect — we only clear it on success below.
    state.walletHostOpening = { brandId, brandLabel, status: 'error' };
    state.error = `${brandLabel} not detected in this browser. Install the extension and click Retry, or pick another wallet.`;
    render();
    return;
  }
  state.selectedWalletName = candidate.name;
  state.browserWalletPickerOpen = false;
  const pairingUuid = launchParams.pairing;
  clearWalletBrandLaunchParam();
  try {
    await runConnect();
    pushToast(
      'success',
      t('Return to your desktop app'),
      tf('{brand} is connected. Switch back to the Agentic desktop window.', { brand: brandLabel }),
    );
    if (pairingUuid) {
      // Cross-device pairing path: register the host on the cloud relay
      // and start the inbox loop so the desktop can sign through us.
      void startWalletHostPairingRelay(pairingUuid, brandLabel);
    }
  } catch (err) {
    pushToast(
      'error',
      t('Connect failed'),
      err instanceof Error ? err.message : String(err),
    );
  } finally {
    state.walletHostOpening = null;
    render();
  }
}

const WALLET_HOST_PAIRING_RELAY_BASE_URL =
  (import.meta as ImportMeta & { env?: { VITE_AGENTIC_CLOUD_API_BASE_URL?: string } }).env
    ?.VITE_AGENTIC_CLOUD_API_BASE_URL || '';
const WALLET_HOST_PAIRING_INBOX_INTERVAL_MS = 2000;
const QR_RELAY_SIGN_POLL_INTERVAL_MS = 3000;

interface WalletHostPairingRuntime {
  uuid: string;
  brandLabel: string;
  pollHandle: number | null;
  /** Set true after we surface the banner so we don't keep re-rendering. */
  bannerShown: boolean;
  /** Set true after a fatal POST error so we stop spamming logs. */
  fatal: boolean;
}

let walletHostPairing: WalletHostPairingRuntime | null = null;

/** Same-origin relative URL when running on agentic-signer.com itself,
 *  absolute URL when running on a different origin (dev / Tauri webview
 *  testing). The wallet-host typically runs same-origin so the relative
 *  path avoids the CORS preflight. */
function pairingRelayUrl(path: string): string {
  return WALLET_HOST_PAIRING_RELAY_BASE_URL
    ? `${WALLET_HOST_PAIRING_RELAY_BASE_URL}${path}`
    : path;
}

async function startWalletHostPairingRelay(uuid: string, brandLabel: string): Promise<void> {
  if (!state.address || !state.capabilities) {
    console.warn('[pairing-relay] address/capabilities missing — skipping host POST');
    return;
  }
  // POST the host details so the desktop's poll picks them up.
  try {
    const response = await fetch(pairingRelayUrl(`/api/pair/${encodeURIComponent(uuid)}/host`), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        address: state.address,
        capabilities: state.capabilities,
        walletName: state.selectedWalletName || brandLabel,
      }),
    });
    if (!response.ok) {
      console.warn(`[pairing-relay] POST host returned ${response.status}`);
      return;
    }
  } catch (err) {
    console.warn('[pairing-relay] POST host failed', err);
    return;
  }
  // Stop any prior pairing loop and replace with this one.
  stopWalletHostPairingRelay();
  walletHostPairing = {
    uuid,
    brandLabel,
    pollHandle: window.setInterval(() => {
      void runWalletHostInboxTick();
    }, WALLET_HOST_PAIRING_INBOX_INTERVAL_MS),
    bannerShown: false,
    fatal: false,
  };
  // Surface a persistent banner so the user knows to keep the tab open.
  pushToast(
    'pending',
    t('Stay on this tab'),
    t('Signing for the desktop is routed through this browser tab. Closing it interrupts pending signatures.'),
  );
  // Wire the global unload cleanup so a stale interval doesn't survive.
  window.addEventListener('beforeunload', stopWalletHostPairingRelay, { once: true });
}

function stopWalletHostPairingRelay(): void {
  if (walletHostPairing?.pollHandle !== null && walletHostPairing?.pollHandle !== undefined) {
    window.clearInterval(walletHostPairing.pollHandle);
  }
  walletHostPairing = null;
}

async function runWalletHostInboxTick(): Promise<void> {
  const pairing = walletHostPairing;
  if (!pairing || pairing.fatal) return;
  let response: Response;
  try {
    response = await fetch(pairingRelayUrl(`/api/pair/${encodeURIComponent(pairing.uuid)}/inbox`), {
      method: 'GET',
      headers: { accept: 'application/json' },
    });
  } catch (err) {
    console.warn('[pairing-relay] inbox fetch failed', err);
    return;
  }
  if (!response.ok) {
    if (response.status === 404 || response.status === 410) {
      // Pairing record gone (TTL expired or revoked) — stop the loop.
      pairing.fatal = true;
      stopWalletHostPairingRelay();
    }
    return;
  }
  const payload = (await response.json().catch(() => null)) as
    | { requests?: Array<{ requestId: string; request: SigningRequest }> }
    | null;
  if (!payload?.requests || payload.requests.length === 0) return;
  for (const entry of payload.requests) {
    void resolveWalletHostInboxEntry(pairing.uuid, entry.requestId, entry.request).catch((err) => {
      console.warn('[pairing-relay] wallet-host inbox entry failed', err);
    });
  }
}

async function resolveWalletHostInboxEntry(
  pairingUuid: string,
  requestId: string,
  request: SigningRequest,
): Promise<void> {
  if (!walletBackend || !client) {
    await postPairingResult(pairingUuid, requestId, rejectedApprovalResource(
      requestId,
      'wallet_unreachable',
      'Wallet not connected on this tab.',
    ));
    return;
  }
  let approval: ApprovalResource | null = null;
  try {
    approval = await walletBackend.submit(request);
  } catch (err) {
    await postPairingResult(pairingUuid, requestId, rejectedApprovalResource(
      requestId,
      protocolErrorPayload(err).code,
      protocolErrorPayload(err).message,
    ));
    return;
  }
  // The submit may resolve immediately (most browser-wallet adapters) or
  // return a pending approval that needs polling. Walk the poll until we
  // get a terminal status.
  const startedAt = Date.now();
  const POLL_TIMEOUT_MS = 60_000;
  while (approval && approval.status === 'pending' && Date.now() - startedAt < POLL_TIMEOUT_MS) {
    await new Promise((resolve) => window.setTimeout(resolve, 500));
    if (!walletBackend) return;
    try {
      approval = await walletBackend.poll(approval.requestId);
    } catch (err) {
      await postPairingResult(pairingUuid, requestId, rejectedApprovalResource(
        requestId,
        protocolErrorPayload(err).code,
        protocolErrorPayload(err).message,
      ));
      return;
    }
  }
  if (!approval) return;
  // Override the requestId with the relay's UUID so the desktop can match.
  await postPairingResult(pairingUuid, requestId, { ...approval, requestId });
}

function rejectedApprovalResource(
  requestId: string,
  code: string,
  message: string,
): ApprovalResource {
  return {
    requestId: requestId as ApprovalResource['requestId'],
    status: 'rejected',
    error: {
      code: code as ProtocolErrorPayload['code'],
      message,
      recoverable: false,
    },
  };
}

async function postPairingResult(
  pairingUuid: string,
  requestId: string,
  payload: ApprovalResource,
): Promise<void> {
  try {
    const response = await fetch(pairingRelayUrl(`/api/pair/${encodeURIComponent(pairingUuid)}/inbox/${encodeURIComponent(requestId)}`), {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!response.ok) {
      throw new Error(`Pairing relay returned ${response.status} while delivering the wallet result.`);
    }
  } catch (err) {
    console.warn('[pairing-relay] POST inbox result failed', err);
    throw err;
  }
}

async function deliverQrConnectResult(
  session: EncryptedDeeplinkSessionRecord,
  requestId: string,
  payload: ApprovalResource,
): Promise<boolean> {
  try {
    await postPairingResult(session.pairing, requestId, payload);
    clearQrConnectPendingRequest(session.pairing, requestId);
    clearQrConnectActiveSign(session.pairing);
    qrConnect.retryPayload = null;
    return true;
  } catch (err) {
    qrConnect.mode = 'error';
    qrConnect.wallet = session.wallet;
    qrConnect.pairing = session.pairing;
    qrConnect.requestId = requestId;
    qrConnect.walletUrl = '';
    qrConnect.retryPayload = payload;
    qrConnect.message = t('Could not deliver wallet approval.');
    qrConnect.detail = err instanceof Error
      ? tf('{message} Tap Retry to send the wallet result again.', { message: err.message })
      : t('Tap Retry to send the wallet result again.');
    render();
    return false;
  }
}

async function retryQrConnectResultDelivery(): Promise<void> {
  const payload = qrConnect.retryPayload;
  const pairing = qrConnect.pairing;
  const requestId = qrConnect.requestId;
  if (!payload || !pairing || !requestId) return;
  const session = loadQrConnectSession(pairing);
  if (!session) {
    setQrConnectError(t('Agentic pairing expired.'), t('Return to Agentic and scan a fresh QR code.'));
    return;
  }
  setQrConnectProcessing(session.wallet, pairing, t('Retrying wallet approval delivery.'), t('Sending the signed result back to Agentic.'));
  if (await deliverQrConnectResult(session, requestId, payload)) {
    startQrConnectRelay(session, 'relay-active');
  }
}

function protocolErrorPayload(err: unknown): { code: string; message: string } {
  if (err instanceof ProtocolError) {
    return { code: err.code, message: err.message };
  }
  if (err instanceof Error) {
    return { code: 'wallet_unreachable', message: err.message };
  }
  return { code: 'wallet_unreachable', message: String(err) };
}

// ─── Phantom / Solflare QR deeplink relay page ──────────────────────────

type QrConnectMode =
  | 'processing'
  | 'connected'
  | 'relay-active'
  | 'opening-wallet'
  | 'error';

interface QrConnectRuntime {
  mode: QrConnectMode;
  wallet: EncryptedDeeplinkWalletId | null;
  pairing: string;
  requestId: string;
  message: string;
  detail: string;
  walletUrl: string;
  lastHandledUrl: string;
  pollHandle: number | null;
  consecutiveInboxFailures: number;
  retryPayload: ApprovalResource | null;
}

interface PairingDeeplinkMetadata {
  wallet: EncryptedDeeplinkWalletId;
  cluster: Cluster;
  appUrl: string;
  dappPublicKey: string;
  dappSecretKey: string;
}

const QR_CONNECT_SESSION_STORAGE_PREFIX = 'agentic-qr-connect-session:';
const QR_CONNECT_PENDING_STORAGE_PREFIX = 'agentic-qr-connect-pending:';
const QR_CONNECT_ACTIVE_SESSION_STORAGE_KEY = 'agentic-qr-connect-active-session';
// Pointer-by-pairing fallback so we can still match the wallet's signed
// response when the wallet drops our `requestId` query param during the
// redirect_link round-trip. Observed on Solflare's Android signTransaction
// callback (other params survive, requestId — the last one in our URL —
// gets dropped); fallback covers the same risk on any future wallet that
// rebuilds the redirect URL instead of appending to it.
const QR_CONNECT_ACTIVE_SIGN_STORAGE_PREFIX = 'agentic-qr-connect-active-sign:';
const QR_CONNECT_ACTIVE_SIGN_TTL_MS = 10 * 60 * 1000;
const QR_CONNECT_SESSION_TTL_MS = 30 * 60 * 1000;
const QR_CONNECT_PENDING_TTL_MS = 10 * 60 * 1000;

const qrConnect: QrConnectRuntime = {
  mode: 'processing',
  wallet: null,
  pairing: '',
  requestId: '',
  message: 'Preparing wallet connection.',
  detail: 'Checking the encrypted wallet response.',
  walletUrl: '',
  lastHandledUrl: '',
  pollHandle: null,
  consecutiveInboxFailures: 0,
  retryPayload: null,
};

function scheduleQrConnectRoute(): void {
  if (currentRoute() !== '/qr-connect') return;
  window.queueMicrotask(() => {
    void startQrConnectRoute();
  });
}

async function startQrConnectRoute(): Promise<void> {
  if (currentRoute() !== '/qr-connect') return;
  const href = window.location.href;
  if (qrConnect.lastHandledUrl === href) return;
  qrConnect.lastHandledUrl = href;
  await handleQrConnectRoute(href);
}

async function handleQrConnectRoute(href: string): Promise<void> {
  const parsed = parseQrConnectUrl(href);
  qrConnect.wallet = parsed.wallet;
  qrConnect.pairing = parsed.pairing;
  qrConnect.requestId = parsed.requestId;
  qrConnect.walletUrl = '';
  qrConnect.retryPayload = null;

  if (!parsed.wallet || !parsed.pairing) {
    const session = loadActiveQrConnectSession();
    if (session) {
      qrConnect.wallet = session.wallet;
      qrConnect.pairing = session.pairing;
      qrConnect.requestId = '';
      startQrConnectRelay(session, 'relay-active');
      return;
    }
    stopQrConnectRelay();
    setQrConnectError(
      t('This QR connection link is incomplete.'),
      t('Go back to Agentic and scan a fresh Phantom or Solflare QR code.'),
    );
    return;
  }

  try {
    if (parsed.error) {
      await handleQrConnectWalletError(parsed.pairing, parsed.requestId, parsed.error);
      return;
    }
    if (parsed.phase === 'connect') {
      await handleQrConnectConnectCallback(href, parsed.wallet, parsed.pairing);
      return;
    }
    if (parsed.phase === 'sign') {
      if (!parsed.requestId) {
        console.warn(
          '[qr-connect] redirect missing requestId — falling back to active-sign pointer',
          { queryKeys: parsed.queryKeys, pairing: parsed.pairing, wallet: parsed.wallet },
        );
      }
      await handleQrConnectSignCallback(href, parsed.wallet, parsed.pairing, parsed.requestId);
      return;
    }

    const session = loadQrConnectSession(parsed.pairing);
    if (!session) {
      stopQrConnectRelay();
      setQrConnectError(
        t('No active phone relay session was found.'),
        t('Scan the QR code again from Agentic and approve the wallet Connect prompt.'),
      );
      return;
    }
    startQrConnectRelay(session, 'relay-active');
  } catch (err) {
    stopQrConnectRelay();
    setQrConnectError(
      t('Wallet relay failed.'),
      err instanceof Error ? err.message : String(err),
    );
  }
}

async function handleQrConnectWalletError(
  pairing: string,
  requestId: string,
  error: ProtocolErrorPayload,
): Promise<void> {
  // Same redirect-strip fallback as the success path — wallets that drop
  // requestId on success drop it on rejection too. Pick the active pointer
  // so the desktop still sees a rejection event for the right request.
  const effectiveRequestId = requestId || loadQrConnectActiveSign(pairing) || '';
  const session = loadQrConnectSession(pairing);
  if (effectiveRequestId) {
    const payload = rejectedApprovalFromWalletError(effectiveRequestId, error);
    if (session) {
      if (!await deliverQrConnectResult(session, effectiveRequestId, payload)) return;
    } else {
      await postPairingResult(pairing, effectiveRequestId, payload);
      clearQrConnectPendingRequest(pairing, effectiveRequestId);
      clearQrConnectActiveSign(pairing);
    }
  }
  scrubQrConnectUrl(session?.wallet ?? qrConnect.wallet, pairing);
  if (session) {
    startQrConnectRelay(session, 'relay-active');
    return;
  }
  stopQrConnectRelay();
  setQrConnectError(t('Wallet request rejected.'), error.message);
}

async function handleQrConnectConnectCallback(
  href: string,
  wallet: EncryptedDeeplinkWalletId,
  pairing: string,
): Promise<void> {
  setQrConnectProcessing(wallet, pairing, t('Decrypting wallet approval.'), t('Registering this phone with the Agentic pairing relay.'));
  const metadata = await fetchPairingDeeplinkMetadata(pairing);
  if (metadata.wallet !== wallet) {
    throw new ProtocolError('invalid_request', 'Wallet response does not match this QR wallet.');
  }
  const decrypted = decryptConnectResponse(wallet, href, metadata.dappSecretKey);
  const session: EncryptedDeeplinkSessionRecord = {
    pairing,
    wallet,
    cluster: metadata.cluster,
    address: decrypted.publicKey,
    session: decrypted.session,
    dappPublicKey: metadata.dappPublicKey,
    dappSecretKey: metadata.dappSecretKey,
    walletEncryptionPublicKey: decrypted.walletEncryptionPublicKey,
    sharedSecret: decrypted.sharedSecret,
    createdAt: Date.now(),
  };
  saveQrConnectSession(session);
  await postQrConnectHost(session);
  scrubQrConnectUrl(wallet, pairing);
  startQrConnectRelay(session, 'connected');
}

async function handleQrConnectSignCallback(
  href: string,
  wallet: EncryptedDeeplinkWalletId,
  pairing: string,
  requestId: string,
): Promise<void> {
  // Some wallets (notably Solflare on Android) drop our `requestId` query
  // param from the redirect_link round-trip. Fall back to the pointer we
  // wrote when we opened the wallet — it's keyed by pairing alone and
  // survives the redirect even when query params don't.
  const effectiveRequestId = requestId || loadQrConnectActiveSign(pairing) || '';
  if (!effectiveRequestId) {
    throw new ProtocolError('invalid_request', 'Wallet signing callback is missing requestId.');
  }
  const session = loadQrConnectSession(pairing);
  if (!session || session.wallet !== wallet) {
    throw new ProtocolError('unauthorized', 'This phone relay session expired. Scan the Agentic QR again.');
  }
  setQrConnectProcessing(wallet, pairing, t('Processing wallet approval.'), t('Sending the signed result back to Agentic.'));
  const request = loadQrConnectPendingRequest(pairing, effectiveRequestId);
  if (!request) {
    const err = new ProtocolError('invalid_request', 'No matching Agentic signing request was found on this phone.');
    if (!await deliverQrConnectResult(session, effectiveRequestId, deeplinkApprovalResourceFromError(effectiveRequestId, err))) {
      return;
    }
    scrubQrConnectUrl(wallet, pairing);
    startQrConnectRelay(session, 'relay-active');
    return;
  }
  let resultPayload: ApprovalResource;
  try {
    const payload = decryptSigningResponse(href, session.sharedSecret);
    const approval = await resolveSigningPayload({
      wallet,
      request,
      payload,
      sendRawTransaction: async (transaction) => sendQrConnectRawTransaction(session.cluster, transaction),
    });
    resultPayload = { ...approval, requestId: effectiveRequestId };
  } catch (err) {
    resultPayload = deeplinkApprovalResourceFromError(effectiveRequestId, err);
  }
  if (!await deliverQrConnectResult(session, effectiveRequestId, resultPayload)) return;
  scrubQrConnectUrl(wallet, pairing);
  startQrConnectRelay(session, 'relay-active');
}

function setQrConnectProcessing(
  wallet: EncryptedDeeplinkWalletId | null,
  pairing: string,
  message: string,
  detail: string,
): void {
  qrConnect.mode = 'processing';
  qrConnect.wallet = wallet;
  qrConnect.pairing = pairing;
  qrConnect.message = message;
  qrConnect.detail = detail;
  qrConnect.walletUrl = '';
  qrConnect.retryPayload = null;
  render();
}

function setQrConnectError(message: string, detail: string): void {
  qrConnect.mode = 'error';
  qrConnect.message = message;
  qrConnect.detail = detail;
  qrConnect.walletUrl = '';
  render();
}

function startQrConnectRelay(
  session: EncryptedDeeplinkSessionRecord,
  mode: Extract<QrConnectMode, 'connected' | 'relay-active'>,
): void {
  stopQrConnectRelay();
  qrConnect.mode = mode;
  qrConnect.wallet = session.wallet;
  qrConnect.pairing = session.pairing;
  qrConnect.requestId = '';
  qrConnect.walletUrl = '';
  qrConnect.consecutiveInboxFailures = 0;
  qrConnect.retryPayload = null;
  qrConnect.message =
    mode === 'connected'
      ? t('Connection successful. Signing into Agentic.')
      : t('Keep this page open to approve Agentic requests.');
  qrConnect.detail =
    mode === 'connected'
      ? t('Agentic will switch to the connected wallet shortly.')
      : t('When Agentic asks for a signature, this page will open your wallet for approval.');
  qrConnect.pollHandle = window.setInterval(() => {
    void runQrConnectInboxTick(session);
  }, WALLET_HOST_PAIRING_INBOX_INTERVAL_MS);
  void runQrConnectInboxTick(session);
  if (mode === 'connected') {
    window.setTimeout(() => {
      if (qrConnect.mode !== 'connected' || qrConnect.pairing !== session.pairing) return;
      qrConnect.mode = 'relay-active';
      qrConnect.message = t('Keep this page open to approve Agentic requests.');
      qrConnect.detail = t('When Agentic asks for a signature, this page will open your wallet for approval.');
      render();
    }, 1600);
  }
  window.addEventListener('beforeunload', stopQrConnectRelay, { once: true });
  render();
}

function stopQrConnectRelay(): void {
  if (qrConnect.pollHandle !== null) {
    window.clearInterval(qrConnect.pollHandle);
    qrConnect.pollHandle = null;
  }
}

async function runQrConnectInboxTick(session: EncryptedDeeplinkSessionRecord): Promise<void> {
  if (qrConnect.pairing !== session.pairing) return;
  let response: Response;
  try {
    response = await fetch(pairingRelayUrl(`/api/pair/${encodeURIComponent(session.pairing)}/inbox`), {
      method: 'GET',
      headers: { accept: 'application/json' },
    });
  } catch (err) {
    console.warn('[qr-connect] inbox fetch failed', err);
    qrConnect.consecutiveInboxFailures += 1;
    if (qrConnect.consecutiveInboxFailures >= 2) {
      qrConnect.detail = t('Reconnecting to the pairing relay. Keep this page open; it will retry automatically.');
      render();
    }
    return;
  }
  qrConnect.consecutiveInboxFailures = 0;
  if (!response.ok) {
    if (response.status === 404 || response.status === 410) {
      stopQrConnectRelay();
      clearQrConnectSession(session.pairing);
      setQrConnectError(t('Agentic pairing expired.'), t('Return to Agentic and scan a fresh QR code.'));
    } else if (response.status === 429) {
      qrConnect.detail = t('The pairing relay is rate limiting this phone. Keep this page open; it will retry automatically.');
      render();
    }
    return;
  }
  const payload = (await response.json().catch(() => null)) as
    | { requests?: Array<{ requestId: string; request: SigningRequest }> }
    | null;
  const entry = payload?.requests?.[0];
  if (!entry) return;
  await openQrConnectWalletForRequest(session, entry.requestId, entry.request);
}

async function openQrConnectWalletForRequest(
  session: EncryptedDeeplinkSessionRecord,
  requestId: string,
  request: SigningRequest,
): Promise<void> {
  try {
    saveQrConnectPendingRequest(session.pairing, requestId, request);
    saveQrConnectActiveSign(session.pairing, requestId);
    qrConnect.mode = 'opening-wallet';
    qrConnect.wallet = session.wallet;
    qrConnect.pairing = session.pairing;
    qrConnect.requestId = requestId;
    qrConnect.walletUrl = '';
    qrConnect.message = tf('Opening {wallet} approval.', { wallet: qrConnectWalletLabel(session.wallet) });
    qrConnect.detail = t('If this page is running inside the wallet browser, the approval prompt should appear here.');
    render();

    const injectedApproval = await approveWithInjectedWallet({
      wallet: session.wallet,
      sessionAddress: session.address,
      request,
      sendRawTransaction: async (transaction) => sendQrConnectRawTransaction(session.cluster, transaction),
    });
    if (injectedApproval) {
      if (!await deliverQrConnectResult(session, requestId, { ...injectedApproval, requestId })) return;
      startQrConnectRelay(session, 'relay-active');
      return;
    }

    const redirect = new URL('/qr-connect', window.location.origin);
    redirect.searchParams.set('wallet', session.wallet);
    redirect.searchParams.set('pairing', session.pairing);
    redirect.searchParams.set('phase', 'sign');
    redirect.searchParams.set('requestId', requestId);
    const httpsWalletUrl = buildSigningUrlForRequest({
      session,
      request,
      redirectLink: redirect.toString(),
    });
    // On Android, the HTTPS universal link is unreliable for `/ul/v1/sign*`
    // paths even after the user taps — Solflare's App Link verification
    // routes `/ul/v1/connect` to the app but lets `/ul/v1/signTransaction`
    // fall through to the browser, which then offers a Play Store install.
    // Switching to an `intent://` URI on Android tells the OS to launch the
    // wallet package directly via Intent resolution, bypassing App Links
    // entirely; if the wallet is not installed Chrome falls back to the
    // HTTPS link automatically.
    const walletUrl = state.mwaEnvironment.isAndroid
      ? buildAndroidWalletIntentUrl(session.wallet, httpsWalletUrl)
      : httpsWalletUrl;
    qrConnect.walletUrl = walletUrl;
    qrConnect.message = tf('Tap to approve in {wallet}.', { wallet: qrConnectWalletLabel(session.wallet) });
    // Android Chrome only fires App Links on navigations that carry a user
    // activation. The relay receives sign requests by background poll, so
    // any JS-initiated `location.assign` to the wallet URL here is treated
    // as a non-gesture nav and falls through to a normal web load — the
    // wallet's universal-link page then renders the Play Store install
    // prompt. Letting the user tap the rendered button below preserves the
    // gesture and lets the OS route the deeplink to the wallet app.
    qrConnect.detail = t('Tap the button below. Your wallet will open with the request to approve, then return you here automatically.');
    render();
  } catch (err) {
    if (!await deliverQrConnectResult(
      session,
      requestId,
      deeplinkApprovalResourceFromError(requestId, err),
    )) return;
    startQrConnectRelay(session, 'relay-active');
  }
}

async function fetchPairingDeeplinkMetadata(pairing: string): Promise<PairingDeeplinkMetadata> {
  const response = await fetch(pairingRelayUrl(`/api/pair/${encodeURIComponent(pairing)}/deeplink`), {
    method: 'GET',
    headers: { accept: 'application/json' },
  });
  const payload = (await response.json().catch(() => null)) as unknown;
  if (!response.ok) {
    throw new ProtocolError('wallet_unreachable', `Pairing relay returned ${response.status} while reading deeplink metadata.`);
  }
  if (!isPairingDeeplinkMetadata(payload)) {
    throw new ProtocolError('invalid_request', 'Pairing relay returned malformed deeplink metadata.');
  }
  return payload;
}

async function postQrConnectHost(session: EncryptedDeeplinkSessionRecord): Promise<void> {
  const response = await fetch(pairingRelayUrl(`/api/pair/${encodeURIComponent(session.pairing)}/host`), {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      address: session.address,
      walletName: `${qrConnectWalletLabel(session.wallet)} mobile`,
      capabilities: {
        backend: 'remote-relay-deeplink',
        cluster: [session.cluster],
        supports: {
          signMessage: false,
          signTransaction: true,
          signAndSendTransaction: true,
          multiSign: false,
          simulationPreview: false,
        },
        address: session.address,
      } satisfies AdapterCapabilities,
    }),
  });
  if (!response.ok) {
    throw new ProtocolError('wallet_unreachable', `Pairing relay returned ${response.status} while registering the phone.`);
  }
}

async function sendQrConnectRawTransaction(cluster: Cluster, transaction: Uint8Array): Promise<string> {
  const connection = new Connection(defaultRpcUrl(cluster), 'confirmed');
  const txid = await connection.sendRawTransaction(transaction, {
    preflightCommitment: 'confirmed',
    maxRetries: 3,
  });
  await connection.confirmTransaction(txid, 'confirmed');
  return txid;
}

function saveQrConnectSession(session: EncryptedDeeplinkSessionRecord): void {
  writeQrConnectStorage(qrConnectSessionStorageKey(session.pairing), JSON.stringify(session));
  writeQrConnectStorage(QR_CONNECT_ACTIVE_SESSION_STORAGE_KEY, JSON.stringify({
    pairing: session.pairing,
    ts: Date.now(),
  }));
}

function clearQrConnectSession(pairing: string): void {
  removeQrConnectStorage(qrConnectSessionStorageKey(pairing));
  const active = loadQrConnectActivePairing();
  if (active === pairing) {
    removeQrConnectStorage(QR_CONNECT_ACTIVE_SESSION_STORAGE_KEY);
  }
}

function loadQrConnectSession(pairing: string): EncryptedDeeplinkSessionRecord | null {
  const key = qrConnectSessionStorageKey(pairing);
  const raw = readQrConnectStorage(key);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!isQrConnectSessionRecord(parsed)) return null;
    if (Date.now() - parsed.createdAt > QR_CONNECT_SESSION_TTL_MS) {
      removeQrConnectStorage(key);
      return null;
    }
    return parsed;
  } catch {
    return null;
  }
}

function loadActiveQrConnectSession(): EncryptedDeeplinkSessionRecord | null {
  const pairing = loadQrConnectActivePairing();
  return pairing ? loadQrConnectSession(pairing) : null;
}

function loadQrConnectActivePairing(): string | null {
  const raw = readQrConnectStorage(QR_CONNECT_ACTIVE_SESSION_STORAGE_KEY);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as { pairing?: unknown; ts?: unknown };
    if (typeof parsed.pairing !== 'string') return null;
    const pairing = parsed.pairing.trim();
    if (!pairing) return null;
    const ts = typeof parsed.ts === 'number' ? parsed.ts : 0;
    if (Date.now() - ts > QR_CONNECT_SESSION_TTL_MS) {
      removeQrConnectStorage(QR_CONNECT_ACTIVE_SESSION_STORAGE_KEY);
      return null;
    }
    return pairing;
  } catch {
    return null;
  }
}

function saveQrConnectPendingRequest(pairing: string, requestId: string, request: SigningRequest): void {
  writeQrConnectStorage(
    qrConnectPendingStorageKey(pairing, requestId),
    JSON.stringify({ request, ts: Date.now() }),
  );
}

function loadQrConnectPendingRequest(pairing: string, requestId: string): SigningRequest | null {
  const key = qrConnectPendingStorageKey(pairing, requestId);
  const raw = readQrConnectStorage(key);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (isSigningRequest(parsed)) return parsed;
    if (parsed && typeof parsed === 'object') {
      const record = parsed as { request?: unknown; ts?: unknown };
      const ts = typeof record.ts === 'number' ? record.ts : 0;
      if (Date.now() - ts > QR_CONNECT_PENDING_TTL_MS) {
        removeQrConnectStorage(key);
        return null;
      }
      return isSigningRequest(record.request) ? record.request : null;
    }
    return null;
  } catch {
    return null;
  }
}

function clearQrConnectPendingRequest(pairing: string, requestId: string): void {
  removeQrConnectStorage(qrConnectPendingStorageKey(pairing, requestId));
}

function qrConnectSessionStorageKey(pairing: string): string {
  return `${QR_CONNECT_SESSION_STORAGE_PREFIX}${pairing}`;
}

function qrConnectPendingStorageKey(pairing: string, requestId: string): string {
  return `${QR_CONNECT_PENDING_STORAGE_PREFIX}${pairing}:${requestId}`;
}

function qrConnectActiveSignStorageKey(pairing: string): string {
  return `${QR_CONNECT_ACTIVE_SIGN_STORAGE_PREFIX}${pairing}`;
}

function saveQrConnectActiveSign(pairing: string, requestId: string): void {
  writeQrConnectStorage(
    qrConnectActiveSignStorageKey(pairing),
    JSON.stringify({ requestId, ts: Date.now() }),
  );
}

function loadQrConnectActiveSign(pairing: string): string | null {
  const key = qrConnectActiveSignStorageKey(pairing);
  const raw = readQrConnectStorage(key);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as { requestId?: unknown; ts?: unknown };
    if (typeof parsed.requestId !== 'string') return null;
    const requestId = parsed.requestId.trim();
    if (!requestId) return null;
    const ts = typeof parsed.ts === 'number' ? parsed.ts : 0;
    if (Date.now() - ts > QR_CONNECT_ACTIVE_SIGN_TTL_MS) {
      removeQrConnectStorage(key);
      return null;
    }
    return requestId;
  } catch {
    return null;
  }
}

function clearQrConnectActiveSign(pairing: string): void {
  removeQrConnectStorage(qrConnectActiveSignStorageKey(pairing));
}

function readQrConnectStorage(key: string): string | null {
  // Wallet deeplink callbacks can return in a fresh browser tab/context. Keep
  // sessionStorage as the primary short-lived store, with localStorage as a
  // same-origin cross-tab fallback for Phantom/Solflare redirect round-trips.
  for (const store of qrConnectStorageTargets()) {
    try {
      const value = store.getItem(key);
      if (value) return value;
    } catch {
      // Ignore blocked storage and try the next target.
    }
  }
  return null;
}

function writeQrConnectStorage(key: string, value: string): void {
  for (const store of qrConnectStorageTargets()) {
    try {
      store.setItem(key, value);
    } catch {
      // Best-effort only; the paired relay can fall back to the next store.
    }
  }
}

function removeQrConnectStorage(key: string): void {
  for (const store of qrConnectStorageTargets()) {
    try {
      store.removeItem(key);
    } catch {
      // Ignore blocked storage.
    }
  }
}

function qrConnectStorageTargets(): Storage[] {
  const stores: Storage[] = [];
  try {
    if (window.sessionStorage) stores.push(window.sessionStorage);
  } catch {
    // Ignore blocked storage.
  }
  try {
    if (window.localStorage) stores.push(window.localStorage);
  } catch {
    // Ignore blocked storage.
  }
  return stores;
}

function scrubQrConnectUrl(wallet: EncryptedDeeplinkWalletId | null, pairing: string): void {
  if (!wallet || !pairing) return;
  const url = new URL('/qr-connect', window.location.origin);
  url.searchParams.set('relay', 'active');
  window.history.replaceState({}, '', url.toString());
  qrConnect.lastHandledUrl = window.location.href;
}

function qrConnectWalletLabel(wallet: EncryptedDeeplinkWalletId | null): string {
  if (wallet === 'phantom') return 'Phantom';
  if (wallet === 'solflare') return 'Solflare';
  return 'wallet';
}

function resetQrConnectSession(): void {
  const pairing = qrConnect.pairing || loadQrConnectActivePairing() || '';
  if (pairing) {
    clearQrConnectSession(pairing);
    const activeRequest = loadQrConnectActiveSign(pairing);
    if (activeRequest) {
      clearQrConnectPendingRequest(pairing, activeRequest);
      clearQrConnectActiveSign(pairing);
    }
  }
  removeQrConnectStorage(QR_CONNECT_ACTIVE_SESSION_STORAGE_KEY);
  stopQrConnectRelay();
  qrConnect.mode = 'error';
  qrConnect.wallet = null;
  qrConnect.pairing = '';
  qrConnect.requestId = '';
  qrConnect.message = t('QR relay reset.');
  qrConnect.detail = t('Return to Agentic and scan a fresh Phantom or Solflare QR code.');
  qrConnect.walletUrl = '';
  qrConnect.retryPayload = null;
  window.history.replaceState({}, '', new URL('/qr-connect', window.location.origin).toString());
  qrConnect.lastHandledUrl = window.location.href;
  render();
}

function bindQrConnectPage(): void {
  if (currentRoute() !== '/qr-connect') return;
  for (const el of document.querySelectorAll<HTMLElement>('[data-qr-connect-action]')) {
    bindOnce(el, 'click', (event) => {
      const action = el.dataset.qrConnectAction;
      if (action === 'retry-delivery') {
        event.preventDefault();
        void retryQrConnectResultDelivery();
        return;
      }
      if (action === 'start-over') {
        event.preventDefault();
        resetQrConnectSession();
      }
    });
  }
}

function isPairingDeeplinkMetadata(value: unknown): value is PairingDeeplinkMetadata {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  return (
    (record.wallet === 'phantom' || record.wallet === 'solflare') &&
    isQrConnectCluster(record.cluster) &&
    typeof record.appUrl === 'string' &&
    typeof record.dappPublicKey === 'string' &&
    typeof record.dappSecretKey === 'string'
  );
}

function isQrConnectSessionRecord(value: unknown): value is EncryptedDeeplinkSessionRecord {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  return (
    (record.wallet === 'phantom' || record.wallet === 'solflare') &&
    isQrConnectCluster(record.cluster) &&
    typeof record.pairing === 'string' &&
    typeof record.address === 'string' &&
    typeof record.session === 'string' &&
    typeof record.dappPublicKey === 'string' &&
    typeof record.dappSecretKey === 'string' &&
    typeof record.walletEncryptionPublicKey === 'string' &&
    typeof record.sharedSecret === 'string' &&
    typeof record.createdAt === 'number'
  );
}

function isSigningRequest(value: unknown): value is SigningRequest {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  const payload = record.payload as Record<string, unknown> | undefined;
  return (
    typeof record.id === 'string' &&
    (record.kind === 'sign_message' || record.kind === 'sign_transaction' || record.kind === 'sign_and_send_transaction') &&
    isQrConnectCluster(record.cluster) &&
    Boolean(payload) &&
    typeof payload?.data === 'string' &&
    (payload?.encoding === 'utf8' || payload?.encoding === 'base64')
  );
}

function isQrConnectCluster(value: unknown): value is Cluster {
  return value === 'mainnet-beta' || value === 'testnet' || value === 'devnet' || value === 'localnet';
}

function qrConnectPage(): string {
  const wallet = qrConnect.wallet;
  const label = qrConnectWalletLabel(wallet);
  const message = qrConnect.message === 'Preparing wallet connection.'
    ? t('Preparing wallet connection.')
    : qrConnect.message;
  const detail = qrConnect.detail === 'Checking the encrypted wallet response.'
    ? t('Checking the encrypted wallet response.')
    : qrConnect.detail;
  const logoMarkup = wallet
    ? brandLogoMarkup(wallet, 'qr-connect-logo')
    : `<span class="qr-connect-logo placeholder" aria-hidden="true"></span>`;
  const tone = qrConnect.mode === 'error' ? 'error' : qrConnect.mode === 'opening-wallet' ? 'pending' : 'success';
  const action = qrConnect.walletUrl
    ? `<a class="button-link qr-connect-open-wallet" href="${escapeHtml(qrConnect.walletUrl)}" data-qr-connect-open-wallet>${escapeHtml(tf('Open {brand}', { brand: label }))}</a>`
    : '';
  const retryAction = qrConnect.retryPayload
    ? `<button type="button" class="primary" data-qr-connect-action="retry-delivery">${t('Retry delivery')}</button>`
    : '';
  return `
    <main class="qr-connect-page">
      <section class="qr-connect-card ${tone}" aria-live="polite">
        ${logoMarkup}
        <p class="eyebrow mini">${escapeHtml(tf('{brand} QR relay', { brand: label }))}</p>
        <h1>${escapeHtml(message)}</h1>
        <p>${escapeHtml(detail)}</p>
        ${qrConnect.mode === 'processing' || qrConnect.mode === 'opening-wallet'
          ? '<span class="desktop-connect-flow-spinner qr-connect-spinner" aria-hidden="true"></span>'
          : ''}
        ${action}
        ${retryAction}
        ${qrConnect.mode === 'relay-active'
          ? `<p class="qr-connect-warning">${escapeHtml(t('Closing or leaving this page stops signing until you scan again.'))}</p>`
          : ''}
        ${qrConnect.mode === 'relay-active' || qrConnect.mode === 'error'
          ? `<button type="button" class="utility qr-connect-reset" data-qr-connect-action="start-over">${t('Start over')}</button>`
          : ''}
      </section>
    </main>
  `;
}

/** Retry handler for the wallet-host opening splash's error state. The
 *  user might have just installed the extension; re-run the auto-connect
 *  to pick up the late registration. */
function handleWalletHostRetry(): void {
  const opening = state.walletHostOpening;
  if (!opening || opening.status !== 'error') return;
  // Refresh the wallet list in case the extension registered between the
  // 5s timeout and the user clicking Retry.
  try {
    state.wallets = visibleBrowserWallets(listAvailableWallets());
  } catch {
    // Discovery error already surfaced by previous attempt.
  }
  state.error = '';
  void runWalletHostBrandAutoConnect(opening.brandId);
}

/** Renders the "Opening <Brand>…" splash inside the wallet rail while
 *  `state.walletHostOpening` is set. Replaces the normal standby content
 *  so the user has a clear status. The error path adds a Retry button. */
function walletHostOpeningSplashHtml(): string {
  const opening = state.walletHostOpening;
  if (!opening) return '';
  const { brandId, brandLabel, status } = opening;
  const logoId = brandId.toLowerCase();
  const logoSrc = (BRAND_LOGOS as Record<string, string | undefined>)[logoId] ?? null;
  const logoMarkup = logoSrc
    ? `<img class="wallet-host-opening-logo" src="${escapeHtml(logoSrc)}" alt="" />`
    : `<span class="wallet-host-opening-logo placeholder" aria-hidden="true"></span>`;
  if (status === 'waiting') {
    return `
      <aside class="panel custody-panel wallet-host-opening-panel" data-layout="app-rail">
        <div class="wallet-host-opening" role="status" aria-live="polite">
          ${logoMarkup}
          <h2>Opening ${escapeHtml(brandLabel)}…</h2>
          <p>Waiting for the ${escapeHtml(brandLabel)} extension to register on this page.</p>
          <span class="desktop-connect-flow-spinner wallet-host-opening-spinner" aria-hidden="true"></span>
          <p class="wallet-host-opening-hint">If a popup didn't appear, make sure ${escapeHtml(brandLabel)} is installed in this browser and unlocked.</p>
        </div>
      </aside>
    `;
  }
  return `
    <aside class="panel custody-panel wallet-host-opening-panel" data-layout="app-rail">
      <div class="wallet-host-opening wallet-host-opening-error" role="alert">
        ${logoMarkup}
        <h2>${escapeHtml(brandLabel)} not detected</h2>
        <p>We waited a few seconds for the ${escapeHtml(brandLabel)} extension to announce itself on this page and didn't see it.</p>
        <p class="wallet-host-opening-hint">Install ${escapeHtml(brandLabel)} from your browser's extension store, unlock it, then click Retry. Or close this tab and pick a different connection method on the desktop.</p>
        <div class="wallet-host-opening-actions">
          <button type="button" class="primary" data-wallet-host-action="retry">${t('Retry')}</button>
        </div>
      </div>
    </aside>
  `;
}

function bindWalletHostOpening(): void {
  if (!state.walletHostOpening) return;
  for (const el of document.querySelectorAll<HTMLButtonElement>('[data-wallet-host-action="retry"]')) {
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      handleWalletHostRetry();
    });
  }
}

// ─── Embedded Agentic Wallet UI (Slice C) ────────────────────────────────
// Module-level slice rather than a field on `state` to keep this isolated
// from the 200+ field `DemoState`. The overlay state itself is reduced via
// `reduceEmbeddedWalletOverlay`; `ipc` and `pollHandle` are initialized in
// the Tauri branch of bootstrap.

interface EmbeddedWalletRuntime {
  ipc: WalletIpc | null;
  status: WalletStatus | null;
  overlay: EmbeddedWalletOverlayState;
  pollHandle: WalletStatusPollHandle | null;
}

const embeddedWallet: EmbeddedWalletRuntime = {
  ipc: null,
  status: null,
  overlay: initialEmbeddedWalletOverlayState(),
  pollHandle: null,
};

function dispatchEmbeddedWalletOverlay(action: EmbeddedWalletOverlayAction): void {
  embeddedWallet.overlay = reduceEmbeddedWalletOverlay(embeddedWallet.overlay, action);
  render();
}

type DesktopOverlayKind = 'embedded-wallet' | 'walletconnect-qr' | 'ledger';

/**
 * Close any sibling overlays before opening a new one. Slices C / E / G
 * each render a full-screen modal — letting two stack would land a confused
 * user with overlapping passwords / QR codes / Ledger prompts.
 */
function closeSiblingOverlays(except: DesktopOverlayKind): void {
  if (except !== 'embedded-wallet' && embeddedWallet.overlay.mode !== 'closed') {
    dispatchEmbeddedWalletOverlay({ type: 'close' });
  }
  if (except !== 'walletconnect-qr' && walletConnect.overlay.mode !== 'closed') {
    cancelWalletConnectPairing();
  }
  if (except !== 'ledger' && ledger.overlay.mode !== 'closed') {
    stopLedgerPoll();
    ledger.pairingToken += 1;
    dispatchLedgerOverlay({ type: 'close' });
  }
}

function openEmbeddedWalletOverlay(
  mode: Exclude<EmbeddedWalletOverlayMode, 'closed' | 'show-phrase'>,
): void {
  // Idempotent: rapid double-click on the same trigger must not reset the
  // user's in-progress form input. Re-entry while already open is a no-op.
  if (embeddedWallet.overlay.mode !== 'closed') return;
  closeSiblingOverlays('embedded-wallet');
  dispatchEmbeddedWalletOverlay({ type: 'open', mode });
}

async function submitEmbeddedWalletForm(): Promise<void> {
  if (!embeddedWallet.ipc) {
    dispatchEmbeddedWalletOverlay({
      type: 'submitError',
      error: 'Wallet is unavailable on this surface.',
    });
    return;
  }
  const { mode, draft } = embeddedWallet.overlay;
  if (mode === 'create') {
    const check = validateCreate(draft);
    if (!check.ok) {
      dispatchEmbeddedWalletOverlay({ type: 'submitError', error: check.error });
      return;
    }
    dispatchEmbeddedWalletOverlay({ type: 'submitStart' });
    try {
      const result = await embeddedWallet.ipc.create(draft.password);
      dispatchEmbeddedWalletOverlay({
        type: 'submitSuccessCreated',
        mnemonic: result.mnemonic,
      });
    } catch (err) {
      dispatchEmbeddedWalletOverlay({
        type: 'submitError',
        error: err instanceof Error ? err.message : String(err),
      });
    }
    return;
  }
  if (mode === 'import') {
    const check = validateImport(draft);
    if (!check.ok) {
      dispatchEmbeddedWalletOverlay({ type: 'submitError', error: check.error });
      return;
    }
    dispatchEmbeddedWalletOverlay({ type: 'submitStart' });
    try {
      await embeddedWallet.ipc.import(draft.password, draft.mnemonic);
      dispatchEmbeddedWalletOverlay({ type: 'submitSuccessClose' });
      await reconnectAgenticAfterUnlock();
    } catch (err) {
      dispatchEmbeddedWalletOverlay({
        type: 'submitError',
        error: err instanceof Error ? err.message : String(err),
      });
    }
    return;
  }
  if (mode === 'unlock') {
    const check = validateUnlock({ password: draft.password });
    if (!check.ok) {
      dispatchEmbeddedWalletOverlay({ type: 'submitError', error: check.error });
      return;
    }
    dispatchEmbeddedWalletOverlay({ type: 'submitStart' });
    try {
      await embeddedWallet.ipc.unlock(draft.password);
      dispatchEmbeddedWalletOverlay({ type: 'submitSuccessClose' });
      await reconnectAgenticAfterUnlock();
    } catch (err) {
      dispatchEmbeddedWalletOverlay({
        type: 'submitError',
        error: err instanceof Error ? err.message : String(err),
      });
    }
    return;
  }
  if (mode === 'reset-confirm') {
    const check = validateResetConfirm({ password: draft.password });
    if (!check.ok) {
      dispatchEmbeddedWalletOverlay({ type: 'submitError', error: check.error });
      return;
    }
    dispatchEmbeddedWalletOverlay({ type: 'submitStart' });
    try {
      await embeddedWallet.ipc.deleteWallet(draft.password);
      embeddedWallet.status = null;
      dispatchEmbeddedWalletOverlay({ type: 'open', mode: 'create' });
      pushToast('info', t('Wallet reset'), t('Set up a new Agentic Wallet to continue.'));
    } catch (err) {
      dispatchEmbeddedWalletOverlay({
        type: 'submitError',
        error: err instanceof Error ? err.message : String(err),
      });
    }
  }
}

function stopEmbeddedWalletPoll(): void {
  if (embeddedWallet.pollHandle) {
    embeddedWallet.pollHandle.stop();
    embeddedWallet.pollHandle = null;
  }
}

async function reconnectAgenticAfterUnlock(): Promise<void> {
  // After successful create/import/unlock, kick off the regular connect flow.
  // It will now find `wallet_status.unlocked === true` and fall through to
  // the normal Wallet Standard path.
  state.selectedWalletName = AGENTIC_WALLET_NAME;
  await runConnect();
}

function handleEmbeddedWalletAction(action: string | undefined): void {
  if (!action) return;
  switch (action) {
    case 'close':
      dispatchEmbeddedWalletOverlay({ type: 'close' });
      return;
    case 'toggle-phrase-revealed':
      dispatchEmbeddedWalletOverlay({ type: 'togglePhraseRevealed' });
      return;
    case 'copy-phrase':
      void copyEmbeddedWalletPhrase();
      return;
    case 'phrase-continue':
      if (!embeddedWallet.overlay.phraseSavedAcknowledged) return;
      dispatchEmbeddedWalletOverlay({ type: 'submitSuccessClose' });
      void reconnectAgenticAfterUnlock();
      return;
    case 'open-reset':
      dispatchEmbeddedWalletOverlay({ type: 'open', mode: 'reset-confirm' });
      return;
    default:
      // Tab toggles + checkbox toggles are handled by their dedicated
      // dataset attributes in `bind()`.
      return;
  }
}

async function copyEmbeddedWalletPhrase(): Promise<void> {
  const phrase = embeddedWallet.overlay.createdMnemonic;
  if (!phrase) return;
  try {
    await navigator.clipboard.writeText(phrase);
    pushToast('success', t('Phrase copied'), t('Paste it into your password manager and clear the clipboard after.'));
  } catch (err) {
    pushToast(
      'error',
      t('Could not copy phrase'),
      err instanceof Error ? err.message : t('Clipboard access denied.'),
    );
  }
}

function setEmbeddedWalletField(
  name: string,
  value: string,
): void {
  if (name !== 'password' && name !== 'confirm' && name !== 'mnemonic') return;
  // Mutate without re-rendering on every keystroke; the next render picks it
  // up. (We still rerender on errors via dispatchEmbeddedWalletOverlay.)
  embeddedWallet.overlay = reduceEmbeddedWalletOverlay(embeddedWallet.overlay, {
    type: 'setField',
    name: name as keyof EmbeddedWalletOverlayDraft,
    value,
  });
}

function setEmbeddedWalletTab(mode: string): void {
  if (mode !== 'create' && mode !== 'import') return;
  dispatchEmbeddedWalletOverlay({ type: 'setTab', mode });
}

function setEmbeddedWalletAcknowledge(checked: boolean): void {
  dispatchEmbeddedWalletOverlay({ type: 'acknowledgePhraseSaved', checked });
}

// ─── Per-brand picker panels (Slice D) ──────────────────────────────────
// Tauri-only "Other wallets" section beneath the existing picker. Each
// brand row offers: Scan QR (disabled until Slice E), Import recovery phrase
// (drives Slice C's overlay), and an opt-in external-browser fallback. The
// external-browser preference is persisted to localStorage.

const DESKTOP_EXTERNAL_BROWSER_PREF_KEY = 'desktop-external-browser-wallet';

const embeddedWalletBrandPanels: DesktopBrandPanelsState = initialDesktopBrandPanelsState();

function hydrateDesktopBrandPanelsPrefs(): void {
  try {
    embeddedWalletBrandPanels.externalBrowserEnabled =
      window.localStorage.getItem(DESKTOP_EXTERNAL_BROWSER_PREF_KEY) === 'true';
  } catch {
    // localStorage may be unavailable in some test runners; keep the default.
  }
}

function persistDesktopBrandPanelsPrefs(): void {
  try {
    window.localStorage.setItem(
      DESKTOP_EXTERNAL_BROWSER_PREF_KEY,
      embeddedWalletBrandPanels.externalBrowserEnabled ? 'true' : 'false',
    );
  } catch {
    // Best-effort persistence.
  }
}

function dispatchDesktopBrandPanels(action: DesktopBrandPanelsAction): void {
  const next = reduceDesktopBrandPanels(embeddedWalletBrandPanels, action);
  embeddedWalletBrandPanels.expanded = next.expanded;
  embeddedWalletBrandPanels.externalBrowserEnabled = next.externalBrowserEnabled;
  if (action.type === 'setExternalBrowserEnabled') {
    persistDesktopBrandPanelsPrefs();
  }
  render();
}

function collapseDesktopBrandPanels(): void {
  if (embeddedWalletBrandPanels.expanded === null) return;
  embeddedWalletBrandPanels.expanded = null;
}

function desktopBrandPanelsBlock(): string {
  if (!state.tauriNativeEnvironment.isTauriNative) return '';
  const ledgerLogoUrl = (BRAND_LOGOS as Record<string, string | undefined>).ledger ?? null;
  return desktopBrandPanelsHtml({
    state: embeddedWalletBrandPanels,
    logoUrl: (logoId) => {
      const url = (BRAND_LOGOS as Record<string, string | undefined>)[logoId];
      return url ?? null;
    },
    scanQrEnabledFor: (brandId) =>
      Boolean(WALLETCONNECT_PROJECT_ID) && isWalletConnectSupportedBrand(brandId),
    hardware: { ledger: { logoUrl: ledgerLogoUrl } },
  });
}

function handleDesktopBrandAction(
  action: string | undefined,
  brandId: string | undefined,
): void {
  if (!action) return;
  switch (action) {
    case 'toggle':
      if (!brandId) return;
      dispatchDesktopBrandPanels({ type: 'togglePanel', brandId });
      return;
    case 'import':
      // Slice C overlay does the actual work; brand id is contextual today
      // (panel just narrows the user's intent). Future polish: pass brand
      // hint to overlay header.
      openEmbeddedWalletOverlay('import');
      return;
    case 'external-browser': {
      collapseDesktopBrandPanels();
      void openDesktopBrowserConnectPage(brandId ?? null);
      return;
    }
    case 'scan-qr':
      if (!brandId) return;
      void handleScanQrForBrand(brandId);
      return;
    case 'connect-ledger':
      openLedgerOverlay();
      return;
    default:
      return;
  }
}

function bindDesktopBrandPanels(): void {
  if (!state.tauriNativeEnvironment.isTauriNative) return;
  // Full renders replace the rail, while workspace morphs preserve nodes.
  // bindOnce keeps this safe on both paths.
  for (const el of document.querySelectorAll<HTMLElement>('[data-desktop-brand-action]')) {
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      handleDesktopBrandAction(
        el.dataset.desktopBrandAction,
        el.dataset.desktopBrandId,
      );
    });
  }
  for (const el of document.querySelectorAll<HTMLInputElement>('[data-desktop-brand-pref]')) {
    bindOnce(el, 'change', () => {
      if (el.dataset.desktopBrandPref !== 'external-browser') return;
      dispatchDesktopBrandPanels({
        type: 'setExternalBrowserEnabled',
        enabled: el.checked,
      });
    });
  }
}

// ─── WalletConnect-Solana QR pairing (Slice E) ──────────────────────────
// Wires the "Scan QR with [brand] mobile" buttons from Slice D's brand
// panels. Lazy-inits a SignClient when the user first clicks scan-qr,
// renders the WC pairing URI as a QR code, and registers a Wallet Standard
// wallet once the session is approved. Sessions persist via WC's own
// localStorage; re-registered on next launch.

const WALLETCONNECT_PROJECT_ID =
  (import.meta as ImportMeta & { env?: { VITE_AGENTIC_WC_PROJECT_ID?: string } }).env
    ?.VITE_AGENTIC_WC_PROJECT_ID ?? '';
const WALLETCONNECT_QR_SETUP_TIMEOUT_MS = 15_000;

const WALLET_CONNECT_BRAND_LOGOS: Record<string, string> = {
  phantom: 'phantom',
  solflare: 'solflare',
  backpack: 'backpack',
  jupiter: 'jupiter',
  magicEden: 'magiceden',
};

const WALLETCONNECT_SESSION_META_STORAGE_KEY = 'agentic-walletconnect-session-meta-v1';

interface PersistedWalletConnectSessionMeta {
  topic: string;
  brandId: string | null;
  peerName: string | null;
  address: string;
  createdAt: number;
}

interface WalletConnectRuntime {
  client: WalletConnectSolanaClient | null;
  initPromise: Promise<WalletConnectSolanaClient> | null;
  overlay: WalletConnectQrOverlayState;
  /** Track the topic/id of the in-flight pairing so stale approvals are ignored. */
  pendingTopic: string | null;
  pendingPairingId: number;
}

const walletConnect: WalletConnectRuntime = {
  client: null,
  initPromise: null,
  overlay: initialWalletConnectQrOverlayState(),
  pendingTopic: null,
  pendingPairingId: 0,
};

function dispatchWalletConnectOverlay(action: WalletConnectQrOverlayAction): void {
  walletConnect.overlay = reduceWalletConnectQrOverlay(walletConnect.overlay, action);
  render();
}

function beginWalletConnectPairing(): number {
  walletConnect.pendingPairingId += 1;
  walletConnect.pendingTopic = null;
  return walletConnect.pendingPairingId;
}

function isActiveWalletConnectPairing(pairingId: number): boolean {
  return walletConnect.pendingPairingId === pairingId && walletConnect.overlay.mode !== 'closed';
}

function cancelWalletConnectPairing(): void {
  walletConnect.pendingPairingId += 1;
  walletConnect.pendingTopic = null;
  dispatchWalletConnectOverlay({ type: 'close' });
}

function walletConnectTopicFromUri(uri: string): string | null {
  const match = /^wc:([^@?#]+)/i.exec(uri.trim());
  return match?.[1] ?? null;
}

function walletConnectSetupTimeoutMessage(phase: string): string {
  return `WalletConnect ${phase} timed out before a QR code was created. Check that the hosted app CSP allows wss: connections and that the Reown project allows this domain.`;
}

async function withWalletConnectQrSetupTimeout<T>(
  promise: Promise<T>,
  phase: string,
): Promise<T> {
  let timeoutId: number | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<never>((_, reject) => {
        timeoutId = window.setTimeout(() => {
          reject(new Error(walletConnectSetupTimeoutMessage(phase)));
        }, WALLETCONNECT_QR_SETUP_TIMEOUT_MS);
      }),
    ]);
  } finally {
    if (timeoutId !== undefined) {
      window.clearTimeout(timeoutId);
    }
  }
}

async function disconnectStaleWalletConnectSession(
  client: WalletConnectSolanaClient,
  session: WalletConnectSession,
): Promise<void> {
  await client.disconnect(session.topic).catch((err) => {
    console.warn('[walletconnect] stale approved session cleanup failed', err);
  });
}

function walletConnectAppMetadata(): {
  name: string;
  description: string;
  url: string;
  icons: string[];
} {
  const origin =
    typeof window !== 'undefined' && window.location
      ? window.location.origin
      : 'https://agentic-signer.com';
  if (!state.tauriNativeEnvironment.isTauriNative) {
    return {
      name: 'Agentic',
      description: 'Solana Agent Wallet Adapter',
      url: origin,
      icons: [],
    };
  }
  return {
    name: 'Agentic Desktop',
    description: 'Solana Agent Wallet Adapter - desktop runtime',
    url: origin,
    icons: [],
  };
}

async function initWalletConnectSignClient(): Promise<SignClientLike> {
  // Dynamic import keeps the WC bundle (and its protobuf/relay deps) out of
  // the initial page load. Only paid when the user first clicks scan-qr.
  const mod = await import('@walletconnect/sign-client');
  const SignClient = (mod as unknown as { default?: { init: (opts: unknown) => Promise<unknown> } })
    .default ?? (mod as unknown as { init: (opts: unknown) => Promise<unknown> });
  const instance = await withWalletConnectQrSetupTimeout(
    SignClient.init({
      projectId: WALLETCONNECT_PROJECT_ID,
      metadata: walletConnectAppMetadata(),
    }),
    'relay startup',
  );
  return instance as SignClientLike;
}

async function ensureWalletConnectClient(): Promise<WalletConnectSolanaClient> {
  if (walletConnect.client) return walletConnect.client;
  if (walletConnect.initPromise) return walletConnect.initPromise;
  if (!WALLETCONNECT_PROJECT_ID) {
    throw new Error('VITE_AGENTIC_WC_PROJECT_ID is not configured.');
  }
  walletConnect.initPromise = (async () => {
    const signClient = await initWalletConnectSignClient();
    const client = createWalletConnectSolanaClient({
      projectId: WALLETCONNECT_PROJECT_ID,
      metadata: walletConnectAppMetadata(),
      signClient,
    });
    // Attach listeners BEFORE caching the client so the cache invariant
    // holds: any caller reading `walletConnect.client` knows the listeners
    // are wired. Without this ordering, a concurrent re-entry between the
    // assignment and the .on() calls would see a clientless of listeners.
    // `session_delete` / `session_expire` mean the WC SignClient has
    // ALREADY torn down its local mapping for `topic`. Calling
    // `client.disconnect(topic)` here would throw "session not found"
    // since the entry is gone. We only unregister our Wallet Standard
    // entry. User-initiated teardown happens via the wallet's
    // `standard:disconnect` feature, which DOES call client.disconnect.
    client.on('session_delete', (topic) => {
      unregisterWalletConnectSolanaWallet(topic);
      clearWalletConnectSessionMeta(topic);
      if (state.selectedWalletName.includes('(mobile)')) {
        traceWalletCleared('walletconnect-session-delete');
        state.address = '';
        render();
      }
    });
    client.on('session_expire', (topic) => {
      unregisterWalletConnectSolanaWallet(topic);
      clearWalletConnectSessionMeta(topic);
    });
    walletConnect.client = client;
    return client;
  })();
  try {
    return await walletConnect.initPromise;
  } finally {
    walletConnect.initPromise = null;
  }
}

function walletConnectChainsForCurrentCluster(): string[] {
  const cluster = state.cluster as SolanaClusterId;
  // Mainnet-only product: the cluster is always mainnet-beta; on any unexpected
  // value fall back to mainnet (never advertise a devnet WalletConnect chain).
  try {
    return [solanaWalletConnectChainId(cluster)];
  } catch {
    return [solanaWalletConnectChainId('mainnet-beta')];
  }
}

function registerBrandSession(brandId: string, session: WalletConnectSession): string {
  const brand = WALLET_CONNECT_BRANDS[brandId];
  if (!brand) throw new Error(`Unsupported WalletConnect brand: ${brandId}`);
  const logoId = WALLET_CONNECT_BRAND_LOGOS[brandId] ?? brandId;
  const iconUrl = (BRAND_LOGOS as Record<string, string | undefined>)[logoId];
  if (!iconUrl) throw new Error(`Missing brand logo for ${brandId}`);
  const walletName = `${brand.name} (mobile)`;
  // The package's `register` is keyed by `brand.id|address` so a re-pair
  // with a new topic but the same address replaces (not duplicates) the
  // previous registration. No parallel map in main.ts needed.
  registerWalletConnectSolanaWallet({
    brand: { id: brandId, name: walletName },
    session,
    client: walletConnect.client!,
    icon: iconUrl as `data:image/svg+xml;base64,${string}`,
  });
  saveWalletConnectSessionMeta({
    topic: session.topic,
    brandId,
    peerName: session.peerName ?? null,
    address: session.address,
    createdAt: Date.now(),
  });
  return walletName;
}

/** Generic 1x1 transparent PNG as a typed `data:image/png;base64,...` URI —
 *  used as a last-resort icon when a WalletConnect peer doesn't advertise
 *  any icons in its metadata. The wallet picker still surfaces the wallet
 *  name and address; the icon slot just falls back to a neutral square. */
const WALLETCONNECT_GENERIC_ICON: `data:image/png;base64,${string}` =
  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=';

/** Register a WC session without pre-binding a brand id. Used by the
 *  desktop's brand-agnostic QR path — the wallet identifies itself via the
 *  session's `peerName`/`peerIcons` (carried through `resolveSession`). */
function registerAnyWalletConnectSession(session: WalletConnectSession): string {
  const peerName = session.peerName?.trim();
  const walletName = peerName ? `${peerName} (mobile)` : 'WalletConnect mobile';
  const peerIcon = session.peerIcons?.find((s) => typeof s === 'string' && s.length > 0);
  // Wallet Standard's `WalletIcon` type expects a `data:` URI; in practice
  // both the runtime and the existing brand-specific path tolerate HTTPS
  // URLs (cast-through). Prefer the peer's advertised icon when present.
  const icon = peerIcon
    ? (peerIcon as `data:image/svg+xml;base64,${string}`)
    : WALLETCONNECT_GENERIC_ICON;
  registerWalletConnectSolanaWallet({
    // Keyed deduplication by `walletconnect-any|address` — repairing the
    // same address (via the same or different mobile wallet) replaces.
    brand: { id: 'walletconnect-any', name: walletName },
    session,
    client: walletConnect.client!,
    icon,
  });
  saveWalletConnectSessionMeta({
    topic: session.topic,
    brandId: null,
    peerName: session.peerName ?? null,
    address: session.address,
    createdAt: Date.now(),
  });
  return walletName;
}

function registerWalletConnectSessionForDisplay(
  session: WalletConnectSession,
  requestedBrandId?: string,
): string {
  const inferredBrandId = inferWalletConnectBrandForSession(session);
  const fallbackBrandId = requestedBrandId && WALLET_CONNECT_BRANDS[requestedBrandId]
    ? requestedBrandId
    : null;
  const brandId = inferredBrandId ?? fallbackBrandId;
  if (brandId && WALLET_CONNECT_BRANDS[brandId]) {
    return registerBrandSession(brandId, session);
  }
  return registerAnyWalletConnectSession(session);
}

function loadWalletConnectSessionMeta(): Record<string, PersistedWalletConnectSessionMeta> {
  try {
    const parsed = JSON.parse(
      window.localStorage.getItem(WALLETCONNECT_SESSION_META_STORAGE_KEY) ?? '{}',
    ) as unknown;
    if (!parsed || typeof parsed !== 'object') return {};
    const out: Record<string, PersistedWalletConnectSessionMeta> = {};
    for (const [topic, value] of Object.entries(parsed as Record<string, unknown>)) {
      if (!value || typeof value !== 'object') continue;
      const record = value as Record<string, unknown>;
      const brandId = record.brandId;
      const peerName = record.peerName;
      if (
        typeof record.topic !== 'string' ||
        record.topic !== topic ||
        (typeof brandId !== 'string' && brandId !== null) ||
        (typeof peerName !== 'string' && peerName !== null) ||
        typeof record.address !== 'string' ||
        typeof record.createdAt !== 'number'
      ) {
        continue;
      }
      out[topic] = {
        topic,
        brandId,
        peerName,
        address: record.address,
        createdAt: record.createdAt,
      };
    }
    return out;
  } catch {
    return {};
  }
}

function saveWalletConnectSessionMeta(meta: PersistedWalletConnectSessionMeta): void {
  try {
    const all = loadWalletConnectSessionMeta();
    all[meta.topic] = meta;
    window.localStorage.setItem(WALLETCONNECT_SESSION_META_STORAGE_KEY, JSON.stringify(all));
  } catch {
    // Best-effort display metadata only; WalletConnect owns the real session.
  }
}

function clearWalletConnectSessionMeta(topic: string): void {
  try {
    const all = loadWalletConnectSessionMeta();
    delete all[topic];
    window.localStorage.setItem(WALLETCONNECT_SESSION_META_STORAGE_KEY, JSON.stringify(all));
  } catch {
    // Best-effort display metadata only.
  }
}

async function handleScanQrForBrand(brandId: string): Promise<void> {
  if (!isWalletConnectSupportedBrand(brandId)) {
    pushToast(
      'pending',
      t('Coming soon'),
      tf('{brand} via WalletConnect ships in a later release.', { brand: brandId }),
    );
    return;
  }
  if (!WALLETCONNECT_PROJECT_ID) {
    pushToast(
      'error',
      t('WalletConnect not configured'),
      tf('Set {envVar} before launching to enable mobile pairing.', { envVar: 'VITE_AGENTIC_WC_PROJECT_ID' }),
    );
    return;
  }
  // Idempotent: don't abandon an in-flight pairing if the user double-taps
  // Scan QR or clicks two brand rows in quick succession.
  if (walletConnect.overlay.mode !== 'closed') return;
  closeSiblingOverlays('walletconnect-qr');
  const pairingId = beginWalletConnectPairing();
  dispatchWalletConnectOverlay({ type: 'openConnecting', brandId });
  try {
    const client = await ensureWalletConnectClient();
    if (!isActiveWalletConnectPairing(pairingId)) return;
    const chains = walletConnectChainsForCurrentCluster();
    const { uri, approval } = await withWalletConnectQrSetupTimeout(
      client.connect({ chains }),
      'pairing request',
    );
    walletConnect.pendingTopic = walletConnectTopicFromUri(uri);
    let qrDataUrl = '';
    try {
      const QRCodeMod = await import('qrcode');
      const generator = (QRCodeMod as { default?: typeof import('qrcode') }).default ?? QRCodeMod;
      qrDataUrl = await generator.toDataURL(uri, {
        errorCorrectionLevel: 'M',
        margin: 2,
        width: 320,
      });
    } catch (err) {
      console.warn('[walletconnect] qrcode generation failed', err);
    }
    if (!isActiveWalletConnectPairing(pairingId)) return;
    dispatchWalletConnectOverlay({ type: 'setUri', uri, qrDataUrl });

    const session = await approval();
    if (!isActiveWalletConnectPairing(pairingId)) {
      await disconnectStaleWalletConnectSession(client, session);
      return;
    }
    dispatchWalletConnectOverlay({ type: 'completing' });
    const walletName = registerBrandSession(brandId, session);
    walletConnect.pendingTopic = null;
    dispatchWalletConnectOverlay({ type: 'close' });
    state.wallets = visibleBrowserWallets(listAvailableWallets());
    state.selectedWalletName = walletName;
    await runConnect();
  } catch (err) {
    if (!isActiveWalletConnectPairing(pairingId)) return;
    const message = err instanceof Error ? err.message : String(err);
    walletConnect.pendingTopic = null;
    dispatchWalletConnectOverlay({ type: 'setError', error: message });
  }
}

function desktopWalletConnectQrPayload(displayBrandId: string | undefined, uri: string): string {
  void displayBrandId;
  return uri;
}

/** Brand-agnostic WalletConnect pairing used by the desktop Discover →
 *  "Scan QR with phone" flow. WalletConnect wallets scan the raw WC URI.
 *  Phantom/Solflare are handled by the encrypted deeplink branch instead. */
async function handleScanQrAnyWallet(displayBrandId?: string): Promise<void> {
  if (!WALLETCONNECT_PROJECT_ID) {
    pushToast(
      'error',
      t('WalletConnect not configured'),
      tf('Set {envVar} before launching to enable mobile pairing.', { envVar: 'VITE_AGENTIC_WC_PROJECT_ID' }),
    );
    return;
  }
  if (walletConnect.overlay.mode !== 'closed') return;
  closeSiblingOverlays('walletconnect-qr');
  const pairingId = beginWalletConnectPairing();
  // `displayBrandId` brands the rendered QR card header (e.g. "Scan with
  // Backpack mobile" + Backpack logo). The approved wallet still identifies
  // itself in `session.peerName` post-approval.
  dispatchWalletConnectOverlay({ type: 'openConnecting', brandId: displayBrandId ?? '' });
  try {
    const client = await ensureWalletConnectClient();
    if (!isActiveWalletConnectPairing(pairingId)) return;
    const chains = walletConnectChainsForCurrentCluster();
    const { uri, approval } = await withWalletConnectQrSetupTimeout(
      client.connect({ chains }),
      'pairing request',
    );
    walletConnect.pendingTopic = walletConnectTopicFromUri(uri);
    const qrPayload = desktopWalletConnectQrPayload(displayBrandId, uri);
    let qrDataUrl = '';
    try {
      const QRCodeMod = await import('qrcode');
      const generator = (QRCodeMod as { default?: typeof import('qrcode') }).default ?? QRCodeMod;
      qrDataUrl = await generator.toDataURL(qrPayload, {
        errorCorrectionLevel: 'M',
        margin: 2,
        width: 320,
      });
    } catch (err) {
      console.warn('[walletconnect] qrcode generation failed', err);
    }
    if (!isActiveWalletConnectPairing(pairingId)) return;
    dispatchWalletConnectOverlay({ type: 'setUri', uri, qrDataUrl });

    const session = await approval();
    if (!isActiveWalletConnectPairing(pairingId)) {
      await disconnectStaleWalletConnectSession(client, session);
      return;
    }
    dispatchWalletConnectOverlay({ type: 'completing' });
    const walletName = registerWalletConnectSessionForDisplay(session, displayBrandId);
    walletConnect.pendingTopic = null;
    dispatchWalletConnectOverlay({ type: 'close' });
    state.wallets = visibleBrowserWallets(listAvailableWallets());
    state.selectedWalletName = walletName;
    await runConnect();
  } catch (err) {
    if (!isActiveWalletConnectPairing(pairingId)) return;
    const message = err instanceof Error ? err.message : String(err);
    walletConnect.pendingTopic = null;
    dispatchWalletConnectOverlay({ type: 'setError', error: message });
  }
}

async function copyWalletConnectUri(): Promise<void> {
  const uri = walletConnect.overlay.uri;
  if (!uri) return;
  try {
    await navigator.clipboard.writeText(uri);
    pushToast('success', t('URI copied'), t('Paste into a WC-compatible wallet.'));
  } catch (err) {
    pushToast(
      'error',
      t('Could not copy'),
      err instanceof Error ? err.message : t('Clipboard access denied.'),
    );
  }
}

function handleWalletConnectOverlayAction(action: string | undefined): void {
  switch (action) {
    case 'cancel':
      cancelWalletConnectPairing();
      return;
    case 'copy-uri':
      void copyWalletConnectUri();
      return;
    case 'open-deeplink':
      // Anchor's default href handles the OS deep-link; nothing to do.
      return;
    default:
      return;
  }
}

function bindWalletConnectOverlay(): void {
  if (walletConnect.overlay.mode === 'closed') return;
  for (const el of document.querySelectorAll<HTMLElement>('[data-walletconnect-action]')) {
    const action = el.dataset.walletconnectAction;
    if (action === 'open-deeplink') continue; // anchor click goes through naturally
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      handleWalletConnectOverlayAction(action);
    });
  }
}

function walletConnectOverlayBlock(): string {
  // The Tauri desktop renders the same state machine inline inside the
  // discover-flow rail, so suppress the modal mount on native to avoid a
  // double-render.
  if (!shouldRenderDetachedWalletConnectOverlay({
    isTauriNative: state.tauriNativeEnvironment.isTauriNative,
    flowStep: desktopConnect.flow.step,
  })) return '';
  return walletConnectQrOverlayHtml({
    state: walletConnect.overlay,
    logoUrl: (logoId) => (BRAND_LOGOS as Record<string, string | undefined>)[logoId] ?? null,
    surface: walletConnectQrSurface(),
    preferDeepLink: preferWalletConnectSameDeviceLaunch(),
  });
}

function walletConnectQrSurface(): 'desktop' | 'website' {
  return state.tauriNativeEnvironment.isTauriNative ? 'desktop' : 'website';
}

function preferWalletConnectSameDeviceLaunch(): boolean {
  if (state.tauriNativeEnvironment.isTauriNative) return false;
  return state.mwaEnvironment.isAndroid || state.mwaEnvironment.isIos || isLikelyMobileWalletDevice();
}

function isLikelyMobileWalletDevice(): boolean {
  if (typeof navigator === 'undefined') return false;
  const ua = navigator.userAgent || '';
  if (/Android|iPhone|iPad|iPod/i.test(ua)) return true;
  const coarsePointer = typeof window !== 'undefined'
    && typeof window.matchMedia === 'function'
    && window.matchMedia('(pointer: coarse)').matches;
  const touchPoints = navigator.maxTouchPoints ?? 0;
  return coarsePointer && touchPoints > 0 && typeof window !== 'undefined' && window.innerWidth < 900;
}

async function restoreWalletConnectSessions(): Promise<void> {
  if (!WALLETCONNECT_PROJECT_ID) return;
  try {
    const client = await ensureWalletConnectClient();
    const metaByTopic = loadWalletConnectSessionMeta();
    for (const session of client.listSessions()) {
      try {
        const persisted = metaByTopic[session.topic];
        registerWalletConnectSessionForDisplay({
          ...session,
          peerName: session.peerName ?? persisted?.peerName ?? undefined,
        }, persisted?.brandId ?? undefined);
        state.wallets = visibleBrowserWallets(listAvailableWallets());
      } catch (err) {
        console.warn('[walletconnect] failed to restore session', err);
      }
    }
  } catch (err) {
    console.warn('[walletconnect] restore failed', err);
  }
}

function inferWalletConnectBrandForSession(session: WalletConnectSession): string | null {
  const peerName = session.peerName?.toLowerCase() ?? '';
  for (const [brandId, descriptor] of Object.entries(WALLET_CONNECT_BRANDS)) {
    if (peerName.includes(descriptor.name.toLowerCase())) return brandId;
  }
  return null;
}

void unregisterAllWalletConnectWallets; // referenced by tests / future tear-down
void unregisterWalletConnectSolanaWallet;

// ─── Ledger USB-HID hardware wallet (Slice G) ───────────────────────────
// Drives the "Connect Ledger" overlay (`ledgerOverlay.ts`) and routes the
// IPC commands defined in `apps/desktop-shell/src-tauri/src/ledger/`. The
// transport is owned by the Rust side; this slice handles the TS lifecycle
// (polling for a device, deriving an address, registering a Wallet
// Standard wallet, kicking off `runConnect()`).

const LEDGER_SEARCH_POLL_INTERVAL_MS = 1200;
const LEDGER_TAURI_INITIAL_ACCOUNTS_PER_FAMILY = 40;
const LEDGER_WEB_INITIAL_ACCOUNTS_PER_FAMILY = 10;
const LEDGER_LOAD_MORE_ACCOUNTS_PER_FAMILY = 10;
const LEDGER_MAX_ACCOUNTS_PER_FAMILY = 100;
const LEDGER_BALANCE_BATCH_SIZE = 20;
const LEDGER_BALANCE_FALLBACK_CONCURRENCY = 4;
const LEDGER_ACTIVITY_CONCURRENCY = 6;
const LEDGER_LAST_ACCOUNT_STORAGE_KEY = 'agentic-ledger-last-account-v1';
const LEDGER_RECENT_ACCOUNTS_STORAGE_KEY = 'agentic-ledger-recent-accounts-v1';
const LEDGER_RECENT_ACCOUNT_LIMIT = 2;

type LedgerWebHidRuntimeStatus = 'idle' | 'preparing' | 'ready' | 'error';

interface PersistedLedgerAccountSelection {
  address: string;
  derivationPath: string;
  family: 'default' | 'legacy';
  index: number;
  cluster: Cluster;
  connectedAt: string;
}

interface LedgerRuntime {
  ipc: LedgerIpc | null;
  overlay: LedgerOverlayState;
  pollHandle: number | null;
  /** Per-pairing token; bumped on every overlay open so stale async work no-ops. */
  pairingToken: number;
  accounts: LedgerAccountCandidate[];
  nextDefaultIndex: number;
  nextLegacyIndex: number;
  webHidRuntimeStatus: LedgerWebHidRuntimeStatus;
  webHidRuntimeError: string;
}

const ledger: LedgerRuntime = {
  ipc: null,
  overlay: initialLedgerOverlayState(),
  pollHandle: null,
  pairingToken: 0,
  accounts: [],
  nextDefaultIndex: 0,
  nextLegacyIndex: 0,
  webHidRuntimeStatus: 'idle',
  webHidRuntimeError: '',
};

function dispatchLedgerOverlay(action: LedgerOverlayAction): void {
  ledger.overlay = reduceLedgerOverlay(ledger.overlay, action);
  render();
}

function prepareLedgerWebHidRuntime(): void {
  if (state.tauriNativeEnvironment.isTauriNative) return;
  if (!detectLedgerWebHidSupport().supported) return;
  if (ledger.webHidRuntimeStatus === 'preparing' || ledger.webHidRuntimeStatus === 'ready') return;
  ledger.webHidRuntimeStatus = 'preparing';
  ledger.webHidRuntimeError = '';
  void preloadWebHidLedgerRuntime().then(() => {
    ledger.webHidRuntimeStatus = 'ready';
    ledger.webHidRuntimeError = '';
    render();
  }).catch((err) => {
    ledger.webHidRuntimeStatus = 'error';
    ledger.webHidRuntimeError = err instanceof Error ? err.message : String(err);
    render();
  });
}

function handleLedgerDeviceDisconnect(): void {
  unregisterAllLedgerWallets();
  ledger.accounts = [];
  ledger.nextDefaultIndex = 0;
  ledger.nextLegacyIndex = 0;
  try {
    state.wallets = visibleBrowserWallets(listAvailableWallets());
  } catch {
    state.wallets = [];
  }
  if (state.selectedWalletName === LEDGER_WALLET_NAME) {
    client = null;
    walletBackend = null;
    traceWalletCleared('ledger-teardown');
    state.address = '';
    state.capabilities = null;
    state.selectedWalletName = '';
    state.selectedWalletLogoId = undefined;
    state.selectedWalletIcon = undefined;
    state.transactionStatus = 'Ledger disconnected.';
    state.steps.connect = 'idle';
    clearWalletPathSession();
    savePersistedState();
    pushToast('pending', t('Ledger disconnected'), t('Reconnect the device and choose Ledger again.'));
  }
  if (ledger.overlay.mode !== 'closed') {
    dispatchLedgerOverlay({
      type: 'setError',
      error: 'Ledger disconnected. Reconnect the device and try again.',
    });
    return;
  }
  render();
}

function ensureLedgerIpc(): LedgerIpc | null {
  if (ledger.ipc) return ledger.ipc;
  const invoke = detectLedgerTauriInvoke();
  if (invoke) {
    ledger.ipc = createTauriLedgerIpc(invoke);
    return ledger.ipc;
  }
  const webHidSupport = detectLedgerWebHidSupport();
  if (!webHidSupport.supported) return null;
  ledger.ipc = createWebHidLedgerIpc({
    onDisconnect: handleLedgerDeviceDisconnect,
  });
  return ledger.ipc;
}

function ledgerUnavailableMessage(): string {
  if (state.tauriNativeEnvironment.isTauriNative) {
    return 'Could not reach the Tauri runtime to talk to the Ledger device.';
  }
  const support = detectLedgerWebHidSupport();
  if (!support.supported) {
    return support.message
      ?? 'Ledger USB is not available in this browser. Use Chrome or Edge on desktop, or connect with QR/browser extension.';
  }
  if (ledger.webHidRuntimeStatus === 'error') {
    return ledger.webHidRuntimeError || 'Ledger USB support failed to load. Refresh and try again.';
  }
  if (ledger.webHidRuntimeStatus !== 'ready') {
    return 'Ledger USB support is still loading. Try again in a moment.';
  }
  return '';
}

function stopLedgerPoll(): void {
  if (ledger.pollHandle !== null) {
    window.clearInterval(ledger.pollHandle);
    ledger.pollHandle = null;
  }
}

function startLedgerSearchPoll(ipc: LedgerIpc, token: number): void {
  stopLedgerPoll();
  const tick = async () => {
    if (ledger.pairingToken !== token) return; // pairing aborted/refreshed
    try {
      const devices = await ipc.listDevices();
      if (ledger.pairingToken !== token) return;
      if (devices.length === 0) return; // keep polling
      stopLedgerPoll();
      await proceedToAppCheck(ipc, devices[0]!, token);
    } catch (err) {
      if (ledger.pairingToken !== token) return;
      stopLedgerPoll();
      dispatchLedgerOverlay({
        type: 'setError',
        error: err instanceof Error ? err.message : String(err),
      });
    }
  };
  // Kick off an immediate first attempt so the user doesn't wait for the
  // interval if the device is already plugged in.
  void tick();
  ledger.pollHandle = window.setInterval(() => {
    void tick();
  }, LEDGER_SEARCH_POLL_INTERVAL_MS);
}

async function proceedToAppCheck(
  ipc: LedgerIpc,
  device: LedgerDevice,
  token: number,
): Promise<void> {
  dispatchLedgerOverlay({
    type: 'deviceFound',
    device: {
      productName: device.productName,
      vendorId: device.vendorId,
      productId: device.productId,
    },
  });
  try {
    await ipc.connect();
    if (ledger.pairingToken !== token) return;
    const initialAccountsPerFamily = state.tauriNativeEnvironment.isTauriNative
      ? LEDGER_TAURI_INITIAL_ACCOUNTS_PER_FAMILY
      : LEDGER_WEB_INITIAL_ACCOUNTS_PER_FAMILY;
    await scanLedgerAccountBatch(ipc, token, {
      defaultCount: initialAccountsPerFamily,
      legacyCount: initialAccountsPerFamily,
      reset: true,
    });
  } catch (err) {
    if (ledger.pairingToken !== token) return;
    dispatchLedgerOverlay({
      type: 'setError',
      error: err instanceof Error ? err.message : String(err),
    });
  }
}

async function scanLedgerAccountBatch(
  ipc: LedgerIpc,
  token: number,
  options: { defaultCount: number; legacyCount: number; reset: boolean },
): Promise<void> {
  if (options.reset) {
    ledger.accounts = [];
    ledger.nextDefaultIndex = 0;
    ledger.nextLegacyIndex = 0;
    dispatchLedgerOverlay({
      type: 'scanStarted',
      status: 'Retrieving addresses from your Ledger...',
      progress: 8,
    });
  } else {
    dispatchLedgerOverlay({
      type: 'loadMoreStarted',
      status: 'Retrieving more Ledger addresses...',
      progress: 12,
    });
  }

  const defaultCount = Math.min(
    options.defaultCount,
    Math.max(0, LEDGER_MAX_ACCOUNTS_PER_FAMILY - ledger.nextDefaultIndex),
  );
  const legacyCount = Math.min(
    options.legacyCount,
    Math.max(0, LEDGER_MAX_ACCOUNTS_PER_FAMILY - ledger.nextLegacyIndex),
  );
  const paths = ledgerAccountPaths({
    defaultStart: ledger.nextDefaultIndex,
    defaultCount,
    legacyStart: ledger.nextLegacyIndex,
    legacyCount,
  });
  const recentSelections = persistedLedgerSelections();
  const discoveryPaths = dedupeLedgerAccountPaths([
    ...(options.reset ? recentSelections.map(ledgerAccountPathFromSelection) : []),
    ...paths,
  ]);
  if (discoveryPaths.length === 0) {
    dispatchLedgerOverlay({
      type: 'accountsReady',
      accounts: ledger.accounts,
      selectedAddress: ledger.overlay.address ?? recentSelections[0]?.address,
      canLoadMore: false,
    });
    return;
  }

  const derived = await ipc.getAddresses(discoveryPaths.map((path) => path.derivationPath));
  if (ledger.pairingToken !== token) return;
  ledger.nextDefaultIndex += defaultCount;
  ledger.nextLegacyIndex += legacyCount;

  dispatchLedgerOverlay({
    type: 'scanProgress',
    status: 'Checking SOL balances...',
    progress: 58,
  });
  const candidates = await enrichLedgerAccounts(discoveryPaths, derived);
  if (ledger.pairingToken !== token) return;

  dispatchLedgerOverlay({
    type: 'scanProgress',
    status: 'Ranking Ledger accounts...',
    progress: 88,
  });
  const nextRecentSelections = persistedLedgerSelections();
  const preferredAddress = ledger.overlay.address ?? nextRecentSelections[0]?.address;
  ledger.accounts = rankLedgerAccounts(
    mergeLedgerAccountCandidates(ledger.accounts, candidates),
    { recentAddresses: nextRecentSelections.map((selection) => selection.address) },
  );
  dispatchLedgerOverlay({
    type: 'accountsReady',
    accounts: ledger.accounts,
    selectedAddress: preferredAddress,
    canLoadMore: canLoadMoreLedgerAccounts(),
  });
}

async function loadMoreLedgerAccounts(): Promise<void> {
  const ipc = ledger.ipc;
  if (!ipc || ledger.overlay.mode !== 'choose-address' || ledger.overlay.loadingMore) return;
  const token = ledger.pairingToken;
  try {
    await scanLedgerAccountBatch(ipc, token, {
      defaultCount: LEDGER_LOAD_MORE_ACCOUNTS_PER_FAMILY,
      legacyCount: LEDGER_LOAD_MORE_ACCOUNTS_PER_FAMILY,
      reset: false,
    });
  } catch (err) {
    if (ledger.pairingToken !== token) return;
    dispatchLedgerOverlay({
      type: 'setError',
      error: err instanceof Error ? err.message : String(err),
    });
  }
}

function canLoadMoreLedgerAccounts(): boolean {
  return ledger.nextDefaultIndex < LEDGER_MAX_ACCOUNTS_PER_FAMILY
    || ledger.nextLegacyIndex < LEDGER_MAX_ACCOUNTS_PER_FAMILY;
}

function ledgerAccountPathFromSelection(selection: PersistedLedgerAccountSelection): LedgerAccountPath {
  return {
    derivationPath: selection.derivationPath,
    family: selection.family,
    index: selection.index,
    order: selection.family === 'default' ? selection.index : 10_000 + selection.index,
  };
}

function dedupeLedgerAccountPaths(paths: readonly LedgerAccountPath[]): LedgerAccountPath[] {
  const seen = new Set<string>();
  const out: LedgerAccountPath[] = [];
  for (const path of paths) {
    if (seen.has(path.derivationPath)) continue;
    seen.add(path.derivationPath);
    out.push(path);
  }
  return out;
}

async function enrichLedgerAccounts(
  paths: readonly LedgerAccountPath[],
  derived: readonly LedgerDerivedAddress[],
): Promise<LedgerAccountCandidate[]> {
  const accounts = mergeLedgerDerivedAccounts(paths, derived);
  const connection = new Connection(activeRpcUrl(), 'confirmed');
  const lamportsByAddress = await ledgerSolBalancesByAddress(connection, accounts);

  const activityByAddress = await ledgerActivityByAddress(connection, accounts);
  return accounts.map((account) => {
    const activity = activityByAddress.has(account.address)
      ? activityByAddress.get(account.address)!
      : null;
    const hasBalance = lamportsByAddress.has(account.address);
    return toLedgerAccountCandidate(account, {
      solBalanceLamports: hasBalance ? lamportsByAddress.get(account.address) : null,
      balanceUnavailable: !hasBalance,
      hasActivity: activity,
      activityUnavailable: activity === null,
    });
  });
}

async function ledgerSolBalancesByAddress(
  connection: Connection,
  accounts: readonly { address: string }[],
): Promise<Map<string, number>> {
  const out = new Map<string, number>();
  for (let start = 0; start < accounts.length; start += LEDGER_BALANCE_BATCH_SIZE) {
    const chunk = accounts.slice(start, start + LEDGER_BALANCE_BATCH_SIZE);
    try {
      const infos = await connection.getMultipleAccountsInfo(
        chunk.map((account) => new PublicKey(account.address)),
        'confirmed',
      );
      chunk.forEach((account, index) => {
        out.set(account.address, infos[index]?.lamports ?? 0);
      });
    } catch (err) {
      console.warn('[ledger] balance batch enrichment failed', err);
      await mapWithConcurrency(chunk, LEDGER_BALANCE_FALLBACK_CONCURRENCY, async (account) => {
        try {
          const lamports = await connection.getBalance(new PublicKey(account.address), 'confirmed');
          out.set(account.address, lamports);
        } catch (singleErr) {
          console.warn('[ledger] balance lookup failed', account.address, singleErr);
        }
      });
    }
  }
  return out;
}

async function ledgerActivityByAddress(
  connection: Connection,
  accounts: readonly { address: string }[],
): Promise<Map<string, boolean | null>> {
  const out = new Map<string, boolean | null>();
  await mapWithConcurrency(accounts, LEDGER_ACTIVITY_CONCURRENCY, async (account) => {
    try {
      const signatures = await connection.getSignaturesForAddress(
        new PublicKey(account.address),
        { limit: 1 },
        'confirmed',
      );
      out.set(account.address, signatures.length > 0);
    } catch (err) {
      console.warn('[ledger] activity enrichment failed', err);
      out.set(account.address, null);
    }
  });
  return out;
}

async function mapWithConcurrency<T>(
  items: readonly T[],
  limit: number,
  worker: (item: T) => Promise<void>,
): Promise<void> {
  const workers = Array.from({ length: Math.max(1, Math.min(limit, items.length)) }, async (_, workerIndex) => {
    for (let index = workerIndex; index < items.length; index += Math.max(1, limit)) {
      await worker(items[index]!);
    }
  });
  await Promise.all(workers);
}

function persistedLedgerSelections(): PersistedLedgerAccountSelection[] {
  return readLedgerSelectionStorage()
    .filter((selection) => selection.cluster === state.cluster)
    .slice(0, LEDGER_RECENT_ACCOUNT_LIMIT);
}

function readLedgerSelectionStorage(): PersistedLedgerAccountSelection[] {
  const selections: PersistedLedgerAccountSelection[] = [];
  try {
    const parsed = JSON.parse(localStorage.getItem(LEDGER_RECENT_ACCOUNTS_STORAGE_KEY) ?? '[]') as unknown;
    const entries = Array.isArray(parsed) ? parsed : [parsed];
    for (const entry of entries) {
      const selection = parsePersistedLedgerSelection(entry);
      if (selection) selections.push(selection);
    }
  } catch {
    // Ignore malformed convenience storage.
  }

  try {
    const legacy = parsePersistedLedgerSelection(
      JSON.parse(localStorage.getItem(LEDGER_LAST_ACCOUNT_STORAGE_KEY) ?? 'null') as unknown,
    );
    if (legacy) selections.push(legacy);
  } catch {
    // Ignore malformed legacy storage.
  }

  return capLedgerSelectionsPerCluster(dedupeLedgerSelections(selections));
}

function parsePersistedLedgerSelection(value: unknown): PersistedLedgerAccountSelection | null {
  if (!value || typeof value !== 'object') return null;
  const parsed = value as Partial<PersistedLedgerAccountSelection>;
  const cluster = typeof parsed.cluster === 'string' && isCluster(parsed.cluster)
    ? parsed.cluster
    : null;
  if (
    typeof parsed.address !== 'string' ||
    parsed.address.trim().length === 0 ||
    typeof parsed.derivationPath !== 'string' ||
    parsed.derivationPath.trim().length === 0 ||
    (parsed.family !== 'default' && parsed.family !== 'legacy') ||
    !Number.isInteger(parsed.index) ||
    Number(parsed.index) < 0 ||
    !cluster
  ) {
    return null;
  }
  return {
    address: parsed.address.trim(),
    derivationPath: parsed.derivationPath.trim(),
    family: parsed.family,
    index: Number(parsed.index),
    cluster,
    connectedAt: typeof parsed.connectedAt === 'string' ? parsed.connectedAt : '',
  };
}

function dedupeLedgerSelections(
  selections: readonly PersistedLedgerAccountSelection[],
): PersistedLedgerAccountSelection[] {
  const seen = new Set<string>();
  const out: PersistedLedgerAccountSelection[] = [];
  for (const selection of selections) {
    const key = `${selection.cluster}|${selection.address}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(selection);
  }
  return out;
}

function capLedgerSelectionsPerCluster(
  selections: readonly PersistedLedgerAccountSelection[],
): PersistedLedgerAccountSelection[] {
  const counts = new Map<Cluster, number>();
  const out: PersistedLedgerAccountSelection[] = [];
  for (const selection of selections) {
    const count = counts.get(selection.cluster) ?? 0;
    if (count >= LEDGER_RECENT_ACCOUNT_LIMIT) continue;
    counts.set(selection.cluster, count + 1);
    out.push(selection);
  }
  return out;
}

function persistLedgerSelection(account: LedgerAccountCandidate): void {
  const payload: PersistedLedgerAccountSelection = {
    address: account.address,
    derivationPath: account.derivationPath,
    family: account.family,
    index: account.index,
    cluster: state.cluster,
    connectedAt: new Date().toISOString(),
  };
  const next = capLedgerSelectionsPerCluster(dedupeLedgerSelections([
    payload,
    ...readLedgerSelectionStorage(),
  ]));
  try {
    localStorage.setItem(LEDGER_LAST_ACCOUNT_STORAGE_KEY, JSON.stringify(payload));
    localStorage.setItem(LEDGER_RECENT_ACCOUNTS_STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Persistence is a convenience only; pairing must not depend on storage.
  }
}

function openLedgerOverlay(): void {
  // Idempotent: double-tap on "Connect Ledger" must not reset the search
  // poll or invalidate the pairing token while a pair is already in flight.
  if (ledger.overlay.mode !== 'closed') return;
  if (!state.tauriNativeEnvironment.isTauriNative && detectLedgerWebHidSupport().supported) {
    prepareLedgerWebHidRuntime();
    if (ledger.webHidRuntimeStatus !== 'ready') {
      const message = ledgerUnavailableMessage();
      pushToast('pending', t('Preparing Ledger USB'), message);
      closeSiblingOverlays('ledger');
      stopLedgerPoll();
      ledger.pairingToken += 1;
      dispatchLedgerOverlay({
        type: 'setError',
        error: message,
      });
      return;
    }
  }
  const ipc = ensureLedgerIpc();
  if (!ipc) {
    const message = ledgerUnavailableMessage();
    pushToast(
      'error',
      t('Ledger not available'),
      message,
    );
    closeSiblingOverlays('ledger');
    stopLedgerPoll();
    ledger.pairingToken += 1;
    dispatchLedgerOverlay({
      type: 'setError',
      error: message,
    });
    return;
  }
  const webRequest = state.tauriNativeEnvironment.isTauriNative
    ? null
    : ipc.requestDevice?.();
  closeSiblingOverlays('ledger');
  ledger.pairingToken += 1;
  ledger.accounts = [];
  ledger.nextDefaultIndex = 0;
  ledger.nextLegacyIndex = 0;
  const token = ledger.pairingToken;
  dispatchLedgerOverlay({ type: 'open' });
  if (webRequest) {
    void webRequest.then((device) => {
      if (ledger.pairingToken !== token) return;
      if (!device) {
        dispatchLedgerOverlay({
          type: 'setError',
          error: 'No Ledger device was selected.',
        });
        return;
      }
      void proceedToAppCheck(ipc, device, token);
    }).catch((err) => {
      if (ledger.pairingToken !== token) return;
      dispatchLedgerOverlay({
        type: 'setError',
        error: err instanceof Error ? err.message : String(err),
      });
    });
    return;
  }
  startLedgerSearchPoll(ipc, token);
}

async function confirmLedgerAddress(): Promise<void> {
  const ipc = ledger.ipc;
  if (!ipc) return;
  const overlay = ledger.overlay;
  if (overlay.mode !== 'choose-address' || !overlay.address) return;
  const selectedAccount = overlay.accounts.find((account) => account.address === overlay.address);
  if (!selectedAccount) return;
  const token = ledger.pairingToken;
  dispatchLedgerOverlay({ type: 'confirmingAddress' });
  const toastId = beginLedgerDeviceApprovalToast(ledgerConnectApprovalMessage(), { force: true });
  try {
    // Re-fetch the selected address with display-on-device. The chooser
    // already has the base64 public key from scanning, but this second call
    // proves the user approved the exact selected path on the Ledger screen.
    await waitForLedgerPromptPaint();
    const fresh = await ipc.getAddress(overlay.derivationPath, true);
    if (ledger.pairingToken !== token) {
      dismissLedgerDeviceApprovalToast(toastId);
      return;
    }
    if (fresh.address !== overlay.address) {
      completeLedgerDeviceApprovalToast(
        toastId,
        'error',
        'Ledger connection failed',
        'The Ledger returned a different address. Please retry.',
      );
      dispatchLedgerOverlay({
        type: 'setError',
        error: 'The Ledger derived a different address on re-check. Please retry.',
      });
      return;
    }
    const publicKey = decodeLedgerPublicKey(fresh.address, fresh.publicKeyB64);
    unregisterAllLedgerWallets();
    registerLedgerWallet({
      ipc,
      address: fresh.address,
      publicKey,
      derivationPath: overlay.derivationPath,
    });
    persistLedgerSelection(selectedAccount);
    state.wallets = visibleBrowserWallets(listAvailableWallets());
    state.selectedWalletName = LEDGER_WALLET_NAME;
    await runConnect({
      onError: () => {
        // The Ledger overlay keeps the selected account context and renders
        // the retryable failure after this call returns.
      },
    });
    if (ledger.pairingToken !== token) {
      dismissLedgerDeviceApprovalToast(toastId);
      return;
    }
    if (
      state.steps.connect === 'error'
      || state.selectedWalletName !== LEDGER_WALLET_NAME
      || !sameWalletAddress(state.address, fresh.address)
    ) {
      const message = state.error
        || state.transactionStatus
        || 'Ledger connection did not complete. Please retry.';
      completeLedgerDeviceApprovalToast(toastId, 'error', 'Ledger connection failed', message);
      dispatchLedgerOverlay({
        type: 'setError',
        error: message,
      });
      return;
    }
    dispatchLedgerOverlay({ type: 'close' });
    completeLedgerDeviceApprovalToast(toastId, 'success', 'Ledger connected', short(fresh.address));
  } catch (err) {
    if (ledger.pairingToken !== token) {
      dismissLedgerDeviceApprovalToast(toastId);
      return;
    }
    const normalized = normalizeLedgerSigningError(err, { force: true });
    const message = ledgerErrorMessage(normalized);
    completeLedgerDeviceApprovalToast(toastId, 'error', 'Ledger connection failed', message);
    dispatchLedgerOverlay({
      type: 'setError',
      error: message,
    });
  }
}

function handleLedgerOverlayAction(action: string | undefined, address?: string): void {
  switch (action) {
    case 'cancel':
      stopLedgerPoll();
      ledger.pairingToken += 1; // invalidate any in-flight handlers
      dispatchLedgerOverlay({ type: 'close' });
      if (
        desktopConnect.flow.step === 'ledger'
      ) {
        dispatchDesktopConnectFlow({ type: 'back' });
      }
      return;
    case 'retry':
      stopLedgerPoll();
      ledger.pairingToken += 1;
      {
        const retryState = ledgerConfirmationRetryState(ledger.overlay);
        if (retryState) {
          ledger.overlay = retryState;
          render();
          void confirmLedgerAddress();
          return;
        }
      }
      const staleIpc = ledger.ipc;
      ledger.ipc = null;
      void staleIpc?.disconnect().catch(() => {});
      dispatchLedgerOverlay({ type: 'close' });
      openLedgerOverlay();
      return;
    case 'select-account':
      if (address) dispatchLedgerOverlay({ type: 'selectAccount', address });
      return;
    case 'copy-address':
      if (address) {
        if (!navigator.clipboard?.writeText) {
          pushToast('error', t('Copy failed'), t('Clipboard API is not available in this context.'));
          return;
        }
        void navigator.clipboard.writeText(address).then(() => {
          pushToast('success', t('Ledger address copied'), short(address));
        }).catch((err) => {
          pushToast('error', t('Copy failed'), err instanceof Error ? err.message : String(err));
        });
      }
      return;
    case 'toggle-expanded':
      dispatchLedgerOverlay({ type: 'toggleAccountsExpanded' });
      return;
    case 'load-more':
      void loadMoreLedgerAccounts();
      return;
    case 'confirm-address':
      void confirmLedgerAddress();
      return;
    default:
      return;
  }
}

function bindLedgerOverlay(): void {
  if (ledger.overlay.mode === 'closed') return;
  for (const el of document.querySelectorAll<HTMLElement>('[data-ledger-action]')) {
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      handleLedgerOverlayAction(el.dataset.ledgerAction, el.dataset.ledgerAddress);
    });
  }
}

function ledgerOverlayBlock(): string {
  // The Tauri desktop renders the same state machine inline inside the
  // discover-flow rail, so suppress the modal mount on native to avoid a
  // double-render.
  if (!shouldRenderDetachedLedgerOverlay({
    isTauriNative: state.tauriNativeEnvironment.isTauriNative,
    flowStep: desktopConnect.flow.step,
  })) return '';
  return ledgerOverlayHtml(ledger.overlay, walletConnectQrSurface());
}

// ─── Desktop discover flow (inline rail) ─────────────────────────────────
// Drives the multi-step "Discover → Method → (Browser ext / QR / Ledger)"
// flow inside the left wallet rail on the Tauri desktop. The actual pairing
// machinery (WalletConnect, Ledger HID, open-in-browser) is reused as-is —
// this section only owns the inline UI and routing.

interface DesktopDeeplinkQr {
  /** Which variant this data URL was generated for; cleared when variant
   *  changes so we never display a stale QR for the wrong wallet. */
  variant: EncryptedDeeplinkWalletId | null;
  /** PNG data URL ready to drop into an `<img src>`; null until the async
   *  qrcode generation completes for the active variant. */
  dataUrl: string | null;
  /** The raw URL the QR encodes — surfaced under the QR as a fallback so the
   *  user can copy/paste if the camera scan fails. */
  url: string | null;
  /** Non-null when the QR was rendered but the pairing relay metadata POST failed. */
  relayError: string | null;
}

/** Cloud-pairing state for the Phantom/Solflare QR path. The desktop
 *  generates the UUID, embeds it in the wallet's universal-link deeplink,
 *  then polls `/api/pair/<uuid>/host` until the wallet-host on the phone
 *  registers its address — at which point we adopt via `RemoteRelayBackend`. */
interface DesktopPairing {
  uuid: string;
  /** Picked brand — drives the rendered banner and the wallet name we display
   *  before the relay reports its own. */
  wallet: EncryptedDeeplinkWalletId;
  /** setInterval handle for the host-poll loop; cleared on adoption / back / timeout. */
  pollHandle: number | null;
  /** Epoch ms when the pairing was started; used to fire the 5-min soft toast. */
  startedAt: number;
  /** Flips to true after the 5-min toast fires so we don't spam. */
  warnedTimeout: boolean;
}

interface DesktopConnectRuntime {
  flow: DesktopConnectFlowState;
  /** setInterval handle while polling the bridge for awaiting-browser. */
  pollHandle: number | null;
  /** Deeplink QR cache for Phantom/Solflare; rebuilt whenever the user enters that variant. */
  deeplinkQr: DesktopDeeplinkQr;
  /** Active cross-device pairing record (Phantom/Solflare via cloud relay). */
  pairing: DesktopPairing | null;
  /** Pairing UUIDs already adopted in this session. Prevents a duplicate
   *  `afterWalletConnected` + toast if the relay returns the host record on
   *  two consecutive polls (or the user re-enters the flow with the same UUID). */
  adoptedPairings: Set<string>;
}

const desktopConnect: DesktopConnectRuntime = {
  flow: initialDesktopConnectFlowState(),
  pollHandle: null,
  deeplinkQr: { variant: null, dataUrl: null, url: null, relayError: null },
  pairing: null,
  adoptedPairings: new Set<string>(),
};

const DESKTOP_QR_ENV = ((import.meta as ImportMeta & { env?: DesktopQrConfigEnv }).env ?? {}) as DesktopQrConfigEnv;
const PAIRING_RELAY_BASE_URL = resolveDesktopPairingRelayBaseUrl(DESKTOP_QR_ENV);
const QR_CONNECT_APP_URL = resolveQrConnectAppUrl(DESKTOP_QR_ENV);
const BROWSER_EXTENSION_WALLET_SELECT_ID = 'browserExtensionWalletSelect';

const PAIRING_POLL_INTERVAL_MS = 1500;
const PAIRING_TIMEOUT_MS = 5 * 60 * 1000;

/** brandId → wallet-standard wallet names. Used by the wallet-host page's
 *  legacy `?wallet=` auto-connect path for mobile deeplinks. */
const DESKTOP_BRAND_WALLET_NAMES: Record<string, readonly string[]> = {
  backpack: ['Backpack'],
  phantom: ['Phantom'],
  jupiter: ['Jupiter', 'Jupiter Mobile'],
  solflare: ['Solflare'],
};

function browserWalletNameMatchesBrand(walletName: string, brandId: string | undefined): boolean {
  if (!brandId) return true;
  const names = DESKTOP_BRAND_WALLET_NAMES[brandId];
  if (!names) return false;
  const normalized = walletName.trim().toLowerCase();
  return names.some((name) => name.toLowerCase() === normalized);
}

function browserWalletBrandIdForName(walletName: string): string | undefined {
  const normalized = walletName.trim().toLowerCase();
  if (!normalized) return undefined;
  for (const [brandId, names] of Object.entries(DESKTOP_BRAND_WALLET_NAMES)) {
    if (names.some((name) => name.toLowerCase() === normalized)) {
      return brandId;
    }
  }
  return undefined;
}

function discoveredWalletForBrand(brandId: string): DiscoveredWallet | undefined {
  const names = DESKTOP_BRAND_WALLET_NAMES[brandId];
  if (!names) return undefined;
  return state.wallets.find((wallet) => browserWalletNameMatchesBrand(wallet.name, brandId));
}

function requestedDesktopBrowserWalletBrand(): string | undefined {
  const brandId = launchParams.walletBrand?.trim();
  if (!brandId) return undefined;
  if (cliView && cliView.surface !== 'desktop') return undefined;
  return DESKTOP_BRAND_WALLET_NAMES[brandId] ? brandId : undefined;
}

function browserWalletPathForCurrentSurface(): NonNullable<BrowserWalletSession['path']> {
  return cliView?.surface === 'desktop' || Boolean(launchParams.bridgeUrl || launchParams.bridgeToken)
    ? 'desktop-browser-extension'
    : 'browser-extension';
}

function multiPathWalletFlowAvailable(): boolean {
  return canUseMultiPathWalletFlow({
    isAndroidNative: state.androidNativeEnvironment.isAndroidNative,
    isIosNative: state.iosNativeEnvironment.isIosNative,
    isCliMode: Boolean(cliView),
    isTauriNative: state.tauriNativeEnvironment.isTauriNative,
  });
}

function stopDesktopConnectPoll(): void {
  if (desktopConnect.pollHandle !== null) {
    window.clearInterval(desktopConnect.pollHandle);
    desktopConnect.pollHandle = null;
  }
}

function dispatchDesktopConnectFlow(action: DesktopConnectFlowAction): void {
  desktopConnect.flow = reduceDesktopConnectFlow(desktopConnect.flow, action);
  if (desktopConnect.flow.step !== 'awaiting-browser') {
    stopDesktopConnectPoll();
  }
  if (desktopConnect.flow.step === 'method') {
    prepareLedgerWebHidRuntime();
  }
  render();
}

function escapeHtmlForFlow(value: string): string {
  return value.replace(/[&<>"']/g, (ch) => {
    switch (ch) {
      case '&':
        return '&amp;';
      case '<':
        return '&lt;';
      case '>':
        return '&gt;';
      case '"':
        return '&quot;';
      default:
        return '&#39;';
    }
  });
}

function brandLogoMarkup(brandId: string, sizeClass = 'desktop-connect-flow-logo'): string {
  // The brand panels map their `logoId` to BRAND_LOGOS keys; DESKTOP_BRAND_PANELS
  // already pre-resolves that. We re-use it here for the method/brand rows.
  const descriptor = DESKTOP_BRAND_PANELS.find((b) => b.id === brandId);
  const logoId = descriptor?.logoId ?? brandId;
  const url = (BRAND_LOGOS as Record<string, string | undefined>)[logoId];
  if (!url) {
    return `<span class="${sizeClass} placeholder" aria-hidden="true"></span>`;
  }
  return `<img class="${sizeClass}" src="${escapeHtmlForFlow(url)}" alt="" />`;
}

function desktopMethodPickerBody(): string {
  const ledgerWebHidSupport = detectLedgerWebHidSupport();
  const ledgerAvailable = state.tauriNativeEnvironment.isTauriNative
    ? Boolean(detectLedgerTauriInvoke())
    : ledgerWebHidSupport.supported && ledger.webHidRuntimeStatus === 'ready';
  const ledgerDisabledReason = ledgerAvailable ? '' : ledgerUnavailableMessage();
  const extensionSubcopy = state.tauriNativeEnvironment.isTauriNative
    ? 'Open the wallet pairing page in your default browser. Choose Backpack, Phantom, Jupiter, or Solflare there.'
    : 'Use an installed wallet extension.';
  const qrSubcopy = state.tauriNativeEnvironment.isTauriNative
    ? 'Pair Backpack or Jupiter over WalletConnect, or Phantom/Solflare with encrypted wallet links. Your phone signs; this desktop relays.'
    : 'Scan with a wallet on your phone.';
  const ledgerSubcopy = state.tauriNativeEnvironment.isTauriNative
    ? 'USB-HID. Plug in and unlock your device, then open the Solana app.'
    : ledgerAvailable
      ? 'Connect a Ledger over USB.'
      : ledgerWebHidSupport.supported && ledger.webHidRuntimeStatus !== 'error'
        ? 'Preparing Ledger USB support...'
      : ledgerDisabledReason;
  // Inline lucide glyphs (Monitor / QrCode / Usb) so the cards match SolPulse's
  // wallet-method picker (icon + title + short description). No React/lucide here.
  const svgIcon = (paths: string, color: string): string =>
    `<span class="desktop-method-tile-icon" style="color:${color}"><svg xmlns="http://www.w3.org/2000/svg" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths}</svg></span>`;
  const monitorIcon = svgIcon('<rect width="20" height="14" x="2" y="3" rx="2"/><line x1="8" x2="16" y1="21" y2="21"/><line x1="12" x2="12" y1="17" y2="21"/>', '#5eead4');
  const qrIcon = svgIcon('<rect width="5" height="5" x="3" y="3" rx="1"/><rect width="5" height="5" x="16" y="3" rx="1"/><rect width="5" height="5" x="3" y="16" rx="1"/><path d="M21 16h-3a2 2 0 0 0-2 2v3"/><path d="M21 21v.01"/><path d="M12 7v3a2 2 0 0 1-2 2H7"/><path d="M3 12h.01"/><path d="M12 3h.01"/><path d="M12 16v.01"/><path d="M16 12h1"/><path d="M21 12v.01"/><path d="M12 21v-1"/>', '#6ee7b7');
  const usbIcon = svgIcon('<circle cx="10" cy="7" r="1"/><circle cx="4" cy="20" r="1"/><path d="M4.7 19.3 19 5"/><path d="m21 3-3 1 2 2Z"/><path d="M9.26 7.68 5 12l2 5"/><path d="m10 14 5 2 3.5-3.5"/><path d="m18 12 1-1 1 1-1 1Z"/>', '#d4d4d8');
  return `
    <p class="desktop-connect-flow-lede">Choose how you'd like to connect your wallet.</p>
    <div class="desktop-connect-flow-methods">
      <button type="button" class="desktop-method-tile" data-desktop-flow-action="method:extension">
        ${monitorIcon}
        <span class="desktop-method-tile-text">
          <span class="desktop-method-tile-title">${escapeHtmlForFlow(t('Browser extension'))}</span>
          <span class="desktop-method-tile-sub">${escapeHtmlForFlow(extensionSubcopy)}</span>
        </span>
      </button>
      <button type="button" class="desktop-method-tile" data-desktop-flow-action="method:qr">
        ${qrIcon}
        <span class="desktop-method-tile-text">
          <span class="desktop-method-tile-title">${escapeHtmlForFlow(t('QR code'))}</span>
          <span class="desktop-method-tile-sub">${escapeHtmlForFlow(qrSubcopy)}</span>
        </span>
      </button>
      <button type="button" class="desktop-method-tile" data-desktop-flow-action="method:ledger" ${ledgerAvailable ? '' : `disabled title="${escapeHtmlForFlow(ledgerDisabledReason)}"`}>
        ${usbIcon}
        <span class="desktop-method-tile-text">
          <span class="desktop-method-tile-title">${escapeHtmlForFlow(t('Ledger'))}</span>
          <span class="desktop-method-tile-sub">${escapeHtmlForFlow(ledgerSubcopy)}</span>
        </span>
      </button>
    </div>
  `;
}

/** The wallet brands offered on the QR step. Order matters — it's
 *  the order the rows render. Backpack and Jupiter scan the raw WalletConnect
 *  URI; Phantom and Solflare scan encrypted wallet connect deeplinks. */
const DESKTOP_QR_WALLETS: ReadonlyArray<{
  id: DesktopQrWallet;
  label: string;
  logoId: string;
}> = [
  { id: 'backpack', label: 'Backpack', logoId: 'backpack' },
  { id: 'jupiter', label: 'Jupiter', logoId: 'jupiter' },
  { id: 'phantom', label: 'Phantom', logoId: 'phantom' },
  { id: 'solflare', label: 'Solflare', logoId: 'solflare' },
];

/** Body for the QR step. Branches on `desktopConnect.flow.qrWallet`:
 *  - `null` → 4-tile wallet picker (Backpack/Jupiter/Phantom/Solflare).
 *  - `'backpack'` / `'jupiter'` → branded raw WC QR.
 *  - `'phantom'` / `'solflare'` → wallet-specific encrypted deeplink QR. */
function desktopQrBody(): string {
  const wallet = desktopConnect.flow.qrWallet;
  if (wallet === null) {
    return desktopQrWalletPicker();
  }
  if (wallet === 'backpack' || wallet === 'jupiter') {
    const brandName = wallet === 'backpack' ? 'Backpack' : 'Jupiter';
    const websiteSurface = !state.tauriNativeEnvironment.isTauriNative;
    const descriptor = WALLET_CONNECT_BRANDS[wallet];
    return `
      <div class="desktop-connect-flow-body walletconnect-qr-inline">
        ${walletConnectQrBodyHtml({
          state: walletConnect.overlay,
          logoUrl: (logoId) => (BRAND_LOGOS as Record<string, string | undefined>)[logoId] ?? null,
          // Custom brand resolver: synthesize a descriptor for the picked
          // wallet with an empty deepLinkPrefix so the body shows the
          // branded header ("Scan with Backpack mobile") without rendering
          // the same-device deeplink button (we're cross-device here).
          brand: () => ({
            id: wallet,
            name: brandName,
            deepLinkPrefix: websiteSurface ? (descriptor?.deepLinkPrefix ?? '') : '',
            logoId: wallet,
          }),
          agnostic: false,
          surface: walletConnectQrSurface(),
          preferDeepLink: websiteSurface && preferWalletConnectSameDeviceLaunch(),
        })}
      </div>
    `;
  }
  // Phantom/Solflare — encrypted deeplink QR.
  const brandName = wallet === 'phantom' ? 'Phantom' : 'Solflare';
  const relayTarget = state.tauriNativeEnvironment.isTauriNative ? 'desktop' : 'Agentic';
  const cached = desktopConnect.deeplinkQr;
  const qrMarkup = cached.variant === wallet && cached.dataUrl
    ? `<img class="walletconnect-qr-overlay-qr" src="${escapeHtmlForFlow(cached.dataUrl)}" alt="${escapeHtmlForFlow(tf('QR code that opens {brand} mobile', { brand: brandName }))}" />`
    : `<div class="walletconnect-qr-overlay-qr placeholder" aria-hidden="true"></div>`;
  const relayError = cached.variant === wallet && cached.relayError
    ? `<div class="desktop-connect-flow-deeplink-error" role="alert">${escapeHtmlForFlow(cached.relayError)}</div>`
    : '';
  return `
    <div class="desktop-connect-flow-body desktop-deeplink-qr-inline">
      <div class="walletconnect-qr-overlay-brand">
        ${brandLogoMarkup(wallet, 'walletconnect-qr-overlay-brand-logo')}
        <span>Scan with your phone's Camera app - ${escapeHtmlForFlow(brandName)} will open</span>
      </div>
      ${qrMarkup}
      <p class="desktop-connect-flow-deeplink-hint">
        Scan this QR with ${escapeHtmlForFlow(brandName)}. The wallet will show its native Connect prompt.
      </p>
      <div class="desktop-connect-flow-deeplink-note" role="note">
        After approval, keep the phone page open. Future ${escapeHtmlForFlow(relayTarget)} signing requests will route through that page and reopen ${escapeHtmlForFlow(brandName)} for approval.
      </div>
      ${relayError}
    </div>
  `;
}

/** Renders the 4-tile wallet picker shown when the user lands on the QR
 *  step before choosing a wallet. Each tile is a flat clickable row with
 *  the brand SVG on the left, the brand label, and a chevron on the right. */
function desktopQrWalletPicker(): string {
  const rows = DESKTOP_QR_WALLETS.map((entry) => {
    const walletConnectRequired = entry.id === 'backpack' || entry.id === 'jupiter';
    const disabled = walletConnectRequired && !WALLETCONNECT_PROJECT_ID;
    const reason = 'WalletConnect project ID is not configured.';
    return `
    <button
      type="button"
      class="desktop-qr-wallet-tile"
      data-desktop-flow-action="pick-qr-wallet"
      data-desktop-qr-wallet="${escapeHtmlForFlow(entry.id)}"
      ${disabled ? `disabled title="${escapeHtmlForFlow(reason)}"` : ''}
    >
      ${brandLogoMarkup(entry.logoId, 'desktop-qr-wallet-tile-logo')}
      <span class="desktop-qr-wallet-tile-copy">
        <span class="desktop-qr-wallet-tile-label">${escapeHtmlForFlow(entry.label)}</span>
        ${disabled ? `<span class="desktop-qr-wallet-tile-note">${escapeHtmlForFlow(reason)}</span>` : ''}
      </span>
      <span class="desktop-qr-wallet-tile-arrow" aria-hidden="true">${disabled ? '' : '›'}</span>
    </button>
  `;
  }).join('');
  return `
    <p class="desktop-connect-flow-lede">Pick your mobile wallet. We'll show the right QR for that wallet's protocol.</p>
    <div class="desktop-qr-wallet-picker" role="list">${rows}</div>
  `;
}

function desktopBrowserExtensionBody(): string {
  const rows = DESKTOP_QR_WALLETS.map((entry) => `
    <button
      type="button"
      class="desktop-qr-wallet-tile"
      data-desktop-flow-action="pick-extension-wallet"
      data-desktop-extension-wallet="${escapeHtmlForFlow(entry.id)}"
      ${state.busy ? 'disabled' : ''}
    >
      ${brandLogoMarkup(entry.logoId, 'desktop-qr-wallet-tile-logo')}
      <span class="desktop-qr-wallet-tile-copy">
        <span class="desktop-qr-wallet-tile-label">${escapeHtmlForFlow(entry.label)}</span>
      </span>
      <span class="desktop-qr-wallet-tile-arrow" aria-hidden="true">›</span>
    </button>
  `).join('');
  const lede = state.tauriNativeEnvironment.isTauriNative
    ? 'Pick the browser extension to open in your default browser. Agentic Desktop will only accept that provider for this connection.'
    : 'Pick the browser extension to open in this browser. Agentic will only connect through that provider.';
  return `
    <div class="desktop-connect-flow-body browser-extension-inline">
      <p class="desktop-connect-flow-lede">${escapeHtmlForFlow(lede)}</p>
      <div class="desktop-qr-wallet-picker" role="list">${rows}</div>
    </div>
  `;
}

function desktopAwaitingBrowserBody(): string {
  const brandId = desktopConnect.flow.selectedBrandId ?? '';
  const brand = DESKTOP_BRAND_PANELS.find((b) => b.id === brandId);
  const name = brand?.name ?? 'your browser wallet';
  const logo = brand ? brandLogoMarkup(brand.id, 'desktop-connect-flow-awaiting-logo') : '';
  return `
    <div class="desktop-connect-flow-awaiting">
      ${logo}
      <h3>Waiting for ${escapeHtmlForFlow(name)}…</h3>
      <p>Choose and authorize a wallet in the browser tab. This panel closes automatically once Agentic Desktop detects the wallet.</p>
      <div class="desktop-connect-flow-awaiting-status" role="status" aria-live="polite">
        <span class="desktop-connect-flow-spinner" aria-hidden="true"></span>
        <span>${escapeHtmlForFlow(t('Waiting for your wallet…'))}</span>
      </div>
      <div class="desktop-connect-flow-awaiting-actions">
        <button type="button" class="utility" data-desktop-flow-action="awaiting-retry">${escapeHtmlForFlow(t('Reopen browser'))}</button>
      </div>
      <p class="desktop-connect-flow-awaiting-hint">${escapeHtmlForFlow(t('If nothing happens, make sure the extension is installed in your default browser. You can also press Back and pick a different connection method.'))}</p>
    </div>
  `;
}

function desktopConnectFlowBlock(): string {
  if (!multiPathWalletFlowAvailable()) return '';
  if (desktopConnect.flow.step === 'idle') return '';
  let title = 'Discover wallet';
  let body = '';
  switch (desktopConnect.flow.step) {
    case 'method':
      title = 'Discover wallet';
      body = desktopMethodPickerBody();
      break;
    case 'extension':
      title = 'Browser extension';
      body = desktopBrowserExtensionBody();
      break;
    case 'qr':
      title = 'Scan QR with phone';
      body = desktopQrBody();
      break;
    case 'ledger':
      title = ledger.overlay.mode === 'error' ? "Couldn't connect Ledger" : 'Connect Ledger';
      body = `<div class="desktop-connect-flow-body ledger-overlay-inline">${ledgerOverlayBodyHtml(ledger.overlay, walletConnectQrSurface())}</div>`;
      break;
    case 'awaiting-browser':
      title = 'Waiting for browser';
      body = desktopAwaitingBrowserBody();
      break;
    default:
      return '';
  }
  return `
    <section class="desktop-connect-flow" aria-label="${escapeHtmlForFlow(title)}">
      <header class="desktop-connect-flow-head">
        <button type="button" class="desktop-connect-flow-back" data-desktop-flow-action="back" aria-label="Back">←</button>
        <h2>${escapeHtmlForFlow(title)}</h2>
      </header>
      <div class="desktop-connect-flow-content">
        ${body}
      </div>
    </section>
  `;
}

// ─── Desktop discover flow — handlers ────────────────────────────────────

async function runDesktopDiscover(): Promise<void> {
  if (!multiPathWalletFlowAvailable()) return;
  if (desktopConnect.flow.step !== 'idle') return;
  clearPendingBrowserWalletChoice({ clearWallets: true });
  dispatchDesktopConnectFlow({ type: 'startMethod' });
}

function handleDesktopMethodSelect(method: DesktopConnectMethod): void {
  if (method === 'extension') {
    clearPendingBrowserWalletChoice({ clearWallets: true });
    dispatchDesktopConnectFlow({ type: 'pickMethod', method: 'extension' });
    return;
  }
  if (method === 'ledger') {
    // Switch UI first so the inline body renders, then drive the existing
    // Ledger state machine. `openLedgerOverlay` is idempotent and reusable.
    dispatchDesktopConnectFlow({ type: 'pickMethod', method: 'ledger' });
    openLedgerOverlay();
    return;
  }
  if (method === 'qr') {
    // Switch UI to the QR step but DO NOT auto-launch any pairing yet — the
    // step opens on a 4-tile wallet picker (Backpack/Jupiter/Phantom/Solflare).
    // Pairing fires only after the user picks a wallet in `handleDesktopQrWalletSelect`.
    dispatchDesktopConnectFlow({ type: 'pickMethod', method: 'qr' });
    return;
  }
}

/** Generate a PNG data URL from an arbitrary URL string using the same
 *  dynamic `qrcode` import the WC flow already uses. Returns the empty
 *  string on failure (caller surfaces a placeholder). */
async function renderUrlQrDataUrl(target: string): Promise<string> {
  try {
    const QRCodeMod = await import('qrcode');
    const generator = (QRCodeMod as { default?: typeof import('qrcode') }).default ?? QRCodeMod;
    return await generator.toDataURL(target, {
      // Error-correction L because Phantom Connect URLs are long (~300 chars).
      // M starts to push the QR towards higher versions that scan poorly on a
      // phone camera at typical viewing distances.
      errorCorrectionLevel: 'L',
      margin: 2,
      width: 320,
    });
  } catch (err) {
    console.warn('[desktop-qr-variant] qrcode generation failed', err);
    return '';
  }
}

/** Build the deeplink URL for Phantom/Solflare given the current
 *  cluster, return both the raw URL and a fresh QR data URL. The data URL
 *  is rendered into `<img src>` inside `desktopQrBody()`. `pairing` (when
 *  set) gets threaded into the redirect/destination URL so the wallet-host
 *  page in the phone's in-app browser can POST its address to the matching
 *  cloud pairing record. */
async function buildDesktopVariantQr(
  variant: EncryptedDeeplinkWalletId,
  pairing: string,
): Promise<{ url: string; dataUrl: string; relayError: string | null }> {
  const appUrl = QR_CONNECT_APP_URL;
  const redirect = new URL('/qr-connect', appUrl);
  redirect.searchParams.set('wallet', variant);
  redirect.searchParams.set('pairing', pairing);
  redirect.searchParams.set('phase', 'connect');
  const keypair = generatePhantomConnectKeypair();
  const url = variant === 'phantom'
    ? buildPhantomConnectUrl({
        dappPublicKey: keypair.publicKey,
        redirectLink: redirect.toString(),
        cluster: state.cluster,
        appUrl,
      })
    : buildSolflareConnectUrl({
        dappPublicKey: keypair.publicKey,
        redirectLink: redirect.toString(),
        cluster: state.cluster,
        appUrl,
      });
  const dataUrl = await renderUrlQrDataUrl(url);
  if (!dataUrl) {
    throw new Error('QR image generation failed.');
  }
  let relayError: string | null = null;
  try {
    await registerDesktopDeeplinkPairing(pairing, {
      wallet: variant,
      cluster: state.cluster,
      appUrl,
      dappPublicKey: keypair.publicKey,
      dappSecretKey: keypair.secretKey,
    });
  } catch (err) {
    relayError = desktopPairingRelaySetupError(err);
  }
  return { url, dataUrl, relayError };
}

async function registerDesktopDeeplinkPairing(
  pairingUuid: string,
  metadata: {
    wallet: EncryptedDeeplinkWalletId;
    cluster: Cluster;
    appUrl: string;
    dappPublicKey: string;
    dappSecretKey: string;
  },
): Promise<void> {
  const response = await fetch(`${PAIRING_RELAY_BASE_URL}/api/pair/${encodeURIComponent(pairingUuid)}/deeplink`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(metadata),
  });
  if (!response.ok) {
    const payload = (await response.json().catch(() => ({}))) as { error?: string; message?: string };
    throw new Error(payload.error || payload.message || `Pairing relay returned ${response.status}.`);
  }
}

function desktopPairingRelaySetupError(err: unknown): string {
  const message = err instanceof Error ? err.message : String(err);
  if (message === 'method_not_allowed' || message.includes('method_not_allowed')) {
    return 'Pairing relay does not support deeplink metadata. Restart local dev with the updated relay or deploy the render-web pairing route.';
  }
  return message;
}

function handleDesktopQrWalletSelect(wallet: DesktopQrWallet): void {
  if (desktopConnect.flow.qrWallet === wallet) return;
  if ((wallet === 'backpack' || wallet === 'jupiter') && !WALLETCONNECT_PROJECT_ID) {
    pushToast(
      'error',
      t('WalletConnect not configured'),
      tf('Set {envVar} before launching to enable Backpack or Jupiter mobile pairing.', { envVar: 'VITE_AGENTIC_WC_PROJECT_ID' }),
    );
    return;
  }
  // Tear down any prior WC session before launching a new one — switching
  // from Backpack → Jupiter (or back via the picker) should start a fresh
  // URI rather than reuse a stale topic. Also clear any prior pairing.
  if (walletConnect.overlay.mode !== 'closed') {
    cancelWalletConnectPairing();
  }
  stopDesktopPairing();
  desktopConnect.deeplinkQr = { variant: null, dataUrl: null, url: null, relayError: null };
  dispatchDesktopConnectFlow({ type: 'pickQrWallet', wallet });
  if (wallet === 'backpack' || wallet === 'jupiter') {
    // Backpack/Jupiter scan the raw WalletConnect URI.
    void handleScanQrAnyWallet(wallet);
    return;
  }
  // Phantom/Solflare — start a cross-device encrypted-deeplink pairing,
  // encode the UUID into the wallet universal-link, and begin polling the
  // relay so we can adopt the wallet when the phone reports its address.
  const pairingUuid = generatePairingUuid();
  desktopConnect.pairing = {
    uuid: pairingUuid,
    wallet,
    pollHandle: null,
    startedAt: Date.now(),
    warnedTimeout: false,
  };
  desktopConnect.deeplinkQr = { variant: wallet, dataUrl: null, url: null, relayError: null };
  void buildDesktopVariantQr(wallet, pairingUuid).then(({ url, dataUrl, relayError }) => {
    // Race-safety: the user may have switched away while we were generating.
    if (desktopConnect.flow.qrWallet !== wallet) return;
    if (desktopConnect.pairing?.uuid !== pairingUuid) return;
    desktopConnect.deeplinkQr = { variant: wallet, url, dataUrl, relayError };
    if (relayError) {
      stopDesktopPairing();
      pushToast(
        'error',
        tf('Could not prepare {wallet} relay', { wallet: wallet === 'phantom' ? 'Phantom' : 'Solflare' }),
        relayError,
      );
      render();
      return;
    }
    startDesktopPairingPoll(pairingUuid, wallet);
    render();
  }).catch((err) => {
    if (desktopConnect.flow.qrWallet !== wallet) return;
    if (desktopConnect.pairing?.uuid !== pairingUuid) return;
    stopDesktopPairing();
    desktopConnect.deeplinkQr = { variant: null, url: null, dataUrl: null, relayError: null };
    pushToast(
      'error',
      tf('Could not prepare {wallet} QR', { wallet: wallet === 'phantom' ? 'Phantom' : 'Solflare' }),
      err instanceof Error ? err.message : String(err),
    );
    render();
  });
}

/** Returns a v4 UUID. Uses the crypto API in modern browsers; falls back
 *  to a manual base16 polyfill on older WebViews (the Tauri WebKit
 *  baseline ships `crypto.randomUUID` on recent macOS but we don't want
 *  to crash on older Linux builds). */
function generatePairingUuid(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  bytes[6] = (bytes[6]! & 0x0f) | 0x40; // version 4
  bytes[8] = (bytes[8]! & 0x3f) | 0x80; // variant 10
  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

function stopDesktopPairing(): void {
  if (desktopConnect.pairing?.pollHandle !== null && desktopConnect.pairing?.pollHandle !== undefined) {
    window.clearInterval(desktopConnect.pairing.pollHandle);
  }
  desktopConnect.pairing = null;
}

function startDesktopPairingPoll(uuid: string, wallet: EncryptedDeeplinkWalletId): void {
  if (!desktopConnect.pairing || desktopConnect.pairing.uuid !== uuid) return;
  desktopConnect.pairing.pollHandle = window.setInterval(() => {
    void pollPairingHost(uuid, wallet);
  }, PAIRING_POLL_INTERVAL_MS);
}

async function pollPairingHost(uuid: string, wallet: EncryptedDeeplinkWalletId): Promise<void> {
  // Confirm we're still polling for this exact pairing — user may have
  // pressed Back or switched wallets during the in-flight request.
  if (desktopConnect.pairing?.uuid !== uuid) return;
  let response: Response;
  try {
    response = await fetch(`${PAIRING_RELAY_BASE_URL}/api/pair/${encodeURIComponent(uuid)}/host`, {
      method: 'GET',
      headers: { accept: 'application/json' },
    });
  } catch {
    // Network blip — keep polling. Don't toast on every miss.
    maybeWarnPairingTimeout();
    return;
  }
  maybeWarnPairingTimeout();
  if (response.status === 404) return;
  if (!response.ok) {
    console.warn(`[pairing] relay returned ${response.status}`);
    return;
  }
  const payload = (await response.json().catch(() => null)) as
    | { address?: string; capabilities?: AdapterCapabilities; walletName?: string }
    | null;
  if (!payload?.address || !payload.capabilities || !payload.walletName) return;
  if (desktopConnect.pairing?.uuid !== uuid) return;
  await adoptPairedWallet({
    address: payload.address,
    capabilities: payload.capabilities,
    walletName: payload.walletName,
    pairingUuid: uuid,
    wallet,
  });
}

function maybeWarnPairingTimeout(): void {
  const p = desktopConnect.pairing;
  if (!p || p.warnedTimeout) return;
  if (Date.now() - p.startedAt < PAIRING_TIMEOUT_MS) return;
  p.warnedTimeout = true;
  pushToast(
    'pending',
    t('Still waiting…'),
    t('Open your wallet on the phone and finish approving the connection.'),
  );
}

async function adoptPairedWallet(input: {
  address: string;
  capabilities: AdapterCapabilities;
  walletName: string;
  pairingUuid: string;
  wallet: EncryptedDeeplinkWalletId;
}): Promise<void> {
  // Stamp the latch BEFORE the pairing-state guard so that even if two polls
  // race past `stopDesktopPairing` (which runs synchronously on the first
  // call but only after this check) we still adopt at most once per UUID.
  if (desktopConnect.adoptedPairings.has(input.pairingUuid)) return;
  desktopConnect.adoptedPairings.add(input.pairingUuid);
  if (desktopConnect.pairing?.uuid !== input.pairingUuid) return;
  stopDesktopPairing();
  walletBackend = new RemoteRelayBackend({
    baseUrl: PAIRING_RELAY_BASE_URL,
    pairingUuid: input.pairingUuid,
  });
  client = new SolanaSigningClient({
    backend: walletBackend,
    pollIntervalMs: QR_RELAY_SIGN_POLL_INTERVAL_MS,
  });
  state.address = input.address;
  state.capabilities = input.capabilities;
  state.selectedWalletName = input.walletName;
  state.selectedWalletLogoId = walletProviderLogoIdForName(input.wallet) ?? input.wallet;
  state.selectedWalletIcon = undefined;
  // The cloud-relay path does NOT activate the local Tauri bridge — the
  // signer lives on the phone, not on this machine.
  state.bridgeActive = false;
  state.bridgeStatus = 'Signing through cloud pairing relay.';
  state.transactionStatus = `Wallet paired via your phone on ${state.cluster}.`;
  rememberWalletPathSession({
    path: 'qr',
    address: input.address,
    walletName: input.walletName,
    walletBrandId: input.wallet,
  });
  try {
    await afterWalletConnected();
  } catch (err) {
    console.warn('[adoptPairedWallet] afterWalletConnected failed', err);
  }
  savePersistedState();
  trackWalletConnectSuccess(walletConnectSurface(), state.cluster, 'qr_pairing_relay');
  pushToast('success', tf('Connected via your phone - {walletName}', { walletName: input.walletName }), short(input.address));
  dispatchDesktopConnectFlow({ type: 'reset' });
}

function desktopBrowserConnectUrl(brandId?: string | null): string {
  const walletBrand = brandId?.trim() || undefined;
  return buildDesktopBrowserConnectUrl({
    walletHostUrl: inferredWalletHostUrl({ route: '/connect', wallet: walletBrand }),
    bridgeUrl: state.bridgeUrl,
    bridgeToken: state.bridgeToken,
    ...(walletBrand ? { walletBrand } : {}),
  });
}

function desktopBrowserSignUrl(requestId: string): string {
  const walletBrand =
    state.walletPathSession?.path === 'desktop-browser-extension'
      ? state.walletPathSession.walletBrandId
      : browserWalletBrandIdForName(state.selectedWalletName);
  return buildDesktopBrowserIntentUrl({
    walletHostUrl: inferredWalletHostUrl({ route: '/sign', wallet: walletBrand }),
    bridgeUrl: state.bridgeUrl,
    bridgeToken: state.bridgeToken,
    ...(walletBrand ? { walletBrand } : {}),
    ...(state.address ? { walletAddress: state.address } : {}),
    intent: 'sign',
    requestId,
  });
}

async function openDesktopBrowserSignPage(approval: ApprovalResource): Promise<void> {
  if (!state.tauriNativeEnvironment.isTauriNative) return;
  if (!state.bridgeUrl || !state.bridgeToken) {
    throw new ProtocolError('wallet_unreachable', 'Wallet approval page could not be opened because the local wallet service is not ready.');
  }
  const requestId = String(approval.requestId ?? '').trim();
  if (!requestId) {
    throw new ProtocolError('invalid_request', 'Wallet approval page could not be opened because the signing request is missing an id.');
  }
  const target = desktopBrowserSignUrl(requestId);
  try {
    await tauriNativeOpenExternalUrl(target);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    pushToast('error', t('Could not open approval page'), message);
    throw err;
  }
}

async function openDesktopBrowserConnectPage(brandId?: string | null): Promise<void> {
  // The Rust side rotates the legacy `local-agent-wallet` token to a per-install
  // random one (lib.rs:1129). The webview mirrors that via
  // syncBridgeConfigFromTauriStatus, but bootstrap fires that sync async; if the
  // user clicks before it lands, the URL goes out with a stale/empty token, the
  // external browser POSTs /bridge/connect with the wrong header, the bridge
  // 401s, and the desktop poll spins forever. Awaiting start_bridge here (it's
  // idempotent on the Rust side) guarantees we have the live token + URL.
  let status: TauriBridgeStatus | null = state.tauriBridgeStatus;
  if (state.tauriNativeEnvironment.isTauriNative) {
    status = await tauriNativeStartBridge();
    if (status) {
      state.tauriBridgeStatus = status;
      syncBridgeConfigFromTauriStatus(status);
    }
    if (!isDesktopBridgeReady(status)) {
      const detail = desktopBridgeNotReadyMessage(status, tauriNativeLastBridgeError());
      pushToast('error', t('Wallet service not ready'), detail);
      dispatchDesktopConnectFlow({ type: 'reset' });
      return;
    }
  }
  if (!state.bridgeUrl || !state.bridgeToken) {
    const detail = desktopBridgeNotReadyMessage(status, tauriNativeLastBridgeError());
    pushToast('error', t('Wallet service not ready'), detail);
    dispatchDesktopConnectFlow({ type: 'reset' });
    return;
  }
  const target = desktopBrowserConnectUrl(brandId);
  void tauriNativeOpenExternalUrl(target).catch((err) => {
    pushToast(
      'error',
      t('Could not open browser'),
      err instanceof Error ? err.message : String(err),
    );
  });
  dispatchDesktopConnectFlow({
    type: 'beginAwaitingBrowser',
    brandId: brandId ?? null,
    startedAt: Date.now(),
  });
  startAwaitingBrowserPoll(brandId ?? null);
}

const AWAITING_BROWSER_POLL_INTERVAL_MS = 1500;
const AWAITING_BROWSER_TIMEOUT_MS = 5 * 60 * 1000;
const AWAITING_BROWSER_MAX_CONSECUTIVE_401 = 3;

function startAwaitingBrowserPoll(brandId?: string | null): void {
  // Idempotent: a previous poll (e.g. from a prior Reopen) must be cancelled
  // before we start a new one so we don't double-fire detection.
  stopDesktopConnectPoll();
  if (!state.bridgeUrl || !state.bridgeToken) {
    // No bridge config means we can't poll. Surface a soft notice; the user
    // can still confirm via Back/Reopen. The Local-runtime panel exposes the
    // bridge sidecar controls.
    pushToast(
      'pending',
      t('Wallet service not ready'),
      t('Restart Agentic Desktop, then reopen the browser wallet connection.'),
    );
    return;
  }
  let timedOut = false;
  let consecutive401 = 0;
  const onPollError = (err: unknown): 'stop' | 'continue' => {
    // 401 means the webview's bridgeToken doesn't match the bridge's rotated
    // token — no amount of waiting will fix that. Surface it instead of
    // silently spinning so the user can restart the runtime.
    if (err instanceof BridgeRequestError && err.status === 401) {
      consecutive401 += 1;
      if (consecutive401 >= AWAITING_BROWSER_MAX_CONSECUTIVE_401) {
        pushToast(
          'error',
          t('Wallet connection expired'),
          t('Restart Agentic Desktop, then try connecting the browser wallet again.'),
        );
        return 'stop';
      }
    } else {
      consecutive401 = 0;
    }
    return 'continue';
  };
  desktopConnect.pollHandle = window.setInterval(() => {
    // Stop polling if the user navigated away from the awaiting screen.
    if (desktopConnect.flow.step !== 'awaiting-browser') {
      stopDesktopConnectPoll();
      return;
    }
    const startedAt = desktopConnect.flow.awaitingBrowserStartedAt ?? Date.now();
    if (!timedOut && Date.now() - startedAt > AWAITING_BROWSER_TIMEOUT_MS) {
      timedOut = true;
      pushToast(
        'pending',
        t('Still waiting…'),
        t('The browser hasn\'t reported a connection yet. Check the wallet popup or click Reopen browser.'),
      );
      // Continue polling — user may eventually complete the flow.
    }
    void pollBridgeForHost(brandId ?? null, onPollError);
  }, AWAITING_BROWSER_POLL_INTERVAL_MS);
  void pollBridgeForHost(brandId ?? null, onPollError);
}

async function pollBridgeForHost(
  brandId: string | null,
  onError: (err: unknown) => 'stop' | 'continue',
): Promise<void> {
  let capabilities: AdapterCapabilities;
  try {
    capabilities = await bridgeRequest<AdapterCapabilities>('/bridge/status');
  } catch (err) {
    // Persistent 401s short-circuit polling (onError pushes a toast). Other
    // errors (sidecar restarting, network blip) keep retrying on the next tick.
    if (onError(err) === 'stop') {
      stopDesktopConnectPoll();
    }
    return;
  }
  const address = capabilities.address?.trim();
  if (!address) return;
  if (brandId) {
    const walletName = capabilities.walletName?.trim() ?? '';
    if (walletName && !browserWalletNameMatchesBrand(walletName, brandId)) {
      const expected = DESKTOP_BRAND_PANELS.find((brand) => brand.id === brandId)?.name ?? brandId;
      state.bridgeStatus = `Waiting for ${expected}; browser reported ${walletName}.`;
      render();
      return;
    }
  }
  // Detection: a host has registered with the bridge. Stop the poll, adopt.
  stopDesktopConnectPoll();
  await adoptBridgeHost(address, capabilities, brandId ?? null);
}

function bridgeWalletProviderName(
  capabilities: AdapterCapabilities,
  brand: (typeof DESKTOP_BRAND_PANELS)[number] | undefined,
): string {
  return capabilities.walletName?.trim() || brand?.name || '';
}

function bridgeWalletLogoIdForProvider(
  capabilities: AdapterCapabilities,
  providerName: string,
): WalletProviderLogoId | undefined {
  if (isWalletProviderLogoId(capabilities.walletLogoId)) {
    return capabilities.walletLogoId;
  }
  return walletProviderLogoIdForName(providerName);
}

function bridgeWalletIconForProvider(
  capabilities: AdapterCapabilities,
  logoId: WalletProviderLogoId | undefined,
): string | undefined {
  if (logoId) return undefined;
  const icon = capabilities.walletIcon?.trim();
  return icon || undefined;
}

async function adoptBridgeHost(
  address: string,
  capabilities: AdapterCapabilities,
  brandId?: string | null,
): Promise<void> {
  // Race-safety: if the user clicked Back while the poll was in-flight, drop
  // the adoption — they no longer want it.
  if (desktopConnect.flow.step !== 'awaiting-browser') return;
  if (!state.bridgeUrl || !state.bridgeToken) return;
  walletBackend = new RemoteBridgeBackend({
    bridgeUrl: state.bridgeUrl,
    token: state.bridgeToken,
    onPendingApproval: openDesktopBrowserSignPage,
  });
  client = new SolanaSigningClient({ backend: walletBackend });
  const brand = brandId ? DESKTOP_BRAND_PANELS.find((b) => b.id === brandId) : undefined;
  const providerName = bridgeWalletProviderName(capabilities, brand);
  const logoId = bridgeWalletLogoIdForProvider(capabilities, providerName);
  state.address = address;
  state.capabilities = capabilities;
  state.selectedWalletName = providerName || 'Browser wallet';
  state.selectedWalletLogoId = logoId;
  state.selectedWalletIcon = bridgeWalletIconForProvider(capabilities, logoId);
  state.bridgeActive = true;
  state.bridgeAutoReconnect = true;
  state.bridgeStatus = providerName
    ? `Browser wallet connected through ${providerName}.`
    : 'Browser wallet connected to Agentic Desktop.';
  state.transactionStatus = `Wallet connected via browser on ${state.cluster}.`;
  rememberWalletPathSession({
    path: 'desktop-browser-extension',
    address,
    walletName: state.selectedWalletName,
    walletBrandId: brandId ?? browserWalletBrandIdForName(providerName),
  });
  startBridgePolling();
  try {
    await afterWalletConnected();
  } catch (err) {
    console.warn('[adoptBridgeHost] afterWalletConnected failed', err);
  }
  savePersistedState();
  trackWalletConnectSuccess('tauri_native', state.cluster, 'browser_extension_auto');
  pushToast('success', t('Wallet connected via browser'), short(address));
  dispatchDesktopConnectFlow({ type: 'reset' });
}

function handleDesktopBack(): void {
  const step = desktopConnect.flow.step;
  const qrWallet = desktopConnect.flow.qrWallet;
  if (step === 'qr') {
    // Back always tears down any active WC session and clears the deeplink
    // cache. The reducer decides whether we land back on the picker
    // (qrWallet was set) or pop out to the method picker (already on picker).
    if (walletConnect.overlay.mode !== 'closed') {
      cancelWalletConnectPairing();
    }
    if (qrWallet !== null) {
      desktopConnect.deeplinkQr = { variant: null, dataUrl: null, url: null, relayError: null };
    }
    // Cancel any in-flight cross-device pairing — the user is no longer
    // expecting a phone connection for this UUID.
    stopDesktopPairing();
  }
  if (step === 'ledger') {
    stopLedgerPoll();
    ledger.pairingToken += 1;
    dispatchLedgerOverlay({ type: 'close' });
  }
  if (step === 'awaiting-browser') {
    stopDesktopConnectPoll();
  }
  dispatchDesktopConnectFlow({ type: 'back' });
}

function handleDesktopAwaitingRetry(): void {
  void openDesktopBrowserConnectPage(desktopConnect.flow.selectedBrandId);
}

async function connectBrowserExtensionBrand(brandId: DesktopQrWallet): Promise<void> {
  const brandLabel = DESKTOP_BRAND_PANELS.find((brand) => brand.id === brandId)?.name ?? brandId;
  let selected = false;
  await run('discover', async () => {
    discoverBrowserWallets({ resetSelection: true });
    const candidate = discoveredWalletForBrand(brandId);
    if (!candidate) {
      throw new Error(`${brandLabel} extension not found in this browser. Install or unlock ${brandLabel}, then try again.`);
    }
    state.selectedWalletName = candidate.name;
    state.selectedWalletLogoId = walletProviderLogoIdForName(candidate.name);
    state.selectedWalletIcon = candidate.icon;
    state.browserWalletPickerOpen = false;
    selected = true;
  });
  if (!selected) return;
  await runConnect();
}

function handleDesktopExtensionWalletSelect(brandId: DesktopQrWallet): void {
  if (desktopConnect.flow.step !== 'extension') return;
  if (state.tauriNativeEnvironment.isTauriNative) {
    void openDesktopBrowserConnectPage(brandId);
    return;
  }
  void connectBrowserExtensionBrand(brandId);
}

function bindDesktopConnectFlow(): void {
  if (!multiPathWalletFlowAvailable()) return;
  for (const el of document.querySelectorAll<HTMLElement>('[data-desktop-flow-action]')) {
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      const raw = el.dataset.desktopFlowAction ?? '';
      if (raw === 'back') {
        handleDesktopBack();
        return;
      }
      if (raw.startsWith('method:')) {
        const m = raw.slice('method:'.length) as DesktopConnectMethod;
        if (m === 'extension' || m === 'qr' || m === 'ledger') {
          handleDesktopMethodSelect(m);
        }
        return;
      }
      if (raw === 'pick-qr-wallet') {
        const w = el.dataset.desktopQrWallet;
        if (w === 'backpack' || w === 'jupiter' || w === 'phantom' || w === 'solflare') {
          handleDesktopQrWalletSelect(w);
        }
        return;
      }
      if (raw === 'pick-extension-wallet') {
        const w = el.dataset.desktopExtensionWallet;
        if (w === 'backpack' || w === 'jupiter' || w === 'phantom' || w === 'solflare') {
          handleDesktopExtensionWalletSelect(w);
        }
        return;
      }
      if (raw === 'awaiting-retry') {
        handleDesktopAwaitingRetry();
        return;
      }
    });
  }
}

function handleBrowserWalletSelectChange(select: HTMLSelectElement): void {
  const walletName = select.value;
  if (!walletName) return;
  notifyLocalWorkspaceBackupReminder('Back up before switching wallet selection.');
  state.selectedWalletName = walletName;
  const selected = discoveredWalletByName(walletName);
  state.selectedWalletLogoId = walletProviderLogoIdForName(selected?.name ?? walletName);
  state.selectedWalletIcon = selected?.icon;
  state.browserWalletPickerOpen = false;
  clearBrowserWalletSession();
  clearWalletPathSession();

  const inlineBrowserExtensionSelection =
    select.id === BROWSER_EXTENSION_WALLET_SELECT_ID &&
    multiPathWalletFlowAvailable() &&
    desktopConnect.flow.step === 'extension' &&
    !state.address;
  if (inlineBrowserExtensionSelection) {
    state.error = '';
    savePersistedState();
    render();
    return;
  }

  resetWalletConnection();
  void clearDeviceAgentForWalletBoundary();
  void signOutCloudSessionForWalletBoundary('wallet-changed', { toast: true }).then((signedOut) => {
    if (signedOut) render();
  });
  state.error = '';
  savePersistedState();
  render();
}

// Selection side effects shared by the dev-controls <select> change handler and
// the public iOS "Connect wallet" dropdown: tear down any prior wallet boundary,
// set the selected provider, and (for Jupiter) pre-request the return
// notification permission. Does NOT render — callers render/connect afterwards.
async function applyIosWalletSelection(walletId: IosNativeWalletId): Promise<void> {
  notifyLocalWorkspaceBackupReminder('Back up before switching wallet selection.');
  await disconnectWalletBackend().catch(() => undefined);
  resetWalletConnection();
  await clearDeviceAgentForWalletBoundary();
  state.selectedIosWalletId = walletId;
  state.selectedWalletName = iosWalletLabel(walletId);
  state.selectedWalletLogoId = walletProviderLogoIdForName(state.selectedWalletName);
  state.selectedWalletIcon = undefined;
  if (walletId === 'jupiter') {
    // Request return-notification permission the moment Jupiter is selected — before
    // any connect/sign bounce — so the native bridge's "tap to return to Agentic"
    // notification can fire after the user approves in Jupiter. Fire-and-forget; the
    // connect flow also ensures this resolves before the first bounce.
    state.jupiterReturnNotifyStatus = undefined;
    void iosNativeEnsureReturnNotificationPermission().then((status) => {
      state.jupiterReturnNotifyStatus = status;
    });
  }
  void signOutCloudSessionForWalletBoundary('wallet-changed', { toast: true }).then((signedOut) => {
    if (signedOut) render();
  });
  state.error = '';
  savePersistedState();
}

async function handleIosWalletSelectChange(select: HTMLSelectElement): Promise<void> {
  const walletId = select.value;
  if (!isIosNativeWalletId(walletId)) return;
  await applyIosWalletSelection(walletId);
  render();
}

// Public iOS flow: the user picked a provider from the "Connect wallet" dropdown
// — select it (if changed) and connect in one tap.
async function chooseIosWalletAndConnect(walletId: string): Promise<void> {
  if (!isIosNativeWalletId(walletId)) return;
  state.iosConnectWalletMenuOpen = false;
  if (walletId !== state.selectedIosWalletId) {
    await applyIosWalletSelection(walletId);
  }
  await runConnect();
}

// Delegated (install-once) handler for the iOS "Connect wallet" dropdown: toggle,
// row select→connect, outside-click close, Escape close. Delegation survives the
// per-render markup rebuild and covers the dynamically-rendered provider rows.
let iosConnectWalletHandlerInstalled = false;
function installIosConnectWalletHandler(): void {
  if (iosConnectWalletHandlerInstalled || typeof document === 'undefined') return;
  iosConnectWalletHandlerInstalled = true;
  document.addEventListener('click', (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const toggle = target.closest<HTMLButtonElement>('[data-ios-connect-toggle]');
    if (toggle) {
      event.preventDefault();
      if (toggle.disabled) return;
      state.iosConnectWalletMenuOpen = !state.iosConnectWalletMenuOpen;
      render();
      return;
    }
    const option = target.closest<HTMLElement>('[data-ios-connect-wallet-id]');
    if (option) {
      event.preventDefault();
      const walletId = option.getAttribute('data-ios-connect-wallet-id');
      if (walletId) void chooseIosWalletAndConnect(walletId);
      return;
    }
    if (state.iosConnectWalletMenuOpen && !target.closest('[data-ios-connect-wallet]')) {
      state.iosConnectWalletMenuOpen = false;
      render();
    }
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && state.iosConnectWalletMenuOpen) {
      state.iosConnectWalletMenuOpen = false;
      render();
    }
  });
}

