function bindEmbeddedWalletOverlay(): void {
  if (embeddedWallet.overlay.mode === 'closed') return;
  for (const el of document.querySelectorAll<HTMLElement>('[data-embedded-wallet-action]')) {
    const action = el.dataset.embeddedWalletAction;
    if (action === 'acknowledge-phrase') {
      bindOnce(el, 'change', () => {
        setEmbeddedWalletAcknowledge((el as HTMLInputElement).checked);
      });
      continue;
    }
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      handleEmbeddedWalletAction(action);
    });
  }
  for (const el of document.querySelectorAll<HTMLElement>('[data-embedded-wallet-tab]')) {
    bindOnce(el, 'click', (event) => {
      event.preventDefault();
      setEmbeddedWalletTab(el.dataset.embeddedWalletTab ?? '');
    });
  }
  for (const el of document.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>(
    '[data-embedded-wallet-field]',
  )) {
    bindOnce(el, 'input', () => {
      setEmbeddedWalletField(el.dataset.embeddedWalletField ?? '', el.value);
    });
  }
  for (const form of document.querySelectorAll<HTMLFormElement>(
    'form[data-embedded-wallet-form]',
  )) {
    bindOnce(form, 'submit', (event) => {
      event.preventDefault();
      void submitEmbeddedWalletForm();
    });
  }
}

function captureMobileRailRenderSnapshot(): MobileRailRenderSnapshot | null {
  const sheet = state.activeMobileRailSheet;
  if (!sheet || typeof document === 'undefined') return null;
  const root = document.querySelector<HTMLElement>('[data-mobile-rail-sheet-root]');
  const body = document.querySelector<HTMLElement>('.mobile-rail-sheet-body');
  if (!root || !body) return null;
  const snapshot: MobileRailRenderSnapshot = {
    sheet,
    scrollTop: body.scrollTop,
  };
  const active = document.activeElement;
  if (
    active instanceof HTMLElement &&
    root.contains(active) &&
    (active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement)
  ) {
    if (active.id) {
      snapshot.focusSelector = `#${cssEscape(active.id)}`;
    }
    snapshot.selectionStart = active.selectionStart;
    snapshot.selectionEnd = active.selectionEnd;
  }
  return snapshot;
}

function restoreMobileRailRenderSnapshot(snapshot: MobileRailRenderSnapshot | null): void {
  if (!snapshot || state.activeMobileRailSheet !== snapshot.sheet || typeof document === 'undefined') return;
  const apply = () => {
    if (state.activeMobileRailSheet !== snapshot.sheet) return;
    const body = document.querySelector<HTMLElement>('.mobile-rail-sheet-body');
    if (body) body.scrollTop = snapshot.scrollTop;
    if (!snapshot.focusSelector) return;
    const target = document.querySelector<HTMLInputElement | HTMLTextAreaElement>(snapshot.focusSelector);
    if (!target) return;
    // Flag is read synchronously by the rail focusin listener (focus dispatches the
    // event inline) so it skips the smooth re-center that would defeat preventScroll.
    restoringMobileRailFocus = true;
    try {
      target.focus({ preventScroll: true });
    } finally {
      restoringMobileRailFocus = false;
    }
    if (
      typeof snapshot.selectionStart === 'number' &&
      typeof snapshot.selectionEnd === 'number' &&
      typeof target.setSelectionRange === 'function'
    ) {
      target.setSelectionRange(snapshot.selectionStart, snapshot.selectionEnd);
    }
  };
  apply();
  window.requestAnimationFrame(apply);
}

interface PlannerInputSnapshot {
  focusSelector: string;
  selectionStart: number | null;
  selectionEnd: number | null;
}

// Preserve the focused connector-form input (id + caret) across the full innerHTML rebuild. The chat
// surfaces morph (skipping the focused input) and the mobile-rail sheet has its own snapshot, but a
// plain full render on the New Request tab otherwise drops the caret + dismisses the mobile keyboard
// for any [data-template-field] input — which the live borrow health panel's debounced render() would
// trigger mid-typing. Generalized so every connector form benefits, not just borrow.
function capturePlannerInputSnapshot(): PlannerInputSnapshot | null {
  if (typeof document === 'undefined') return null;
  const active = document.activeElement;
  if (!(active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement)) return null;
  if (!active.hasAttribute('data-template-field') || !active.id) return null;
  return {
    focusSelector: `#${cssEscape(active.id)}`,
    selectionStart: active.selectionStart,
    selectionEnd: active.selectionEnd,
  };
}

function restorePlannerInputSnapshot(snapshot: PlannerInputSnapshot | null): void {
  if (!snapshot || typeof document === 'undefined') return;
  // Inside a mobile-rail sheet the rail snapshot already owns focus restoration (with its own
  // preventScroll + re-center suppression); don't double-focus.
  if (state.activeMobileRailSheet) return;
  const target = document.querySelector<HTMLInputElement | HTMLTextAreaElement>(snapshot.focusSelector);
  if (!target || !target.hasAttribute('data-template-field') || document.activeElement === target) return;
  target.focus({ preventScroll: true });
  if (
    typeof snapshot.selectionStart === 'number' &&
    typeof snapshot.selectionEnd === 'number' &&
    typeof target.setSelectionRange === 'function'
  ) {
    target.setSelectionRange(snapshot.selectionStart, snapshot.selectionEnd);
  }
}

async function withMobileSheetCleanupTimeout<T>(promise: Promise<T>, label: string): Promise<T> {
  let timeoutId: number | undefined;
  try {
    return await Promise.race([
      promise,
      new Promise<never>((_, reject) => {
        timeoutId = window.setTimeout(() => {
          reject(new Error(`${label} timed out. Close and reopen this sheet, then try again.`));
        }, MOBILE_SHEET_CLEANUP_TIMEOUT_MS);
      }),
    ]);
  } finally {
    if (timeoutId !== undefined) window.clearTimeout(timeoutId);
  }
}

function syncBodyScrollLockDatasets(route: AppRoute | null): void {
  if (typeof document === 'undefined' || !document.body) return;
  const mobileViewport = isMobileAppViewport();
  const currentMobileRailSheet = state.activeMobileRailSheet;
  if (
    currentMobileRailSheet &&
    shouldApplyMobileRailBodyDataset({
      activeTab: state.activeTab,
      mobileViewport,
      route,
      sheet: currentMobileRailSheet,
    })
  ) {
    document.body.dataset.mobileRailSheet = currentMobileRailSheet;
  } else {
    delete document.body.dataset.mobileRailSheet;
  }
  if (mobileViewport && state.activeExpandNoteField) {
    document.body.dataset.expandNoteSheet = state.activeExpandNoteField.kind;
  } else {
    delete document.body.dataset.expandNoteSheet;
  }
  // iOS-only: lock the OUTER webview scroll while on the Chat tab. Older binaries used
  // ios.contentInset:'automatic', where a scrollable 100dvh body could make iOS pump the adjusted
  // inset and visually jitter. New binaries own safe areas in CSS, but the chat route still uses the
  // same fixed outer frame so the inner .chat-transcript is the only scroll owner. Android/web never
  // get the flag.
  if (IS_IOS_APP && mobileViewport && state.activeTab === 'chat') {
    document.body.dataset.chatRoute = '1';
  } else {
    delete document.body.dataset.chatRoute;
  }
}

function reconcileBodyScrollLockDatasetsAfterRender(): void {
  if (typeof document === 'undefined' || !document.body) return;
  if (document.body.dataset.mobileRailSheet && !document.querySelector('[data-mobile-rail-sheet-root]')) {
    state.activeMobileRailSheet = null;
    delete document.body.dataset.mobileRailSheet;
  }
  if (document.body.dataset.expandNoteSheet && !document.querySelector('[data-expand-note-root]')) {
    state.activeExpandNoteField = null;
    delete document.body.dataset.expandNoteSheet;
  }
  // Belt-and-suspenders: if the chat panel is no longer mounted (tab switch, chat→overview
  // auto-redirect) restore normal outer scroll even if a render path missed clearing the flag.
  if (document.body.dataset.chatRoute && !document.querySelector('[data-chat-scroll]')) {
    delete document.body.dataset.chatRoute;
  }
}

// ─────────────────────────────────────────────────────────────────────────

// ── Chat-tab in-place morph render ────────────────────────────────────────
// The app normally paints by replacing appRoot.innerHTML, which destroys and recreates every
// node — a visible blink on Android/iOS and a scrollTop reset that makes the transcript jump.
// For the Chat tab we instead morph the new #workspace markup onto the live DOM (domMorph.ts)
// so node identity — and with it focus, scroll, text selection and CSS animation state —
// survives. Only the chat panel + the two bottom sheets are touched; the non-chat subtrees
// (rail, tab bars, request-context) are left exactly as they were so their (non-idempotent)
// listeners stay intact without a rebind.
const WORKSPACE_MORPH_SKIP_SELECTOR = [
  '[data-morph-skip]',
  // Imperatively-mounted panels + canvases must NOT be reconciled away (their DOM is owned by JS,
  // not the HTML string). Everything else in #workspace is morphed for every tab.
  '[data-plan-connector-pairing-panel]',
  '[data-connector-keys-panel]',
  '[data-tauri-local-runtime-panel]',
  'canvas',
].join(',');

let lastRenderedChatOutsideWorkspaceHtml = '';
let lastRenderedPageShellModalSignature = '';

// Markup the full render path appends AFTER #workspace: the toast stack (inside pageShell) and
// the four wallet overlays (appended at appRoot). The Chat morph only patches #workspace, so
// these must be unchanged for the fast path to be safe to take.
function chatOutsideWorkspaceHtml(): string {
  return embeddedWalletOverlayHtml(embeddedWallet.overlay)
    + walletConnectOverlayBlock()
    + ledgerOverlayBlock()
    + connectorConnectSurfaceHtml();
}

// The delete/confirm modals live in pageShell() OUTSIDE #workspace, so the Chat morph fast-path
// (which only patches #workspace + the toast stack) never paints them. Each builder returns '' when
// its modal is closed, so this signature flips the moment any modal opens or closes — letting
// canMorphActiveTab() fall back to a full render so the modal is actually injected/removed. NOTE:
// this string is compared only, never appended (the modals are already rendered inside pageShell).
function pageShellModalSignature(): string {
  return cloudWorkspaceDeleteModal()
    + completedDeleteModal()
    + generatedPlanDeleteModal()
    + inboxDeleteModal()
    + deleteAllInboxModal()
    + deleteAllCheckModal()
    + deleteAllRepeatsModal()
    + deleteAllDoneModal();
}

function bindWalletSurfaceControls(): void {
  bindEmbeddedWalletOverlay();
  bindDesktopBrandPanels();
  bindDesktopConnectFlow();
  bindWalletHostOpening();
  bindWalletConnectOverlay();
  bindLedgerOverlay();
  bindQrConnectPage();
}

// True when a render() can be served by the scoped in-place morph instead of a full rebuild:
// we're still on /app, its workspace DOM already exists (so every binder attached once on the
// first full paint), and nothing OUTSIDE #workspace (a toast / a wallet overlay) changed since
// the last paint. Serves BOTH the Chat tab AND any open mobile-rail bottom sheet — every sheet
// (AI Connector 'ai-drafting', workspace-storage, wallet-balances, connector-connect, chat-*)
// is rendered INSIDE #workspace via appWorkspace()→mobileRailBottomSheet(), so morphing it
// preserves node identity (focus/scroll/caret/value survive → no blink on any control tap).
function canMorphActiveTab(): boolean {
  if (!appRoot || typeof document === 'undefined') return false;
  if (currentRoute() !== '/app') return false;
  const sheetOpen = Boolean(state.activeMobileRailSheet);
  // Off the Chat tab, only morph while a bottom sheet is open — EXCEPT on iOS native, where EVERY
  // /app tab morphs so tab switches never rebuild the backdrop-filter dock/nav (the WKWebView blink).
  // Web/Android keep the full render path for non-chat/non-sheet tabs (isIosAppShellSurface() false).
  if (state.activeTab !== 'chat' && !sheetOpen && !isIosAppShellSurface()) return false;
  const workspace = document.getElementById('workspace');
  // Require the existing active panel so this is an in-tab update, not a first paint.
  // Route changes and anything OUTSIDE #workspace (a toast / a wallet overlay) take the
  // full render path.
  if (!workspace || !workspace.querySelector('[data-layout="active-panel"]')) return false;
  // A sheet-open morph off the Chat tab must be an IN-SHEET update, not the first paint that
  // injects the sheet — require the live sheet root so the opening render still takes the full
  // path (adding the sheet + playing its enter animation); subsequent taps then morph.
  if (sheetOpen && state.activeTab !== 'chat' && !workspace.querySelector('[data-mobile-rail-sheet-root]')) return false;
  if (chatOutsideWorkspaceHtml() !== lastRenderedChatOutsideWorkspaceHtml) return false;
  // A pageShell modal (delete confirm, etc.) opening/closing must take the full render path so the
  // modal — which lives outside #workspace — is actually painted/removed.
  if (pageShellModalSignature() !== lastRenderedPageShellModalSignature) return false;
  return true;
}

// SINGLE source of truth for post-render chat autoscroll. Called by BOTH the morph fast path
// (renderWorkspace) and the full-render path (restoreChatComposerAfterRender) — and nothing else —
// so the two can never again diverge into the sync+rAF double-snap that thrashed iOS (regressions
// #1–3). The snap decision lives in the pure decideChatAutoscroll(); there is exactly ONE deferred
// snap here, and chatScrollToBottom() is itself instant+idempotent. `domRecreated` is true only for
// the full path, whose innerHTML rebuild reset the transcript scrollTop to 0 — the morph path
// preserves scrollTop and passes false. Enforced by chatRenderInvariants.test.ts.
function applyChatAutoscrollAfterRender(domRecreated: boolean): void {
  const session = activeChatSession();
  const decision = decideChatAutoscroll({
    sessionId: session?.id ?? null,
    messageCount: session?.messages.length ?? 0,
    lastRenderedSessionId: lastRenderedChatSessionId,
    lastRenderedMessageCount: lastRenderedChatMsgCount,
    forceScrollBottom: chatForceScrollBottom,
  });
  lastRenderedChatSessionId = decision.nextSessionId;
  lastRenderedChatMsgCount = decision.nextMessageCount;
  if (decision.snapToBottom) {
    chatForceScrollBottom = false;
    // Full path rebuilt innerHTML (scrollTop reset to 0): snap synchronously BEFORE paint so the
    // transcript never flashes its top on entry. Instant (chatScrollToBottom forces
    // scroll-behavior:auto), so this plus the deferred re-snap land at the same scrollTop and never
    // animate-fight — that fight under scroll-behavior:smooth was the historic iOS jitter. The
    // morph path preserves scrollTop, so it skips the sync snap.
    if (domRecreated) chatScrollToBottom(true);
    // Cards/quotes settle their height a frame after layout; re-snap once so the last message is
    // fully in view even if a card grew. This is the ONLY deferred snap in the file.
    requestAnimationFrame(() => chatScrollToBottom(true));
  } else if (domRecreated) {
    // Full path with no new message: innerHTML was wiped → re-pin iff the user was at the bottom
    // pre-render (chatScrollPinned, captured in captureChatComposerSnapshot). The morph path
    // preserves scrollTop, so it passes false and does nothing here.
    chatScrollToBottom(false);
  }
}

function renderWorkspace(): void {
  const workspace = document.getElementById('workspace');
  if (!workspace) return;
  const onChatTab = state.activeTab === 'chat';

  // Leaving Chat via the (iOS-widened) morph path must cancel an in-flight stream, mirroring render()
  // — otherwise it keeps appending to a transcript the morph just replaced. Idempotent.
  if (!onChatTab && chatStreamActive()) cancelChatStream();

  // In-tab bookkeeping mirroring render(): keep the connector surface consistent and run the
  // sheet/expand-note lifecycle predicates.
  reconcileChatConnectorSession();
  const route = currentRoute();
  reconcileConnectorConnectSession(route);
  if (shouldClearActiveMobileRailSheet({
    activeTab: state.activeTab,
    mobileViewport: isMobileAppViewport(),
    route,
    sheet: state.activeMobileRailSheet,
  })) {
    if (state.activeMobileRailSheet === 'chat-action') {
      state.chatActionPicker = null;
      state.chatComposerOpen = false;
    }
    state.activeMobileRailSheet = null;
  }
  if (state.activeExpandNoteField && !isMobileAppViewport()) {
    state.activeExpandNoteField = null;
  }

  // Close transient menus + ABORT the sheets' bind-time AbortControllers so the re-bind below
  // re-arms them cleanly (torn down by abort, not by an innerHTML wipe). Mirrors render().
  closeTemplatePickerInteractions();
  closeDemoLanguagePickerInteractions();
  closeArtifactPickerInteractions();
  closeWalletBalanceOverlayInteractions();
  closePlanConnectorPairingPanelInteractions();
  closeMobileRailSheetInteractions();
  closeExpandNoteSheetInteractions();

  suppressMobileRailSheetEnterAnimation = shouldSuppressMobileRailSheetEnterAnimation({
    currentSheet: state.activeMobileRailSheet,
    previousSheet: lastRenderedMobileRailSheet,
    forceSuppress: suppressMobileRailSheetEnterAnimation,
  });
  syncBodyScrollLockDatasets(route);

  // Never let the morph overwrite the control the user is mid-interaction with (a focused input's
  // value/selection, or the chat composer draft).
  const activeEl = document.activeElement;

  morphElement(workspace, appWorkspace('app'), {
    getNodeKey: (node) => {
      const el = node as Element;
      if (!el || el.nodeType !== 1 || typeof el.getAttribute !== 'function') return undefined;
      const idKey = el.getAttribute('id') || el.getAttribute('data-chat-msg-id');
      if (idKey) return idKey;
      // Stable keys for the toggling DIRECT children of #workspace: the intro <div> appears/disappears
      // on the Home tab and the tx-modal scrim toggles in at position 0, shifting sibling positions.
      // Without these keys morphdom matches by position and would remove+recreate .workspace and the
      // backdrop-filter dock on every such toggle — a WORSE blink than the bug this morph fixes. Each
      // value is unique among rendered nodes (app-intro / app-shell / the dock).
      const layout = el.getAttribute('data-layout');
      if (layout === 'app-intro' || layout === 'app-shell' || layout === 'android-bottom-tab-dock') {
        return 'layout:' + layout;
      }
      return undefined;
    },
    onBeforeElUpdated: (fromEl) => {
      if (fromEl.nodeType === 1 && typeof fromEl.matches === 'function' && fromEl.matches(WORKSPACE_MORPH_SKIP_SELECTOR)) {
        return false;
      }
      // Only skip a focused INPUT/TEXTAREA (preserve its typed value + cursor). A focused button
      // (a just-clicked tab/pill) MUST still morph so its active/aria-selected class updates —
      // node identity is preserved either way, so focus is never lost.
      if (fromEl === activeEl && (fromEl instanceof HTMLInputElement || fromEl instanceof HTMLTextAreaElement)) return false;
      return true;
    },
  });

  // The chat composer textarea renders empty (its draft is JS-injected); the morph clears it.
  if (onChatTab) {
    const input = document.querySelector<HTMLTextAreaElement>('[data-chat-input]');
    if (input && input !== activeEl) {
      input.value = chatActiveDraft();
      chatAutoGrow(input);
    }
  }

  reconcileBodyScrollLockDatasetsAfterRender();

  // Morph the toast stack in place too (it lives outside #workspace) so toast-producing actions and
  // dismissals never force a full-render blink.
  const toastRoot = document.getElementById('toast-root');
  if (toastRoot) {
    morphElement(toastRoot, `<div id="toast-root">${toastStack()}</div>`, {});
  }

  // Re-bind everything idempotently. bind()'s inline + picker/sheet handlers use bindOnce; the
  // sheets' AbortControllers were aborted above and are re-armed here. The wallet rail can be
  // inserted by the morph path, so its specialized binders must run here too.
  bind();
  bindConnectorConnectSurface();
  bindWalletSurfaceControls();
  restoreDisclosureOpenState(disclosureOpenState);

  // Imperative panels are skip-listed (morph preserves a mounted one's state). Mount only a
  // freshly-added (empty) container — re-mounting a populated one would reset it.
  const pairingPanel = document.querySelector('[data-plan-connector-pairing-panel]');
  if (pairingPanel && pairingPanel.childElementCount === 0) mountPlanConnectorPairingPanel();
  const keysPanel = document.querySelector('[data-connector-keys-panel]');
  if (keysPanel && keysPanel.childElementCount === 0) mountConnectorKeysPanel({ container: 'connector-keys-panel', onChange: onConnectorKeysPanelChange });
  if (state.tauriNativeEnvironment.isTauriNative) {
    const tauriPanel = document.querySelector('[data-tauri-local-runtime-panel]');
    if (tauriPanel && tauriPanel.childElementCount === 0) mountTauriLocalRuntimePanel('tauri-local-runtime-panel');
  }

  if (onChatTab) {
    // Morph path uses the SAME autoscroll helper as the full path — keep them unified; divergence
    // here is the historic iOS-jitter regression root.
    applyChatAutoscrollAfterRender(false);
    syncChatKeyboardInset();
  }
  updateTabTitleBadge();

  // Data side-effects the full render() path runs — required now that iOS morphs non-chat tabs.
  // Each is internally gated (route/tab) + de-duped (scheduled/in-flight guard), so calling them on
  // every morph is safe and a no-op off their target tab.
  flushPendingSpendNavigation();
  scheduleInboxSwapQuoteHydration();
  scheduleVisibleTokenMarketHydration();

  lastRenderedMobileRailSheet = state.activeMobileRailSheet;
  suppressMobileRailSheetEnterAnimation = false;
  lastRenderedChatOutsideWorkspaceHtml = chatOutsideWorkspaceHtml();
  lastRenderedPageShellModalSignature = pageShellModalSignature();
}
function render(): void {
  if (!appRoot) return;
  // Defer re-render while the user is mid-IME-composition in the chat input: a
  // full innerHTML rebuild would drop the in-progress CJK/accented characters.
  // The render flushes on compositionend (or input blur). Streaming tokens still
  // paint via direct DOM append, so the transcript keeps updating meanwhile.
  if (chatComposing && document.activeElement instanceof HTMLElement && document.activeElement.matches('[data-chat-input]')) {
    chatRenderDeferredDuringComposition = true;
    return;
  }
  if (chatResearchFixturesEnabled() && !chatTabHidden() && chatTabAiConnected()) state.activeTab = 'chat';
  // Normalize a stranded Chat tab before any markup is built, so
  // the tab bar and active panel agree on the same active tab in this render.
  if (state.activeTab === 'chat' && (chatTabHidden() || !chatTabAiConnected())) state.activeTab = 'overview';
  reconcileConnectorConnectSession(currentRoute());
  // Chat-tab fast path: patch the workspace IN PLACE (DOM morph) instead of wiping
  // appRoot.innerHTML, so the sheet, transcript, Primary/Advanced tabs, Pending list,
  // popovers and Receive never blink and the scroll never jumps (the Android/iOS WebView
  // pain). The full render path below still runs for the tab's first paint, for cross-tab
  // navigation, and whenever something OUTSIDE the workspace (a toast or a wallet overlay)
  // must change — cases the scoped morph cannot repaint.
  if (canMorphActiveTab()) {
    renderWorkspace();
    return;
  }
  // Restore the New Request planner draft if the chat Connector Actions surface was left open
  // while the user navigated off the Chat tab (e.g. switched tabs without closing the desktop
  // popover) — before any markup, so New Request never renders the connector form's data.
  reconcileChatConnectorSession();
  const mobileRailSnapshot = captureMobileRailRenderSnapshot();
  const plannerInputSnapshot = capturePlannerInputSnapshot();
  // Publish the connected wallet address to the shared dev-tab sinks BEFORE
  // pageContent() runs, so dev-tab guards (which fire inside pageContent's
  // tab-nav fan-out) see the current address synchronously. Both writes are
  // idempotent and run on every render.
  const connectedForDevTabs = state.address || undefined;
  setConnectedAddress(connectedForDevTabs);
  setConnectedCluster(state.cluster);
  // Publish the native cloud session (Bearer token + client id + signed-in flag)
  // so the standalone dev-tab clients (streaming/mpp/ap2/session probe) can
  // authenticate on native, where the same-origin cookie is never set. On web
  // this pushes an empty token and the clients keep using the cookie.
  const nativeCloudActive = nativeCloudApiSurfaceActive();
  setCloudAuth({
    token: nativeCloudActive ? nativeCloudSessionToken() : null,
    clientHeader: nativeCloudActive ? nativeCloudClientHeader() : null,
    signedIn: cloudSessionMatchesWallet(),
  });
  syncBrowserDeviceAgentWalletAddress();
  if (typeof document !== 'undefined' && document.body) {
    if (connectedForDevTabs) {
      document.body.dataset.walletAddress = connectedForDevTabs;
      document.body.dataset.cluster = state.cluster;
    } else {
      delete document.body.dataset.walletAddress;
      delete document.body.dataset.cluster;
    }
  }
  const route = currentRoute();
  if (route !== '/qr-connect' && qrConnect.pollHandle !== null) {
    stopQrConnectRelay();
  }
  reconcileConnectorConnectSession(route);
  if (
    route !== '/aiconnectors' &&
    (
      aiConnectorsPairingPollTimer !== null ||
      aiConnectorsPairingState.status !== 'idle' ||
      aiConnectorsReadinessKeyValue ||
      aiConnectorsReadinessState.status !== 'missing-credentials'
    )
  ) {
    stopAiConnectorsPairingPoll();
    resetAiConnectorsPairingState();
    resetAiConnectorsReadinessState();
  }
  // Cancel an in-flight chat stream if the user navigated away from the Chat tab.
  if (chatStreamActive() && state.activeTab !== 'chat') {
    cancelChatStream();
  }
  if (shouldClearActiveMobileRailSheet({
    activeTab: state.activeTab,
    mobileViewport: isMobileAppViewport(),
    route,
    sheet: state.activeMobileRailSheet,
  })) {
    if (state.activeMobileRailSheet === 'chat-action') {
      state.chatActionPicker = null;
      state.chatComposerOpen = false;
    }
    state.activeMobileRailSheet = null;
  }
  if (state.activeExpandNoteField && !isMobileAppViewport()) {
    state.activeExpandNoteField = null;
  }
  applyRouteTitle(route);
  trackPageView(route ?? normalizePathname(window.location.pathname), document.title);
  closeTemplatePickerInteractions();
  closeDemoLanguagePickerInteractions();
  closeArtifactPickerInteractions();
  closeWalletBalanceOverlayInteractions();
  closePlanConnectorPairingPanelInteractions();
  closeMobileRailSheetInteractions();
  closeExpandNoteSheetInteractions();
  const currentMobileRailSheet = state.activeMobileRailSheet;
  suppressMobileRailSheetEnterAnimation = shouldSuppressMobileRailSheetEnterAnimation({
    currentSheet: currentMobileRailSheet,
    previousSheet: lastRenderedMobileRailSheet,
    forceSuppress: suppressMobileRailSheetEnterAnimation,
  });
  syncBodyScrollLockDatasets(route);
  captureChatComposerSnapshot();
  const outsideWorkspaceHtml = chatOutsideWorkspaceHtml();
  appRoot.innerHTML = pageShell(pageContent(route), route) + outsideWorkspaceHtml;
  // Snapshots the regions that live OUTSIDE #workspace (toasts + the wallet overlays) so the
  // Chat-tab morph fast-path (canMorphChat) can tell when one of them changed and must take
  // the full render path instead — the scoped workspace morph cannot repaint them.
  lastRenderedChatOutsideWorkspaceHtml = outsideWorkspaceHtml;
  lastRenderedPageShellModalSignature = pageShellModalSignature();
  reconcileBodyScrollLockDatasetsAfterRender();
  flushPendingSpendNavigation();
  bind();
  bindConnectorConnectSurface();
  restoreDisclosureOpenState(disclosureOpenState);
  bindWalletSurfaceControls();
  restoreMobileRailRenderSnapshot(mobileRailSnapshot);
  restoreChatComposerAfterRender();
  restorePlannerInputSnapshot(plannerInputSnapshot);
  mountPlanConnectorPairingPanel();
  mountConnectorKeysPanel({ container: 'connector-keys-panel', onChange: onConnectorKeysPanelChange });
  if (state.tauriNativeEnvironment.isTauriNative) {
    mountTauriLocalRuntimePanel('tauri-local-runtime-panel');
  }
  scheduleQrConnectRoute();
  scheduleAiConnectorsReadinessRefresh();
  updateTabTitleBadge();
  scheduleInboxSwapQuoteHydration();
  scheduleVisibleTokenMarketHydration();
  scheduleReleaseDownloadHydration();
  lastRenderedMobileRailSheet = state.activeMobileRailSheet;
  suppressMobileRailSheetEnterAnimation = false;
}

interface PendingSpendNavigation {
  filter: SpendNavFilter;
  selectedEnvelopeKey?: string;
}

let pendingSpendNavigation: PendingSpendNavigation | null = null;
let spendBridgeHandlersInstalled = false;

function openSpendFilter(filter: SpendNavFilter, selectedEnvelopeKey?: string): boolean {
  const spendTab = findDevTab('spend');
  if (!spendTab?.guard()) return false;
  state.activeTab = 'spend';
  state.error = '';
  pendingSpendNavigation = selectedEnvelopeKey ? { filter, selectedEnvelopeKey } : { filter };
  render();
  return true;
}

function flushPendingSpendNavigation(): void {
  if (!pendingSpendNavigation || typeof window === 'undefined') return;
  const navigation = pendingSpendNavigation;
  pendingSpendNavigation = null;
  window.dispatchEvent(new CustomEvent('spend:set-filter', { detail: navigation }));
}

function refreshSpendView(): void {
  if (typeof window === 'undefined') return;
  window.dispatchEvent(new CustomEvent('spend:refresh'));
}

function spendFilterForLegacyTab(tab: string): SpendNavFilter | null {
  switch (tab) {
    case 'inbox':
      return 'needs_approval';
    case 'schedule':
      return 'active_schedules';
    case 'sessions':
      return 'live_streams';
    case 'agent-protocols':
      return 'all';
    default:
      return null;
  }
}

function isSpendNavFilter(value: string | undefined): value is SpendNavFilter {
  return value === 'all' ||
    value === 'needs_approval' ||
    value === 'active_schedules' ||
    value === 'live_streams' ||
    value === 'settled';
}

function spendEnvelopeKeyForLegacyOpen(tab: string, id: string | undefined): string | undefined {
  if (!id) return undefined;
  if (tab === 'inbox') return `one-time:${id}`;
  if (tab === 'schedule') return `recurring:${id}`;
  if (tab === 'sessions') return `streaming:${id}`;
  return undefined;
}

function installSpendBridgeHandlers(): void {
  if (typeof window === 'undefined' || spendBridgeHandlersInstalled) return;
  spendBridgeHandlersInstalled = true;
  window.addEventListener('spend:approval-op', (event) => {
    const detail = customEventDetail(event);
    const actionId = stringDetail(detail, 'actionId');
    const op = stringDetail(detail, 'op');
    if (!actionId || !op) return;
    void runPreparedActionOp(actionId, op)
      .then(refreshSpendView)
      .catch((err) => {
        state.error = redactSecrets(err instanceof Error ? err.message : String(err));
        pushToast('error', t('Spend action failed'), state.error);
        render();
      });
  });
  window.addEventListener('spend:recurring-op', (event) => {
    const detail = customEventDetail(event);
    const scheduleId = stringDetail(detail, 'scheduleId');
    const op = stringDetail(detail, 'op');
    if (!scheduleId || !op) return;
    void runRecurringOp(scheduleId, op)
      .then(refreshSpendView)
      .catch((err) => {
        state.error = redactSecrets(err instanceof Error ? err.message : String(err));
        pushToast('error', t('Repeat action failed'), state.error);
        render();
      });
  });
  window.addEventListener('spend:legacy-open', (event) => {
    const detail = customEventDetail(event);
    const tab = stringDetail(detail, 'tab');
    if (!tab) return;
    const open = stringDetail(detail, 'open');
    state.activeTab = tab as ActiveTab;
    if (tab === 'schedule' && stringDetail(detail, 'recurringView') === 'active') {
      state.recurringView = 'active';
      state.listPages.recurring = 1;
    }
    state.error = '';
    render();
    if (tab === 'inbox' && open) {
      focusInboxApprovalCard(open);
    }
    if (tab === 'sessions' && open) {
      void openSessionDetail(open).catch((err) => {
        state.error = redactSecrets(err instanceof Error ? err.message : String(err));
        pushToast('error', t('Could not open session'), state.error);
        render();
      });
    }
  });
}

function customEventDetail(event: Event): Record<string, unknown> | null {
  const detail = (event as CustomEvent<unknown>).detail;
  return detail && typeof detail === 'object' ? detail as Record<string, unknown> : null;
}

function stringDetail(detail: Record<string, unknown> | null, key: string): string | undefined {
  const value = detail?.[key];
  return typeof value === 'string' && value ? value : undefined;
}

function normalizeInitialRoute(): void {
  const legacyRoute = HASH_ROUTE_MAP.get(window.location.hash);
  if (legacyRoute) {
    window.history.replaceState({}, '', legacyRoute);
    return;
  }

  const normalizedPath = normalizePathname(window.location.pathname);
  if (normalizedPath === '/browser') {
    window.history.replaceState({}, '', '/app');
    return;
  }

  if (normalizedPath === '/dos') {
    window.history.replaceState({}, '', '/docs');
    return;
  }

  // Inside the native mobile shells, the marketing root has no on-device value (it's hero copy +
  // CLI install commands). If the WebView lands on `/` — e.g. via the bundled fallback
  // when the remote shell fails — bounce to the guided demo so the user immediately
  // sees an interactive Solana approval flow instead of a developer landing page.
  if (normalizedPath === '/' && (state.androidNativeEnvironment.isAndroidNative || state.iosNativeEnvironment.isIosNative)) {
    window.history.replaceState({}, '', '/demo');
    return;
  }

  if (isAppRoute(normalizedPath) && window.location.pathname !== normalizedPath) {
    window.history.replaceState({}, '', normalizedPath);
  }
}

function currentRoute(): AppRoute | null {
  const path = normalizePathname(window.location.pathname);
  return isAppRoute(path) ? path : null;
}

function navigateTo(route: AppRoute): void {
  const currentPath = normalizePathname(window.location.pathname);
  if (currentPath !== route) {
    window.history.pushState({}, '', route);
  }
  render();
  window.scrollTo({ top: 0, behavior: 'auto' });
}

function normalizePathname(pathname: string): string {
  if (pathname === '/') return '/';
  return pathname.replace(/\/+$/, '') || '/';
}

function isAppRoute(pathname: string): pathname is AppRoute {
  return ROUTE_PATH_SET.has(pathname);
}

// "/docs/connectors" -> ["route-docs", "route-docs-connectors"].
//
// A nested route emits its parent's class as well as its own. Without this,
// "/docs/connectors" produced only `route-docs-connectors`, which `.route-docs`
// does not match (it is a class selector, not a prefix) — so every rule written
// for "the docs pages" silently applied to the /docs index alone.
function routeShellClasses(activeRoute: AppRoute | null): string {
  if (!activeRoute) return 'route-unknown';
  if (activeRoute === '/') return 'route-home';
  const segments = activeRoute.slice(1).split('/').filter(Boolean);
  return segments
    .map((_, index) => `route-${segments.slice(0, index + 1).join('-').replace(/[^a-z0-9-]/g, '-')}`)
    .join(' ');
}

function pageShell(content: string, activeRoute: AppRoute | null): string {
  const routeClass = routeShellClasses(activeRoute);
  const iosShellClass = state.iosNativeEnvironment.isIosNative || IS_IOS_APP
    ? `ios-native-shell${state.iosLayoutContract === 'css-safe-area-v1' ? ' ios-css-safe-area' : ''}`
    : '';
  const platformClass = iosShellClass
    ? iosShellClass
    : isAndroidAppShellSurface()
      ? 'android-shell'
      : '';
  return `
    <div id="toast-root">${toastStack()}</div>
    <section class="shell homepage-shell ${routeClass} ${platformClass}">
      ${homepageNav(activeRoute)}
      ${content}
      ${cloudWorkspaceDeleteModal()}
      ${completedDeleteModal()}
      ${generatedPlanDeleteModal()}
      ${inboxDeleteModal()}
      ${deleteAllInboxModal()}
      ${deleteAllCheckModal()}
      ${deleteAllRepeatsModal()}
      ${deleteAllDoneModal()}
      ${activeRoute === '/app' || activeRoute === '/demo' ? workspaceBackupRestoreModal() : ''}
      ${homepageFooter()}
    </section>
  `;
}

function pageContent(route: AppRoute | null): string {
  switch (route) {
    case '/':
      return homePage();
    case '/docs':
      return docsPage();
    case '/docs/ai-connectors':
      return aiConnectorsDocsPage();
    case '/docs/how-it-works':
      return docsHowItWorksPage();
    case '/docs/cloud-storage':
      return docsCloudStoragePage();
    case '/docs/connectors':
      return docsConnectorsPage();
    case '/docs/agent-payments':
      return docsAgentPaymentsSkillsPage();
    case '/builders':
      return buildersPage();
    case '/app':
      return cliView ? cliAppPage() : appPage();
    case '/connect':
    case '/disconnect':
    case '/approve':
    case '/sign':
    case '/sign-in':
    case '/sign-out':
    case '/delete-storage':
      return cliAppPage();
    case '/qr-connect':
      return qrConnectPage();
    case '/cli':
      return cliPage();
    case '/desktop':
      return desktopPage();
    case '/aiconnectors':
      return aiConnectorsPage();
    case '/android':
      // The Android download page is not relevant on iOS; suppress it even if deep-linked.
      return IS_IOS_APP ? notFoundPage() : androidPage();
    case '/demo':
      return demoPage();
    case '/mwa-test':
      return SHOW_ANDROID_EXAMPLE_TAB ? mwaTestPage() : notFoundPage();
    case '/privacy':
      return privacyPage();
    case '/terms':
      return termsPage();
    case '/delete-account':
      return deleteAccountPage();
    case '/agentic-login':
      return agenticLoginPage();
    default:
      return notFoundPage();
  }
}

// CLI signed-request callback handler. The Solana Agent Wallet CLI's
// `auth login`, `profile publish/delete`, and `cloud-workspace delete` all
// open this page with ?nonce=...&message=...&callback=...&state=...&summary=...
// The user signs the message with their connected wallet; the wallet host POSTs
// {signature, walletAddress, state, proofEncoding, proofTxBase64?, signatureEncoding}
// back to the loopback callback. The CLI then attaches the signed envelope to
// the matching server endpoint (verify-wallet / agents/profile / cloud-workspace/delete).
function agenticLoginPage(): string {
  const url = new URL(window.location.href);
  const nonce = url.searchParams.get('nonce') ?? '';
  const message = url.searchParams.get('message') ?? '';
  const callback = url.searchParams.get('callback') ?? '';
  const desiredWallet = cliView?.walletAddress ?? url.searchParams.get('walletAddress') ?? '';
  const summary = url.searchParams.get('summary') ?? 'Agentic CLI signed request';
  const connected = state.address ?? '';
  const walletReady = Boolean(connected) && (!desiredWallet || desiredWallet === connected);

  // Use the SPA-wide escapeHtml helper (defined further down in this file).
  const messageHtml = escapeHtml(message || t('No message provided.'));
  const calloutHtml = (() => {
    if (!nonce || !message || !callback) {
      return `<p class="agentic-login__error">${escapeHtml(t('Missing required parameters. Re-run the original CLI command.'))}</p>`;
    }
    if (!connected) {
      return `<p class="agentic-login__error">${escapeHtml(t('Connect your wallet from the main app first, then return to this tab.'))}</p>`;
    }
    if (desiredWallet && desiredWallet !== connected) {
      return `<p class="agentic-login__error">${tf('CLI requested {requested}… but the connected wallet is {connected}…. Switch wallets and reload.', { requested: escapeHtml(desiredWallet.slice(0, 8)), connected: escapeHtml(connected.slice(0, 8)) })}</p>`;
    }
    return '';
  })();

  return `
    <section class="agentic-login">
      <h1>${escapeHtml(summary)}</h1>
      <p>${escapeHtml(t('Your Solana Agent Wallet CLI is requesting a wallet signature. Review the message below and sign with your connected wallet. Agentic never sees your private key.'))}</p>
      <dl class="agentic-login__details">
        <dt>${escapeHtml(t('Nonce'))}</dt><dd><code>${escapeHtml(nonce || '-')}</code></dd>
        <dt>${escapeHtml(t('Connected wallet'))}</dt><dd><code>${escapeHtml(connected || t('not connected'))}</code></dd>
        <dt>${escapeHtml(t('Callback'))}</dt><dd><code>${escapeHtml(callback || '-')}</code></dd>
      </dl>
      <pre class="agentic-login__message" aria-label="${escapeHtml(t('Message to sign'))}">${messageHtml}</pre>
      ${calloutHtml}
      <button id="agenticLoginSign" class="agentic-login__sign" ${walletReady ? '' : 'disabled'}>
        ${walletReady ? escapeHtml(t('Sign and return to CLI')) : escapeHtml(t('Connect wallet to continue'))}
      </button>
      <p id="agenticLoginStatus" class="agentic-login__status" role="status"></p>
    </section>
  `;
}

