function walletIcon(
  wallet: DiscoveredWallet | undefined,
  fallback: string,
  className: string,
  fallbackLogoId?: BrandLogoId,
): string {
  const iconSrc = wallet?.icon ?? (fallbackLogoId ? BRAND_LOGOS[fallbackLogoId] : undefined);
  if (iconSrc) {
    return `
      <span class="${escapeHtml(className)} wallet-provider-icon" aria-hidden="true">
        <img src="${escapeHtml(iconSrc)}" alt="" />
      </span>
    `;
  }
  return `<span class="${escapeHtml(className)} wallet-provider-fallback" aria-hidden="true">${escapeHtml(fallback)}</span>`;
}

function discoveredWalletByName(name: string): DiscoveredWallet | undefined {
  const normalized = name.toLowerCase();
  return state.wallets.find((wallet) => wallet.name.toLowerCase().includes(normalized));
}

function providerInitials(name: string): string {
  return name
    .split(/[\s/-]+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? '')
    .join('');
}

function walletLogoIdForName(name: string): BrandLogoId | undefined {
  return walletLogoIdForProviderName(name);
}

function walletProviderLogoIdForName(name: string): WalletProviderLogoId | undefined {
  const logoId = walletLogoIdForProviderName(name);
  return isWalletProviderLogoId(logoId) ? logoId : undefined;
}

function missionStrip(): string {
  const openApprovals = state.preparedActions.filter(
    (action) => !isTerminalPreparedAction(action),
  ).length;
  return `
    <section class="mission-strip">
      ${metric(t('Wallet'), state.address ? short(state.address) : t('Not connected'), state.address ? 'online' : '')}
      ${metric(t('Cluster'), titleCaseCluster(state.cluster), state.cluster === 'mainnet-beta' ? 'warn' : '')}
      ${metric(t('Bridge'), state.bridgeActive ? t('Ready') : t('Offline'), state.bridgeActive ? 'online' : '')}
      ${metric(t('Approvals'), tf('{count} queued', { count: openApprovals }), openApprovals > 0 ? 'warn' : '')}
    </section>
  `;
}

function systemSpine(): string {
  const openApprovals = state.preparedActions.filter(
    (action) => !isTerminalPreparedAction(action),
  ).length;
  return `
    <div class="system-spine" aria-label="${escapeHtml(t('System status'))}">
      ${spineNode(t('Wallet'), state.address ? short(state.address) : t('Connect wallet'), state.address ? 'online' : '')}
      ${spineNode(t('Network'), titleCaseCluster(state.cluster), state.cluster === 'mainnet-beta' ? 'warn' : '')}
      ${spineNode(t('Bridge'), state.bridgeActive ? t('Ready') : t('Offline'), state.bridgeActive ? 'online' : '')}
      ${spineNode(t('Queue'), `${openApprovals}`, openApprovals > 0 ? 'warn' : '')}
    </div>
  `;
}

function spineNode(label: string, value: string, tone = ''): string {
  return `
    <div class="spine-node ${tone}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </div>
  `;
}

function metric(label: string, value: string, tone = ''): string {
  return `
    <div class="mission-metric ${tone}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </div>
  `;
}

const SYSTEM_HEALTH_ORDER: HealthCheckId[] = ['rpc', 'jupiter', 'wallet', 'cluster', 'ai'];

function systemHealthStrip(): string {
  const health = state.systemHealth;
  const worst = health?.worstStatus ?? 'unknown';
  const checks = health?.checks;
  return `
    <section class="system-health-strip ${worst}" aria-label="${escapeHtml(t('System health'))}">
      <button
        type="button"
        class="system-health-strip-toggle"
        data-health-action="toggle-drawer"
        aria-expanded="${state.systemHealthDrawerOpen ? 'true' : 'false'}"
      >
        <span class="system-health-strip-label">${escapeHtml(t('System health'))}</span>
        <span class="system-health-dots">
          ${SYSTEM_HEALTH_ORDER.map((id) => {
            const check = checks?.[id];
            const status = check?.status ?? 'unknown';
            const label = check?.label ?? healthCheckLabel(id);
            const message = check?.message ?? t('Checking…');
            return `
              <span class="system-health-dot ${status}" title="${escapeHtml(label)}: ${escapeHtml(message)}">
                <i class="health-dot" aria-hidden="true"></i>
                <span class="health-dot-label">${escapeHtml(label)}</span>
                <span class="health-dot-status">${escapeHtml(healthStatusShort(status))}</span>
              </span>
            `;
          }).join('')}
        </span>
        <span class="system-health-strip-cta">${state.systemHealthDrawerOpen ? escapeHtml(t('Close')) : escapeHtml(t('Details'))}</span>
      </button>
    </section>
  `;
}

function systemHealthDrawer(): string {
  if (!state.systemHealthDrawerOpen) return '';
  const health = state.systemHealth;
  const lastCheckedAt = health?.lastCheckedAt;
  return `
    <div class="system-health-drawer-scrim" data-health-action="close-drawer" aria-hidden="true"></div>
    <aside class="system-health-drawer open" role="dialog" aria-label="${escapeHtml(t('System health detail'))}">
      <header class="system-health-drawer-header">
        <div>
          <p class="system-health-drawer-eyebrow">${escapeHtml(t('System health'))}</p>
          <h2>${escapeHtml(t('What is connected right now'))}</h2>
          ${
            lastCheckedAt
              ? `<small>${escapeHtml(tf('Last checked {time}', { time: formatDateTime(lastCheckedAt) }))}</small>`
              : `<small>${escapeHtml(t('Checking…'))}</small>`
          }
        </div>
        <button
          type="button"
          class="system-health-drawer-close"
          data-health-action="close-drawer"
          aria-label="${escapeHtml(t('Close system health'))}"
        >&times;</button>
      </header>
      <div class="system-health-drawer-body">
        ${SYSTEM_HEALTH_ORDER.map((id) => systemHealthDetailRow(id, health?.checks[id])).join('')}
      </div>
      <footer class="system-health-drawer-footer">
        <button type="button" class="primary" data-health-action="recheck" ${state.systemHealthChecking ? 'disabled' : ''}>${state.systemHealthChecking ? escapeHtml(t('Checking…')) : escapeHtml(t('Recheck all'))}</button>
        <button type="button" class="utility" data-health-action="copy-debug">${escapeHtml(t('Copy debug snapshot'))}</button>
      </footer>
    </aside>
  `;
}

function systemHealthDetailRow(id: HealthCheckId, check: HealthCheck | undefined): string {
  const status = check?.status ?? 'unknown';
  const label = check?.label ? t(check.label) : healthCheckLabel(id);
  const message = check?.message ? t(check.message) : t('Checking…');
  const detail = check?.detail ? t(check.detail) : '';
  const checkedAt = check?.checkedAt ?? '';
  const remediation = check?.remediation;
  return `
    <article class="system-health-row ${status}" data-health-row="${escapeHtml(id)}">
      <div class="system-health-row-head">
        <span class="system-health-dot ${status}"><i class="health-dot" aria-hidden="true"></i></span>
        <div class="system-health-row-copy">
          <strong>${escapeHtml(label)}</strong>
          <p>${escapeHtml(message)}</p>
        </div>
        <span class="system-health-row-status">${escapeHtml(healthStatusShort(status))}</span>
      </div>
      ${detail ? `<p class="system-health-row-detail">${escapeHtml(detail)}</p>` : ''}
      ${checkedAt ? `<small class="system-health-row-time">${escapeHtml(formatDateTime(checkedAt))}</small>` : ''}
        ${
          remediation
          ? `<button type="button" class="utility system-health-row-remediation" data-health-action="remediate" data-health-intent="${escapeHtml(remediation.intent)}">${escapeHtml(t(remediation.label))}</button>`
          : ''
      }
    </article>
  `;
}

function healthCheckLabel(id: HealthCheckId): string {
  switch (id) {
    case 'rpc': return t('RPC');
    case 'jupiter': return t('Jupiter');
    case 'wallet': return t('Wallet');
    case 'cluster': return t('Cluster');
    case 'ai': return t('AI');
  }
}

function healthStatusShort(status: HealthStatus): string {
  switch (status) {
    case 'ok': return t('ok');
    case 'warn': return t('slow');
    case 'fail': return t('down');
    case 'unknown': return '…';
  }
}

function walletRail(): string {
  // Wallet-host browser-extension auto-connect splash. Short-circuits the
  // normal rail content so the user sees clear "Opening <Brand>…" state
  // instead of the standby UI while we wait for the extension to register.
  // Only in the browser path (not Tauri-native — desktop rail has its own
  // discover flow).
  if (
    state.walletHostOpening &&
    !state.tauriNativeEnvironment.isTauriNative &&
    !state.address
  ) {
    return walletHostOpeningSplashHtml();
  }
  const showConnectionDetails = SHOW_DEV_CONTROLS && !state.address;
  const multiPathFlow = multiPathWalletFlowAvailable();
  const showPublicWalletPicker =
    !SHOW_DEV_CONTROLS &&
    !state.address &&
    !multiPathFlow &&
    !state.androidNativeEnvironment.isAndroidNative &&
    !state.iosNativeEnvironment.isIosNative &&
    !state.tauriNativeEnvironment.isTauriNative &&
    state.wallets.length > 0;
  const wallet = walletIdentity();
  const connected = Boolean(state.address);
  const headingTitleMarkup = connected
    ? `<h2>${escapeHtml(wallet.title)}</h2>`
    : `<h2 class="signer-title-desktop-only">${escapeHtml(wallet.title)}</h2>`;
  const summaryStrongMarkup = `<strong>${escapeHtml(wallet.summary)}</strong>`;
  const summaryDetailMarkup = connected
    ? `<p>${escapeHtml(wallet.detail)}</p>`
    : `<p class="signer-detail-desktop-only">${escapeHtml(wallet.detail)}</p>`;
  const connectionsReadiness = connected
    ? t('Wallet connected. You can review, approve, and sign.')
    : t('Connect your wallet to approve and sign. AI connector and cloud sync are optional.');
  // Connections re-org (reviewer feedback): group the wallet/AI/cloud connections under one
  // prioritized "Connections" header with Required/Optional labels for native mobile app shells.
  const nativeConnectionRail = IS_ANDROID_APP || IS_IOS_APP;
  const connectionsRailHead = nativeConnectionRail ? `
      <div class="connections-rail-head">
        <p class="eyebrow mini">${escapeHtml(t('Connections'))}</p>
        <p class="connections-rail-readiness">${escapeHtml(connectionsReadiness)}</p>
        <p class="connection-group-label">${escapeHtml(t('Required'))}</p>
      </div>` : '';
  return `
    <aside class="panel custody-panel custody-module" data-layout="app-rail">
      ${connectionsRailHead}
      <div class="signer-row ${connected ? 'connected' : 'disconnected'}${nativeConnectionRail ? ' native-connection-signer' : ''}">
        <div class="rail-heading custody-heading">
          ${walletRailIcon(wallet)}
          <div>
            <p class="eyebrow mini">${escapeHtml(t('Signer'))}</p>
            ${headingTitleMarkup}
            ${connected && isMobileAppViewport() ? walletBalanceMobileTrigger() : ''}
          </div>
        </div>

        <div class="connection-summary custody-card ${connected ? 'has-address-copy' : ''}">
          <span class="status-dot ${connected ? 'online' : ''}"></span>
          <div>
            ${summaryStrongMarkup}
            ${summaryDetailMarkup}
            ${connected ? walletAddressCopyButton(state.address) : ''}
          </div>
        </div>
        ${connected && !isMobileAppViewport() ? walletBalanceRailCard() : ''}
      </div>

      ${showPublicWalletPicker ? `
      <details class="rail-details wallet-picker-details" open>
        <summary>${escapeHtml(t('Wallet choices'))}</summary>
        <label class="field">
          <span>${escapeHtml(t('Selected wallet'))}</span>
          ${selectPicker({
            id: 'walletSelect',
            value: state.selectedWalletName,
            options: walletSelectOptions(),
            disabled: state.wallets.length === 0 || state.busy,
            open: state.browserWalletPickerOpen,
          })}
        </label>
        ${desktopBrandPanelsBlock()}
      </details>` : ''}

      ${publicWalletActions()}

      ${desktopConnectFlowBlock()}

      ${nativeConnectionRail ? `<p class="connection-group-label">${escapeHtml(t('Optional'))}</p>` : ''}
      <div class="rail-primary-stack">
        ${cloudWorkspaceCard()}
        ${aiSettingsPanel('rail')}
      </div>
      ${SHOW_DEV_CONTROLS ? `
      <details class="rail-details developer-settings" ${showConnectionDetails ? 'open' : ''}>
        <summary>${escapeHtml(t('Developer settings'))}</summary>
        ${developerConnectionSettings()}
      </details>` : ''}

      ${SHOW_DEV_CONTROLS && state.address ? `
      <details class="rail-details bridge-details" ${state.bridgeActive ? 'open' : ''}>
        <summary>${escapeHtml(t('Bridge operations'))}</summary>
        ${bridgeBox()}
      </details>` : ''}
      ${SHOW_DEV_CONTROLS && state.address ? `
      <details class="rail-details">
        <summary>${escapeHtml(t('Environment'))}</summary>
        ${mobileWalletBox()}
      </details>` : ''}
    </aside>
  `;
}

function preferencesButton(): string {
  const active = state.activeTab === 'preferences';
  return `
    <button
      type="button"
      data-tab="preferences"
      class="utility preferences-open-button ${active ? 'active' : ''}"
      aria-pressed="${active ? 'true' : 'false'}"
      aria-label="${escapeHtml(t('Open Preferences'))}"
    >
      ${escapeHtml(t('Preferences'))}
    </button>
  `;
}

function preferencesPanel(): string {
  return `
    <div class="preferences-page" data-layout="preferences-page">
      <header class="preferences-page-head">
        <div>
          <p class="preferences-eyebrow">${escapeHtml(t('Workspace'))}</p>
          <h2 id="preferences-title">${escapeHtml(t('Preferences'))}</h2>
          <p>${escapeHtml(t('Configure the browser workspace. These settings shape drafting, review, labels, alerts, and retries without changing wallet authority.'))}</p>
        </div>
        ${IS_ANDROID_APP ? `
          <div class="preferences-language-row">
            <span class="preferences-language-label">${escapeHtml(t('Language'))}</span>
            ${demoLanguagePicker()}
          </div>
        ` : ''}
      </header>
      ${preferencesStoragePolicy()}
      <nav class="preferences-subtabs" role="tablist" aria-label="${escapeHtml(t('Preferences sections'))}">
        ${PREFERENCES_VIEW_OPTIONS.map((option) => preferencesViewButton(option.view, option.title, option.desktopLabel)).join('')}
      </nav>
      ${preferencesMobileTabs()}
      <div class="preferences-view">
        ${preferencesActiveView()}
      </div>
    </div>
  `;
}

const PREFERENCES_VIEW_OPTIONS: ReadonlyArray<{
  view: PreferencesView;
  title: string;
  desktopLabel: string;
  mobileLabel: string;
}> = [
  { view: 'workspace', title: 'Workspace', desktopLabel: 'Backup & alerts', mobileLabel: 'Backup & Alerts' },
  { view: 'ai', title: 'AI Connector', desktopLabel: 'Prompts & connector', mobileLabel: 'Prompts & Connector' },
  { view: 'access', title: 'Agent Access', desktopLabel: 'Agents & connectors', mobileLabel: 'Agents & Connectors' },
  { view: 'rules', title: 'Review Rules', desktopLabel: 'Recipients & policy', mobileLabel: 'Recipients & Policy' },
  { view: 'tokens', title: 'Tokens & Retry', desktopLabel: 'Labels & failures', mobileLabel: 'Labels & Failures' },
];

function preferencesViewOption(view: PreferencesView): (typeof PREFERENCES_VIEW_OPTIONS)[number] {
  return PREFERENCES_VIEW_OPTIONS.find((option) => option.view === view) ?? PREFERENCES_VIEW_OPTIONS[0]!;
}

function preferencesMobileViewOptions(): Array<(typeof PREFERENCES_VIEW_OPTIONS)[number]> {
  return MOBILE_PREFERENCES_VIEW_ORDER
    .map((view) => preferencesViewOption(view as PreferencesView));
}

function preferencesMobileTabs(): string {
  const options = preferencesMobileViewOptions();
  return `
    <nav class="preferences-mobile-tabs android-tab-card" role="tablist" aria-label="${escapeHtml(t('Preferences sections'))}">
      <div class="android-tab-strip preferences-mobile-tabs-strip">
        ${options.map(preferencesMobileTabButton).join('')}
      </div>
    </nav>
  `;
}

function preferencesMobileTabButton(option: (typeof PREFERENCES_VIEW_OPTIONS)[number]): string {
  const active = state.preferencesView === option.view;
  return `
    <button
      type="button"
      class="android-tab preferences-mobile-tab${active ? ' active' : ''}"
      role="tab"
      aria-selected="${active ? 'true' : 'false'}"
      data-preferences-view="${escapeHtml(option.view)}"
      title="${escapeHtml(preferencesViewSummary(option.view))}"
    >
      <span class="android-tab-icon">${commandCenterIcon(preferencesViewIcon(option.view))}</span>
      <span class="android-tab-label">${escapeHtml(preferencesMobileShortLabel(option))}</span>
    </button>
  `;
}

function preferencesMobileShortLabel(option: (typeof PREFERENCES_VIEW_OPTIONS)[number]): string {
  if (option.view === 'access') return t('Connectors');
  if (option.view === 'workspace') return t('Backup');
  if (option.view === 'tokens') return t('Tokens');
  if (option.view === 'rules') return t('Rules');
  return t('AI');
}

// One glyph per section, shared by the desktop card strip and the native tab
// strip so a section reads the same on both surfaces.
function preferencesViewIcon(view: PreferencesView): CommandCenterIconId {
  switch (view) {
    case 'access':
      return 'connectors';
    case 'rules':
      return 'guardrails';
    case 'tokens':
      return 'tokens';
    case 'ai':
      return 'ai';
    case 'workspace':
      return 'backup';
  }
}

function preferencesStoragePolicy(): string {
  const cloudSynced = state.cloudSession.status === 'signed-in' && cloudSessionMatchesWallet();
  const cloudTitle = state.cloudSession.status === 'unavailable'
    ? 'Cloud unavailable'
    : cloudSynced
      ? 'Cloud sync on'
      : 'Cloud sync off';
  const cloudDetail = cloudSynced
    ? 'Supported non-secret preferences can sync.'
    : 'Sign in from Cloud Storage to sync supported non-secret preferences.';
  return `
    <section class="preferences-storage-policy" aria-label="${escapeHtml(t('Preferences save policy'))}">
      ${preferencesStoragePolicyItem('Local first', 'Changes apply in this browser immediately.', storageBadge('local-only'))}
      ${preferencesStoragePolicyItem(cloudTitle, cloudDetail, cloudSynced ? storageBadge('cloud-synced') : storageBadge('local-only'))}
      ${preferencesStoragePolicyItem('Secrets stay local', 'AI keys, bridge tokens, wallet auth, and notification permission never sync.', storageBadge('session-only'))}
    </section>
  `;
}

function preferencesStoragePolicyItem(title: string, detail: string, badge?: StorageDurabilityBadge): string {
  return `
    <article>
      <span>${escapeHtml(t(title))}</span>
      <strong>${escapeHtml(preferencesStoragePolicyShortTitle(title))}${badge ? storageBadgeHtml(badge) : ''}</strong>
      <span>${escapeHtml(t(detail))}</span>
    </article>
  `;
}

function preferencesStoragePolicyShortTitle(title: string): string {
  if (title === 'Local first') return t('Saved in this browser');
  if (title.startsWith('Cloud')) return t(title);
  if (title === 'Secrets stay local') return t('Secrets never sync');
  return t(title);
}

function storageBadge(kind: StorageDurabilityKind, title?: string): StorageDurabilityBadge {
  switch (kind) {
    case 'cloud-synced':
      return { kind, label: t('Cloud synced'), title: title ?? t('Saved to the wallet-scoped cloud workspace.') };
    case 'bridge-local':
      return { kind, label: t('Bridge local'), title: title ?? t('Saved in the local bridge workspace for the connected wallet.') };
    case 'session-only':
      return { kind, label: t('Session only'), title: title ?? t('Stored only for this browser session.') };
    case 'cloud-pending':
      return { kind, label: t('Cloud pending'), title: title ?? t('Waiting to upload to Agentic Cloud.') };
    case 'cloud-failed':
      return { kind, label: t('Cloud retry'), title: title ?? t('Cloud upload failed and can be retried.') };
    case 'local-only':
    default:
      return { kind: 'local-only', label: t('Local workspace'), title: title ?? t('Saved only in this browser workspace.') };
  }
}

function storageBadgeHtml(badge: StorageDurabilityBadge): string {
  if (badge.kind === 'local-only') return '';
  return `<span class="storage-durability-chip ${escapeHtml(badge.kind)}" title="${escapeHtml(badge.title)}">${escapeHtml(badge.label)}</span>`;
}

function workflowSourceStorageBadge(source?: WorkflowRecordSource): StorageDurabilityBadge {
  if (source === 'cloud') return storageBadge('cloud-synced');
  if (source === 'local-bridge') return storageBadge('bridge-local');
  return storageBadge('local-only');
}

function generatedPlanStorageBadge(record: GeneratedPlanRecord): StorageDurabilityBadge {
  if (record.workflowSource === 'cloud' && record.cloudSyncStatus === 'pending') {
    return storageBadge('cloud-pending', t('Signed locally. Cloud sync will retry when reachable.'));
  }
  return workflowSourceStorageBadge(record.workflowSource ?? 'browser');
}

function preparedActionStorageBadge(action: PreparedAction): StorageDurabilityBadge {
  return workflowSourceStorageBadge(action.workflowSource ?? (isBrowserWorkflowId(action.id) ? 'browser' : 'local-bridge'));
}

function recurringPaymentStorageBadge(payment: RecurringPayment): StorageDurabilityBadge {
  return workflowSourceStorageBadge(recurringPaymentWorkflowSource(payment));
}

function completedPlanStorageBadge(plan: CompletedPlanRecord): StorageDurabilityBadge {
  return workflowSourceStorageBadge(plan.workflowSource ?? (plan.actionId && isBrowserWorkflowId(plan.actionId) ? 'browser' : undefined));
}

function proofStorageBadge(artifact: LabArtifact): StorageDurabilityBadge {
  if (artifact.cloudReceiptId || artifact.cloudSyncStatus === 'synced') return storageBadge('cloud-synced');
  if (artifact.cloudSyncStatus === 'pending') return storageBadge('cloud-pending');
  if (artifact.cloudSyncStatus === 'failed') return storageBadge('cloud-failed', artifact.cloudSyncError || undefined);
  if (artifact.bridgeArchived || artifact.bridgeSyncStatus === 'synced') return storageBadge('bridge-local');
  if (artifact.bridgeSyncStatus === 'pending') return storageBadge('bridge-local', t('Waiting to mirror to the local bridge archive.'));
  return storageBadge('local-only');
}

interface LocalWorkspaceSummary {
  requests: number;
  approvals: number;
  repeatPayments: number;
  done: number;
  proofs: number;
  total: number;
}

interface LocalCloudImportCandidates {
  plans: GeneratedPlanRecord[];
  approvals: PreparedAction[];
  repeatPayments: RecurringPayment[];
  proofs: LabArtifact[];
  summary: LocalWorkspaceSummary;
}

function localWorkspaceSummary(): LocalWorkspaceSummary {
  if (!state.address) {
    return localWorkspaceSummaryFromCounts({ requests: 0, approvals: 0, repeatPayments: 0, done: 0, proofs: 0 });
  }
  const requests = state.generatedPlans
    .filter((record) => record.workflowSource !== 'cloud')
    .filter((record) => recordMatchesWalletScope(record, state.address))
    .filter((record) => !record.template)
    .length;
  const approvals = state.preparedActions
    .filter((action) => action.workflowSource !== 'cloud')
    .filter((action) => recordMatchesWalletScope(action, state.address))
    .filter((action) => !isTerminalPreparedAction(action))
    .length;
  const repeatPayments = state.recurringPayments
    .filter((payment) => recurringPaymentWorkflowSource(payment) !== 'cloud')
    .filter((payment) => recordMatchesWalletScope(payment, state.address))
    .filter((payment) => !isRecurringPaymentCompleted(payment))
    .length;
  const done = state.localCompletedPlans
    .filter((record) => record.workflowSource !== 'cloud')
    .filter((record) => recordMatchesWalletScope(record, state.address))
    .length;
  const proofs = state.labArtifacts
    .filter((artifact) => recordMatchesWalletScope(artifact, state.address))
    .filter((artifact) => !(artifact.cloudReceiptId || artifact.cloudSyncStatus === 'synced'))
    .length;
  return localWorkspaceSummaryFromCounts({ requests, approvals, repeatPayments, done, proofs });
}

function localCloudImportCandidates(): LocalCloudImportCandidates {
  if (!state.address) {
    const summary = localWorkspaceSummaryFromCounts({ requests: 0, approvals: 0, repeatPayments: 0, done: 0, proofs: 0 });
    return { plans: [], approvals: [], repeatPayments: [], proofs: [], summary };
  }
  const plans = state.generatedPlans
    .filter((record) => record.workflowSource !== 'cloud')
    .filter((record) => recordMatchesWalletScope(record, state.address))
    .filter((record) => !record.template && !record.importedToCloudAt);
  const approvals = state.preparedActions
    .filter((action) => action.workflowSource !== 'cloud')
    .filter((action) => recordMatchesWalletScope(action, state.address))
    .filter((action) => !action.recurringId && !isTerminalPreparedAction(action) && !action.importedToCloudAt)
    .filter((action) => cloudImportableApprovalKind(action.kind));
  const repeatPayments = state.recurringPayments
    .filter((payment) => recurringPaymentWorkflowSource(payment) !== 'cloud')
    .filter((payment) => recordMatchesWalletScope(payment, state.address))
    .filter((payment) => !isRecurringPaymentCompleted(payment) && !payment.importedToCloudAt)
    .filter((payment) => cloudImportableRecurringPayment(payment));
  const proofs = state.labArtifacts
    .filter((artifact) => recordMatchesWalletScope(artifact, state.address))
    .filter((artifact) => isCloudEvidenceReceiptKind(artifact.kind))
    .filter((artifact) => !artifact.cloudReceiptId && artifact.cloudSyncStatus !== 'synced');
  const summary = localWorkspaceSummaryFromCounts({
    requests: plans.length,
    approvals: approvals.length,
    repeatPayments: repeatPayments.length,
    done: 0,
    proofs: proofs.length,
  });
  return { plans, approvals, repeatPayments, proofs, summary };
}

function localWorkspaceSummaryFromCounts(counts: Omit<LocalWorkspaceSummary, 'total'>): LocalWorkspaceSummary {
  return {
    ...counts,
    total: counts.requests + counts.approvals + counts.repeatPayments + counts.done + counts.proofs,
  };
}

function cloudImportableApprovalKind(kind: PreparedActionKind): boolean {
  return kind === 'transfer_sol' ||
    kind === 'transfer_spl' ||
    kind === 'swap' ||
    kind === 'manual_review' ||
    kind === 'read_only' ||
    kind === 'custom_transaction' ||
    kind === 'custom' ||
    kind === 'skill_fee_split';
}

function cloudImportableRecurringPayment(payment: RecurringPayment): boolean {
  if (payment.actionKind === 'swap' || payment.outputToken) return true;
  return (payment.token || 'SOL').toUpperCase() === 'SOL';
}

function localWorkspacePrompt(context: 'backup' | 'cloud'): string {
  const importCandidates = localCloudImportCandidates();
  const summary = context === 'cloud' ? importCandidates.summary : localWorkspaceSummary();
  if (summary.total === 0) return '';
  const importCount = importCandidates.summary.total;
  const importButton = context === 'cloud' && cloudSessionMatchesWallet() && importCount > 0
    ? `<button type="button" class="primary" data-cloud-action="copy-local-to-cloud" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Transfer to storage'))}</button>`
    : '';
  // In 'backup' context this prompt lives inside the Workspace-backup panel, which already renders the
  // primary Export button — keep the reminder + local-item counts but don't duplicate the button.
  const action = context === 'backup' ? '' : importButton;
  const detail = context === 'cloud'
    ? state.cloudSession.status === 'unavailable'
      ? t('These items stay on this device until storage is available.')
      : cloudSessionMatchesWallet() && importCount > 0
        ? t('Transfer eligible local items into this wallet storage.')
        : t('Sign in to create storage and transfer eligible local items into it.')
    : t('Export before signing out, switching wallets, or clearing browser data.');
  const title = context === 'cloud'
    ? state.cloudSession.status === 'unavailable'
      ? t('Local items on device')
      : t('Local items ready')
    : t('Back up local workspace');
  const ariaLabel = context === 'cloud' ? t('Local workspace storage prompt') : t('Local workspace backup prompt');
  return `
    <section class="local-workspace-prompt ${context}-context" aria-label="${escapeHtml(ariaLabel)}">
      <div>
        <span>${storageBadgeHtml(storageBadge('local-only'))}</span>
        <strong>${escapeHtml(title)}</strong>
        <p>${escapeHtml(detail)}</p>
      </div>
      <div class="local-workspace-counts">
        ${localWorkspaceCountPill(t('Requests'), summary.requests)}
        ${localWorkspaceCountPill(t('Approvals'), summary.approvals)}
        ${localWorkspaceCountPill(t('Repeats'), summary.repeatPayments)}
        ${localWorkspaceCountPill(t('Done'), summary.done)}
        ${localWorkspaceCountPill(t('Proofs'), summary.proofs)}
      </div>
      ${action ? `<div class="local-workspace-actions">${action}</div>` : ''}
    </section>
  `;
}

function localWorkspaceCountPill(label: string, count: number): string {
  if (count === 0) return '';
  return `<span><em>${escapeHtml(label)}</em><strong>${count}</strong></span>`;
}

function localWorkspaceImportSummaryLabel(summary: LocalWorkspaceSummary): string {
  return [
    localWorkspaceCountPhrase(summary.requests, t('request'), t('requests')),
    localWorkspaceCountPhrase(summary.approvals, t('approval'), t('approvals')),
    localWorkspaceCountPhrase(summary.repeatPayments, t('repeat payment'), t('repeat payments')),
    localWorkspaceCountPhrase(summary.proofs, t('proof'), t('proofs')),
  ].filter(Boolean).join(', ');
}

function localWorkspaceCountPhrase(count: number, singular: string, plural: string): string {
  if (count === 0) return '';
  return count === 1 ? tf('{count} {label}', { count, label: singular }) : tf('{count} {label}', { count, label: plural });
}

function savedPromptCountLabel(count: number): string {
  return count === 1
    ? tf('{count} quick prompt', { count })
    : tf('{count} quick prompts', { count });
}

function preferencesViewButton(view: PreferencesView, title: string, detail: string): string {
  const active = state.preferencesView === view;
  return `
    <button
      type="button"
      class="${active ? 'active' : ''}"
      data-preferences-view="${escapeHtml(view)}"
      role="tab"
      aria-selected="${active ? 'true' : 'false'}"
    >
      <span class="preferences-subtab-icon">${commandCenterIcon(preferencesViewIcon(view))}</span>
      <span class="preferences-subtab-eyebrow">${escapeHtml(t(detail))}</span>
      <strong>${escapeHtml(t(title))}</strong>
      <em>${escapeHtml(preferencesViewSummary(view))}</em>
    </button>
  `;
}

function preferencesViewSummary(view: PreferencesView): string {
  switch (view) {
    case 'workspace': {
      const pending = state.pendingTransactions.length;
      const unresolved = unresolvedPendingTransactions().length;
      const alertsOn = notificationEnabledCount();
      if (unresolved > 0) return tf('{unresolved} unresolved tx · {alertsOn} alerts on', { unresolved, alertsOn });
      return tf('{pending} pending tx · {alertsOn} alerts on', { pending, alertsOn });
    }
    case 'ai': {
      const extras = [
        SHOW_MULTI_AGENT_REVIEW && state.aiSettings.multiReviewer ? t('multi-review') : '',
        state.aiSettings.autoBackgroundWatch ? t('background watch') : '',
        state.plannerPrefs.houseRules.trim() ? t('rules') : '',
        state.plannerPrefs.savedPrompts.length ? tf('{n} prompts', { n: state.plannerPrefs.savedPrompts.length }) : '',
      ].filter(Boolean);
      return extras.length ? extras.join(' · ') : t('review defaults');
    }
    case 'access': {
      const enabledAgents = state.agents.filter((agent) => agent.enabled).length;
      const enabledConnectors = enabledProtocolConnectors(state.connectedDapps, state.cluster).length;
      if (isMobileAiPathPolicySurface()) return tf('{enabledConnectors} connectors on', { enabledConnectors });
      return tf('{enabledAgents}/{total} agents · {enabledConnectors} connectors on', { enabledAgents, total: state.agents.length, enabledConnectors });
    }
    case 'rules': {
      const railsOn = safetyRailsEnabledCount();
      const recipients = state.recipientRules.recipients.length;
      // Agent Policies is hidden (SHOW_AGENT_POLICIES); drop its count from the chip so it doesn't
      // reference a panel the user can't see.
      if (!SHOW_AGENT_POLICIES) {
        return tf('{recipients} recipients · {railsOn} rails', { recipients, railsOn });
      }
      const enabledPolicies = state.agentPolicies.filter((policy) => policy.enabled).length;
      return tf('{recipients} recipients · {railsOn} rails · {enabledPolicies} policies', { recipients, railsOn, enabledPolicies });
    }
    case 'tokens': {
      const autoRetries = autoRetryEnabledCount(state.failurePolicies);
      // Custom Tokens is hidden (SHOW_CUSTOM_TOKENS), so don't surface a stale count for a panel the
      // user can't see — the tab is auto-retry only.
      if (!SHOW_CUSTOM_TOKENS) {
        return tf('{autoRetries} auto retries', { autoRetries });
      }
      return tf('{customTokens} custom tokens · {autoRetries} auto retries', { customTokens: state.customTokens.length, autoRetries });
    }
  }
}

function notificationEnabledCount(): number {
  const settings = state.notificationSettings;
  return [settings.browser, settings.due, settings.pending, settings.confirmed, settings.failed]
    .filter(Boolean).length;
}

function safetyRailsEnabledCount(): number {
  const rails = state.safetyRails;
  return [rails.programs.enabled, rails.tokens.enabled, rails.spend.enabled, rails.slippage.enabled]
    .filter(Boolean).length;
}

let connectorSecretsRefreshPromise: Promise<void> | undefined;

function connectorSecretSummary(id: string): ConnectorSecretsSummary[ByoKeyConnectorId] | undefined {
  return connectorNeedsCredential(id) ? state.connectorSecrets.secrets[id] : undefined;
}

function connectorHasSavedCredential(id: string): boolean {
  return connectorSecretSummary(id)?.hasKey === true;
}

function connectorCredentialDraft(id: ByoKeyConnectorId): ConnectorCredentialDraft {
  return state.protocolConnectorCredentialDrafts[id] ?? { apiKey: '' };
}

function connectorCredentialReady(id: string, draftApiKey = ''): boolean {
  return !connectorNeedsCredential(id) || connectorHasSavedCredential(id) || draftApiKey.trim().length > 0;
}

function connectorReadinessForConnector(
  connector: ConnectedDappAdapter,
  actionCategory: ActionCategory | null,
  hasCredential = connectorHasSavedCredential(connector.id),
): ConnectorReadinessResult {
  return connectorReadiness({
    connector,
    clusterSupported: isClusterSupported(connector, state.cluster),
    walletAddress: state.address || undefined,
    hasCredential,
    actionCategory,
  });
}

function connectorCredentialReadyIds(): ConnectedDappId[] {
  return PROTOCOL_CONNECTORS
    .filter((connector) => !connectorNeedsCredential(connector.id) || connectorHasSavedCredential(connector.id))
    .map((connector) => connector.id);
}

function updateConnectorSecretSummary(
  connector: ByoKeyConnectorId,
  summary: ConnectorSecretsSummary[ByoKeyConnectorId],
): void {
  state.connectorSecrets.secrets = {
    ...state.connectorSecrets.secrets,
    [connector]: {
      hasKey: summary.hasKey,
      ...(summary.baseUrl ? { baseUrl: summary.baseUrl } : {}),
      ...(summary.savedAt ? { savedAt: summary.savedAt } : {}),
    },
  };
  state.connectorSecrets.loaded = true;
  state.connectorSecrets.available = true;
  state.connectorSecrets.error = '';
}

async function refreshConnectorSecretsSummary(options: { force?: boolean; renderOnChange?: boolean } = {}): Promise<void> {
  if (connectorSecretsRefreshPromise && !options.force) return connectorSecretsRefreshPromise;
  if (state.connectorSecrets.loaded && !options.force) return;
  state.connectorSecrets.loading = true;
  state.connectorSecrets.error = '';
  if (options.renderOnChange) render();
  connectorSecretsRefreshPromise = (async () => {
    try {
      const { secrets, available } = await listConnectorSecrets();
      state.connectorSecrets = {
        loading: false,
        loaded: true,
        available,
        error: '',
        secrets: { ...emptyConnectorSecretsSummary(), ...secrets },
      };
    } catch (err) {
      state.connectorSecrets = {
        ...state.connectorSecrets,
        loading: false,
        loaded: true,
        available: true,
        error: err instanceof Error ? err.message : String(err),
      };
    } finally {
      connectorSecretsRefreshPromise = undefined;
      if (options.renderOnChange) render();
    }
  })();
  return connectorSecretsRefreshPromise;
}

function scheduleConnectorSecretsRefresh(): void {
  if (state.connectorSecrets.loaded || state.connectorSecrets.loading || connectorSecretsRefreshPromise) return;
  void refreshConnectorSecretsSummary({ renderOnChange: true });
}

function onConnectorKeysPanelChange(): void {
  void refreshConnectorSecretsSummary({ force: true, renderOnChange: true });
}

