// One portfolio row: token logo (or monogram fallback) + name/amount on the left, USD value
// with a "% of portfolio · 24h change" subline on the right. Logos, full names, and the 24h
// change are hydrated lazily into tokenMarketMetadata by ensureWalletBalanceSheetMarket(); every
// enriched field degrades gracefully when absent so the row never reflows. Shared by the Home-tab
// rail card/overlay AND the mobile/chat Wallet Balances sheet.
function walletBalanceAssetRowHtml(asset: WalletBalanceAsset, totalUsd = 0): string {
  const meta = tokenMarketMetadata.get(asset.mint);
  const logo = meta?.logoURI || knownTokenLogo(asset.mint);
  const title = walletBalanceAssetTitle(asset, meta);
  const mono = ((asset.symbol || '?').replace(/[^A-Za-z0-9]/g, '').slice(0, 3) || '?').toUpperCase();
  const valueText = asset.valueUsd === undefined ? t('price unavailable') : formatWalletBalanceUsd(asset.valueUsd);
  const ratio = totalUsd > 0 && asset.valueUsd !== undefined ? asset.valueUsd / totalUsd : NaN;
  const pct = Number.isFinite(ratio) && ratio > 0
    ? `${(ratio * 100).toFixed(ratio >= 0.1 ? 0 : 1)}%`
    : '';
  // Jupiter stats24h.priceChange is a PERCENT (e.g. 1.25 = +1.25%): classify off the rounded
  // displayed value so "flat" (▬) is reachable and we never render a coloured ▲0.00% / ▼0.00%.
  const change = typeof meta?.priceChange24h === 'number' && Number.isFinite(meta.priceChange24h) ? meta.priceChange24h : undefined;
  const changeStr = change !== undefined ? Math.abs(change).toFixed(2) : '';
  const isFlat = changeStr === '0.00';
  const deltaClass = change === undefined ? '' : isFlat ? 'flat' : change > 0 ? 'up' : 'down';
  const deltaArrow = change === undefined ? '' : isFlat ? '▬' : change > 0 ? '▲' : '▼';
  const deltaText = change === undefined ? '' : `${deltaArrow}${changeStr}%`;
  const subInner = [
    pct ? escapeHtml(pct) : '',
    deltaText ? `<span class="wallet-balance-delta ${deltaClass}">${escapeHtml(deltaText)}</span>` : '',
  ].filter(Boolean).join(' · ');
  // Monogram is the always-present base layer; the logo <img> overlays it. A failed/slow image is
  // hidden by the delegated capture-phase error handler (see bindWalletBalanceLogoFallback) so the
  // monogram shows through instead of a broken-image glyph — no inline onerror (CSP-safe).
  const logoInner = `<span class="wallet-balance-mono">${escapeHtml(mono)}</span>${
    logo ? `<img class="wallet-balance-logo-img" src="${escapeHtml(logo)}" alt="" loading="lazy" referrerpolicy="no-referrer" />` : ''
  }`;
  return `
    <div class="wallet-balance-row" data-mint="${escapeHtml(asset.mint)}">
      <span class="wallet-balance-logo" aria-hidden="true">${logoInner}</span>
      <span class="wallet-balance-id">
        <strong>${escapeHtml(title)}</strong>
        <small>${escapeHtml(formatWalletBalanceAmount(asset.amount, asset.symbol))}</small>
      </span>
      <span class="wallet-balance-val">
        <strong>${escapeHtml(valueText)}</strong>
        ${subInner ? `<em class="wallet-balance-sub">${subInner}</em>` : ''}
      </span>
    </div>
  `;
}

function publicWalletActions(): string {
  const androidNative = state.androidNativeEnvironment.isAndroidNative;
  const iosNative = state.iosNativeEnvironment.isIosNative;
  const tauriNative = state.tauriNativeEnvironment.isTauriNative;
  const multiPathFlow = multiPathWalletFlowAvailable();
  if (state.address) {
    return `
      <div class="wallet-actions public-wallet-actions connected">
        <button id="disconnect" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Disconnect wallet'))}</button>
      </div>
    `;
  }
  if (multiPathFlow && desktopConnect.flow.step !== 'idle') {
    return `<div class="wallet-actions public-wallet-actions native-wallet-actions in-flow"></div>`;
  }
  if (tauriNative) {
    // Desktop: drive the inline Discover → method flow rather than the
    // browser's Discover-then-pick-from-dropdown wiring (extensions don't
    // inject into the Tauri webview).
    return `
      <div class="wallet-actions public-wallet-actions native-wallet-actions">
        <button data-start-action="discover-desktop" class="primary" ${state.busy ? 'disabled' : ''}>
          ${walletButtonIcon()}
          <span>${escapeHtml(t('Discover'))}</span>
        </button>
      </div>
    `;
  }
  if (iosNative) {
    // iOS: the green "Connect wallet" CTA IS the provider picker — tapping it
    // opens a clean logo+name dropdown of the 4 wallets (no separate control).
    return iosConnectWalletActions();
  }
  if (androidNative) {
    return `
      <div class="wallet-actions public-wallet-actions native-wallet-actions">
        <button data-start-action="connect" class="primary wallet-connect-cta" ${state.busy ? 'disabled' : ''}>
          ${walletButtonIcon()}
          <span>${escapeHtml(t('Connect wallet'))}</span>
        </button>
      </div>
    `;
  }
  return `
    <div class="wallet-actions public-wallet-actions">
      <button data-start-action="discover" class="primary" ${state.busy ? 'disabled' : ''}>
        ${escapeHtml(t('Discover'))}
      </button>
    </div>
  `;
}

function walletButtonIcon(): string {
  return `
    <svg class="wallet-button-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <path d="M19 7h-1V6.5A2.5 2.5 0 0 0 15.5 4H5.75A3.75 3.75 0 0 0 2 7.75v8.5A3.75 3.75 0 0 0 5.75 20H19a3 3 0 0 0 3-3v-7a3 3 0 0 0-3-3Zm-3-1a.5.5 0 0 1 .5.5V7H5.75a1.25 1.25 0 0 1 0-2.5h9.75ZM20 17a1 1 0 0 1-1 1H5.75A1.75 1.75 0 0 1 4 16.25V8.76c.52.16 1.08.24 1.75.24H19a1 1 0 0 1 1 1v7Zm-4.5-4.5a1.25 1.25 0 1 0 0 2.5 1.25 1.25 0 0 0 0-2.5Z"></path>
    </svg>
  `;
}

// iOS pre-connect CTA: the "Connect wallet" button opens an inline dropdown of
// the available iOS wallets (logo + name). Selecting a row connects that wallet.
// Replaces the old separate "Choose iOS wallet" collapsible.
function iosConnectWalletActions(): string {
  const open = state.iosConnectWalletMenuOpen && !state.busy;
  const menuId = 'iosConnectWalletMenu';
  const options = state.iosWallets
    .map((wallet) => {
      const logoId = walletProviderLogoIdForName(wallet.name);
      const selected = wallet.id === state.selectedIosWalletId;
      return `
        <button
          type="button"
          class="ios-connect-wallet-option ${selected ? 'selected' : ''}"
          role="option"
          aria-selected="${selected ? 'true' : 'false'}"
          data-ios-connect-wallet-id="${escapeHtml(wallet.id)}"
        >
          ${logoId ? selectPickerLogo(logoId) : ''}
          <strong>${escapeHtml(wallet.name)}</strong>
        </button>
      `;
    })
    .join('');
  return `
    <div class="wallet-actions public-wallet-actions native-wallet-actions ios-connect-wallet ${open ? 'open' : ''}" data-ios-connect-wallet>
      <button
        type="button"
        class="primary wallet-connect-cta ios-connect-wallet-trigger"
        data-ios-connect-toggle
        aria-haspopup="listbox"
        aria-expanded="${open ? 'true' : 'false'}"
        aria-controls="${menuId}"
        ${state.busy ? 'disabled' : ''}
      >
        ${walletButtonIcon()}
        <span>${escapeHtml(t('Connect wallet'))}</span>
        <span class="template-picker-caret ios-connect-wallet-caret" aria-hidden="true"></span>
      </button>
      <div
        id="${menuId}"
        class="ios-connect-wallet-menu"
        role="listbox"
        aria-label="${escapeHtml(t('Choose iOS wallet'))}"
        ${open ? '' : 'hidden'}
      >
        ${options}
      </div>
    </div>
  `;
}

