function terminalCommandRow(label: string, command: string, badge: string): string {
  const copyId = commandCopyId('terminal', label, command);
  const copied = state.recentCopyId === copyId;
  return `
    <div class="terminal-command-row ${copied ? 'copied' : ''}">
      <div>
        <span>${escapeHtml(label)}</span>
        <code>${escapeHtml(command)}</code>
      </div>
      <strong>${escapeHtml(badge)}</strong>
      <button
        class="${copied ? 'copied' : ''}"
        data-copy="${escapeHtml(command)}"
        data-copy-id="${escapeHtml(copyId)}"
        data-copy-name="${escapeHtml(tf('{label} command', { label }))}"
        title="${escapeHtml(tf('Copy {label} command', { label }))}"
      >
        ${copied ? escapeHtml(t('Copied')) : escapeHtml(t('Copy'))}
      </button>
    </div>
  `;
}

function terminalCommandState(runtimePath = currentRuntimePath()): {
  bridgeLine: string;
  bridgeTone: string;
  walletLine: string;
  walletTone: string;
} {
  if (state.bridgeActive && state.address) {
    return {
      bridgeLine: t('Bridge connected'),
      bridgeTone: 'ok',
      walletLine: tf('Wallet {address} ready', { address: short(state.address) }),
      walletTone: 'ok',
    };
  }
  if (state.address) {
    return {
      bridgeLine: t('Bridge offline, terminal app can start it'),
      bridgeTone: 'warn',
      walletLine: tf('Wallet {address} connected in browser', { address: short(state.address) }),
      walletTone: 'ok',
    };
  }
  return {
    bridgeLine: runtimePath.bridgeLine,
    bridgeTone: 'warn',
    walletLine: runtimePath.walletLine,
    walletTone: '',
  };
}

function currentRuntimePath(): RuntimePath {
  return runtimePaths().find((runtimePath) => runtimePath.id === state.selectedRuntimePath) ?? runtimePaths()[0]!;
}

function runtimePathById(id: string | undefined): RuntimePath | undefined {
  return runtimePaths().find((runtimePath) => runtimePath.id === id);
}

function runtimeCommandCopyId(scope: string, runtimePath: RuntimePath): string {
  return commandCopyId(scope, runtimePath.label, runtimePath.command);
}

function commandCopyId(scope: string, label: string, command: string): string {
  return `${scope}:${label}:${command}`;
}

function markCopied(copyId: string): void {
  state.recentCopyId = copyId;
  if (copyResetTimer !== null) {
    window.clearTimeout(copyResetTimer);
  }
  copyResetTimer = window.setTimeout(() => {
    if (state.recentCopyId !== copyId) return;
    state.recentCopyId = '';
    copyResetTimer = null;
    // Don't re-render the chat just to clear the transient "copied" highlight (see copy handler).
    if (state.activeTab !== 'chat') render();
  }, 1600);
}

function signatureLifecycle(items: Array<[string, string, boolean]>): string {
  return `
    <div class="signature-lifecycle signature-trace" aria-label="${escapeHtml(t('Signature lifecycle'))}">
      ${items
        .map(
          ([label, value, complete]) => `
            <div class="trace-node ${complete ? 'complete' : ''}">
              <span class="trace-dot"></span>
              <div>
                <strong>${escapeHtml(label)}</strong>
                <p>${escapeHtml(value)}</p>
              </div>
            </div>
          `,
        )
        .join('')}
    </div>
  `;
}

function signaturePlaceholder(title: string, detail: string): string {
  return `
    <div class="signature-placeholder">
      <span>${escapeHtml(title)}</span>
      <p>${escapeHtml(detail)}</p>
    </div>
  `;
}

function templateOutcome(template: AgentPlanTemplate): TemplateOutcome {
  if (template.actionType === 'read_only') return 'audit';
  if (templateCanQueue(template)) return 'queueable';
  return 'proof';
}

function templateCanQueue(template: AgentPlanTemplate): boolean {
  return ['transfer_sol', 'transfer_spl', 'swap', 'recurring_payment', 'blink_action'].includes(template.actionType) ||
    CONNECTOR_APPROVAL_ACTION_TYPES.has(template.actionType);
}

function planOutcome(plan: AgentPlan): TemplateOutcome {
  if (plan.actionType === 'read_only') return 'audit';
  if (canQueueAgentPlan(plan)) return 'queueable';
  return 'proof';
}

function outcomeLabel(outcome: TemplateOutcome): string {
  switch (outcome) {
    case 'queueable':
      return t('Request approval');
    case 'proof':
      return t('Proof only');
    case 'audit':
      return t('Evidence only');
  }
}

function outcomeShortLabel(outcome: TemplateOutcome): string {
  switch (outcome) {
    case 'queueable':
      return t('Approval-ready');
    case 'proof':
      return t('Proof only');
    case 'audit':
      return t('Evidence only');
  }
}

function outcomeDetailForTemplate(template: AgentPlanTemplate): string {
  const outcome = templateOutcome(template);
  if (template.actionType === 'recurring_payment') {
    return t('This creates a repeat payment. Each due payment appears in Sign Approval for approve or deny.');
  }
  switch (outcome) {
    case 'queueable':
      return t('This draft can request a wallet approval. Signed-in users use Agentic Cloud; signed-out workflow stays on this device.');
    case 'proof':
      return t('This can be signed as review evidence, but it cannot be queued as a transaction.');
    case 'audit':
      return t('This can be signed as evidence only. It does not queue an approval request.');
  }
}

function outcomeDetailForPlan(plan: AgentPlan): string {
  const outcome = planOutcome(plan);
  if (plan.actionType === 'recurring_payment') {
    return t('Queueing creates a repeat payment rule. Future payments still require approval.');
  }
  switch (outcome) {
    case 'queueable':
      return t('Send this plan for approval when you want a wallet decision.');
    case 'proof':
      return t('This plan is for review evidence. Sign a review proof if you want an audit record.');
    case 'audit':
      return t('This plan records read-only context or audit notes. Sign proof only; it does not move funds.');
  }
}

function outcomeClass(outcome: TemplateOutcome): string {
  return `outcome-${outcome}`;
}

function queueActionLabelForPlan(plan: AgentPlan): string {
  return plan.actionType === 'recurring_payment' ? t('Create repeat payment') : t('Send for approval');
}

function templatesForOutcomeFilter(filter = state.templateOutcomeFilter): AgentPlanTemplate[] {
  const cat = state.createActionCategory;
  const selectedConnector = selectedConnectorForCreate(selectedTemplate());
  if (selectedConnector) {
    const list = templatesForConnector(selectedConnector);
    return cat ? list.filter((tpl) => templateMatchesActionCategory(tpl, cat)) : list;
  }
  const templates = oneTimePlanTemplates();
  if (cat) return templates.filter((tpl) => templateMatchesActionCategory(tpl, cat));
  if (filter === 'all') return templates;
  return templates.filter((template) => templateOutcome(template) === filter);
}

// The plan-template picker offers a real choice only when the SELECTED template's action has more
// than one template. Derive the pool from the selected template's OWN action categories (not
// state.createActionCategory) so the picker is correctly hidden even when no category is scoped —
// the default New Request landing (lands on Swap) and connector manage/positions flows leave
// createActionCategory empty, which would otherwise make templatesForOutcomeFilter() return a
// grab-bag and keep the redundant dropdown. Single-option actions (Swap, Send, Jupiter
// Lend/Limit/DCA/Prediction, Lulo, Phoenix limit, Pyth oracle, connector "Check", …) collapse;
// multi-option ones (Kamino lend, Marginfi borrow, Raydium LP, Proof/Evidence, …) keep the picker.
function templatesSharingSelectedAction(): AgentPlanTemplate[] {
  const template = selectedTemplate();
  const selectedConnector = selectedConnectorForCreate(template);
  const pool = selectedConnector ? templatesForConnector(selectedConnector) : oneTimePlanTemplates();
  const cats = templateActionCategories(template);
  if (cats.size === 0) return pool.filter((tpl) => tpl.id === template.id);
  return pool.filter((tpl) => {
    const tcats = templateActionCategories(tpl);
    for (const c of cats) if (tcats.has(c)) return true;
    return false;
  });
}

// True when the selected template is the only plan template for its action. In that case the
// plan-template dropdown offers no real choice, so both render surfaces drop the whole picker block.
function activeCategoryHasSingleTemplate(): boolean {
  return templatesSharingSelectedAction().length <= 1;
}


function oneTimePlanTemplates(): AgentPlanTemplate[] {
  return AGENT_PLAN_TEMPLATES.filter((template) =>
    template.actionType !== 'recurring_payment' &&
    !isDedicatedConnectorTemplate(template),
  );
}

function templatesForConnector(connector: ProtocolConnector): AgentPlanTemplate[] {
  const templates = connectorActionFormsForConnector(connector)
    .map((form) => AGENT_PLAN_TEMPLATES.find((template) => template.id === form.templateId))
    .filter((template): template is AgentPlanTemplate => Boolean(template));
  const seen = new Set<string>();
  return templates.filter((template) => {
    if (seen.has(template.id)) return false;
    seen.add(template.id);
    return template.actionType !== 'recurring_payment';
  });
}

function isDedicatedConnectorTemplate(template: AgentPlanTemplate): boolean {
  return template.connectorActionSource === 'first-class-adapter' &&
    Boolean(connectorActionFormForTemplate(template));
}

function activePanel(): string {
  // Push the active language to demo-i18n/uiLang so self-contained devTab modules render
  // in lock-step (they translate via uiLang's t()/tf(), not main.ts's).
  activeUiLanguage();
  // Chat hidden/disabled on this surface but a prior session persisted the chat
  // tab: fall back to Home so the user never lands on an unavailable tab.
  if (state.activeTab === 'chat' && (chatTabHidden() || !chatTabAiConnected())) state.activeTab = 'overview';
  switch (state.activeTab) {
    case 'overview':
      return commandCenterPanel();
    case 'chat':
      return chatPanel();
    case 'wallet':
      return walletFlowPanel();
    case 'agent':
      return agentPlanPanel();
    case 'generated':
      state.activeTab = 'agent';
      state.oneTimePlanView = 'review';
      return agentPlanPanel();
    case 'inbox':
      return approvalInboxPanel();
    case 'completed':
      return completedPlansPanel();
    case 'schedule':
      return scheduledApprovalsPanel();
    case 'labs':
      return labsPanel();
    case 'preferences':
      return preferencesPanel();
    case 'addressBook':
      // The Address Book tab is hidden from the nav (see ADDRESS_BOOK_TAB_HIDDEN); redirect a
      // persisted/stale activeTab to the command center rather than render the stranded panel.
      if (ADDRESS_BOOK_TAB_HIDDEN) {
        state.activeTab = 'overview';
        return commandCenterPanel();
      }
      return addressBookPanel();
    default: {
      // Layer 1 tab fallthrough. If the activeTab id matches a registered tab
      // AND its guard passes, render its panel. Otherwise fall back to the
      // command center so a stale id never strands the UI.
      const devTab = findDevTab(state.activeTab);
      if (devTab && devTab.guard()) return devTab.render();
      const requiredSurface = requiredMoreSurface(state.activeTab);
      if (requiredSurface) return requiredSurface.render();
      return commandCenterPanel();
    }
  }
}

function spendFallbackPanel(filter: SpendNavFilter): string {
  const spendTab = findDevTab('spend');
  if (!spendTab?.guard()) return commandCenterPanel();
  state.activeTab = 'spend';
  pendingSpendNavigation = { filter };
  return spendTab.render();
}

function commandCenterPanel(): string {
  return `
    <div class="command-shell">
      <div class="command-subtab-row" role="tablist" aria-label="${escapeHtml(t('Home sections'))}">
        ${commandCenterSubtab('center', t('Center'), t('Command overview'))}
        ${commandCenterSubtab('ai', t('Connect AI'), t('Agent setup'))}
        ${commandCenterSubtab('storage', t('Connect Cloud Storage'), t('Device and cloud workspace'), t('Connect Cloud'), t('Cloud workspace'))}
      </div>
      ${state.commandCenterView === 'ai'
        ? commandCenterAiPanel()
        : state.commandCenterView === 'storage'
          ? commandCenterStoragePanel()
          : commandCenterOverviewPanel()}
    </div>
  `;
}

function commandCenterSubtab(
  view: CommandCenterView,
  label: string,
  detail: string,
  mobileLabel?: string,
  mobileDetail?: string,
): string {
  const active = state.commandCenterView === view;
  const labelMarkup = mobileLabel
    ? `<strong class="cc-label-full">${escapeHtml(label)}</strong>` +
      `<strong class="cc-label-mobile">${escapeHtml(mobileLabel)}</strong>`
    : `<strong>${escapeHtml(label)}</strong>`;
  const detailMarkup = mobileDetail
    ? `<span class="cc-detail-full">${escapeHtml(detail)}</span>` +
      `<span class="cc-detail-mobile">${escapeHtml(mobileDetail)}</span>`
    : `<span>${escapeHtml(detail)}</span>`;
  return `
    <button
      type="button"
      class="${active ? 'active' : ''}"
      data-command-center-view="${escapeHtml(view)}"
      role="tab"
      aria-selected="${active ? 'true' : 'false'}"
    >
      ${labelMarkup}
      ${detailMarkup}
    </button>
  `;
}

function commandCenterOverviewPanel(): string {
  const openApprovals = activeWorkflowPreparedActions().filter((action) => !action.archived && isActionInboxActive(action));
  const recurringActive = activeWorkflowRecurringPayments().filter((payment) => payment.status === 'active' && !isRecurringPaymentCompleted(payment));
  const completed = completedPlanRecords();
  const latestProof = state.labArtifacts[0];
  const latestHistory = completed[0];
  const proofLabel = latestProof
    ? `${latestProof.title || receiptLabelForKind(latestProof.kind)} - ${short(latestProof.artifactHash)}`
    : latestHistory
      ? `${latestHistory.status} - ${short(latestHistory.actionId ?? latestHistory.signature ?? latestHistory.id)}`
      : t('No proof yet');
  const headerActions = isMobileAppViewport()
    ? ''
    : `
          <div class="command-center-actions">
            ${chatTabHidden() ? '' : `<button type="button" class="utility" data-tab="chat">${escapeHtml(t('Chat'))}</button>`}
            <button type="button" class="primary" data-one-time-view="create">${escapeHtml(t('New Request'))}</button>
          </div>
        `;
  return `
    <div class="command-overview-stack">
      <section class="approval-object signature-stage stage-overview stage-anchor form-kit ${openApprovals.length ? 'stage-active' : 'stage-draft'}">
        ${formKitHero({
          eyebrow: t('Home'),
          title: t('Approval workspace.'),
          detail: t('AI prepares the review item; the wallet owner checks the details and signs only after review.'),
          icon: 'wallet',
          aside: headerActions,
        })}

        ${SHOW_DEV_CONTROLS ? '' : firstRunActionBand()}
        ${SHOW_DEV_CONTROLS ? '' : trustLayerPanel()}

        ${commandLoopBlock(openApprovals.length > 0, completed.length > 0 || state.labArtifacts.length > 0)}

        ${renderWorkspaceCardGroup({
          wallet: commandCenterWalletCard(),
          approvals: commandCenterCard(t('Approvals'), tf('{n} pending', { n: openApprovals.length }), approvalsCardDetail(openApprovals), openApprovals.length ? 'warn' : 'idle', 'open-inbox', openApprovals.length ? t('Review') : t('Open'), 'approvals'),
          payments: commandCenterCard(t('Repeat Payments'), tf('{n} active', { n: recurringActive.length }), recurringActive[0] ? scheduleLabel(recurringActive[0]) : t('No active repeat payments'), recurringActive.length ? 'good' : 'idle', 'open-recurring', t('Open'), 'recurring'),
          proof: commandCenterCard(t('Save Proof'), proofLabel, latestProof ? formatDateTime(latestProof.createdAt) : latestHistory ? formatDateTime(latestHistory.completedAt) : t('Save a proof or complete an approval'), latestProof || latestHistory ? 'good' : 'idle', 'open-proofs', latestProof || latestHistory ? t('View') : t('Save'), 'proofs'),
        })}

        ${commandPreferenceSnapshot()}
      </section>
    </div>
  `;
}

interface WorkspaceCardGroup {
  wallet: string;
  approvals: string;
  payments: string;
  proof: string;
}

function renderWorkspaceCardGroup(cards: WorkspaceCardGroup): string {
  if (!isMobileAppViewport()) {
    return `
      <div class="command-center-grid">
        ${cards.wallet}
        ${cards.approvals}
        ${cards.payments}
        ${cards.proof}
      </div>
    `;
  }
  const active: AndroidWorkspaceTab = state.androidWorkspaceTab;
  const tabs: Array<{ id: AndroidWorkspaceTab; label: string; icon: CommandCenterIconId; body: string }> = [
    { id: 'wallet', label: t('Wallet'), icon: 'wallet', body: cards.wallet },
    { id: 'approvals', label: t('Approvals'), icon: 'approvals', body: cards.approvals },
    { id: 'payments', label: t('Payments'), icon: 'recurring', body: cards.payments },
    { id: 'proof', label: t('Proof'), icon: 'proofs', body: cards.proof },
  ];
  return `
    <div class="android-tab-card android-workspace-tabs" data-android-tab-group="workspace">
      <div class="android-tab-strip" role="tablist" aria-label="${escapeHtml(t('Workspace sections'))}">
        ${tabs.map((tab) => androidTabButton('workspace', tab.id, tab.label, tab.icon, tab.id === active)).join('')}
      </div>
      <div class="android-tab-body" role="tabpanel">
        ${tabs.find((tab) => tab.id === active)?.body ?? cards.wallet}
      </div>
    </div>
  `;
}

function androidTabButton(
  group: 'workspace' | 'setup' | 'workspace-backup',
  id: string,
  label: string,
  icon: CommandCenterIconId,
  active: boolean,
): string {
  const attr =
    group === 'workspace' ? 'data-android-workspace-tab' :
    group === 'setup' ? 'data-android-setup-tab' :
    'data-android-workspace-backup-tab';
  return `
    <button
      type="button"
      class="android-tab${active ? ' active' : ''}"
      role="tab"
      aria-selected="${active ? 'true' : 'false'}"
      ${attr}="${escapeHtml(id)}"
    >
      <span class="android-tab-icon">${commandCenterIcon(icon)}</span>
      <span class="android-tab-label">${escapeHtml(label)}</span>
    </button>
  `;
}

interface CommandPreferenceSnapshotCard {
  label: string;
  value: string;
  detail: string;
  meta: string;
  tone: 'good' | 'warn' | 'idle';
  icon: CommandCenterIconId;
  logoId?: BrandLogoId;
  logoLabel?: string;
  actionLabel: string;
  action: CommandPreferenceSnapshotAction;
}

function commandPreferenceSnapshot(): string {
  const cards: CommandPreferenceSnapshotCard[] = [
    commandAiPreferenceSnapshotCard(),
    commandCloudPreferenceSnapshotCard(),
    commandConnectorsPreferenceSnapshotCard(),
    commandGuardrailsPreferenceSnapshotCard(),
  ];
  return `
    <section class="command-preference-snapshot" aria-label="${escapeHtml(t('Preference snapshot'))}">
      <div class="command-preference-snapshot-head">
        <div>
          <span>${escapeHtml(t('Preference snapshot'))}</span>
          <h3>${escapeHtml(t('Current setup'))}</h3>
        </div>
        <p>${escapeHtml(t('Most important workspace settings at a glance.'))}</p>
      </div>
      ${renderPreferenceSnapshotGroup(cards)}
    </section>
  `;
}

function renderPreferenceSnapshotGroup(cards: CommandPreferenceSnapshotCard[]): string {
  if (!isMobileAppViewport()) {
    return `
      <div class="command-preference-snapshot-grid">
        ${cards.map(commandPreferenceSnapshotCard).join('')}
      </div>
    `;
  }
  const setupTabs: Array<{ id: AndroidSetupTab; label: string; icon: CommandCenterIconId }> = [
    { id: 'ai', label: t('AI Path'), icon: 'ai' },
    { id: 'cloud', label: t('Cloud'), icon: 'cloud' },
    { id: 'connectors', label: t('Connectors'), icon: 'connectors' },
    { id: 'rules', label: t('Rules'), icon: 'guardrails' },
  ];
  const active = state.androidSetupTab;
  const activeIndex = setupTabs.findIndex((tab) => tab.id === active);
  const card = cards[activeIndex >= 0 ? activeIndex : 0] ?? cards[0];
  return `
    <div class="android-tab-card android-setup-tabs" data-android-tab-group="setup">
      <div class="android-tab-strip" role="tablist" aria-label="${escapeHtml(t('Setup sections'))}">
        ${setupTabs.map((tab) => androidTabButton('setup', tab.id, tab.label, tab.icon, tab.id === active)).join('')}
      </div>
      <div class="android-tab-body" role="tabpanel">
        ${card ? commandPreferenceSnapshotCard(card) : ''}
      </div>
    </div>
  `;
}

function commandAiPreferenceSnapshotCard(): CommandPreferenceSnapshotCard {
  const inventory = aiSetupInventory();
  const configured = inventory.active.configured;
  // Web/desktop ignores inactive-configured AI paths here too (see aiSettingsPanel), so the command
  // snapshot doesn't echo "Device Agent configured" off a cached/staged key. Mobile keeps it.
  const inactive = (IS_ANDROID_APP || IS_IOS_APP) ? inventory.inactiveConfigured[0] : undefined;
  const anyConfigured = configured || Boolean(inactive);
  const path = aiPathPreferenceLabel(state.aiSettings.mode);
  const providerPreset = aiProviderPresetById(state.aiSettings.provider);
  const bridgeStatus = visibleBridgeAiStatus(state.aiStatus);
  const bridgeConnector = state.aiSettings.mode === 'bridge' && bridgeStatus?.engine === 'connector'
    ? bridgeStatus
    : null;
  // Plan Connector (paired-bridge or local-bridge connector engine): show "Plan Connector - Codex" +
  // a plan note (NOT the connector auth status, which was the previous model-slot bug).
  const isPlanConnector = Boolean(state.aiSettings.pairedBridge) || Boolean(bridgeConnector);
  const planConnector = isPlanConnector ? activePlanConnector() : undefined;
  const provider = isPlanConnector
    ? planConnectorTitle(planConnector)
    : state.aiSettings.mode === 'bridge' && state.aiStatus?.provider
    ? state.aiStatus.provider
    : state.aiSettings.mode === 'device-agent' && state.deviceAgentStatus?.provider
      ? state.deviceAgentStatus.provider
    : providerPreset.label;
  const model = isPlanConnector
    ? (state.aiStatus?.model?.trim() || connectorPlanNote(planConnector))
    : state.aiSettings.mode === 'bridge' && state.aiStatus?.model
    ? state.aiStatus.model
    : state.aiSettings.mode === 'device-agent' && state.deviceAgentStatus?.model
      ? state.deviceAgentStatus.model
    : state.aiSettings.model || providerPreset.model;
  const readiness = aiReadinessLabel(state.aiStatus);
  const displayProvider = configured
    ? provider
    : inactive?.provider ?? provider;
  const displayModel = configured
    ? model
    : inactive?.model ?? model;
  return {
    label: t('AI path'),
    value: configured
      ? tf('{path} connected', { path })
      : inactive
        ? tf('{path} configured', { path: aiPathPreferenceLabel(inactive.mode) })
        : tf('{path} selected', { path }),
    detail: `${displayProvider} - ${displayModel || t('model configured')}`,
    meta: configured ? readiness : inactive ? tf('{path} selected', { path }) : readiness,
    tone: anyConfigured ? 'good' : 'warn',
    icon: anyConfigured ? 'aiConnected' : 'ai',
    ...(anyConfigured
      ? {
          logoId: isPlanConnector
            ? connectorBrandLogoId(planConnector)
            : configured ? connectedAiProviderLogoId() : aiProviderLogoId(state.aiSettings.provider),
          logoLabel: displayProvider,
        }
      : {}),
    actionLabel: anyConfigured ? t('Open') : t('Connect'),
    action: { type: 'command', view: 'ai' },
  };
}

function commandCloudPreferenceSnapshotCard(): CommandPreferenceSnapshotCard {
  const signedIn = state.cloudSession.status === 'signed-in';
  const matched = cloudSessionMatchesWallet();
  const mismatch = cloudSessionWalletMismatch();
  const reconnectNeeded = signedIn && !matched && !mismatch;
  const unavailable = state.cloudSession.status === 'unavailable';
  const value = unavailable
    ? t('Cloud unavailable')
    : matched
      ? t('Cloud connected')
      : signedIn
        ? reconnectNeeded
          ? t('Reconnect wallet')
          : t('Wallet mismatch')
        : t('Signed out');
  const detail = matched
    ? tf('Signed in as {address}', { address: short(state.cloudSession.walletAddress) })
    : signedIn
      ? tf('Signed in as {address}. Connect the matching wallet.', { address: short(state.cloudSession.walletAddress) })
      : unavailable
        ? t('Workflow data stays saved on this device.')
        : t('Cloud sync is off; local workspace is active.');
  const meta = matched
    ? t('Sync available')
    : signedIn
      ? t('Wallet identity issue')
      : unavailable
        ? t('Local workspace')
        : t('Local workspace');
  return {
    label: t('Cloud storage'),
    value,
    detail,
    meta,
    tone: matched ? 'good' : signedIn ? 'warn' : 'idle',
    icon: 'cloud',
    actionLabel: matched ? t('Open') : t('Connect'),
    action: { type: 'command', view: 'storage' },
  };
}

function commandConnectorsPreferenceSnapshotCard(): CommandPreferenceSnapshotCard {
  const enabledConnectors = enabledProtocolConnectors(state.connectedDapps, state.cluster);
  const enabledCount = enabledConnectors.length;
  const names = enabledConnectors.slice(0, 2).map((connector) => connector.name).join(', ');
  const extra = enabledCount - 2;
  const detail = enabledCount
    ? `${names}${extra > 0 ? tf(' +{n} more', { n: extra }) : ''}`
    : tf('No connectors enabled for {cluster}.', { cluster: titleCaseCluster(state.cluster) });
  return {
    label: t('Connectors'),
    value: tf('{count} {noun} set', { count: enabledCount, noun: enabledCount === 1 ? t('connector') : t('connectors') }),
    detail,
    meta: '',
    tone: enabledCount ? 'good' : 'idle',
    icon: 'connectors',
    actionLabel: t('Manage'),
    action: { type: 'preferences', view: 'access' },
  };
}

function commandGuardrailsPreferenceSnapshotCard(): CommandPreferenceSnapshotCard {
  const railsOn = safetyRailsEnabledCount();
  // Agent Policies is hidden (SHOW_AGENT_POLICIES), so its count neither shows in the detail nor
  // flips this card to "set" on its own.
  const enabledPolicies = SHOW_AGENT_POLICIES ? state.agentPolicies.filter((policy) => policy.enabled).length : 0;
  const recipients = state.recipientRules.recipients.length;
  const alertsOn = notificationEnabledCount();
  const hasCustomReview = railsOn > 0 || enabledPolicies > 0 || recipients > 0 || alertsOn > 0;
  return {
    label: t('Review rules'),
    value: hasCustomReview ? t('Preferences set') : t('Defaults active'),
    detail: `${countPhrase(recipients, t('recipient'), t('recipients'))} - ${countPhrase(railsOn, t('rail'), t('rails'))}${SHOW_AGENT_POLICIES ? ` - ${countPhrase(enabledPolicies, t('policy'), t('policies'))}` : ''} - ${countPhrase(alertsOn, t('alert'), t('alerts'))}`,
    meta: hasCustomReview ? t('Review extras on') : t('No extra rules'),
    tone: hasCustomReview ? 'good' : 'idle',
    icon: 'guardrails',
    actionLabel: t('Review'),
    action: { type: 'preferences', view: 'rules' },
  };
}

function commandPreferenceSnapshotCard(card: CommandPreferenceSnapshotCard): string {
  const hasMeta = Boolean(card.meta.trim());
  const meta = hasMeta ? `<em>${escapeHtml(card.meta)}</em>` : '';
  const providerLogo = card.logoId
    ? `
      <span class="command-preference-provider-logo" title="${escapeHtml(card.logoLabel ?? card.label)}">
        ${brandLogo(card.logoId, 'command-preference-provider-logo-mark')}
      </span>
    `
    : '';
  // const aiPathVisual = card.icon === 'aiConnected' ? commandConnectedAiPathVisual() : '';
  const aiPathVisual = '';
  const cardClass = ['command-preference-card', card.tone, providerLogo ? 'has-provider-logo' : '']
    .filter(Boolean)
    .join(' ');
  return `
    <article class="${escapeHtml(cardClass)}">
      ${aiPathVisual}
      ${providerLogo}
      <div class="command-preference-card-label">
        ${commandCenterIcon(card.icon)}
        <span>${escapeHtml(card.label)}</span>
      </div>
      <strong>${escapeHtml(card.value)}</strong>
      <p>${escapeHtml(card.detail)}</p>
      <div class="command-preference-card-foot${hasMeta ? '' : ' no-meta'}">
        ${meta}
        ${commandPreferenceSnapshotButton(card)}
      </div>
    </article>
  `;
}

function commandPreferenceSnapshotButton(card: CommandPreferenceSnapshotCard): string {
  if (card.action.type === 'command') {
    return `<button type="button" class="utility" data-command-center-view="${escapeHtml(card.action.view)}">${escapeHtml(card.actionLabel)}</button>`;
  }
  return `<button type="button" class="utility" data-tab="preferences" data-preferences-view="${escapeHtml(card.action.view)}">${escapeHtml(card.actionLabel)}</button>`;
}

function aiPathPreferenceLabel(mode: AiSettings['mode']): string {
  switch (mode) {
    case 'hosted':
      return 'Hosted BYOK';
    case 'bridge':
      return 'Local Bridge';
    case 'device-agent':
      return 'Device Agent';
    case 'session':
      return IS_ANDROID_APP ? 'Android Session' : (IS_IOS_APP || state.iosNativeEnvironment.isIosNative) ? 'iOS Session' : 'Browser Session';
  }
}

function countPhrase(count: number, singular: string, plural = `${singular}s`): string {
  return tf('{count} {label}', { count, label: count === 1 ? singular : plural });
}

function androidMobileAiPathTabLabel(mode: AiSettings['mode']): string {
  switch (mode) {
    case 'device-agent':
      return 'Device Agent';
    case 'hosted':
      return 'BYOK';
    case 'bridge':
      return 'Bridge';
    case 'session':
      return 'Session';
  }
}

function approvalsCardDetail(openApprovals: PreparedAction[]): string {
  const next = openApprovals[0];
  if (!next) return t('No approvals waiting');
  const recipient = recipientParam(next);
  const recipientShort = recipient ? recipientDisplayLabel(recipient) : '';
  let base: string;
  if (next.kind === 'transfer_sol') {
    const amount = stringParam(next, 'amountSol') || stringParam(next, 'amount');
    const amountText = amount ? `${amount} SOL` : 'SOL';
    base = recipientShort ? tf('Send {amount} to {recipient}', { amount: amountText, recipient: recipientShort }) : tf('Send {amount}', { amount: amountText });
  } else if (next.kind === 'transfer_spl') {
    const amount = stringParam(next, 'amount');
    const token = stringParam(next, 'token') || 'token';
    const tokenText = looksLikeMintAddress(token) ? tokenDisplayLabel(token) : token;
    const amountText = amount ? `${amount} ${tokenText}` : tokenText;
    base = recipientShort ? tf('Send {amount} to {recipient}', { amount: amountText, recipient: recipientShort }) : tf('Send {amount}', { amount: amountText });
  } else if (next.kind === 'swap') {
    const input = stringParam(next, 'inputToken') || 'input';
    const output = stringParam(next, 'outputToken') || 'output';
    const amount = stringParam(next, 'amount') || stringParam(next, 'amountIn');
    const inputLabel = looksLikeMintAddress(input) ? tokenDisplayLabel(input) : input;
    const outputLabel = looksLikeMintAddress(output) ? tokenDisplayLabel(output) : output;
    base = amount ? tf('Swap {amount} {input} to {output}', { amount, input: inputLabel, output: outputLabel }) : tf('Swap {input} to {output}', { input: inputLabel, output: outputLabel });
  } else {
    base = preparedActionCardTitle(next);
  }
  const extra = openApprovals.length - 1;
  return extra > 0 ? tf('{base} (+{n} more)', { base, n: extra }) : base;
}

function commandCenterAiPanel(): string {
  const inventory = aiSetupInventory();
  const configured = inventory.active.configured;
  const anyConfigured = inventory.anyConfigured;
  const confirmed = isAiPlannerConfirmedForCurrentSettings();
  const headerActions = isMobileAppViewport()
    ? ''
    : `
          <div class="command-center-actions">
            <button type="button" class="primary" data-one-time-view="create">${escapeHtml(t('New Request'))}</button>
          </div>
        `;
  return `
    <div class="command-detail-stack command-ai-panel">
      <section class="approval-object signature-stage command-page-card form-kit">
        ${formKitHero({
          eyebrow: t('Connect AI'),
          title: t('Connect an AI route.'),
          detail: t('Set up the agent route, provider, model, and connection boundary. Workflow actions still require explicit review.'),
          icon: 'ai',
          aside: headerActions,
        })}

        <div class="command-route-grid" aria-label="${escapeHtml(t('AI route capabilities'))}">
          ${commandAiRouteCards()}
        </div>

        ${isMobileAppViewport()
          ? `
        ${commandAiWorkflowEducation()}

        <div class="command-ai-boundary">
          <strong>${escapeHtml(configured ? confirmed ? t('Planner confirmed') : t('Planner configured') : anyConfigured ? t('Inactive path configured') : t('Templates work without AI'))}</strong>
          <span>${escapeHtml(t('AI prepares drafts; you approve in your wallet. Private keys never leave your wallet.'))}</span>
        </div>

        ${commandAiDataDisclosure()}`
          : `
        <div class="command-ai-two-col">
          ${commandAiNoAiCard()}
          ${commandAiDataDisclosure()}
        </div>`}

        ${aiSettingsCard('planner')}
      </section>
    </div>
  `;
}

function commandAiRouteCards(): string {
  const mobileAiPathPolicy = isMobileAiPathPolicySurface();
  const hostedCloudSignInRequired = mobileAiPathPolicy && !cloudSessionMatchesWallet();
  const deviceAgentFirst = deviceAgentPathAvailableForCurrentProvider();
  const websitePlanConnectorAvailable = websitePlanConnectorSetupAvailable();
  // phonePairingAvailable() self-gates by platform (Android bridge or iOS scanner), so no IS_ANDROID_APP prefix.
  const planConnectorAvailable = phonePairingAvailable() || websitePlanConnectorAvailable;
  const definitions: Array<{ id: AndroidAiRouteTab; mode: AiSettings['mode'] | null; title: string; detail: string; meta: string; available: boolean }> = [
    {
      id: 'hosted',
      mode: 'hosted',
      title: t('Hosted BYOK'),
      detail: hostedCloudSignInRequired
        ? t('Cloud sign-in required for Hosted BYOK relay. Your AI key is not stored.')
        : t('Connect a preset provider key through Agentic for AI agent requests.'),
      meta: t('Cloud'),
      available: true,
    },
    {
      id: 'bridge',
      mode: 'bridge',
      title: t('Local Bridge AI'),
      detail: t('Connect the local runtime so AI agent requests can use this machine.'),
      meta: t('Local'),
      available: !mobileAiPathPolicy,
    },
    {
      id: 'session',
      mode: 'session',
      title: IS_ANDROID_APP ? t('Android Session') : (IS_IOS_APP || state.iosNativeEnvironment.isIosNative) ? t('iOS Session') : t('Browser Session'),
      detail: tf('Connect a temporary key in {location} without saving it to Agentic.', { location: (IS_ANDROID_APP || IS_IOS_APP || state.iosNativeEnvironment.isIosNative) ? t('this app runtime') : t('this tab') }),
      meta: t('Session'),
      // Session is a browser/web route, not a native mobile app route.
      available: !IS_TAURI_APP && !mobileAiPathPolicy,
    },
    {
      id: 'device-agent',
      mode: 'device-agent',
      title: IS_TAURI_APP && state.tauriBridgeStatus?.bridgeReachable
        ? t('Desktop Device Agent')
        : t('Device Agent'),
      detail: IS_TAURI_APP && state.tauriBridgeStatus?.bridgeReachable
        ? t('Routed through the local desktop bridge. Agent requests stay on this machine and never round-trip to the cloud.')
        : IS_ANDROID_APP
          ? t('Connect the on-device runtime so agent requests stay inside this app boundary.')
          : t('Connect the gated Device Agent setup for this wallet.'),
      meta: IS_TAURI_APP && state.tauriBridgeStatus?.bridgeReachable
        ? t('Desktop')
        : t('On-device'),
      available: mobileAiPathPolicy || deviceAgentModeVisible(),
    },
    {
      id: 'plan-connector',
      mode: null,
      title: 'Plan Connector',
      detail: websitePlanConnectorAvailable
        ? t('Use Codex, Claude, Gemini, or Antigravity from this computer without pasting a provider API key.')
        : state.aiSettings.pairedBridge
          ? t('Your phone is paired to this computer plan connector.')
          : t('Use Codex, Claude, Gemini, or Antigravity from your signed-in computer. Scan one QR from Android.'),
      meta: websitePlanConnectorAvailable
        ? t('Website plan connection')
        : state.aiSettings.pairedBridge ? t('Computer plan connected') : t('Computer plan connection'),
      available: planConnectorAvailable,
    },
  ];
  const mobileModeOrder = visibleMobileAiPathModes({
    mobileAiPathPolicy,
    deviceAgentVisible: deviceAgentModeVisible(),
    isAndroidApp: IS_ANDROID_APP,
  });
  const orderedMobileModeOrder = deviceAgentFirst
    ? mobileModeOrder
    : [
        ...mobileModeOrder.filter((id) => id === 'hosted'),
        ...mobileModeOrder.filter((id) => id !== 'hosted'),
      ];
  const orderedMobileRouteTabs: AndroidAiRouteTab[] = mobileAiPathPolicy
    ? [
        ...orderedMobileModeOrder,
        ...(planConnectorAvailable ? ['plan-connector' as const] : []),
      ]
    : orderedMobileModeOrder;
  const renderRouteEntry = (entry: (typeof definitions)[number]): string =>
    entry.mode
      ? commandAiRouteCard(entry.mode, entry.title, entry.detail, entry.meta)
      : commandPlanConnectorRouteCard();
  const visible = mobileAiPathPolicy
    ? orderedMobileRouteTabs
        .map((id) => definitions.find((entry) => entry.id === id && entry.available))
        .filter((entry): entry is (typeof definitions)[number] => Boolean(entry))
    : definitions.filter((entry) => entry.available);
  if (isMobileAppViewport()) {
    const activeId = visible.some((entry) => entry.id === state.androidAiRouteTab)
      ? state.androidAiRouteTab
      : visible[0]!.id;
    const activeEntry = visible.find((entry) => entry.id === activeId) ?? visible[0]!;
    const shortLabels: Record<AndroidAiRouteTab, string> = {
      hosted: 'BYOK',
      bridge: t('Bridge'),
      session: t('Session'),
      'device-agent': t('Device Agent'),
      'plan-connector': 'Plan Connector',
    };
    return `
      <div class="command-route-tabs android-tab-card" data-android-tab-group="ai-route">
        <div class="android-tab-strip command-route-strip" role="tablist" aria-label="${escapeHtml(t('AI route options'))}">
          ${visible.map((entry) => mobileTabButton(
            'ai-route',
            entry.id,
            mobileAiPathPolicy && entry.mode
              ? (IS_ANDROID_APP || IS_IOS_APP || state.iosNativeEnvironment.isIosNative) ? androidMobileAiPathTabLabel(entry.mode) : mobileAiPathTabLabel(entry.mode)
              : shortLabels[entry.id] ?? entry.title,
            entry.id === activeId,
          )).join('')}
        </div>
        <div class="android-tab-body command-route-body" role="tabpanel">
          ${renderRouteEntry(activeEntry)}
        </div>
      </div>
    `;
  }
  const ordered = IS_ANDROID_APP
    ? ['device-agent', 'plan-connector', 'session', 'hosted', 'bridge']
    : IS_TAURI_APP
      ? ['bridge', 'device-agent', 'hosted']
      : deviceAgentFirst
        ? ['device-agent', 'hosted', 'bridge', 'plan-connector', 'session']
        : ['hosted', 'bridge', 'plan-connector', 'session', 'device-agent'];
  return ordered
    .map((id) => visible.find((entry) => entry.id === id))
    .filter((entry): entry is (typeof definitions)[number] => Boolean(entry))
    .map(renderRouteEntry)
    .join('');
}

