// --- Hybrid chip builder for the composer -------------------------------------
// Picking a Wallet Action seeds a builder shown as editable chips ABOVE the
// textarea. Tapping a token/amount chip opens a picker; the builder compiles
// down to the same plain-text grammar parseChatWalletAction() consumes, so the
// textarea stays the source of truth and full freestyle typing still works.
type ChatBuilderKind = 'swap' | 'send' | 'sign';
interface ChatBuilderToken { symbol: string; mint: string; decimals: number; logoURI?: string; }
type ChatAmountMode = 'token' | 'usd' | 'percent';
interface ChatBuilderAmount { mode: ChatAmountMode; raw: string }
interface ChatActionBuilder {
  kind: ChatBuilderKind;
  fromToken?: ChatBuilderToken; // send + swap (SOL preset, choosable)
  toToken?: ChatBuilderToken;   // swap only
  amount?: ChatBuilderAmount;
  recipient?: string;           // send only
  memo?: string;                // send only
  statement?: string;           // sign only
  slippageBps?: string;         // swap only
}
type ChatPickerField = 'fromToken' | 'toToken' | 'amount' | 'slippage';
interface ChatActionPickerState { field: ChatPickerField }

// Transient editing session for the chat "Connector Actions" surface. While active, the
// surface drives the SAME global planner state (selectedTemplateId/templateFields/…) the
// New Request tab uses — so the ~100 connector forms render + submit with ZERO duplication —
// and this snapshot restores that draft on close so the New Request draft is never disturbed.
interface ChatConnectorSession {
  active: boolean;
  saved: {
    selectedTemplateId: string;
    templateOutcomeFilter: TemplateOutcomeFilter;
    createActionCategory: ActionCategory | '';
    templateFields: Record<string, string>;
    templateTokenModes: Record<string, TokenInputMode>;
    templateTokenSelections: Record<string, TokenFieldSelection>;
    templateFieldErrors: Record<string, string>;
    agentPlan: AgentPlan | null;
    agentSignature: string;
    agentPreparedActionId: string;
  };
}

interface ConnectorConnectSession {
  connectorId: string;
  category: ActionCategory | null;
  surface: 'create' | 'chat' | 'recurring' | 'preferences';
  openerRoute: AppRoute | null;
  openerTab: ActiveTab;
  draftApiKey?: string;
}

// A wallet action built by a sheet Confirm but NOT yet promoted to a card: it waits for the user
// to tap Send. `composerText` is the readable picker-answer label shown in the composer; the card
// is materialized from `preparedAction` (connector) or `recurringDraft` (recurring) — never by
// re-parsing the text — so exact on-chain ids are carried, not re-resolved.
interface ChatHeldAction {
  kind: 'connector' | 'recurring';
  composerText: string;
  preparedAction?: PreparedAction;
  recurringDraft?: RecurringDraft;
  evidence?: boolean;
}

// Transient editing session for the chat "Recurring / DCA" surface. Mirrors ChatConnectorSession:
// the surface drives the SAME global Repeat-tab state (recurringDraft/recurringPreset/…) so the
// recurring form renders + submits with ZERO duplication; this snapshot restores the Repeat-tab
// draft on close so it is never disturbed.
interface ChatRecurringSession {
  active: boolean;
  saved: {
    recurringDraft: RecurringDraft;
    recurringPreset: RecurringPresetId;
    recurringActionCategory: ActionCategory | '';
    recurringTokenModes: Record<string, TokenInputMode>;
    recurringTokenSelections: Record<string, TokenFieldSelection>;
    recurringErrors: Record<string, string>;
    recurringAmountMode: ChatAmountMode;
    askAgentAfterDraft: boolean;
  };
}

const CHAT_BUILDER_SOL: ChatBuilderToken = { symbol: 'SOL', mint: WSOL_MINT, decimals: 9 };

function defaultBuilderFor(kind: ChatBuilderKind): ChatActionBuilder {
  // Swap slippage defaults to Auto (no slippageBps) — Jupiter Ultra routing manages
  // dynamic slippage, so we omit the field end-to-end unless the user picks a number.
  if (kind === 'swap') return { kind, fromToken: { ...CHAT_BUILDER_SOL } };
  if (kind === 'send') return { kind, fromToken: { ...CHAT_BUILDER_SOL } };
  return { kind, statement: '' };
}

// Prepend a leading zero to a bare-decimal entry (".50" -> "0.50") so a $ value
// never serializes as the ambiguous, parser-rejected "$.50". Leaves "0.50", "50",
// and non-numeric/placeholder text untouched.
function leadingZeroDecimal(raw: string): string {
  return /^\.\d/.test(raw) ? `0${raw}` : raw;
}

// Render the amount field as grammar text (token amount, $usd, or pct%).
function chatBuilderAmountText(amount: ChatBuilderAmount | undefined, fallback: string): string {
  const raw = amount?.raw.trim();
  if (!amount || !raw) return fallback;
  if (amount.mode === 'usd') return `$${leadingZeroDecimal(raw)}`;
  if (amount.mode === 'percent') return `${leadingZeroDecimal(raw)}%`;
  return leadingZeroDecimal(raw);
}

// The token's grammar value: symbol for SOL/USDC, base58 mint for everything else
// (so the parser/validator never has to guess a mint for the long tail).
function chatBuilderTokenText(token: ChatBuilderToken | undefined, fallback: string): string {
  if (!token) return fallback;
  const upper = token.symbol.toUpperCase();
  return upper === 'SOL' || upper === 'USDC' ? token.symbol : token.mint;
}

// Compile the builder into the canonical Wallet Actions grammar. Unfilled slots
// keep readable [brackets] so a half-built message degrades to freestyle text.
function compileBuilderToDraft(b: ChatActionBuilder): string {
  if (b.kind === 'sign') {
    return `Sign a proof that ${b.statement?.trim() || '[statement to attest]'}`;
  }
  const amount = chatBuilderAmountText(b.amount, '[amount]');
  if (b.kind === 'send') {
    const token = chatBuilderTokenText(b.fromToken, 'SOL');
    const recipient = b.recipient?.trim() || '[recipient address]';
    const memo = b.memo && b.memo.trim() ? ` memo: ${b.memo.trim()}` : '';
    return `Send ${amount} ${token} to ${recipient}${memo}`;
  }
  const from = chatBuilderTokenText(b.fromToken, 'SOL');
  const to = b.toToken ? chatBuilderTokenText(b.toToken, '[token]') : '[token]';
  // Any explicit bps is written into the grammar; Auto (absent) appends nothing so
  // the parser leaves slippageBps off and the swap uses Ultra dynamic slippage.
  const slippage = b.slippageBps && b.slippageBps.trim() ? ` slippage ${b.slippageBps.trim()}bps` : '';
  // Optional review note (metadata only — not an on-chain memo).
  const note = b.memo && b.memo.trim() ? ` note: ${b.memo.trim()}` : '';
  return `Swap ${amount} ${from} to ${to}${slippage}${note}`;
}

// Short chip labels (friendly symbol/value; never the raw mint).
function chatBuilderAmountLabel(b: ChatActionBuilder): string {
  const a = b.amount;
  if (!a || !a.raw.trim()) return t('Amount');
  if (a.mode === 'usd') return `$${leadingZeroDecimal(a.raw.trim())}`;
  if (a.mode === 'percent') return `${leadingZeroDecimal(a.raw.trim())}%`;
  return leadingZeroDecimal(a.raw.trim());
}

function chatBuilderTokenLabel(token: ChatBuilderToken | undefined, fallback: string): string {
  if (!token) return fallback;
  return token.symbol || short(token.mint);
}

// The FROM asset (for resolving $/% in the amount picker) from the live snapshot.
function chatBuilderFromAsset(b: ChatActionBuilder | null): WalletBalanceAsset | null {
  if (!b?.fromToken) return null;
  return chatSnapshotAssets().find((a) => a.mint === b.fromToken!.mint) ?? null;
}

function chatPanel(): string {
  const session = activeChatSession();
  // Normalize the Pending Approvals dropdown: never stay "open" once the session has no
  // pending cards (e.g. the last one was approved without queueing), so it can't auto-open
  // when a new card appears later.
  if (state.chatPendingOpen && chatSessionPendingApprovals(session).length === 0) {
    state.chatPendingOpen = false;
    state.chatPendingSelectedId = null;
  }
  const fixtureMessages = chatResearchFixturesEnabled() ? chatResearchFixtureMessages() : [];
  const messages = fixtureMessages.length ? fixtureMessages : (session?.messages ?? []);
  const displaySessionId = fixtureMessages.length ? 'chat-research-fixtures' : (session?.id ?? 'chat');
  const hasMessages = messages.length > 0;
  // An active cloud stub (messages not yet fetched) shows a loading placeholder
  // rather than the empty "Talk to your agent" state, which would mismatch the
  // real title shown in the header.
  const loadErrored = Boolean(session?.cloudLoadError);
  const loadingStub = Boolean(session && chatSessionIsCloudStub(session)) && !loadErrored;
  const transcript = loadErrored
    ? chatLoadErrorState(session!)
    : loadingStub
      ? chatLoadingState()
      : chatDecisionCheckModeActive()
        ? chatDecisionEmptyState()
        : hasMessages
          ? messages.map((m) => chatMessageHtml(m, displaySessionId)).join('')
          : chatEmptyState();
  return `
    <section class="chat-surface form-kit" data-layout="chat">
      ${chatHeaderHtml(session)}
      ${chatMobileToolStripHtml(session)}
      <div class="chat-transcript" data-chat-scroll aria-live="polite" aria-atomic="false">
        ${transcript}
      </div>
      <button type="button" class="chat-scroll-pill" data-chat-scroll-pill aria-label="${escapeHtml(t('Scroll to bottom'))}" title="${escapeHtml(t('Scroll to bottom'))}">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 5v14"></path><path d="m19 12-7 7-7-7"></path></svg>
      </button>
      ${chatUsesSheet() && state.chatComposerOpen ? '<div class="chat-plus-scrim" data-chat-plus-close aria-hidden="true"></div>' : ''}
      ${chatComposerHtml()}
      <p class="chat-disclaimer">${escapeHtml(t('The agent reads live data to answer. You always review and sign.'))}</p>
    </section>
  `;
}

// A session counts as having content if its messages are loaded OR it's a
// cloud metadata stub whose messages haven't been lazily fetched yet.
function chatSessionHasContent(session: ChatSession): boolean {
  return session.messages.length > 0 || (session.cloudMessageCount ?? 0) > 0;
}

function chatHeaderHtml(session: ChatSession | null): string {
  const sessions = state.chat.sessions.filter(chatSessionHasContent);
  const activeTitle = session && chatSessionHasContent(session) ? session.title : t('Chat');
  const hasHistory = sessions.length > 0;
  const pendingCount = chatSessionPendingApprovals(session).length;
  return `
    <div class="chat-header">
      <span class="chat-title">${escapeHtml(activeTitle)}</span>
      <div class="chat-header-actions">
        ${!chatUsesSheet() ? chatResearchButtonHtml('web') : ''}
        ${!chatUsesSheet() && decisionCheckVisible() ? chatDecisionButtonHtml('web') : ''}
        ${!chatUsesSheet() && pendingCount > 0 ? `
          <div class="chat-pending chat-pending--web${state.chatPendingOpen ? ' open' : ''}" data-chat-pending>
            <button type="button" class="chat-pending-pill" data-chat-pending-toggle aria-haspopup="listbox" aria-expanded="${state.chatPendingOpen ? 'true' : 'false'}">${escapeHtml(t('Pending Approvals'))} <span class="chat-pending-count">${pendingCount}</span></button>
            ${state.chatPendingOpen ? chatPendingPanelHtml(session, 'web') : ''}
          </div>` : ''}
        ${hasHistory ? `
          <div class="chat-sessions${state.chatHistoryOpen ? ' open' : ''}" data-chat-history>
            <button type="button" class="chat-history-trigger" data-chat-history-trigger aria-haspopup="menu" aria-expanded="${state.chatHistoryOpen ? 'true' : 'false'}">${escapeHtml(t('History'))} <span class="chat-sessions-caret" aria-hidden="true">▾</span></button>
            <div class="chat-sessions-menu" role="menu" ${state.chatHistoryOpen ? '' : 'hidden'}>
              ${sessions.map((s) => {
                // Two-step delete: the × arms an inline Cancel/Delete confirm in the same row
                // so a stray tap can't drop a chat. state.chatDeleteConfirmId holds the armed id.
                const confirming = s.id === state.chatDeleteConfirmId;
                return `
                <div class="chat-session-row${s.id === state.chat.activeSessionId ? ' active' : ''}${confirming ? ' confirming' : ''}" role="presentation">
                  <button type="button" role="menuitem" class="chat-session-open" data-chat-switch="${escapeHtml(s.id)}" aria-label="${escapeHtml(s.title)}" title="${escapeHtml(s.title)}">${escapeHtml(s.title)}</button>
                  ${confirming
                    ? `<div class="chat-session-confirm" role="group" aria-label="${escapeHtml(t('Delete this chat?'))}">
                         <span class="chat-session-confirm-q">${escapeHtml(t('Delete this chat?'))}</span>
                         <span class="chat-session-confirm-actions">
                           <button type="button" role="menuitem" class="chat-session-confirm-cancel" data-chat-del-cancel="${escapeHtml(s.id)}">${escapeHtml(t('Cancel'))}</button>
                           <button type="button" role="menuitem" class="chat-session-confirm-del" data-chat-del-confirm="${escapeHtml(s.id)}">${escapeHtml(t('Delete'))}</button>
                         </span>
                       </div>`
                    : `<button type="button" role="menuitem" class="chat-session-del" data-chat-del="${escapeHtml(s.id)}" aria-label="${escapeHtml(tf('Delete chat {title}', { title: s.title }))}" title="${escapeHtml(t('Delete chat'))}">×</button>`}
                </div>
              `;
              }).join('')}
            </div>
          </div>` : ''}
        <button type="button" data-chat-new>${escapeHtml(t('New chat'))}</button>
      </div>
    </div>
  `;
}

function chatMobileToolStripHtml(session: ChatSession | null): string {
  if (!chatUsesSheet()) return '';
  const researchButton = chatResearchButtonHtml('mobile');
  const decisionButton = decisionCheckVisible() ? chatDecisionButtonHtml('mobile') : '';
  const pendingCount = chatSessionPendingApprovals(session).length;
  const pending = pendingCount > 0 ? `
    <div class="chat-pending chat-pending--mobile chat-pending--top${state.chatPendingOpen ? ' open' : ''}" data-chat-pending>
      <button type="button" class="chat-pending-pill chat-pending-pill--sm" data-chat-pending-toggle aria-haspopup="listbox" aria-expanded="${state.chatPendingOpen ? 'true' : 'false'}"><span class="chat-pending-label">${escapeHtml(t('Pending'))}</span> <span class="chat-pending-count">${pendingCount}</span></button>
      ${state.chatPendingOpen ? chatPendingPanelHtml(session, 'mobile') : ''}
    </div>` : '';
  if (!researchButton && !pending && !decisionButton) return '';
  const decisionOnly = !researchButton && decisionButton ? ' chat-mobile-tool-strip--decision-only' : '';
  const end = decisionButton || pending ? `<div class="chat-mobile-tool-strip-end">${decisionButton}${pending}</div>` : '';
  return `
    <div class="chat-mobile-tool-strip${decisionOnly}">
      ${researchButton}
      ${end}
    </div>`;
}

function chatEmptyState(): string {
  return `
    <div class="chat-empty">
      <div class="chat-empty-mark" aria-hidden="true"></div>
      <h3>${escapeHtml(t('Talk to your agent'))}</h3>
      <p>${escapeHtml(t('Ask about your wallet, tokens, prices, or risk. When you are ready, ask it to prepare a swap or a payment, then approve and sign here.'))}</p>
      <div class="chat-suggest-grid">
        ${CHAT_SUGGESTED_PROMPTS.map((prompt) => `
          <button type="button" class="chat-suggest" data-chat-suggest="${escapeHtml(prompt)}">${escapeHtml(t(prompt))}</button>
        `).join('')}
      </div>
    </div>
  `;
}

function chatDecisionEmptyState(): string {
  return `
    <div class="chat-empty chat-empty--decision">
      <div class="chat-empty-mark" aria-hidden="true"></div>
      <h3>${escapeHtml(t('Agent Decision Planner'))}</h3>
      <p>${escapeHtml(t('Write your conditions, then build a wallet action to check. The agent researches it and returns an exact APPROVE, DENY, or NEEDS INPUT verdict - and lets you sign on approve.'))}</p>
      <div class="chat-suggest-grid">
        ${CHAT_DECISION_SUGGESTED_PROMPTS.map((prompt) => `
          <button type="button" class="chat-suggest" data-chat-suggest="${escapeHtml(prompt)}">${escapeHtml(t(prompt))}</button>
        `).join('')}
      </div>
    </div>
  `;
}

// Shown while a cloud-stub session's messages are being fetched/decompressed on
// open, so the transcript isn't a misleading empty state under the real title.
function chatLoadingState(): string {
  return `
    <div class="chat-empty" aria-busy="true">
      <div class="chat-empty-mark" aria-hidden="true"></div>
      <p>${escapeHtml(t('Loading conversation…'))}</p>
    </div>
  `;
}

// Shown when a cloud-stub session's lazy load failed (decompress failure / 5xx /
// offline) instead of an endless spinner or a misleading empty state. Offers a
// retry that re-issues the GET.
function chatLoadErrorState(session: ChatSession): string {
  const offline = session.cloudLoadError === 'offline';
  const message = offline
    ? t('You are offline. This conversation will load when you reconnect.')
    : t('Could not load this conversation.');
  return `
    <div class="chat-empty" role="alert">
      <div class="chat-empty-mark" aria-hidden="true"></div>
      <p>${escapeHtml(message)}</p>
      <button type="button" class="primary" data-chat-retry-load="${escapeHtml(session.id)}">${escapeHtml(t('Try again'))}</button>
    </div>
  `;
}

// A small ⧉ copy button for a chat message. Carries the raw text in data-chat-copy so
// the morph-safe handler in bindChat() can write it to the clipboard (works for both the
// user bubble and the assistant actions row). copyId scopes the transient highlight.
function chatMsgCopyButtonHtml(text: string, copyId: string): string {
  return `<button type="button" class="chat-msg-copy" data-chat-copy="${escapeHtml(text)}" data-chat-copy-id="${escapeHtml(copyId)}" title="${escapeHtml(t('Copy'))}" aria-label="${escapeHtml(t('Copy message'))}">⧉</button>`;
}

// The assistant message footer action row: a per-message ⧉ copy (any settled, non-error
// message with text) plus the ↻ Regenerate control (last assistant message only). Returns
// '' while a stream is in flight so the inert controls don't flash mid-answer.
function chatAssistantActionsHtml(msg: ChatMessage, sessionId: string, isStreaming: boolean, isError: boolean): string {
  if (isStreaming || chatStreamActive()) return '';
  const isLast = isLastAssistantChatMessage(msg, sessionId);
  const canCopy = !isError && Boolean(msg.content.trim());
  if (!canCopy && !isLast) return '';
  const copyBtn = canCopy ? chatMsgCopyButtonHtml(msg.content, msg.id) : '';
  const regenBtn = isLast
    ? `<button type="button" class="chat-msg-regenerate" data-chat-regenerate title="${escapeHtml(t('Regenerate'))}" aria-label="${escapeHtml(t('Regenerate'))}">↻ ${escapeHtml(t('Regenerate'))}</button>`
    : '';
  return `<div class="chat-msg-actions">${copyBtn}${regenBtn}</div>`;
}

function chatMessageHtml(msg: ChatMessage, sessionId: string): string {
  if (msg.role === 'user') {
    // ✎ edit-and-resend: truncates the chat to before this message + loads it into the
    // composer to re-ask an edited version. Hidden while a stream is in flight OR during a
    // send's preflight (gate on chatStreamActive(), not just chatStreamMsgId, which is null
    // until the assistant placeholder is created — the buttons are inert then but shouldn't show).
    const editBtn = chatStreamActive()
      ? ''
      : `<button type="button" class="chat-msg-edit" data-chat-edit="${escapeHtml(msg.id)}" title="${escapeHtml(t('Edit & resend'))}" aria-label="${escapeHtml(t('Edit & resend'))}">✎</button>`;
    // ⧉ copy: writes the raw message text to the clipboard. Always available (read-only) and
    // bound morph-safely in bindChat() via [data-chat-copy]; reveals on hover/tap alongside ✎.
    const copyBtn = chatMsgCopyButtonHtml(msg.content, msg.id);
    return `<div class="chat-msg user" dir="auto" data-chat-msg-id="${escapeHtml(msg.id)}"><span class="chat-user-text">${escapeHtml(msg.content)}</span>${editBtn}${copyBtn}</div>`;
  }
  if (msg.role === 'system') {
    // Synthetic UI-only notices (e.g. the trim marker) store English text; translate
    // it at render time and render as a centered note rather than an agent bubble.
    if (msg.ephemeral) {
      return `<div class="chat-trim-note" role="note">${escapeHtml(t(msg.content))}</div>`;
    }
    return `<div class="chat-msg assistant"><div class="chat-avatar" aria-hidden="true"></div><div class="chat-body"><div class="chat-text">${renderChatMarkdown(msg.content)}</div></div></div>`;
  }
  const isStreaming = msg.status === 'streaming';
  const isError = msg.status === 'error';
  const streaming = isStreaming ? ' streaming' : '';
  const errored = isError ? ' error' : '';
  const bodyText = isError && msg.error ? msg.error : msg.content;
  // While streaming, paint plain text (tokens append cleanly); once settled,
  // render light markdown. Errors stay plain.
  const bodyHtml = (isStreaming || isError) ? escapeHtml(bodyText) : renderChatMarkdown(bodyText);
  return `
    <div class="chat-msg assistant${streaming}${errored}" data-chat-msg-id="${escapeHtml(msg.id)}" aria-busy="${isStreaming ? 'true' : 'false'}">
      <div class="chat-avatar" aria-hidden="true"></div>
      <div class="chat-body">
        <div class="chat-tools">${chatToolChipsHtml(msg)}</div>
        <div class="chat-text" dir="auto">${bodyHtml}</div>
        ${chatInlineActionHtml(msg, sessionId)}
        ${msg.txReceipt ? `<div class="chat-card">${txBlock(msg.txReceipt.txid, msg.txReceipt.cluster)}</div>` : ''}
        ${msg.receiveCard ? `<div class="chat-card">${chatReceiveCardHtml(msg.receiveCard.address)}</div>` : ''}
        ${msg.recurringCardId ? chatRecurringCardLookupHtml(msg.recurringCardId) : ''}
        ${msg.positionsCard ? chatPositionsCardHtml(msg.positionsCard.category) : ''}
        ${msg.researchCard ? `<div class="chat-card">${chatResearchCardHtml(msg.researchCard)}</div>` : ''}
        ${msg.decisionCheckCard ? `<div class="chat-card">${chatDecisionCheckCardHtml(msg.decisionCheckCard)}</div>` : ''}
        ${chatMessageFooterHtml(msg)}
        ${chatAssistantActionsHtml(msg, sessionId, isStreaming, isError)}
      </div>
    </div>
  `;
}

// The id of the newest assistant message in a session (regenerate re-runs that turn).
function isLastAssistantChatMessage(msg: ChatMessage, sessionId: string): boolean {
  const session = state.chat.sessions.find((s) => s.id === sessionId);
  if (!session) return false;
  for (let i = session.messages.length - 1; i >= 0; i -= 1) {
    const m = session.messages[i];
    if (m && m.role === 'assistant') return m.id === msg.id;
  }
  return false;
}

// A subtle footer under a finished answer: web sources the model cited (Anthropic
// web_search) + a token-usage line. Hidden while streaming and when absent.
function chatMessageFooterHtml(msg: ChatMessage): string {
  if (msg.status === 'streaming') return '';
  const parts: string[] = [];
  if (msg.citations && msg.citations.length > 0) {
    // Show the same number we store (loop.ts dedupes + caps at 12) so stored citations
    // aren't silently dropped at render.
    const links = msg.citations.slice(0, 12).map((c) => {
      let label = (c.title ?? '').trim();
      if (!label) {
        try { label = new URL(c.url).hostname.replace(/^www\./, ''); } catch { label = c.url; }
      }
      return `<a class="chat-citation" href="${escapeHtml(c.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(label)}</a>`;
    }).join('');
    parts.push(`<div class="chat-citations"><span class="chat-meta-label">${escapeHtml(t('Sources'))}</span>${links}</div>`);
  }
  if (msg.usage) {
    const total = (msg.usage.inputTokens + msg.usage.outputTokens).toLocaleString();
    const cached = msg.usage.cacheReadTokens ? ` · ${msg.usage.cacheReadTokens.toLocaleString()} ${t('cached')}` : '';
    const title = `${msg.usage.inputTokens.toLocaleString()} in / ${msg.usage.outputTokens.toLocaleString()} out`;
    parts.push(`<div class="chat-usage" title="${escapeHtml(title)}">${escapeHtml(`${total} ${t('tokens')}${cached}`)}</div>`);
  }
  return parts.length > 0 ? `<div class="chat-meta">${parts.join('')}</div>` : '';
}

function chatToolChipsHtml(msg: ChatMessage): string {
  if (!msg.toolEvidence || msg.toolEvidence.length === 0) return '';
  return msg.toolEvidence
    .map((ev) => `<span class="chat-tool-chip done">${escapeHtml(chatToolDisplayName(ev.tool))}</span>`)
    .join('');
}

// Localized labels for the tool-status chips (the server sends an English label
// we ignore on the client so non-English devices stay localized).
function chatToolRunningLabel(tool: string): string {
  const explicit = explicitChatToolRunningLabelText(tool);
  if (explicit) return t(explicit);
  return tf('Running {tool}…', { tool: chatToolDisplayName(tool) });
}

function chatToolDisplayName(tool: string): string {
  return t(chatToolDisplayLabel(tool));
}

function chatInlineActionHtml(msg: ChatMessage, sessionId: string): string {
  if (msg.preparedActionId) {
    // Deleted from a chat card: short-circuit before the receipt/proposal branches so we never
    // re-offer "Prepare for approval" for a request the user explicitly deleted.
    if (chatDeletedActionIds.has(msg.preparedActionId)) {
      return `<div class="chat-card"><p class="ticket-meta-line">${escapeHtml(t('Deleted.'))}</p></div>`;
    }
    const action = state.preparedActions.find((a) => a.id === msg.preparedActionId);
    if (action) return `<div class="chat-card">${chatActionCard(action)}</div>`;
    // Action no longer live (completed + pruned, or archived). If a receipt exists,
    // show a completed block instead of re-offering "Prepare for approval".
    const receipt = state.receipts.find((r) => r.actionId === msg.preparedActionId);
    if (receipt) {
      const txPart = receipt.txid ? txBlock(receipt.txid, receipt.cluster as Cluster) : '';
      return `<div class="chat-card"><p class="ticket-meta-line">${escapeHtml(t('Completed - receipt in the Done tab.'))}</p>${txPart}</div>`;
    }
    // Action gone + no receipt. Prefer the proposal snapshot below (still re-preparable);
    // but if there is none, render a graceful note instead of a BLANK card (H9-3 — e.g.
    // the action was pruned after a failed pre-flight + regenerate, or a crash-reload).
    if (!msg.proposal) {
      return `<div class="chat-card"><p class="ticket-meta-line">${escapeHtml(t('This prepared action is no longer available.'))}</p></div>`;
    }
  }
  if (msg.proposal) {
    const canPrepare = Boolean(state.address);
    return `
      <div class="chat-card chat-proposal-pending">
        <p class="ticket-meta-line">${escapeHtml(msg.proposal.summary)}</p>
        ${canPrepare
          ? `<button type="button" class="primary" data-chat-promote data-chat-session="${escapeHtml(sessionId)}" data-chat-msg="${escapeHtml(msg.id)}">${escapeHtml(t('Prepare for approval'))}</button>`
          : `<p class="ticket-meta-line">${escapeHtml(t('Connect a wallet to prepare this action.'))}</p>`}
      </div>
    `;
  }
  return '';
}

function chatDecisionCheckCardHtml(card: ChatDecisionCheckCard): string {
  const review = card.review;
  const statusClass = chatDecisionStatusClass(review.status as ChatDecisionStatus);
  const statusLabel = chatDecisionStatusLabel(review.status as ChatDecisionStatus);
  const checked = review.checkedAt ? formatDateTime(review.checkedAt) : '';
  const summary = agentReviewDisplaySummary(review) || agentReviewCompactDecisionText(review, 'Agent decision check completed.');
  const reason = agentReviewDisplayReason(review);
  const sections = agentEvidenceSections(review, { actionType: 'manual_review' })
    .filter((section) => !section.advanced)
    .slice(0, 4);
  const reasonRows = chatDecisionReasonRows(review, sections, summary, reason);
  const evidenceHtml = chatDecisionEvidenceDetailsHtml(sections);
  const questionsHtml = review.questions?.length ? `
    <div class="chat-decision-questions">
      <strong>${escapeHtml(t('Needs input'))}</strong>
      <ul>${review.questions.slice(0, 3).map((question) => `<li>${escapeHtml(question.prompt)}</li>`).join('')}</ul>
    </div>` : '';
  return `
    <article class="chat-decision-card ${escapeHtml(statusClass)}">
      <header class="chat-decision-card-head">
        <div>
          <span>${escapeHtml(t('Agent Decision Planner'))}</span>
          <strong class="chat-decision-verdict-pill">${escapeHtml(statusLabel)}</strong>
        </div>
        ${checked ? `<em>${escapeHtml(checked)}</em>` : ''}
      </header>
      <blockquote class="chat-decision-prompt">
        <span>${escapeHtml(t('Prompt'))}</span>
        <p>${escapeHtml(card.prompt)}</p>
      </blockquote>
      ${card.action ? `
      <blockquote class="chat-decision-prompt chat-decision-action">
        <span>${escapeHtml(t('Wallet action'))}</span>
        <p>${escapeHtml(card.action.summary)}</p>
      </blockquote>` : ''}
      <p class="chat-decision-summary">${escapeHtml(summary)}</p>
      ${questionsHtml}
      <section class="chat-decision-reasons" aria-label="${escapeHtml(t('Pass/fail reasons'))}">
        <h4>${escapeHtml(t('Pass/fail reasons'))}</h4>
        <ul>
          ${reasonRows.map(chatDecisionReasonRowHtml).join('')}
        </ul>
      </section>
      ${evidenceHtml}
    </article>`;
}

type ChatDecisionReasonTone = 'pass' | 'fail' | 'warn' | 'info';

function chatDecisionEvidenceToneForStatus(status: AgentPlanReviewStatus): AgentEvidenceTone {
  if (status === 'approved') return 'good';
  if (status === 'denied' || status === 'error') return 'fail';
  if (status === 'needs_input' || status === 'wallet_required' || status === 'checking') return 'warn';
  return 'neutral';
}

function chatDecisionReasonTone(tone: AgentEvidenceTone): ChatDecisionReasonTone {
  if (tone === 'good') return 'pass';
  if (tone === 'fail') return 'fail';
  if (tone === 'warn') return 'warn';
  return 'info';
}

function chatDecisionReasonChipLabel(tone: ChatDecisionReasonTone): string {
  switch (tone) {
    case 'pass':
      return 'PASS';
    case 'fail':
      return 'FAIL';
    case 'warn':
      return 'WARN';
    case 'info':
    default:
      return 'INFO';
  }
}

function chatDecisionReasonRows(
  review: AgentPlanReviewState,
  sections: AgentEvidenceDisplaySection[],
  summary: string,
  reason: string,
): AgentEvidenceDisplayRow[] {
  const rows: AgentEvidenceDisplayRow[] = [];
  const seen = new Set<string>();
  const add = (row: AgentEvidenceDisplayRow): void => {
    const label = compactSentence(row.label, 72);
    const value = compactSentence(row.value, 180);
    if (!label || !value) return;
    const key = `${label.toLowerCase()}\n${value.toLowerCase()}`;
    if (seen.has(key)) return;
    seen.add(key);
    rows.push({ label, value, tone: row.tone });
  };

  if (reason && reason !== summary) {
    add({
      label: t('Decision reason'),
      value: reason,
      tone: chatDecisionEvidenceToneForStatus(review.status),
    });
  }

  const evidenceRows = sections
    .filter((section) => section.id !== 'sources')
    .flatMap((section) => section.rows)
    .filter((row) => row.label && row.value);
  const emphasizedRows = evidenceRows.filter((row) => row.tone !== 'neutral');
  const neutralRows = evidenceRows.filter((row) => row.tone === 'neutral');
  for (const row of [...emphasizedRows, ...neutralRows]) {
    add(row);
    if (rows.length >= 5) break;
  }

  if (!rows.length) {
    add({
      label: t('Decision result'),
      value: summary || reason || t('The agent returned a decision for this prompt.'),
      tone: chatDecisionEvidenceToneForStatus(review.status),
    });
  }

  return rows.slice(0, 5);
}

function chatDecisionReasonRowHtml(row: AgentEvidenceDisplayRow): string {
  const tone = chatDecisionReasonTone(row.tone);
  return `
    <li class="chat-decision-reason-row ${escapeHtml(tone)}">
      <span class="chat-decision-reason-chip">${escapeHtml(chatDecisionReasonChipLabel(tone))}</span>
      <span class="chat-decision-reason-copy">
        <strong>${escapeHtml(row.label)}</strong>
        <span>${agentEvidenceValueHtml(row)}</span>
      </span>
    </li>`;
}

function chatDecisionEvidenceDetailsHtml(sections: AgentEvidenceDisplaySection[]): string {
  const rowCount = sections.reduce((sum, section) => sum + section.rows.length, 0);
  if (!rowCount) return '';
  return `
    <details class="chat-decision-evidence-details">
      <summary>
        <span>${escapeHtml(t('Evidence checked'))}</span>
        <em>${escapeHtml(tf('{count} rows', { count: rowCount }))}</em>
      </summary>
      <div class="chat-decision-evidence">
        ${sections.map((section) => `
          <section class="chat-decision-section ${escapeHtml(section.id)}">
            <h4>${escapeHtml(section.label)}</h4>
            <dl>
              ${section.rows.slice(0, 5).map((row) => `
                <div class="${escapeHtml(row.tone)}">
                  <dt>${escapeHtml(row.label)}</dt>
                  <dd>${agentEvidenceValueHtml(row)}</dd>
                </div>
              `).join('')}
            </dl>
          </section>
        `).join('')}
      </div>
    </details>`;
}

function chatResearchToneClass(tone: ChatResearchTone | undefined): string {
  return tone === 'good' ? ' good' : tone === 'warn' ? ' warn' : tone === 'fail' ? ' fail' : '';
}

const CHAT_RESEARCH_CARD_BUY_KINDS = new Set<ChatResearchActionId>([
  'token-safety',
  'rug-scan',
  'token-lifecycle',
  'whale-scan',
  'top-traders',
]);
const CHAT_RESEARCH_TOKEN_LIST_BUY_KINDS = new Set<ChatResearchActionId>([
  'trending-tokens',
  'smart-money-tokens',
  'new-listings',
]);

function solscanAccountUrl(account: string, cluster: Cluster = state.cluster): string {
  const clusterParam = cluster === 'mainnet-beta' ? '' : `?cluster=${cluster}`;
  return `https://solscan.io/account/${account}${clusterParam}`;
}

function chatResearchSwapFields(
  mint: string | undefined,
  opts: { symbol?: string; decimals?: number; logoURI?: string } = {},
): Pick<ChatResearchCard, 'swapMint' | 'swapSymbol' | 'swapDecimals' | 'swapLogoURI'> {
  const normalized = mint?.trim();
  if (!normalized || !CHAT_BASE58_MINT.test(normalized)) return {};
  const metadata = tokenMarketMetadata.get(normalized);
  const known = knownBrowserTokenByMint(normalized);
  const logoURI = opts.logoURI || metadata?.logoURI || knownTokenLogo(normalized);
  const symbol = opts.symbol || metadata?.symbol || known?.symbol || tokenDisplayLabel(normalized);
  const decimals = opts.decimals ?? metadata?.decimals ?? known?.decimals;
  return {
    swapMint: normalized,
    swapSymbol: symbol,
    ...(typeof decimals === 'number' && Number.isFinite(decimals) ? { swapDecimals: decimals } : {}),
    ...(logoURI ? { swapLogoURI: logoURI } : {}),
  };
}

function chatResearchCardSwapFields(base: ChatResearchCardBase): Pick<ChatResearchCard, 'swapMint' | 'swapSymbol' | 'swapDecimals' | 'swapLogoURI'> {
  return CHAT_RESEARCH_CARD_BUY_KINDS.has(base.kind) ? chatResearchSwapFields(base.target) : {};
}

function chatResearchCardBuyMint(card: ChatResearchCard): string {
  if (!CHAT_RESEARCH_CARD_BUY_KINDS.has(card.kind)) return '';
  const mint = card.swapMint || card.target || '';
  return CHAT_BASE58_MINT.test(mint) ? mint : '';
}

function chatResearchItemBuyMint(item: ChatResearchListItem, kind: ChatResearchActionId): string {
  const mint = item.swapMint || (CHAT_RESEARCH_TOKEN_LIST_BUY_KINDS.has(kind) ? item.mint : '');
  return mint && CHAT_BASE58_MINT.test(mint) ? mint : '';
}

