// --- Chat "Receive" accessory card --------------------------------------------
// Receive is instant (no form, no Confirm): clicking the pill posts the connected
// address as a scannable QR + a copyable pill. The QR PNG is large + high-entropy, so it
// is NOT persisted on the message — we regenerate it once per address here and render
// synchronously from this cache. A miss kicks an async fill then one render() to swap the
// placeholder for the real image. '' cached means generation failed (show placeholder).
const chatReceiveQrCache = new Map<string, string>();
const chatReceiveQrInFlight = new Set<string>();
function chatReceiveQrFor(address: string): string {
  const cached = chatReceiveQrCache.get(address);
  if (cached !== undefined) return cached;
  if (!chatReceiveQrInFlight.has(address)) {
    chatReceiveQrInFlight.add(address);
    // Encode as a Solana Pay receive URI so a phone wallet scan opens a "send to this address"
    // flow (not just a raw string). The cache stays keyed by the bare address.
    void renderUrlQrDataUrl(`solana:${address}`).then((dataUrl) => {
      chatReceiveQrInFlight.delete(address);
      chatReceiveQrCache.set(address, dataUrl);
      if (state.activeTab === 'chat') render();
    });
  }
  return '';
}
function chatReceiveCardHtml(address: string): string {
  const qr = chatReceiveQrFor(address);
  const qrInner = qr
    ? `<img class="chat-receive-qr-img" src="${escapeHtml(qr)}" alt="${escapeHtml(t('Wallet address QR code'))}" width="180" height="180" />`
    : `<div class="chat-receive-qr-loading" aria-hidden="true"></div>`;
  return `
    <div class="chat-receive-card">
      <div class="chat-receive-qr">${qrInner}</div>
      <div class="chat-receive-pill">
        <code class="chat-receive-addr" title="${escapeHtml(address)}">${escapeHtml(short(address))}</code>
        <button
          type="button"
          class="chat-receive-copy"
          data-copy="${escapeHtml(address)}"
          data-copy-id="chat-receive-address"
          data-copy-name="${escapeHtml(t('Address'))}"
          data-copy-toast="${escapeHtml(t('Copied address'))}"
          data-copy-message=""
          aria-label="${escapeHtml(t('Copy wallet address'))}"
          title="${escapeHtml(t('Copy wallet address'))}"
        >${copyButtonIcon()}<span>${escapeHtml(t('Copy'))}</span></button>
      </div>
    </div>`;
}

// --- Chat wallet-action bottom sheet (Android/iOS) ----------------------------
// On the native shells the chat pickers + the Wallet Actions menu are hosted in
// the shared mobile-rail-sheet engine (solid, keyboard-aware, hardened against
// re-render/focus/paste bugs). Web/desktop keep the inline upward popover.
type ChatPickerVariant = 'inline' | 'sheet';
type ChatTokenPickerMode = 'list' | 'mint';
type ChatTokenField = 'fromToken' | 'toToken';
const CHAT_TOKEN_PAGE = 5;
// Per-field LIST/MINT mode + list pagination. The native-mobile action sheet shows BOTH
// token fields at once (swap input + output), so a single global mode/limit would couple
// them — keep them keyed by field. Desktop shows one picker at a time but reads the same
// per-field helpers.
const chatTokenPickerModes: Partial<Record<ChatTokenField, ChatTokenPickerMode>> = {};
const chatTokenListLimits: Partial<Record<ChatTokenField, number>> = {};
function chatTokenModeFor(field: ChatTokenField): ChatTokenPickerMode { return chatTokenPickerModes[field] ?? 'list'; }
function chatTokenLimitFor(field: ChatTokenField): number { return chatTokenListLimits[field] ?? CHAT_TOKEN_PAGE; }

function chatUsesSheet(): boolean {
  return IS_ANDROID_APP || IS_IOS_APP;
}

// --- Chat "Pending Approvals" per-chat dropdown ------------------------------
// Surfaces not-yet-approved action cards created in the ACTIVE chat session so a
// card buried under later messages can be re-summoned and signed. The count is
// always derived (never decremented by hand): when an action becomes terminal —
// exactly when postChatActionSuccessMessage posts its confirmation — it drops out.
const CHAT_PENDING_PAGE = 5;

// Unique non-terminal PreparedActions linked to THIS session via message.preparedActionId,
// in transcript order. Deduped by id (a re-queued card adds a SECOND message referencing the
// same id). Recurring chat cards use recurringCardId (not preparedActionId) and are excluded.
function chatSessionPendingApprovals(session: ChatSession | null): PreparedAction[] {
  if (!session) return [];
  const seen = new Set<string>();
  const out: PreparedAction[] = [];
  for (const msg of session.messages) {
    const id = msg.preparedActionId;
    if (!id || seen.has(id)) continue;
    const action = state.preparedActions.find((a) => a.id === id);
    if (!action || !isActionInboxActive(action)) continue; // terminal → excluded (auto-decrement)
    seen.add(id);
    out.push(action);
  }
  return out;
}

// One compact row: action title + a key detail (amount, else summary) + status pill.
function chatPendingRowHtml(action: PreparedAction): string {
  const selected = state.chatPendingSelectedId === action.id;
  const amount = amountLabel(action);
  const detail = amount !== 'n/a' ? amount : action.summary;
  return `
    <button type="button" class="chat-pending-row${selected ? ' selected' : ''}" data-chat-pending-select="${escapeHtml(action.id)}" role="option" aria-selected="${selected ? 'true' : 'false'}">
      <span class="chat-pending-row-main">
        <strong class="chat-pending-row-title">${escapeHtml(preparedActionCardTitle(action))}</strong>
        <span class="chat-pending-row-detail">${escapeHtml(detail)}</span>
      </span>
      <span class="status-pill ${statusTone(action.status)}">${escapeHtml(t(action.status))}</span>
    </button>`;
}

// Shared panel body for both web (downward) and mobile (upward) dropdowns; `variant`
// only changes the wrapper class. Clamps the page to the live count on every render.
function chatPendingPanelHtml(session: ChatSession | null, variant: 'web' | 'mobile'): string {
  const pending = chatSessionPendingApprovals(session);
  const totalPages = Math.max(1, Math.ceil(pending.length / CHAT_PENDING_PAGE));
  const page = Math.min(Math.max(Math.trunc(state.chatPendingPage) || 1, 1), totalPages);
  if (state.chatPendingPage !== page) state.chatPendingPage = page; // clamp when the count shrinks
  const rows = pending.slice((page - 1) * CHAT_PENDING_PAGE, page * CHAT_PENDING_PAGE);
  const selectedLive = Boolean(state.chatPendingSelectedId) && pending.some((a) => a.id === state.chatPendingSelectedId);
  const showPrev = page > 1;
  const showNext = page < totalPages;
  const paginator = (showPrev || showNext) ? `
    <div class="chat-pending-pager" role="group" aria-label="${escapeHtml(t('Pages'))}">
      <button type="button" class="chat-pending-arrow${showPrev ? '' : ' is-hidden'}" data-chat-pending-page="prev" aria-label="${escapeHtml(t('Previous page'))}"${showPrev ? '' : ' tabindex="-1" aria-hidden="true"'}>‹</button>
      <span class="chat-pending-pageinfo">${escapeHtml(tf('Page {page} / {total}', { page, total: totalPages }))}</span>
      <button type="button" class="chat-pending-arrow${showNext ? '' : ' is-hidden'}" data-chat-pending-page="next" aria-label="${escapeHtml(t('Next page'))}"${showNext ? '' : ' tabindex="-1" aria-hidden="true"'}>›</button>
    </div>` : '';
  const queueBtn = selectedLive ? `<button type="button" class="primary chat-pending-queue" data-chat-pending-queue>${escapeHtml(t('Queue Approval'))}</button>` : '';
  return `
    <div class="chat-pending-menu chat-pending-menu--${variant}${state.chatPendingOpen ? ' open' : ''}" role="listbox" aria-label="${escapeHtml(t('Pending approvals'))}">
      ${paginator}
      ${queueBtn}
      <div class="chat-pending-list">${rows.map(chatPendingRowHtml).join('')}</div>
    </div>`;
}

// Re-inject the selected pending card as a FRESH assistant message at the bottom,
// resurfacing the buried card. Creates only a ChatMessage referencing the SAME
// action.id — never a second PreparedAction — so the count is unchanged and the
// existing terminal/auto-decrement lifecycle still drives it.
function queueChatPendingApproval(actionId: string | null): void {
  const session = activeChatSession();
  if (!session || !actionId) return;
  const action = state.preparedActions.find((a) => a.id === actionId);
  if (!action || !isActionInboxActive(action)) { // selection went terminal: just close
    state.chatPendingOpen = false;
    state.chatPendingSelectedId = null;
    render();
    return;
  }
  appendChatMessage(session.id, {
    id: newId('chat-msg'),
    role: 'assistant',
    content: t('Here is the action you queued. Review and approve.'),
    createdAt: new Date().toISOString(),
    status: 'done',
    preparedActionId: action.id,
  });
  state.chatPendingOpen = false;
  state.chatPendingSelectedId = null;
  chatForceScrollBottom = true;
  render();
}

// Open the chat-action sheet; if it is already open we are only swapping its body
// (menu -> picker, picker -> picker) so suppress the slide-up replay.
function openChatActionSheet(): void {
  if (state.activeMobileRailSheet === 'chat-action') suppressMobileRailSheetEnterAnimation = true;
  state.activeMobileRailSheet = 'chat-action';
}
function closeChatActionSheet(): void {
  if (state.activeMobileRailSheet === 'chat-action') state.activeMobileRailSheet = null;
  chatSheetTokenOpen = null;
  chatSheetNoteOpen = false;
  chatActionPopoverOpen = false;
}

let walletBalanceLogoFallbackBound = false;
// Hide token-logo <img>s that fail to load (404 / blocked / offline) so the monogram layer beneath
// shows through instead of a broken-image glyph. Delegated + capture phase because `error` events
// don't bubble; registered exactly once. No inline onerror (CSP-safe).
function bindWalletBalanceLogoFallback(): void {
  if (walletBalanceLogoFallbackBound || typeof document === 'undefined') return;
  walletBalanceLogoFallbackBound = true;
  document.addEventListener('error', (event) => {
    const target = event.target;
    if (target instanceof HTMLImageElement && target.classList.contains('wallet-balance-logo-img')) {
      target.style.display = 'none';
    }
  }, true);
}

// Lazily enrich the Wallet Balances sheet rows (logo + full name + 24h price change) for the
// CURRENTLY HELD tokens, then repaint ONCE when anything changed — mirrors ensureChatTokenLogos.
// Source is the public Jupiter lite-api search (CORS-OK, keyless), the same endpoint the
// tokenMarket() client tool reads, so no new BirdEye bridge/cloud route is needed. Results are
// upserted into tokenMarketMetadata (the shared cache the token pickers + rows read). Called when
// a balance surface (mobile/chat sheet or the desktop overlay) is open; gated by a 5-min TTL and
// an in-flight flag so it can't stack fetches across renders.
function ensureWalletBalanceSheetMarket(): void {
  if (walletBalanceMarketInFlight) return;
  const snapshot = state.walletBalance.full ?? state.walletBalance.summary;
  if (!snapshot) return;
  const assets = [snapshot.sol, snapshot.usdc, ...snapshot.others].filter((asset) => asset.amount > 0);
  const mints = [...new Set(assets.map((asset) => asset.mint).filter(Boolean))]
    .filter((mint) => {
      const cached = tokenMarketMetadata.get(mint);
      return !cached || cached.priceChange24h === undefined || Date.now() - cached.fetchedAt > WALLET_BALANCE_MARKET_CACHE_MS;
    });
  if (!mints.length) return;
  walletBalanceMarketInFlight = true;
  const requested = new Set(mints);
  const chunks: string[][] = [];
  for (let i = 0; i < mints.length; i += WALLET_BALANCE_MARKET_BATCH_SIZE) {
    chunks.push(mints.slice(i, i + WALLET_BALANCE_MARKET_BATCH_SIZE));
  }
  void Promise.allSettled(chunks.map(async (chunk) => {
    const arr = await jupiterLiteJson(`/tokens/v2/search?query=${encodeURIComponent(chunk.join(','))}`);
    return Array.isArray(arr) ? arr : [];
  }))
    .then((settled) => {
      let changed = false;
      for (const entry of settled) {
        if (entry.status !== 'fulfilled') continue;
        for (const raw of entry.value) {
          const record = asRecord(raw);
          if (!record) continue;
          // Jupiter v2 token records carry the mint in `id`; ignore any fuzzy matches we didn't ask for.
          const mint = [record.id, record.address, record.mint].find((v): v is string => typeof v === 'string' && v.length > 0);
          if (!mint || !requested.has(mint)) continue;
          const stats = asRecord(record.stats24h);
          const change = stats ? numberField(stats.priceChange) : undefined;
          const symbol = typeof record.symbol === 'string' && record.symbol.trim() ? record.symbol.trim() : undefined;
          const name = typeof record.name === 'string' && record.name.trim() ? record.name.trim() : undefined;
          const logoURI = typeof record.icon === 'string' && record.icon.trim()
            ? record.icon.trim()
            : (typeof record.logoURI === 'string' && record.logoURI.trim() ? record.logoURI.trim() : undefined);
          const prev = tokenMarketMetadata.get(mint);
          const nextLogo = logoURI ?? prev?.logoURI;
          const nextChange = change ?? prev?.priceChange24h;
          tokenMarketMetadata.set(mint, {
            mint,
            symbol: symbol ?? prev?.symbol ?? tokenDisplayLabel(mint),
            name: name ?? prev?.name ?? symbol ?? prev?.symbol ?? tokenDisplayLabel(mint),
            ...(nextLogo ? { logoURI: nextLogo } : {}),
            ...(prev?.decimals !== undefined ? { decimals: prev.decimals } : {}),
            ...(nextChange !== undefined ? { priceChange24h: nextChange } : {}),
            source: 'jupiter',
            fetchedAt: Date.now(),
          });
          changed = true;
        }
      }
      // Repaint once, only if the rows are actually on screen (mobile/chat sheet or desktop overlay).
      if (changed && (
        state.activeMobileRailSheet === 'wallet-balances' ||
        state.activeMobileRailSheet === 'chat-wallet-balances' ||
        state.walletBalance.overlayOpen
      )) render();
    })
    .catch(() => undefined)
    .finally(() => { walletBalanceMarketInFlight = false; });
}

// Hydrate logos for the token LIST lazily (chat is not in the standard
// token-market hydration set), then repaint once when anything changed. Covers the
// owned balances AND the curated preset tokens shown for the swap output.
function ensureChatTokenLogos(): void {
  const field = chatSheetTokenOpen ?? state.chatActionPicker?.field;
  const items = (field === 'fromToken' || field === 'toToken')
    ? chatTokenListItems(field)
    : chatSnapshotAssets().filter((a) => a.amount > 0).map((a) => ({ mint: a.mint }));
  const mints = items
    .map((i) => i.mint)
    .filter((m) => !knownTokenLogo(m) && !tokenMarketMetadata.get(m)?.logoURI);
  if (mints.length === 0) return;
  void fetchTokenMetadataForMints(mints)
    .then((changed) => {
      if (!changed || state.activeTab !== 'chat') return;
      // Repaint while the action sheet is open ONLY when a token dropdown is open (a list of
      // buttons, no focused input to lose) — otherwise a render would drop the soft keyboard
      // mid-type. The rich rows + collapsed trigger show the freshly-loaded logos.
      if (state.activeMobileRailSheet === 'chat-action' && !chatSheetTokenOpen) return;
      render();
    })
    .catch(() => undefined);
}

// The desktop chip builder bar was retired in favour of the consolidated wallet-action
// popover (chatActionPopoverHtml); the old per-chip picker renderers below it
// (chatAmountPickerHtml / chatTokenPickerHtml / chatSlippagePickerHtml + the chip label
// helpers) are now unreachable and can be removed in a follow-up cleanup.

function chatBuilderSlippageLabel(b: ChatActionBuilder): string {
  const bps = b.slippageBps && b.slippageBps.trim() ? b.slippageBps.trim() : '';
  return bps ? tf('{bps} bps', { bps }) : t('Auto');
}

function chatSlippagePickerHtml(b: ChatActionBuilder, variant: ChatPickerVariant = 'inline'): string {
  const current = b.slippageBps && b.slippageBps.trim() ? b.slippageBps.trim() : '';
  const presetBtn = (bps: string): string =>
    `<button type="button" class="chat-amount-pct${current === bps ? ' active' : ''}" data-chat-slippage-bps="${bps}">${escapeHtml(tf('{bps} bps', { bps }))}</button>`;
  const autoBtn = `<button type="button" class="chat-amount-pct${current ? '' : ' active'}" data-chat-slippage-bps="auto">${escapeHtml(t('Auto'))}</button>`;
  const title = variant === 'sheet' ? '' : `<p class="chat-picker-title">${escapeHtml(t('Max slippage'))}</p>`;
  const inner = `
    ${title}
    <div class="chat-amount-pcts">${autoBtn}${presetBtn('25')}${presetBtn('50')}${presetBtn('100')}${presetBtn('200')}</div>
    <div class="chat-picker-custom">
      <input type="text" inputmode="numeric" id="chatSlippageInput" class="chat-chip-input" data-chat-slippage-input placeholder="${escapeHtml(t('Custom bps'))}" value="${escapeHtml(current)}" autocomplete="off" />
      <button type="button" class="utility" data-chat-slippage-apply>${escapeHtml(t('Set'))}</button>
    </div>`;
  return variant === 'sheet'
    ? `<div class="chat-sheet-picker chat-amount-picker">${inner}</div>`
    : `<div class="chat-picker chat-amount-picker" data-chat-picker>${inner}</div>`;
}

interface ChatTokenListItem { mint: string; symbol: string; decimals: number; amount?: number; valueUsd?: number; owned: boolean; }

// The LIST options for a token field. The swap OUTPUT (toToken) merges owned
// balances with a curated set of common tokens (you usually don't hold what you're
// swapping INTO), deduped by mint and excluding the current input. The input /
// send token stays owned-only — you can only swap or send from what you hold.
function chatTokenListItems(field: ChatPickerField): ChatTokenListItem[] {
  const owned: ChatTokenListItem[] = chatSnapshotAssets()
    .filter((a) => a.amount > 0)
    .map((a) => ({ mint: a.mint, symbol: a.symbol, decimals: a.decimals, amount: a.amount, valueUsd: a.valueUsd, owned: true }));
  if (field !== 'toToken') return owned;
  const seen = new Set(owned.map((i) => i.mint));
  const fromMint = state.chatActionBuilder?.fromToken?.mint;
  const preset: ChatTokenListItem[] = [];
  for (const tok of Object.values(KNOWN_BROWSER_TOKENS)) {
    if (seen.has(tok.mint) || tok.mint === fromMint) continue;
    seen.add(tok.mint);
    preset.push({ mint: tok.mint, symbol: tok.symbol, decimals: tok.decimals, owned: false });
  }
  return [...owned, ...preset];
}

// Compact number for tight token rows + the amount readout: 1k / 10k / 104.3k (≤4 sig).
function formatChatCompactAmount(value: number): string {
  if (!Number.isFinite(value) || value <= 0) return '0';
  if (value >= 1000) {
    return new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value).toLowerCase();
  }
  if (value >= 1) return value.toFixed(2).replace(/\.?0+$/, '');
  return value.toPrecision(3).replace(/\.?0+$/, '');
}
// Compact $ for tight rows + the amount readout: $444.43 / $1.2k / $1.2m.
function formatChatCompactUsd(value: number | undefined): string {
  if (value === undefined || !Number.isFinite(value)) return '';
  const abs = Math.abs(value);
  if (abs > 0 && abs < 0.01) return '<$0.01';
  if (abs >= 1000) {
    return `$${new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value).toLowerCase()}`;
  }
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value);
}

// One token row: logo + symbol/(value|name) + bare amount. Rendered once (no
// duplicated symbol/mint, unlike the generic balance row which appends the symbol
// to the amount string). Not-held preset tokens show the name and no amount.
// `compact` runs the owned amount + $ through the compact formatters (for tight sheet rows).
function chatTokenPickerRowHtml(item: ChatTokenListItem, opts: { compact?: boolean } = {}): string {
  const meta = tokenMarketMetadata.get(item.mint);
  const logo = meta?.logoURI || knownTokenLogo(item.mint);
  const symbol = item.symbol || tokenDisplayLabel(item.mint);
  let amount = '';
  let sub = '';
  if (item.owned && item.amount !== undefined) {
    if (opts.compact) {
      amount = formatChatCompactAmount(item.amount);
      sub = formatChatCompactUsd(item.valueUsd);
    } else {
      const amtWithSym = formatWalletBalanceAmount(item.amount, item.symbol);
      amount = amtWithSym.endsWith(` ${item.symbol}`)
        ? amtWithSym.slice(0, amtWithSym.length - item.symbol.length - 1)
        : amtWithSym;
      sub = item.valueUsd === undefined ? '' : formatWalletBalanceUsd(item.valueUsd);
    }
  } else {
    sub = meta?.name && meta.name !== symbol ? meta.name : '';
  }
  return `
    <button type="button" class="chat-token-opt" data-chat-token-pick="${escapeHtml(item.mint)}" data-chat-token-symbol="${escapeHtml(item.symbol)}" data-chat-token-decimals="${item.decimals}"${logo ? ` data-chat-token-logo="${escapeHtml(logo)}"` : ''}>
      <span class="chat-token-logo">${logo
        ? `<img src="${escapeHtml(logo)}" alt="" loading="lazy" />`
        : `<span>${escapeHtml((symbol || '?').slice(0, 3).toUpperCase())}</span>`}</span>
      <span class="chat-token-info"><strong>${escapeHtml(symbol)}</strong>${sub ? `<em>${escapeHtml(sub)}</em>` : ''}</span>
      ${amount ? `<span class="chat-token-amount">${escapeHtml(amount)}</span>` : ''}
    </button>
  `;
}

function chatTokenPickerHtml(field: ChatPickerField, variant: ChatPickerVariant = 'inline'): string {
  const mode = chatTokenModeFor(field as ChatTokenField);
  const searchId = `chat:${field}`;
  const toggle = `
    <div class="chat-token-modes">
      <button type="button" class="chat-token-mode${mode === 'list' ? ' active' : ''}" data-chat-token-mode="list">${escapeHtml(t('List'))}</button>
      <button type="button" class="chat-token-mode${mode === 'mint' ? ' active' : ''}" data-chat-token-mode="mint">${escapeHtml(t('Mint'))}</button>
    </div>`;
  let body: string;
  if (mode === 'mint') {
    body = `
      <div class="chat-token-search">
        <input type="text" id="chatTokenSearchInput" class="chat-chip-input" data-token-search-input="${escapeHtml(searchId)}" placeholder="${escapeHtml(t('Search symbol/name or paste mint'))}" value="${escapeHtml(tokenSearchStates.get(searchId)?.query ?? '')}" autocomplete="off" spellcheck="false" />
        <div class="token-search-results chat-token-search-results" data-token-search-results="${escapeHtml(searchId)}">${tokenSearchDropdownHtml(searchId)}</div>
      </div>`;
  } else {
    const items = chatTokenListItems(field);
    if (items.length === 0) {
      body = `<p class="chat-token-empty">${escapeHtml(t('No tokens with a balance yet.'))}</p>`;
    } else {
      const limit = Math.max(CHAT_TOKEN_PAGE, chatTokenLimitFor(field as ChatTokenField));
      const shown = items.slice(0, limit);
      const remaining = items.length - shown.length;
      const more = remaining > 0
        ? `<button type="button" class="chat-token-more" data-chat-token-more>${escapeHtml(tf('Show {count} more', { count: remaining }))}</button>`
        : '';
      body = `<div class="chat-token-list">${shown.map((i) => chatTokenPickerRowHtml(i)).join('')}</div>${more}`;
    }
  }
  const title = variant === 'sheet' ? '' : `<p class="chat-picker-title">${escapeHtml(t('Choose a token'))}</p>`;
  const inner = `${title}${toggle}${body}`;
  return variant === 'sheet'
    ? `<div class="chat-sheet-picker chat-token-picker" data-chat-picker-field="${field}">${inner}</div>`
    : `<div class="chat-picker chat-token-picker" data-chat-picker data-chat-picker-field="${field}">${inner}</div>`;
}

function chatAmountPickerHtml(b: ChatActionBuilder, variant: ChatPickerVariant = 'inline'): string {
  const mode: ChatAmountMode = b.amount?.mode ?? 'token';
  const raw = b.amount?.raw ?? '';
  const tab = (m: ChatAmountMode, label: string): string =>
    `<button type="button" class="chat-amount-tab${mode === m ? ' active' : ''}" data-chat-amount-mode="${m}">${escapeHtml(label)}</button>`;
  const pctBtn = (p: string): string =>
    `<button type="button" class="chat-amount-pct" data-chat-amount-pct="${p}">${escapeHtml(`${p}%`)}</button>`;
  const placeholder = mode === 'usd' ? t('Dollar amount') : mode === 'percent' ? t('Custom %') : t('Token amount');
  const inner = `
    <div class="chat-amount-tabs">${tab('token', t('Amount'))}${tab('usd', t('USD ($)'))}${tab('percent', t('Percent'))}</div>
    ${mode === 'percent' ? `<div class="chat-amount-pcts">${pctBtn('25')}${pctBtn('50')}${pctBtn('100')}</div>` : ''}
    <div class="chat-picker-custom">
      <input type="text" inputmode="decimal" id="chatAmountInput" class="chat-chip-input" data-chat-amount-input placeholder="${escapeHtml(placeholder)}" value="${escapeHtml(raw)}" autocomplete="off" />
      <button type="button" class="utility" data-chat-amount-apply>${escapeHtml(t('Set'))}</button>
    </div>`;
  return variant === 'sheet'
    ? `<div class="chat-sheet-picker chat-amount-picker">${inner}</div>`
    : `<div class="chat-picker chat-amount-picker" data-chat-picker>${inner}</div>`;
}

// Which sheet token field's collapsed dropdown is expanded (one at a time).
let chatSheetTokenOpen: ChatTokenField | null = null;

// The collapsed token trigger for the sheet's LIST mode: logo + symbol on top + a short
// 4char…4char mint below (no wasteful full "SOL MINT SO1111…"). Tapping toggles the list.
function chatSheetTokenTriggerHtml(field: ChatTokenField, token: ChatBuilderToken | undefined, open: boolean): string {
  const meta = token ? tokenMarketMetadata.get(token.mint) : undefined;
  const logo = token ? (meta?.logoURI || knownTokenLogo(token.mint)) : '';
  const symbol = token ? (token.symbol || tokenDisplayLabel(token.mint)) : t('Pick token');
  const sub = token ? shortHexMint(token.mint) : '';
  return `
    <button type="button" class="chat-sheet-token-trigger${open ? ' open' : ''}" data-chat-token-trigger="${escapeHtml(field)}" aria-haspopup="listbox" aria-expanded="${open ? 'true' : 'false'}">
      <span class="chat-token-logo">${logo
        ? `<img src="${escapeHtml(logo)}" alt="" loading="lazy" />`
        : `<span>${escapeHtml((symbol || '?').slice(0, 3).toUpperCase())}</span>`}</span>
      <span class="chat-sheet-token-copy"><strong>${escapeHtml(symbol)}</strong>${sub ? `<em>${escapeHtml(sub)}</em>` : ''}</span>
      <span class="chat-sheet-token-caret" aria-hidden="true">▾</span>
    </button>`;
}

// One token field for the full-form action sheet, mirroring the New Request token field
// header (label + LIST/MINT toggle). LIST = a collapsed rich trigger that expands to the
// owned/preset rows (logo + symbol + owned amount + $); MINT = the live mint search shell.
function chatSheetTokenFieldHtml(field: ChatTokenField, label: string): string {
  const b = state.chatActionBuilder;
  const current = b ? b[field] : undefined;
  const presetMode = chatTokenModeFor(field) === 'list';
  const modeToggle = `
    <span class="token-choice-mode" role="group" aria-label="${escapeHtml(tf('{field} input mode', { field: label }))}">
      <button type="button" data-chat-token-field-mode="list" data-chat-token-field="${escapeHtml(field)}" class="${presetMode ? 'active' : ''}">${escapeHtml(t('List'))}</button>
      <button type="button" data-chat-token-field-mode="mint" data-chat-token-field="${escapeHtml(field)}" class="${presetMode ? '' : 'active'}">${escapeHtml(t('Mint'))}</button>
    </span>`;
  let body: string;
  if (presetMode) {
    const open = chatSheetTokenOpen === field;
    const trigger = chatSheetTokenTriggerHtml(field, current, open);
    let list = '';
    if (open) {
      const items = chatTokenListItems(field);
      list = items.length > 0
        ? `<div class="chat-sheet-token-list">${items.map((i) => chatTokenPickerRowHtml(i, { compact: true })).join('')}</div>`
        : `<p class="chat-token-empty">${escapeHtml(t('No tokens with a balance yet.'))}</p>`;
    }
    body = `${trigger}${list}`;
  } else {
    const searchId = `chat:${field}`;
    body = `
      <div class="token-search-shell">
        <input data-token-search-input="${escapeHtml(searchId)}" data-chat-token-search-field="${escapeHtml(field)}" value="${escapeHtml(tokenSearchStates.get(searchId)?.query ?? '')}" placeholder="${escapeHtml(t('Search symbol/name or paste mint'))}" autocomplete="off" spellcheck="false" inputmode="search" />
        <div class="token-search-results" data-token-search-results="${escapeHtml(searchId)}">${tokenSearchDropdownHtml(searchId)}</div>
      </div>`;
  }
  return `
    <div class="field compact planner-field token-choice-field${field === 'toToken' ? ' token-field--output' : ''}">
      <span class="token-choice-head">
        <span>${escapeHtml(label)}</span>
        ${modeToggle}
      </span>
      ${body}
    </div>`;
}

// A plain labelled text/number field for the action sheet (amount, slippage, recipient,
// memo). Reuses the existing live input handlers via the data-* attribute passed in.
function chatSheetTextFieldHtml(opts: { label: string; value: string; placeholder: string; attr: string; inputmode?: string; mono?: boolean }): string {
  return `
    <label class="field compact planner-field${opts.mono ? ' chat-sheet-mono' : ''}">
      <span>${escapeHtml(opts.label)}</span>
      <input ${opts.attr} value="${escapeHtml(opts.value)}" placeholder="${escapeHtml(opts.placeholder)}" autocomplete="off" spellcheck="false"${opts.inputmode ? ` inputmode="${escapeHtml(opts.inputmode)}"` : ''} />
    </label>`;
}

// The chat send recipient field: same monospace text field but routed through the shared
// recipient control so it gets the [Address|Saved] pills, one-tap Paste, and the saved-recipients
// dropdown. Reuses the live data-chat-chip-recipient handler.
function chatSheetRecipientFieldHtml(b: ChatActionBuilder): string {
  const inputHtml = `<input data-chat-chip-recipient value="${escapeHtml(b.recipient ?? '')}" placeholder="${escapeHtml(t('Recipient public key'))}" autocomplete="off" spellcheck="false" />`;
  return `
    <label class="field compact planner-field chat-sheet-mono recipient-field">
      <span>${escapeHtml(t('Recipient address'))}</span>
      ${recipientControlHtml({ key: 'chat:recipient', inputHtml })}
    </label>`;
}

// A responsive field row mirroring the New Request mobile grid: two short fields pair
// side-by-side, a single field spans full width.
function chatSheetFieldRow(...fields: string[]): string {
  const shape = fields.length > 1 ? 'mobile-field-pair' : 'mobile-field-full';
  return `<div class="mobile-planner-field-row ${shape}">${fields.map((f) => `<div class="mobile-planner-field">${f}</div>`).join('')}</div>`;
}

// A CONCRETE amount (in the active unit) for a % of the input token's balance. Mirrors
// resolveChatAmount's percent path incl. the native-SOL fee buffer at 100%.
function chatPercentAmount(asset: WalletBalanceAsset, pct: number, mode: ChatAmountMode): string {
  if (!(asset.amount > 0) || !(pct > 0)) return '';
  let tokenAmount = asset.amount * (pct / 100);
  if (asset.mint === WSOL_MINT && pct >= 100) tokenAmount = Math.max(0, tokenAmount - SOL_FEE_RESERVE);
  if (!(tokenAmount > 0)) return '';
  if (mode === 'usd') {
    const price = asset.priceUsd;
    if (!price || !(price > 0)) return '';
    return (tokenAmount * price).toFixed(2).replace(/\.?0+$/, '');
  }
  return trimChatAmount(tokenAmount, asset.decimals);
}

// Whether the note row is expanded (swap "+ Add a note").
let chatSheetNoteOpen = false;

// The amount field: a [ $ | Token ] unit pill ($ default), the input with the selected
// token's owned balance shown right-aligned (in the active unit), and 50 / 100 / custom %
// quick-fills that compute a concrete amount from that balance.
function chatSheetAmountFieldHtml(b: ChatActionBuilder, label: string): string {
  const mode: ChatAmountMode = b.amount?.mode === 'token' ? 'token' : 'usd';
  const raw = b.amount?.raw ?? '';
  const asset = chatBuilderFromAsset(b);
  let balanceText = '';
  if (asset) {
    balanceText = mode === 'usd'
      ? formatChatCompactUsd(asset.valueUsd)
      : `${formatChatCompactAmount(asset.amount)} ${asset.symbol}`;
  }
  const unitPill = `
    <span class="token-choice-mode" role="group" aria-label="${escapeHtml(t('Amount unit'))}">
      <button type="button" data-chat-amount-unit="usd" class="${mode === 'usd' ? 'active' : ''}">$</button>
      <button type="button" data-chat-amount-unit="token" class="${mode === 'token' ? 'active' : ''}">${escapeHtml(t('Token'))}</button>
    </span>`;
  const pctBtn = (p: string): string =>
    `<button type="button" class="chat-amount-pct" data-chat-pct="${p}">${escapeHtml(`${p}%`)}</button>`;
  return `
    <div class="field compact planner-field chat-amount-block">
      <span class="token-choice-head">
        <span>${escapeHtml(label)}</span>
        ${unitPill}
      </span>
      <div class="chat-amount-field">
        <input data-chat-amount-input data-chat-amount-mode-current="${mode}" value="${escapeHtml(raw)}" placeholder="${escapeHtml(mode === 'usd' ? '$0.00' : '0.00')}" inputmode="decimal" autocomplete="off" spellcheck="false" />
        ${balanceText ? `<span class="chat-amount-balance" aria-hidden="true">${escapeHtml(balanceText)}</span>` : ''}
      </div>
      <div class="chat-amount-pcts">
        ${pctBtn('50')}${pctBtn('100')}
        <input class="chat-amount-pct-input" data-chat-pct-input placeholder="${escapeHtml(t('Custom %'))}" inputmode="numeric" autocomplete="off" />
        <button type="button" class="chat-amount-pct chat-amount-pct-apply" data-chat-pct-apply aria-label="${escapeHtml(t('Apply percent'))}">%</button>
      </div>
    </div>`;
}

// The slippage field: [ Auto | Custom ] pills. Auto = no cap (Jupiter Ultra dynamic);
// Custom = an editable bps input (validated 1–5000 in the live handler).
function chatSheetSlippageFieldHtml(b: ChatActionBuilder): string {
  const custom = Boolean(b.slippageBps && b.slippageBps.trim());
  const modePill = `
    <span class="token-choice-mode" role="group" aria-label="${escapeHtml(t('Slippage mode'))}">
      <button type="button" data-chat-slippage-mode="auto" class="${custom ? '' : 'active'}">${escapeHtml(t('Auto'))}</button>
      <button type="button" data-chat-slippage-mode="custom" class="${custom ? 'active' : ''}">${escapeHtml(t('Custom'))}</button>
    </span>`;
  const input = custom
    ? `<input data-chat-slippage-live value="${escapeHtml(b.slippageBps?.trim() ?? '')}" placeholder="50" inputmode="numeric" autocomplete="off" />`
    : `<input value="${escapeHtml(t('Auto'))}" disabled />`;
  return `
    <div class="field compact planner-field">
      <span class="token-choice-head">
        <span>${escapeHtml(t('Max slippage (bps)'))}</span>
        ${modePill}
      </span>
      ${input}
    </div>`;
}

// The swap "+ Add a note" row: collapsed until tapped (or a note already exists).
function chatSheetNoteRowHtml(b: ChatActionBuilder): string {
  const hasNote = Boolean(b.memo && b.memo.trim());
  if (!chatSheetNoteOpen && !hasNote) {
    return `<button type="button" class="chat-sheet-add-note" data-chat-note-toggle>${escapeHtml(t('+ Add a note'))}</button>`;
  }
  return `
    <label class="field compact planner-field">
      <span>${escapeHtml(t('Note (optional)'))}</span>
      <input data-chat-memo-input value="${escapeHtml(b.memo ?? '')}" placeholder="${escapeHtml(t('Reason or context for this swap'))}" autocomplete="off" spellcheck="false" />
    </label>`;
}

// The full single-sheet form for a wallet action (native mobile). Every field is visible
// at once (no per-field sub-sheets), typed inputs sit near the top so the sheet rides
// above the keyboard, and a sticky Confirm autofills the composer grammar.
function chatActionSheetFormHtml(b: ChatActionBuilder): string {
  let fields: string;
  if (b.kind === 'swap') {
    fields = `
      ${chatSheetFieldRow(chatSheetTokenFieldHtml('fromToken', t('Input token')), chatSheetTokenFieldHtml('toToken', t('Output token')))}
      ${chatSheetFieldRow(chatSheetAmountFieldHtml(b, t('Token amount')))}
      ${chatSheetFieldRow(chatSheetSlippageFieldHtml(b))}
      ${chatSheetFieldRow(chatSheetNoteRowHtml(b))}`;
  } else if (b.kind === 'send') {
    fields = `
      ${chatSheetFieldRow(chatSheetRecipientFieldHtml(b))}
      ${chatSheetFieldRow(chatSheetTokenFieldHtml('fromToken', t('Token')))}
      ${chatSheetFieldRow(chatSheetAmountFieldHtml(b, t('Amount')))}
      ${chatSheetFieldRow(chatSheetTextFieldHtml({ label: t('Memo / reason'), value: b.memo ?? '', placeholder: t('Invoice, friend payment, reimbursement'), attr: 'data-chat-memo-input' }))}`;
  } else {
    // sign — interim simple statement form (the proof/evidence template builder replaces
    // this branch).
    fields = chatSheetFieldRow(`
      <label class="field compact planner-field">
        <span>${escapeHtml(t('Statement to attest'))}</span>
        <input data-chat-chip-statement value="${escapeHtml(b.statement ?? '')}" placeholder="${escapeHtml(t('Statement to attest'))}" autocomplete="off" spellcheck="false" />
      </label>`);
  }
  return `
    <div class="chat-sheet-form" data-chat-sheet-form>
      <div class="chat-sheet-fields mobile-planner-fields">${fields}</div>
      <div class="chat-sheet-confirm">
        <button type="button" class="primary" data-chat-action-confirm>${escapeHtml(t('Confirm'))}</button>
      </div>
    </div>`;
}

// --- Web/desktop consolidated wallet-action popover --------------------------
// One panel anchored above the composer that reuses the SAME field renderers as the
// mobile sheet (no chip cascade). Swap/Send have no Confirm — the field handlers
// live-compile into the composer; Sign reuses the proof builder (its own Confirm).
let chatActionPopoverOpen = false;
let chatConnectorPopoverOpen = false;
let chatRecurringPopoverOpen = false;
let chatRecurringSubmitting = false;
function chatActionPopoverHtml(): string {
  if (chatUsesSheet()) return '';
  const b = state.chatActionBuilder;
  if (!b || !chatActionPopoverOpen) return '';
  const title = b.kind === 'swap' ? t('Swap') : b.kind === 'send' ? t('Send') : t('Sign Proof');
  const row = (cls: string, ...fields: string[]): string =>
    `<div class="chat-popover-row${cls ? ` ${cls}` : ''}">${fields.join('')}</div>`;
  let body: string;
  if (b.kind === 'sign') {
    body = chatProofSheetHtml();
  } else if (b.kind === 'swap') {
    body = `
      <div class="chat-popover-fields">
        ${row('pair', chatSheetTokenFieldHtml('fromToken', t('Input token')), chatSheetTokenFieldHtml('toToken', t('Output token')))}
        ${row('pair', chatSheetAmountFieldHtml(b, t('Token amount')), chatSheetSlippageFieldHtml(b))}
        ${row('', chatSheetNoteRowHtml(b))}
      </div>`;
  } else {
    body = `
      <div class="chat-popover-fields">
        ${row('', chatSheetRecipientFieldHtml(b))}
        ${row('pair', chatSheetTokenFieldHtml('fromToken', t('Token')), chatSheetAmountFieldHtml(b, t('Amount')))}
        ${row('', chatSheetTextFieldHtml({ label: t('Memo / reason'), value: b.memo ?? '', placeholder: t('Invoice, friend payment, reimbursement'), attr: 'data-chat-memo-input' }))}
      </div>`;
  }
  return `
    <div class="chat-action-popover" data-chat-action-popover>
      <div class="chat-popover-head">
        <span class="chat-builder-eyebrow">${escapeHtml(title)}</span>
        <button type="button" class="chat-builder-clear" data-chat-popover-close aria-label="${escapeHtml(t('Close'))}" title="${escapeHtml(t('Close'))}">&times;</button>
      </div>
      ${body}
    </div>`;
}

// --- Chat proof / evidence sheet (native mobile) -----------------------------
// The "Sign proof" action mirrors the New Request proof/evidence builder: two tabs
// (Proof = outcome 'proof'; Evidence = outcome 'audit'), each with a dropdown over all
// templates of that outcome, then the selected template's fields. Confirm composes the
// filled template into a readable statement and seeds the existing sign-proof builder, so
// the composer autofills "Sign a proof that …" and Send queues a sign_proof PreparedAction.
type ChatProofTab = 'proof' | 'audit';
let chatProofTab: ChatProofTab = 'proof';
let chatProofTemplateId = '';
const chatProofFields: Record<string, string> = {};

function chatProofTemplatesFor(tab: ChatProofTab): AgentPlanTemplate[] {
  return AGENT_PLAN_TEMPLATES.filter((tpl) => templateOutcome(tpl) === tab);
}
function chatSelectedProofTemplate(): AgentPlanTemplate | undefined {
  const list = chatProofTemplatesFor(chatProofTab);
  return list.find((tpl) => tpl.id === chatProofTemplateId) ?? list[0];
}
function chatProofResetFields(template: AgentPlanTemplate): void {
  for (const key of Object.keys(chatProofFields)) delete chatProofFields[key];
  for (const f of template.fields) {
    // Select values must stay the raw English enum so selectPicker matching, showWhen
    // visibility, and planner cadence parsing keep working. Text/textarea prefills are
    // user-facing editable copy, so translate them into the active UI language.
    chatProofFields[f.id] = f.type === 'select'
      ? (f.defaultValue ?? '')
      : t(f.defaultValue ?? '');
  }
}
function chatProofEnsureInit(): void {
  const current = chatSelectedProofTemplate();
  if (current && current.id === chatProofTemplateId) return;
  const fallback = current ?? chatProofTemplatesFor(chatProofTab)[0];
  if (!fallback) return;
  chatProofTemplateId = fallback.id;
  chatProofResetFields(fallback);
}
// Honor a field's showWhen visibility against the current chat-proof field values (mirrors
// the New Request form so conditional fields don't render/contribute when irrelevant).
function chatProofFieldVisible(fieldDef: AgentPlanTemplateField): boolean {
  if (!fieldDef.showWhen) return true;
  return Object.entries(fieldDef.showWhen).every(([key, allowed]) => {
    const value = chatProofFields[key] ?? '';
    return Array.isArray(allowed) ? allowed.includes(value) : allowed === value;
  });
}
function composeChatProofStatement(template: AgentPlanTemplate): string {
  const parts = template.fields
    .filter(chatProofFieldVisible)
    .map((f) => {
      const v = (chatProofFields[f.id] ?? f.defaultValue ?? '').trim();
      return v ? `${t(f.label)}: ${v}` : '';
    })
    .filter(Boolean);
  return parts.length ? `${t(template.title)} - ${parts.join(', ')}` : t(template.title);
}
// Seed the sign-proof builder from the filled template and autofill the composer.
function chatProofConfirm(): void {
  const template = chatSelectedProofTemplate();
  if (!template) return;
  state.chatActionBuilder = { kind: 'sign', statement: composeChatProofStatement(template) };
  state.chatActionPicker = null;
  applyChatBuilderDraft();
  closeChatActionSheet();
  render();
}

// --- Chat "Connector Actions" surface (reuses the New Request planner) ----------
// Connector Actions reuses the EXACT New Request connector forms: the surface drives the
// global planner state (selectedTemplateId/templateFields/…), so templatePicker +
// plannerFieldsHtml + the global data-template-field listeners + the submit pipeline all work
// with ZERO per-connector duplication. openChatConnectorSurface snapshots the prior New
// Request draft; close/confirm restores it. Mobile reuses the chat-action sheet; desktop gets
// chatConnectorPopoverHtml. Read-only ("Evidence only") forms sign a proof receipt; queueable
// forms drop a chat-originated PreparedAction into the same approval rail.

// The first connector form usable in chat: its template must exist in AGENT_PLAN_TEMPLATES (blink +
// generic position-check forms are excluded there, and templateById() would otherwise fall back to the
// SWAP template). Prefer a queueable action so the surface opens on something actionable, not a
// read-only/evidence default.
function firstChatUsableConnectorForm(connector: ProtocolConnector): ConnectorActionForm | undefined {
  const inTemplates = (form: ConnectorActionForm): boolean =>
    AGENT_PLAN_TEMPLATES.some((tpl) => tpl.id === form.templateId);
  const forms = connectorActionFormsForConnector(connector).filter(inTemplates);
  return forms.find((form) => form.outcome === 'queueable') ?? forms[0];
}

function chatConnectorsForCreate(): ProtocolConnector[] {
  const env = connectorDraftEnvironment();
  // Action-scoped surfaces filter the route picker to the verb's connectors (Sanctum excluded);
  // otherwise all connectors. Keep enabled connectors plus disabled/credential-required connectors
  // that can open the same Enable/API-key sheet as New Request.
  const cat = state.createActionCategory;
  const scoped = isConnectorAction(cat);
  const base = scoped ? connectorsForCategory(cat as ActionCategory, env) : connectorCreateConnectors(env);
  return base.filter((connector) => {
    const status = connectorCreateStatus(connector, env);
    // Scoped: require a template-backed form IN the category (so switching connectors stays in-scope
    // and never resolves to a wrong/undefined form). Unscoped: any chat-usable form.
    return (status.selectable || connectorCreateStatusIsConnectable(status.kind)) &&
      Boolean(scoped ? firstFormForCategory(connector, cat as ActionCategory) : firstChatUsableConnectorForm(connector));
  });
}

function chatConnectorSurfaceBodyHtml(): string {
  const connectors = chatConnectorsForCreate();
  if (connectors.length === 0) {
    // Action-scoped with no enabled connector → offer to enable the top one inline (else generic hint).
    const gate = isConnectorAction(state.createActionCategory) ? connectGateFor(state.createActionCategory, 'chat') : '';
    return `
      <div class="chat-sheet-form chat-connector-form" data-chat-sheet-form>
        <p class="chat-token-empty">${escapeHtml(t('No connectors enabled. Enable a protocol connector in Preferences to prepare connector actions.'))}</p>
        ${gate}
      </div>`;
  }
  const env = connectorDraftEnvironment();
  const template = selectedTemplate();
  const selectedConnector = selectedConnectorForCreate(template);
  const selectedStatus = selectedConnector ? connectorCreateStatus(selectedConnector, env) : null;
  const selectedNeedsConnect = Boolean(selectedConnector && selectedStatus && !selectedStatus.selectable && connectorCreateStatusIsConnectable(selectedStatus.kind));
  const selectedConnectGate = selectedConnector && selectedNeedsConnect && isConnectorAction(state.createActionCategory)
    ? connectorConnectGateButton(selectedConnector, state.createActionCategory as ActionCategory, 'chat')
    : '';
  // Reuse the New Request connector picker options, minus the "Use connector" clear row
  // (the chat surface always keeps a connector selected), wired to the SAME global handler.
  const connectorOptions = connectorCreatePickerOptions(connectors, env).filter((option) => option.value !== '');
  const connectorPicker = selectPicker({
    id: 'chatConnectorPicker',
    value: selectedConnector?.id ?? '',
    options: connectorOptions,
    attrs: { 'data-connector-create-picker': true },
    className: 'top-connector-picker connector-create-picker',
  });
  const outcome = templateOutcome(template);
  return `
    <div class="chat-sheet-form chat-connector-form" data-chat-sheet-form>
      <div class="field compact planner-field">
        <span>${escapeHtml(t('Connector'))}</span>
        ${connectorPicker}
      </div>
      ${selectedConnectGate}
      ${activeCategoryHasSingleTemplate() ? '' : `
      <div class="field compact planner-field">
        <span>${escapeHtml(t('Plan template'))}</span>
        ${templatePicker(template)}
      </div>`}
      ${template.id === 'connector-jupiter-trigger-limit-orders' ? '' : `
      <div class="chat-connector-template-meta">
        <strong class="template-outcome-badge ${escapeHtml(outcomeClass(outcome))}">${escapeHtml(outcomeShortLabel(outcome))}</strong>
        <p class="template-description">${escapeHtml(t(template.description))}</p>
      </div>`}
      <div class="chat-sheet-fields mobile-planner-fields" data-template-id="${escapeHtml(template.id)}">
        ${plannerFieldsHtml(template)}
      </div>
      ${dcaAutomationNoteHtml()}
      <div class="chat-sheet-confirm">
        <button type="button" class="primary" data-chat-connector-confirm ${selectedNeedsConnect ? 'disabled' : ''}>${escapeHtml(t('Confirm'))}</button>
      </div>
    </div>`;
}

// Title for the connector surface: the action verb when action-scoped (e.g. "Lend"), else generic.
function chatConnectorSurfaceTitle(): string {
  const cat = state.createActionCategory;
  return isConnectorAction(cat) ? connectorActionLabel(cat as ActionCategory) : t('Connector Actions');
}

// Desktop/web connector popover (mobile uses the chat-action sheet instead).
function chatConnectorPopoverHtml(): string {
  if (chatUsesSheet()) return '';
  if (!chatConnectorPopoverOpen || !state.chatConnectorSession?.active) return '';
  return `
    <div class="chat-action-popover chat-connector-popover" data-chat-connector-popover>
      <div class="chat-popover-head">
        <span class="chat-builder-eyebrow">${escapeHtml(chatConnectorSurfaceTitle())}</span>
        <button type="button" class="chat-builder-clear" data-chat-connector-popover-close aria-label="${escapeHtml(t('Close'))}" title="${escapeHtml(t('Close'))}">&times;</button>
      </div>
      ${chatConnectorSurfaceBodyHtml()}
    </div>`;
}

// Snapshot the New Request planner draft + open the chat connector sheet/popover. Shared by the
// action-scoped surfaces (the Advanced "Lend/Limit/…" cards).
function snapshotChatConnectorSession(): void {
  state.chatComposerOpen = false;
  document.querySelector('.chat-plus-menu')?.classList.remove('open');
  state.chatActionBuilder = null;
  state.chatActionPicker = null;
  state.chatConnectorSession = {
    active: true,
    saved: {
      selectedTemplateId: state.selectedTemplateId,
      templateOutcomeFilter: state.templateOutcomeFilter,
      createActionCategory: state.createActionCategory,
      templateFields: { ...state.templateFields },
      templateTokenModes: { ...state.templateTokenModes },
      templateTokenSelections: { ...state.templateTokenSelections },
      templateFieldErrors: { ...state.templateFieldErrors },
      agentPlan: state.agentPlan,
      agentSignature: state.agentSignature,
      agentPreparedActionId: state.agentPreparedActionId,
    },
  };
  if (chatUsesSheet()) {
    openChatActionSheet();
  } else {
    chatActionPopoverOpen = false;
    chatConnectorPopoverOpen = true;
  }
}

// Open the chat connector surface SCOPED to an action verb (Lend/Limit/…): filters the connector
// route picker to that action's protocols (Sanctum excluded), seeds the user's first ENABLED
// connector (gate prompts if none), and scopes sub-actions — mirrors New Request's "Lend ▾".
function openChatActionSurface(category: ActionCategory): void {
  snapshotChatConnectorSession();
  state.createActionCategory = category;
  const env = connectorDraftEnvironment();
  // Only connectors with a template-backed form for the category (firstFormForCategory requires the
  // template to exist) — so seeding never resolves to undefined and leaves a stale surface.
  const inCat = connectorsForCategory(category, env).filter((connector) => firstFormForCategory(connector, category));
  const top = inCat.find((connector) => connectorCreateStatus(connector, env).selectable) ?? inCat[0];
  const form = top ? firstFormForCategory(top, category) : undefined;
  if (form) {
    applyConnectorActionFormForCategory(form, category);
    if (top) {
      const status = connectorCreateStatus(top, env);
      if (!status.selectable && connectorCreateStatusIsConnectable(status.kind)) {
        openConnectorConnect(top.id, category, 'chat');
      }
    }
  } else {
    render();
  }
  // Seed the composer with a live template (mirrors Swap seeding "Swap [amount] SOL to [token]")
  // now that the form is painted — it updates as the user fills the form via the field funnel.
  applyChatConnectorDraftPreview();
}

// Restore the snapshotted New Request planner draft (no render — callers render).
function restoreChatConnectorPlannerSnapshot(): void {
  const session = state.chatConnectorSession;
  if (!session) return;
  const s = session.saved;
  state.selectedTemplateId = s.selectedTemplateId;
  state.templateOutcomeFilter = s.templateOutcomeFilter;
  state.createActionCategory = s.createActionCategory;
  state.templateFields = s.templateFields;
  state.templateTokenModes = s.templateTokenModes;
  state.templateTokenSelections = s.templateTokenSelections;
  state.templateFieldErrors = s.templateFieldErrors;
  state.agentPlan = s.agentPlan;
  state.agentSignature = s.agentSignature;
  state.agentPreparedActionId = s.agentPreparedActionId;
  state.chatConnectorSession = null;
}

function closeChatConnectorSurface(restore: boolean): void {
  if (restore) restoreChatConnectorPlannerSnapshot();
  else state.chatConnectorSession = null;
  if (state.activeMobileRailSheet === 'chat-action') state.activeMobileRailSheet = null;
  chatConnectorPopoverOpen = false;
  // Cancel path: if the composer still holds the un-confirmed live preview (user didn't Confirm and
  // didn't hand-edit it away), clear it so a cancelled advanced draft never lingers. Confirm releases
  // ownership via stageChatHeldAction (chatConnectorPreviewDraft='') so its held label is preserved.
  if (chatConnectorPreviewDraft && chatDraft === chatConnectorPreviewDraft) {
    clearChatComposerDraft();
    chatConnectorPreviewDraft = '';
  }
}

// Catch-all (called at the top of render): if the connector surface was left open while the
// user navigated off the Chat tab, restore the New Request draft so it never shows connector
// data. Mobile sheets also close via closeMobileRailSheet; this covers the desktop popover.
function reconcileChatConnectorSession(): void {
  if (state.chatConnectorSession?.active && state.activeTab !== 'chat') {
    restoreChatConnectorPlannerSnapshot();
    chatConnectorPopoverOpen = false;
    if (state.activeMobileRailSheet === 'chat-action') state.activeMobileRailSheet = null;
    // Drop an un-confirmed live preview so it doesn't linger in the composer on return to Chat.
    if (chatConnectorPreviewDraft && chatDraft === chatConnectorPreviewDraft) {
      clearChatComposerDraft();
      chatConnectorPreviewDraft = '';
    }
  }
  if (state.chatRecurringSession?.active && state.activeTab !== 'chat') {
    restoreChatRecurringSnapshot();
    chatRecurringPopoverOpen = false;
    if (state.activeMobileRailSheet === 'chat-action') state.activeMobileRailSheet = null;
  }
}

// Confirm: build a PreparedAction (queueable) or an evidence proof (read-only) from the filled
// connector form via the EXACT New Request submit pipeline, attach it to a chat card, then
// restore the New Request draft. The agent does no work — pure client-side.
// --- Confirm → structured message → Send → card (held-draft) ------------------
// Connector + Recurring Confirm compiles a readable, ID-free "picker answers" label into the
// composer and stashes the fully-resolved draft in state.chatHeldAction; Send materializes the
// card from that held object (never by re-parsing the text), so exact on-chain ids are carried,
// not re-resolved. Swap/Send/Sign keep their own text round-trip (parseChatWalletAction).

// Readable label from the plan's already-resolved picker answers. Drops the raw-mint rows
// readableParameters() adds (label ends "mint") + any pure base58 value, so no id leaks.
function compileConnectorDraftToMessage(plan: AgentPlan, opts: { amountPlaceholder?: boolean } = {}): string {
  // DCA reads as a sentence ("DCA 100 USDC to SOL") rather than the generic "title · amount", mirroring
  // Swap's composer grammar so the bracket fills in as the spend token/amount/receive token are picked.
  if (plan.actionType === 'jupiter_recurring_create_time_order') {
    return compileDcaConnectorMessage(plan, opts);
  }
  // Reuse the approval CARD's OWN summary primitives — they are concise, deduped, per-protocol,
  // scoped to the SELECTED sub-action, and localized. (The old plan.fields join emitted a row per
  // flattened sub-action field — dupes + irrelevant repay/withdraw rows — because readableParameters
  // ignores showWhen.) `connectorActionDisplayParts` resolves the form + branch from the params, so
  // passing plan.actionType is enough (matches the card call sites).
  const display = connectorActionDisplayParts(plan.actionType, plan.parameters);
  const title = display?.title || t(plan.templateTitle || plan.category || 'Wallet action');
  const amount = connectorPlanAmountInfo(plan)?.label;
  const note = (plan.parameters.memo || plan.parameters.note || plan.userNotes || '').trim();
  const segments = [title];
  // The amount is the one universal blank — while previewing an unfilled draft show its placeholder
  // so the composer reads like Swap's "Swap [amount] SOL to [token]" (the title fills the asset/target
  // in as it's picked). Only when the form actually HAS an amount field (opts.amountPlaceholder) — so
  // an amount-less action (governance vote, oracle post) never shows a misleading "[amount]". On
  // Confirm every required field is filled, so callers pass no placeholder and there are none.
  if (amount) segments.push(amount);
  else if (opts.amountPlaceholder) segments.push('[amount]');
  if (note) segments.push(`note: ${note}`);
  return segments.join(' · ');
}

// DCA-specific composer/held label: "DCA 100 USDC to SOL" (or "DCA [amount] USDC to SOL" while the total
// is unfilled during the live preview). Mirrors Swap's grammar so the bracket fills in as the spend
// amount is entered; the full schedule (orders/interval) rides on the approval card, not the composer.
function compileDcaConnectorMessage(plan: AgentPlan, opts: { amountPlaceholder?: boolean }): string {
  const from = tokenDisplayLabel(planParameter(plan, ['inputMint']) || '') || t('token');
  const to = tokenDisplayLabel(planParameter(plan, ['outputMint']) || '') || t('token');
  const total = planParameter(plan, ['totalAmount']).trim();
  const amountText = total || (opts.amountPlaceholder ? '[amount]' : '');
  const spend = amountText ? `${amountText} ${from}` : from;
  const note = (plan.parameters.memo || plan.parameters.note || plan.userNotes || '').trim();
  const segments = [tf('DCA {spend} to {to}', { spend, to })];
  if (note) segments.push(`note: ${note}`);
  return segments.join(' · ');
}

// True when the LIVE connector form currently renders an amount/price/size input (scoped to the
// selected sub-action, since only visible fields are in the DOM). Drives whether the live preview
// shows an "[amount]" placeholder — mirrors the amount keys connectorPlanAmountInfo resolves.
function connectorFormHasAmountInput(): boolean {
  return CONNECTOR_AMOUNT_FIELD_IDS.some((id) => document.querySelector(`[data-template-field="${id}"]`));
}
const CONNECTOR_AMOUNT_FIELD_IDS = [
  'amount', 'amountSol', 'solAmount', 'msolAmount', 'inputAmount', 'totalAmount', 'plannedAmount',
  'maxAmount', 'collateralAmount', 'borrowAmount', 'makingAmount', 'takingAmount', 'liquidityAmount',
  'shares', 'percentage', 'tokenAAmount', 'tokenBAmount', 'tokenXAmount', 'tokenYAmount',
  'maxTokenAAmount', 'maxTokenBAmount', 'priceSol', 'bidPriceSol', 'maxPriceSol', 'maxPricePerNftSol',
  'maxEscrowSol',
];

function compileRecurringDraftToMessage(draft: RecurringDraft): string {
  // Resolve tokens to symbols so a long-tail DCA token never shows a raw base58 mint.
  const what = recurringDraftIsSwap(draft)
    ? tf('{amount} {from} to {to}', { amount: draft.amount, from: tokenDisplayLabel(draft.inputToken), to: tokenDisplayLabel(draft.outputToken) })
    : tf('{amount} {token}', { amount: draft.amount, token: tokenDisplayLabel(draft.token) });
  return tf('Recurring: {what}', { what });
}

// Stash the held draft + show its label in the composer (the user taps Send to materialize it).
function stageChatHeldAction(held: ChatHeldAction): void {
  state.chatHeldAction = held;
  // The held action now OWNS the composer text (not the live preview). Release the preview so the
  // cancel-clear guard in closeChatConnectorSurface doesn't wipe this committed label — a filled
  // form's final message equals its last preview string.
  chatConnectorPreviewDraft = '';
  setChatActiveDraft(held.composerText);
  const input = document.querySelector<HTMLTextAreaElement>('[data-chat-input]');
  if (input) { input.value = held.composerText; chatAutoGrow(input); }
}

// Send-time consumer: when the composer text matches the held draft, materialize its card. Returns
// true when it handled the message. Mirrors the wording the old Confirm handlers posted inline.
async function tryConsumeHeldChatAction(content: string): Promise<boolean> {
  const held = state.chatHeldAction;
  if (!held || content.trim() !== held.composerText.trim()) return false;
  const session = ensureActiveChatSession();
  appendChatMessage(session.id, { id: newId('chat-msg'), role: 'user', content, createdAt: new Date().toISOString(), status: 'done' });
  state.chatHeldAction = null;
  // A concrete built action supersedes any armed Decision Check policy (this runs BEFORE the
  // decision routing in submitChatMessage, so an armed user who built a connector action isn't
  // dead-ended). Disarm cleanly.
  state.chatDecisionArmed = null;
  clearChatComposerDraft();
  const finish = (): boolean => {
    chatScrollPinned = true;
    chatForceScrollBottom = true;
    saveChatHistoryState();
    void syncChatSessionToCloud(session.id);
    if (state.activeTab === 'chat') render();
    return true;
  };
  // Re-check the wallet at Send: it may have disconnected between Confirm and now (the connector
  // action carries the Confirm-time wallet; recurring creation needs a live wallet).
  if (!state.address) {
    appendChatMessage(session.id, {
      id: newId('chat-msg'), role: 'assistant',
      content: t('Connect a wallet to prepare this action.'),
      createdAt: new Date().toISOString(), status: 'done',
    });
    return finish();
  }
  if (held.kind === 'connector' && held.preparedAction) {
    state.preparedActions = mergePreparedActions([held.preparedAction], state.preparedActions);
    state.materializedActions = state.preparedActions;
    saveBrowserWorkflowState();
    appendChatMessage(session.id, {
      id: newId('chat-msg'),
      role: 'assistant',
      content: held.evidence
        ? t('Prepared this evidence request. Review the card below, then tap Approve or type "sign" to sign a proof.')
        : t('Prepared this action. Review the card below, then tap Approve or type "sign".'),
      createdAt: new Date().toISOString(),
      status: 'done',
      preparedActionId: held.preparedAction.id,
    });
    return finish();
  }
  if (held.kind === 'recurring' && held.recurringDraft) {
    let created: RecurringPayment | undefined;
    try {
      const before = new Set(state.recurringPayments.map((p) => p.id));
      await createRecurringFromDraft(held.recurringDraft, { status: 'active' });
      created = state.recurringPayments.find((p) => !before.has(p.id));
    } catch (err) {
      appendChatMessage(session.id, {
        id: newId('chat-msg'), role: 'assistant',
        content: redactSecrets(err instanceof Error ? err.message : String(err)),
        createdAt: new Date().toISOString(), status: 'error',
      });
      return finish();
    }
    appendChatMessage(session.id, {
      id: newId('chat-msg'),
      role: 'assistant',
      content: chatRecurringConfirmText(created, held.recurringDraft),
      createdAt: new Date().toISOString(),
      status: 'done',
      ...(created ? { recurringCardId: created.id } : {}),
    });
    return finish();
  }
  return finish();
}

function confirmChatConnectorAction(): void {
  if (!state.chatConnectorSession?.active) return;
  if (!chatRequireWalletOrNotify()) return;
  const template = selectedTemplate();
  const parameters = normalizeConnectorDraftParameters(template, readTemplateFields(template));
  state.templateFields = parameters;
  let action: PreparedAction;
  let evidence = false;
  let composerText = '';
  try {
    assertValidTemplatePlanInput(template, parameters, '', { mode: 'template' });
    const plan = planWithRuntimeTokenLabels(buildTemplatePlan(template, parameters, 'template', ''));
    if (canQueueAgentPlan(plan)) {
      action = browserPreparedActionFromPlan(plan);
      action.chatOriginated = true;
    } else if (plan.actionType === 'read_only') {
      // Read-only / "Evidence only" connector form: nothing to queue. Sign a proof receipt
      // attesting the connector check (mirrors New Request's Evidence-only outcome) so it flows
      // through the same chat sign rail and posts a proof receipt.
      evidence = true;
      const statement = (plan.intent || t(template.title)).slice(0, 280);
      action = createBrowserPreparedActionFromProposal({
        kind: 'manual_review',
        summary: t(template.title).slice(0, 140),
        params: { statement, proofKind: 'sign_proof' },
        cluster: state.cluster,
      });
    } else {
      // A queueable form whose action didn't resolve (e.g. a sub-action option wasn't picked, so
      // connectorActionFormTemplateActionType fell back to 'manual_review'). Don't silently sign a
      // proof — ask the user to choose the option.
      throw new Error(t('Choose an action option to continue.'));
    }
    composerText = compileConnectorDraftToMessage(plan);
  } catch (err) {
    // assertValidTemplatePlanInput populates state.templateFieldErrors — surface them inline
    // and keep the surface open so the user can fix the fields.
    pushToast('error', t('Complete required fields'), redactSecrets(err instanceof Error ? err.message : String(err)));
    render();
    return;
  }
  // Confirm → structured message → Send → card: don't materialize the card yet. Stash the fully
  // resolved action (with its exact on-chain ids) and show a readable picker-answer label in the
  // composer; tryConsumeHeldChatAction promotes it to the card when the user taps Send.
  stageChatHeldAction({ kind: 'connector', preparedAction: action, evidence, composerText });
  closeChatConnectorSurface(true);
  chatScrollPinned = true;
  chatForceScrollBottom = true;
  saveChatHistoryState();
  render();
}

// --- Chat "Recurring / DCA" surface (reuses the Repeat Payments form) ----------
