function handleWorkspaceTabEntry(tab: ActiveTab, previous: ActiveTab): void {
  resetNativeAppTabScroll(tab, previous);
  if (tab === 'inbox') {
    void reconcilePendingTransactions({ trigger: 'tab-entry' });
  }
  if (tab === 'completed' && previous !== 'completed' && isMobileAppViewport() && !state.busy) {
    void refreshWorkspaceData({ toast: false });
  }
  if (tab === 'labs' && previous !== 'labs' && state.artifactView === 'signed' && isMobileAppViewport() && !state.busy) {
    void refreshLabArtifactsData({ toast: false });
  }
}

function resetNativeAppTabScroll(tab: ActiveTab, previous: ActiveTab): void {
  // The Chat tab OWNS its own scroll: applyChatAutoscrollAfterRender() snaps the transcript to the
  // BOTTOM. A competing post-render outer scroll-to-TOP here (now + across the next 2 rAF frames,
  // resetNativeAppPanelScroll) races that inner snap frame-by-frame — the visible entry fight. The
  // pre-render outer reset (see the [data-tab] handlers, before the chat DOM exists) already lands
  // the surface at the top, so chat needs no post-render outer reset. Do NOT extend this to touch
  // [data-chat-scroll].
  if (tab === 'chat') return;
  if (!shouldResetNativeAppTabScroll(tab, previous)) return;
  resetNativeAppPanelScroll(tab);
}

function shouldResetNativeAppTabScroll(tab: ActiveTab, _previous: ActiveTab): boolean {
  return Boolean(tab) && shouldResetNativeAppSurfaceScroll();
}

function shouldResetNativeAppSurfaceScroll(): boolean {
  return currentRoute() === '/app' && isNativeAppShellSurface();
}

function resetNativeAppPanelScroll(expectedTab: ActiveTab = state.activeTab): void {
  if (!shouldResetNativeAppSurfaceScroll()) return;
  resetNativeAppScrollToTop();
  const resetIfStillActive = () => {
    if (currentRoute() !== '/app' || !isNativeAppShellSurface() || state.activeTab !== expectedTab) return;
    resetNativeAppScrollToTop();
  };
  window.requestAnimationFrame(() => {
    resetIfStillActive();
    window.requestAnimationFrame(resetIfStillActive);
  });
}

let agenticLoginAutoRefreshAttached = false;
function wireAgenticLoginAutoRefresh(): void {
  if (agenticLoginAutoRefreshAttached) return;
  agenticLoginAutoRefreshAttached = true;
  let lastSeen = state.address ?? '';
  // Poll once per render cycle (already happens via bind() → tick) BUT also
  // poll while the page is open without user activity. requestAnimationFrame
  // gives us cheap, frame-aligned wake-ups that pause when the tab is hidden.
  const tick = () => {
    if (agenticLoginRouteActive()) {
      const current = state.address ?? '';
      if (current !== lastSeen) {
        lastSeen = current;
        render();
      }
    } else {
      lastSeen = state.address ?? '';
    }
    window.requestAnimationFrame(tick);
  };
  window.requestAnimationFrame(tick);
}

function agenticLoginRouteActive(): boolean {
  const path = normalizePathname(window.location.pathname);
  return path === '/agentic-login' || path === '/sign-in' || path === '/delete-storage';
}

type AgenticLoginStatusSetter = (text: string, ok?: boolean) => void;

function cliIntentUsesFocusedWalletProof(): boolean {
  return cliView?.intent === 'sign-in' || cliView?.intent === 'delete-storage';
}

function cliFocusedSigningCommandLabel(): string {
  return cliView?.intent === 'delete-storage' ? '/delete-storage' : '/sign-in';
}

function agenticLoginSigningCopy(): {
  title: string;
  prompt: string;
  successMessage: string;
  doneStatus: string;
  failurePrefix: string;
} {
  if (cliView?.intent === 'delete-storage') {
    return {
      title: 'Delete Agentic Cloud workspace',
      prompt: 'Approve this cloud workspace deletion proof in your wallet. No transaction will be submitted.',
      successMessage: 'Sending deletion proof back to CLI.',
      doneStatus: 'Deletion approved. Return to the terminal.',
      failurePrefix: 'Deletion failed',
    };
  }
  return {
    title: 'Agentic CLI login',
    prompt: 'Approve this CLI login proof in your wallet. No transaction will be submitted.',
    successMessage: 'Sending result back to CLI.',
    doneStatus: 'Signed in. Return to the terminal.',
    failurePrefix: 'Login failed',
  };
}

async function ensureAgenticLoginWalletReady(
  desiredWallet: string,
  setStatus: AgenticLoginStatusSetter,
): Promise<string> {
  if (!cliIntentUsesFocusedWalletProof()) {
    if (!state.address) {
      throw new Error(t('Connect a wallet first with /connect, then return here.'));
    }
    return state.address;
  }

  const requestedWallet = desiredWallet.trim();
  if (cliCloudSignInDirectSignerReady()) {
    if (requestedWallet && !sameWalletAddress(state.address, requestedWallet)) {
      throw new Error(`Connected wallet ${short(state.address)} does not match sign-in wallet ${short(requestedWallet)}.`);
    }
    return state.address;
  }

  if (!isBrowserWalletSurface()) {
    if (!state.address) {
      throw new Error(t('Connect a wallet first with /connect, then return here.'));
    }
    return state.address;
  }

  const preferredWalletName = state.selectedWalletName;
  const preferredSession = state.browserWalletSession;
  if (preferredWalletName || preferredSession) {
    setStatus('Restoring wallet session...');
    await restoreBrowserWalletSession();
    if (cliCloudSignInDirectSignerReady()) {
      if (requestedWallet && !sameWalletAddress(state.address, requestedWallet)) {
        throw new Error(`Connected wallet ${short(state.address)} does not match sign-in wallet ${short(requestedWallet)}.`);
      }
      return state.address;
    }
  }

  setStatus('Opening wallet connection...');
  return connectCliSignInBrowserWallet(requestedWallet, preferredWalletName, preferredSession);
}

async function connectCliSignInBrowserWallet(
  desiredWallet: string,
  preferredWalletName: string,
  preferredSession: BrowserWalletSession | undefined,
): Promise<string> {
  state.wallets = visibleBrowserWallets(listAvailableWallets());
  const preferred =
    browserWalletRestoreName(state.wallets, preferredSession, state.cluster) ||
    reconcileBrowserWalletSelection(state.wallets, preferredWalletName) ||
    reconcileBrowserWalletSelection(state.wallets, state.selectedWalletName) ||
    (state.wallets.length === 1 ? state.wallets[0]!.name : '');
  if (!preferred) {
    throw new Error(`Choose a browser wallet with /connect first, then run ${cliFocusedSigningCommandLabel()} again.`);
  }

  state.selectedWalletName = preferred;
  state.browserWalletPickerOpen = false;
  const selected = selectedWallet();
  const backend = new WalletStandardWebBackend({
    wallet: selected,
    cluster: state.cluster,
    rpcUrl: activeRpcUrl(),
  });
  const address = await backend.connect();
  if (desiredWallet && !sameWalletAddress(address, desiredWallet)) {
    throw new Error(`Connected wallet ${short(address)} does not match sign-in wallet ${short(desiredWallet)}.`);
  }

  walletBackend = backend;
  client = new SolanaSigningClient({ backend });
  state.address = address;
  state.capabilities = await client.capabilities();
  state.selectedWalletName = selected.name;
  state.selectedWalletLogoId = walletProviderLogoIdForName(selected.name);
  state.selectedWalletIcon = selected.icon;
  state.transactionStatus = `Wallet connected on ${state.cluster}.`;
  state.steps.connect = 'done';
  const walletBrandId = browserWalletBrandIdForName(selected.name);
  const browserWalletPath = browserWalletPathForCurrentSurface();
  state.browserWalletSession = createBrowserWalletSession(selected.name, state.cluster, preferredSession?.connectedAt, {
    address,
    walletBrandId,
    path: browserWalletPath,
  });
  rememberWalletPathSession({
    path: browserWalletPath,
    address,
    walletName: selected.name,
    walletBrandId,
    connectedAt: preferredSession?.connectedAt,
  });
  if (state.bridgeToken && isTrustedBridgeUrl(state.bridgeUrl)) {
    await connectBridgeHost().catch((err) => {
      console.info('[cli-sign-in] bridge host sync skipped.', err);
    });
  }
  savePersistedState();
  return address;
}

async function completeAgenticLogin(): Promise<void> {
  const url = new URL(window.location.href);
  const nonce = url.searchParams.get('nonce') ?? '';
  const message = url.searchParams.get('message') ?? '';
  const callback = url.searchParams.get('callback') ?? '';
  const stateParam = url.searchParams.get('state') ?? '';
  const desiredWallet = url.searchParams.get('walletAddress') ?? '';
  const statusEl = document.getElementById('agenticLoginStatus');
  const setStatus = (text: string, ok = true) => {
    if (statusEl) {
      statusEl.textContent = text;
      statusEl.style.color = ok ? 'inherit' : '#c33';
    }
  };
  if (!nonce || !message || !callback) {
    setStatus('Missing nonce/message/callback. Re-run the original CLI command.', false);
    return;
  }
  try {
    const walletAddress = await ensureAgenticLoginWalletReady(desiredWallet, setStatus);
    const signingCopy = agenticLoginSigningCopy();
    setStatus('Requesting wallet signature...');
    // signWalletProofMessage handles the wallet quirks (signMessage vs memo-tx
    // fallback for Phantom/Solflare/Seed Vault on Android, base64 encoding, etc.)
    // so we reuse it instead of calling signMessage directly.
    const result = await signWalletProofMessageWithToast(message, signingCopy.title, state.cluster, {
      message: signingCopy.prompt,
      successMessage: signingCopy.successMessage,
    });
    setStatus('Sending result back to CLI…');
    const callbackUrl = new URL(callback);
    const response = await fetch(callbackUrl.toString(), {
      method: 'POST',
      mode: 'cors',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({
        signature: result.signature,
        walletAddress,
        state: stateParam,
        // Canonical server field names (parseVerifyWalletRequest +
        // parseAgentProfileRequest both read proofEncoding/proofTxBase64).
        // signWalletProofMessage returns base58 for utf8-message signatures;
        // memo-tx fallback also returns base58 today (see MwaController.kt).
        proofEncoding: result.proofEncoding,
        signatureEncoding: result.signatureEncoding,
        ...(result.proofTxBase64 ? { proofTxBase64: result.proofTxBase64 } : {}),
      }),
    });
    if (!response.ok) {
      throw new Error(`Callback returned HTTP ${response.status}.`);
    }
    if (cliView?.intent === 'delete-storage') {
      setStatus('Clearing browser storage...');
      await wipeLocalAppStorage();
    }
    setStatus(signingCopy.doneStatus);
  } catch (err) {
    const signingCopy = agenticLoginSigningCopy();
    setStatus(`${signingCopy.failurePrefix}: ${err instanceof Error ? err.message : String(err)}`, false);
    try {
      await fetch(callback, {
        method: 'POST',
        mode: 'cors',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({
          state: stateParam,
          error: err instanceof Error ? err.message : String(err),
        }),
      });
    } catch {
      // ignore secondary failure
    }
  }
}

function restoreGuidedDemoScenarioAnchor(scenarioId: string, previousTop: number): void {
  const nextButton = Array.from(document.querySelectorAll<HTMLButtonElement>('[data-demo-scenario]'))
    .find((candidate) => candidate.dataset.demoScenario === scenarioId);
  if (!nextButton) return;
  const nextTop = nextButton.getBoundingClientRect().top;
  const delta = nextTop - previousTop;
  if (Math.abs(delta) > 0.5) {
    window.scrollBy({ top: delta, behavior: 'auto' });
  }
  nextButton.focus({ preventScroll: true });
}

function bindRouteLinks(): void {
  for (const link of document.querySelectorAll<HTMLAnchorElement>('a[href]')) {
    bindOnce(link, 'click', (event) => {
      if (
        event.defaultPrevented ||
        event.button !== 0 ||
        event.metaKey ||
        event.ctrlKey ||
        event.shiftKey ||
        event.altKey
      ) {
        return;
      }

      const url = new URL(link.href);
      if (url.origin !== window.location.origin) return;

      const route = normalizePathname(url.pathname);
      if (!isAppRoute(route)) return;

      event.preventDefault();
      trackNavClick(route, navAreaForLink(link));
      if (route === '/mwa-test' && SHOW_ANDROID_EXAMPLE_TAB && agenticAndroidBridge()?.openMwaExample) {
        openAndroidMwaTest();
        return;
      }
      navigateTo(route);
    });
  }
}

function bindExternalLinks(): void {
  if (!nativeExternalLinkOpenerAvailable()) return;
  for (const link of document.querySelectorAll<HTMLAnchorElement>('a[href]')) {
    const href = link.dataset.externalUrl ?? link.getAttribute('href') ?? '';
    if (!shouldInterceptExternalLink(href, window.location.href)) continue;
    bindOnce(link, 'click', (event) => {
      if (
        event.defaultPrevented ||
        event.button !== 0 ||
        event.metaKey ||
        event.ctrlKey ||
        event.shiftKey ||
        event.altKey
      ) {
        return;
      }
      event.preventDefault();
      void openExternalLink(link.dataset.externalUrl ?? link.href);
    });
  }
}

function nativeExternalLinkOpenerAvailable(): boolean {
  return state.tauriNativeEnvironment.isTauriNative || state.androidNativeEnvironment.isAndroidNative;
}

async function openExternalLink(url: string): Promise<void> {
  const result = await openExternalUrlForSurface(url, {
    isTauriNative: state.tauriNativeEnvironment.isTauriNative,
    isAndroidNative: state.androidNativeEnvironment.isAndroidNative,
    tauriOpenExternalUrl: tauriNativeOpenExternalUrl,
    androidOpenExternalUrl: (target) => Boolean(agenticAndroidBridge()?.openExternal?.(target)),
  });
  if (!result.ok) {
    pushToast('error', t('Could not open link'), result.error ?? t('The native app could not open that URL.'));
    render();
  }
}

function navAreaForLink(link: HTMLAnchorElement): string {
  if (link.closest('.homepage-nav')) return 'header';
  if (link.closest('.homepage-footer')) return 'footer';
  if (link.closest('.hero-command-area')) return 'hero';
  if (link.closest('.homepage-cta-actions')) return 'homepage_cta';
  if (link.closest('.browser-app-actions')) return 'workspace_cta';
  if (link.closest('.command-deck')) return 'runtime_deck';
  return 'internal_link';
}

function trackedCliCommandKind(value: string): string | null {
  if (value === NPM_GLOBAL_INSTALL_COMMAND) return 'npm_global_install';
  if (value === NPM_EXEC_COMMAND) return 'npm_exec_app';
  if (value === INSTALLED_APP_COMMAND) return 'installed_app';
  return null;
}

function walletConnectSurface(): string {
  if (state.androidNativeEnvironment.isAndroidNative) return 'android_native';
  if (state.iosNativeEnvironment.isIosNative) return 'ios_native';
  if (state.tauriNativeEnvironment.isTauriNative) return 'tauri_native';
  return 'wallet_standard';
}

// The "Lend ▾" action dropdown(s). Custom dropdown so EVERY option click fires (incl. the shown one).
function bindActionDropdowns(): void {
  for (const picker of document.querySelectorAll<HTMLElement>('[data-action-picker]')) {
    const trigger = picker.querySelector<HTMLButtonElement>('.action-picker-trigger');
    const menu = picker.querySelector<HTMLElement>('.action-picker-menu');
    const options = [...picker.querySelectorAll<HTMLButtonElement>('[data-action-option]')];
    if (!trigger || !menu || options.length === 0) continue;

    const closeMenu = (returnFocus: boolean): void => {
      picker.classList.remove('open');
      trigger.setAttribute('aria-expanded', 'false');
      menu.hidden = true;
      actionPickerController?.abort();
      actionPickerController = null;
      if (returnFocus) trigger.focus({ preventScroll: true });
    };
    const openMenu = (): void => {
      if (trigger.disabled) return;
      actionPickerController?.abort();
      picker.classList.add('open');
      trigger.setAttribute('aria-expanded', 'true');
      menu.hidden = false;
      positionTemplatePickerMenu(trigger, menu);
      window.requestAnimationFrame(() => positionTemplatePickerMenu(trigger, menu));
      actionPickerController = new AbortController();
      const { signal } = actionPickerController;
      window.addEventListener('pointerdown', (event) => {
        if (event.target instanceof Node && picker.contains(event.target)) return;
        closeMenu(false);
      }, { signal });
      window.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') { event.preventDefault(); closeMenu(true); }
      }, { signal });
      window.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
      window.visualViewport?.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
    };

    bindOnce(trigger, 'click', (event) => {
      event.stopPropagation();
      if (menu.hidden) openMenu();
      else closeMenu(false);
    });
    for (const option of options) {
      bindOnce(option, 'click', () => {
        const category = option.dataset.actionOption as ActionCategory | undefined;
        if (!category) return;
        closeMenu(false);
        if (option.dataset.actionScope === 'repeat') selectRecurringAction(category);
        else selectCreateAction(category);
      });
    }
  }
}

// Native compact slippage popover. Reuses the action-picker open/close mechanics (click-outside,
// Escape, reposition on resize) but — unlike the action picker — does NOT close on inner clicks:
// the popover holds the Auto/Custom toggle + % input, which the user interacts with while it stays
// open. Those inner controls keep their existing global [data-template-slippage-*] handlers.
function bindSlippagePickers(): void {
  for (const picker of document.querySelectorAll<HTMLElement>('[data-slippage-picker]')) {
    const trigger = picker.querySelector<HTMLButtonElement>('.slippage-chip-trigger');
    const menu = picker.querySelector<HTMLElement>('.slippage-popover-menu');
    if (!trigger || !menu) continue;
    const fieldId = picker.dataset.slippagePicker ?? '';

    const closeMenu = (returnFocus: boolean): void => {
      picker.classList.remove('open');
      trigger.setAttribute('aria-expanded', 'false');
      menu.hidden = true;
      slippagePickerController?.abort();
      slippagePickerController = null;
      if (returnFocus) trigger.focus({ preventScroll: true });
    };
    const openMenu = (focusInput: boolean): void => {
      if (trigger.disabled) return;
      slippagePickerController?.abort();
      picker.classList.add('open');
      trigger.setAttribute('aria-expanded', 'true');
      menu.hidden = false;
      positionTemplatePickerMenu(trigger, menu);
      window.requestAnimationFrame(() => {
        positionTemplatePickerMenu(trigger, menu);
        if (focusInput) {
          // Generic across surfaces: New Request uses data-template-slippage-field, Repeat uses
          // data-recurring-field — both render the editable % input inside .slippage-popover-body.
          menu.querySelector<HTMLInputElement>('.slippage-popover-body input:not([disabled])')?.focus({ preventScroll: true });
        }
      });
      slippagePickerController = new AbortController();
      const { signal } = slippagePickerController;
      window.addEventListener('pointerdown', (event) => {
        if (event.target instanceof Node && picker.contains(event.target)) return;
        closeMenu(false);
      }, { signal });
      window.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') { event.preventDefault(); closeMenu(true); }
      }, { signal });
      window.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
      window.visualViewport?.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
    };

    bindOnce(trigger, 'click', (event) => {
      event.stopPropagation();
      if (menu.hidden) openMenu(false);
      else closeMenu(false);
    });

    // Re-open after the Auto/Custom toggle's render() rebuilt this DOM. Focus the % input
    // when we landed in Custom mode (the editable input is present in .slippage-popover-body).
    if (slippageReopenOnRender === fieldId) {
      slippageReopenOnRender = null;
      openMenu(Boolean(menu.querySelector('.slippage-popover-body input:not([disabled])')));
    }
  }
  // Drop a stale flag whose picker is no longer on the page (e.g. tab switched away).
  if (slippageReopenOnRender && !document.querySelector(`[data-slippage-picker="${cssEscape(slippageReopenOnRender)}"]`)) {
    slippageReopenOnRender = null;
  }
}

function bindTemplatePicker(): void {
  const picker = document.querySelector<HTMLElement>('[data-template-picker]');
  if (!picker) return;
  const trigger = picker.querySelector<HTMLButtonElement>('#templatePickerButton');
  const menu = picker.querySelector<HTMLElement>('#templatePickerMenu');
  const options = [...picker.querySelectorAll<HTMLButtonElement>('[data-template-option]')];
  if (!trigger || !menu || options.length === 0) return;

  const openPicker = (focusOption: 'selected' | 'first' | 'last' | false = false): void => {
    if (trigger.disabled) return;
    closeTemplatePickerInteractions();
    picker.classList.add('open');
    trigger.setAttribute('aria-expanded', 'true');
    menu.hidden = false;
    positionTemplatePickerMenu(trigger, menu);
    window.requestAnimationFrame(() => positionTemplatePickerMenu(trigger, menu));

    const selectedOption = options.find((option) => option.dataset.templateOption === state.selectedTemplateId) ?? options[0]!;
    const activeOption = focusOption === 'first'
      ? options[0]!
      : focusOption === 'last'
        ? options[options.length - 1]!
        : selectedOption;
    setActiveTemplateOption(options, activeOption, Boolean(focusOption));

    templatePickerController = new AbortController();
    const { signal } = templatePickerController;
    window.addEventListener('pointerdown', (event) => {
      if (event.target instanceof Node && picker.contains(event.target)) return;
      closePicker(false);
    }, { signal });
    window.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        closePicker(true);
      }
    }, { signal });
    window.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
    window.visualViewport?.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
  };

  const closePicker = (returnFocus: boolean): void => {
    picker.classList.remove('open');
    trigger.setAttribute('aria-expanded', 'false');
    menu.hidden = true;
    closeTemplatePickerInteractions();
    if (returnFocus) {
      trigger.focus({ preventScroll: true });
    }
  };

  bindOnce(trigger, 'click', (event) => {
    event.stopPropagation();
    if (menu.hidden) {
      openPicker(false);
    } else {
      closePicker(false);
    }
  });

  bindOnce(trigger, 'keydown', (event) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      openPicker('selected');
      focusAdjacentTemplateOption(options, 1);
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      openPicker('selected');
      focusAdjacentTemplateOption(options, -1);
    }
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      openPicker('selected');
    }
  });

  bindOnce(menu, 'keydown', (event) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      focusAdjacentTemplateOption(options, 1);
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      focusAdjacentTemplateOption(options, -1);
    }
    if (event.key === 'Home') {
      event.preventDefault();
      setActiveTemplateOption(options, options[0]!, true);
    }
    if (event.key === 'End') {
      event.preventDefault();
      setActiveTemplateOption(options, options[options.length - 1]!, true);
    }
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      const activeOption = document.activeElement instanceof HTMLButtonElement
        ? document.activeElement
        : options.find((option) => option.classList.contains('active')) ?? options[0]!;
      const templateId = activeOption.dataset.templateOption;
      if (!templateId) return;
      if (!selectAgentTemplate(templateId)) {
        closePicker(true);
      }
    }
  });

  for (const option of options) {
    bindOnce(option, 'click', () => {
      const templateId = option.dataset.templateOption;
      if (!templateId) return;
      if (!selectAgentTemplate(templateId)) {
        closePicker(true);
      }
    });
    bindOnce(option, 'pointermove', () => setActiveTemplateOption(options, option, false));
  }
}

function closeTemplatePickerInteractions(): void {
  templatePickerController?.abort();
  templatePickerController = null;
}

