function closeOpenSelectPickers(except?: HTMLElement): void {
  for (const openPicker of document.querySelectorAll<HTMLElement>('[data-select-picker].open')) {
    if (openPicker === except) continue;
    openPicker.classList.remove('open');
    openPicker.style.removeProperty('--select-picker-z-index');
    openPicker.style.removeProperty('--select-picker-menu-z-index');
    openPicker.querySelector<HTMLElement>('.select-picker-trigger')?.setAttribute('aria-expanded', 'false');
    const openMenu = openPicker.querySelector<HTMLElement>('.select-picker-menu');
    if (openMenu) openMenu.hidden = true;
  }
}

function bindSelectPickers(): void {
  for (const picker of document.querySelectorAll<HTMLElement>('[data-select-picker]')) {
    const shell = picker.closest<HTMLElement>('.select-picker-shell');
    const select = shell?.querySelector<HTMLSelectElement>('select[data-select-picker-native]');
    const trigger = picker.querySelector<HTMLButtonElement>('.select-picker-trigger');
    const menu = picker.querySelector<HTMLElement>('.select-picker-menu');
    const options = [...picker.querySelectorAll<HTMLButtonElement>('[data-select-picker-option]')];
    const enabledOptions = options.filter((option) => !option.disabled);
    if (!select || !trigger || !menu || enabledOptions.length === 0) continue;

    const openPicker = (focusOption: 'selected' | 'first' | 'last' | false = false): void => {
      if (trigger.disabled) return;
      closeOpenSelectPickers(picker);
      closeSelectPickerInteractions();
      const openOrder = ++selectPickerOpenOrder;
      picker.style.setProperty('--select-picker-z-index', String(220 + openOrder));
      picker.style.setProperty('--select-picker-menu-z-index', String(240 + openOrder));
      picker.classList.add('open');
      trigger.setAttribute('aria-expanded', 'true');
      menu.hidden = false;
      positionTemplatePickerMenu(trigger, menu);
      window.requestAnimationFrame(() => {
        positionTemplatePickerMenu(trigger, menu);
        scrollForcedDownSelectPickerMenuIntoView(trigger, menu);
      });

      const selectedOption = enabledOptions.find((option) => option.dataset.selectPickerOption === select.value) ?? enabledOptions[0]!;
      const activeOption = focusOption === 'first'
        ? enabledOptions[0]!
        : focusOption === 'last'
          ? enabledOptions[enabledOptions.length - 1]!
          : selectedOption;
      setActiveTemplateOption(enabledOptions, activeOption, Boolean(focusOption));

      selectPickerController = new AbortController();
      const { signal } = selectPickerController;
      window.addEventListener('pointerdown', (event) => {
        if (event.target instanceof Node && picker.contains(event.target)) return;
        closePicker(false);
      }, { signal });
      window.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
          event.preventDefault();
          closePicker(true);
        }
      }, { signal });
      window.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
      window.visualViewport?.addEventListener('resize', () => positionTemplatePickerMenu(trigger, menu), { signal });
    };

    const closePicker = (returnFocus: boolean): void => {
      picker.classList.remove('open');
      picker.style.removeProperty('--select-picker-z-index');
      picker.style.removeProperty('--select-picker-menu-z-index');
      trigger.setAttribute('aria-expanded', 'false');
      menu.hidden = true;
      closeSelectPickerInteractions();
      if (returnFocus) {
        trigger.focus({ preventScroll: true });
      }
    };

    const chooseOption = (option: HTMLButtonElement): void => {
      const value = option.dataset.selectPickerOption;
      if (value === undefined || option.disabled) return;
      const currentValue = select.dataset.selectPickerCurrentValue ?? select.value;
      const changed = currentValue !== value;
      select.value = value;
      select.dataset.selectPickerCurrentValue = value;
      updateSelectPickerView(picker, value);
      closePicker(false);
      if (changed) {
        select.dispatchEvent(new Event('input', { bubbles: true }));
        select.dispatchEvent(new Event('change', { bubbles: true }));
      } else {
        trigger.focus({ preventScroll: true });
      }
    };

    const syncWalletPickerState = (next: boolean): void => {
      if (select.id === 'walletSelect' || select.id === BROWSER_EXTENSION_WALLET_SELECT_ID) {
        state.browserWalletPickerOpen = next;
      }
    };

    bindOnce(trigger, 'click', (event) => {
      event.stopPropagation();
      if (menu.hidden) {
        openPicker(false);
        syncWalletPickerState(true);
      } else {
        closePicker(false);
        syncWalletPickerState(false);
      }
    });

    bindOnce(trigger, 'keydown', (event) => {
      if (event.key === 'ArrowDown') {
        event.preventDefault();
        openPicker('selected');
        syncWalletPickerState(true);
        focusAdjacentTemplateOption(enabledOptions, 1);
      }
      if (event.key === 'ArrowUp') {
        event.preventDefault();
        openPicker('selected');
        syncWalletPickerState(true);
        focusAdjacentTemplateOption(enabledOptions, -1);
      }
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        openPicker('selected');
      }
    });

    bindOnce(menu, 'keydown', (event) => {
      if (event.key === 'ArrowDown') {
        event.preventDefault();
        focusAdjacentTemplateOption(enabledOptions, 1);
      }
      if (event.key === 'ArrowUp') {
        event.preventDefault();
        focusAdjacentTemplateOption(enabledOptions, -1);
      }
      if (event.key === 'Home') {
        event.preventDefault();
        setActiveTemplateOption(enabledOptions, enabledOptions[0]!, true);
      }
      if (event.key === 'End') {
        event.preventDefault();
        setActiveTemplateOption(enabledOptions, enabledOptions[enabledOptions.length - 1]!, true);
      }
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        const activeOption = document.activeElement instanceof HTMLButtonElement
          ? document.activeElement
          : enabledOptions.find((option) => option.classList.contains('active')) ?? enabledOptions[0]!;
        chooseOption(activeOption);
      }
    });

    for (const option of enabledOptions) {
      bindOnce(option, 'click', () => chooseOption(option));
      bindOnce(option, 'pointermove', () => setActiveTemplateOption(enabledOptions, option, false));
    }
  }
}

function closeSelectPickerInteractions(): void {
  selectPickerController?.abort();
  selectPickerController = null;
}

interface VirtualKeyboardLike extends EventTarget {
  boundingRect?: DOMRectReadOnly;
}

function virtualKeyboard(): VirtualKeyboardLike | undefined {
  return (navigator as Navigator & { virtualKeyboard?: VirtualKeyboardLike }).virtualKeyboard;
}

function normalizeNativeKeyboardInsets(payload: unknown): { keyboardInset: number; visible: boolean } {
  let value = payload;
  if (typeof payload === 'string') {
    try {
      value = JSON.parse(payload) as unknown;
    } catch {
      value = {};
    }
  }
  const record = isJsonObject(value) ? value : {};
  const rawInset = Number(record.keyboardInset ?? 0);
  const keyboardInset = Number.isFinite(rawInset) ? Math.max(0, Math.floor(rawInset)) : 0;
  const visible = typeof record.visible === 'boolean' ? record.visible && keyboardInset > 0 : keyboardInset > 0;
  return {
    keyboardInset: visible ? keyboardInset : 0,
    visible,
  };
}

function applyNativeKeyboardInsets(payload: unknown): void {
  const next = normalizeNativeKeyboardInsets(payload);
  if (nativeKeyboardInset === next.keyboardInset && nativeKeyboardVisible === next.visible) return;
  nativeKeyboardInset = next.keyboardInset;
  nativeKeyboardVisible = next.visible;
  syncMobileRailSheetViewport();
  syncChatKeyboardInset();
}

function applyVirtualKeyboardInsets(): void {
  const keyboard = virtualKeyboard();
  const rawInset = Number(keyboard?.boundingRect?.height ?? 0);
  const keyboardInset = Number.isFinite(rawInset) ? Math.max(0, Math.floor(rawInset)) : 0;
  const visible = keyboardInset > 0;
  if (virtualKeyboardInset === keyboardInset && virtualKeyboardVisible === visible) return;
  virtualKeyboardInset = visible ? keyboardInset : 0;
  virtualKeyboardVisible = visible;
  syncMobileRailSheetViewport();
  syncChatKeyboardInset();
}

function bindVirtualKeyboardInsets(): void {
  if (virtualKeyboardInsetsBound) return;
  const keyboard = virtualKeyboard();
  if (!keyboard) return;
  virtualKeyboardInsetsBound = true;
  try {
    keyboard.addEventListener('geometrychange', applyVirtualKeyboardInsets);
  } catch {
    // Older WebViews may expose a partial navigator.virtualKeyboard object.
  }
  applyVirtualKeyboardInsets();
}

function bindNativeKeyboardInsets(): void {
  if (nativeKeyboardInsetsBound) return;
  nativeKeyboardInsetsBound = true;
  bindVirtualKeyboardInsets();
  if (IS_ANDROID_APP) {
    (globalThis as typeof globalThis & {
      __agenticAndroidKeyboardInsetBridge?: { update?: (payload: unknown) => void };
    }).__agenticAndroidKeyboardInsetBridge = {
      update: applyNativeKeyboardInsets,
    };
    try {
      const current = agenticAndroidBridge()?.keyboardInsets?.();
      if (current) applyNativeKeyboardInsets(current);
    } catch {
      // Older APKs do not expose keyboardInsets; visualViewport remains the fallback.
    }
  }
  if (IS_IOS_APP) {
    const bridge = agenticIosSystemBridge();
    try {
      void Promise.resolve(bridge?.keyboardMetrics?.())
        .then((payload) => {
          if (payload) applyNativeKeyboardInsets(payload);
        })
        .catch(() => undefined);
    } catch {
      // Older iOS binaries do not expose keyboardMetrics; visualViewport remains the fallback.
    }
    try {
      void Promise.resolve(bridge?.addListener?.('keyboardInsetChange', applyNativeKeyboardInsets))
        .then(() => undefined)
        .catch(() => undefined);
    } catch {
      // Older iOS binaries do not expose keyboard inset events.
    }
  }
}

function focusedMobileRailTextControl(): HTMLInputElement | HTMLTextAreaElement | null {
  const root = document.querySelector<HTMLElement>('[data-mobile-rail-sheet-root]');
  const active = document.activeElement;
  if (
    !root ||
    !(active instanceof HTMLInputElement || active instanceof HTMLTextAreaElement) ||
    !root.contains(active) ||
    active.disabled ||
    active.readOnly
  ) {
    return null;
  }
  return active;
}

function currentMobileRailVisualKeyboardInset(): number {
  const viewport = window.visualViewport;
  return Math.max(
    0,
    Math.floor(
      window.innerHeight -
        Math.floor(viewport?.height ?? window.innerHeight) -
        Math.max(0, Math.floor(viewport?.offsetTop ?? 0)),
    ),
  );
}

function recordMobileRailStableViewportHeight(): void {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  if (!(IS_ANDROID_APP || IS_IOS_APP) || !isMobileAppViewport()) return;
  const innerHeight = Math.floor(window.innerHeight);
  if (!Number.isFinite(innerHeight) || innerHeight <= 0) return;
  if (mobileRailStableInnerHeight <= 0) {
    mobileRailStableInnerHeight = innerHeight;
  }
  const hasKeyboardMetric =
    nativeKeyboardVisible ||
    virtualKeyboardVisible ||
    currentMobileRailVisualKeyboardInset() > 0;
  if (!focusedMobileRailTextControl() && !hasKeyboardMetric) {
    mobileRailStableInnerHeight = innerHeight;
  }
}

function mobileRailFocusedControlFallbackInset(): number {
  if (!(IS_ANDROID_APP || IS_IOS_APP) || !isMobileAppViewport()) return 0;
  if (!focusedMobileRailTextControl()) return 0;
  // Once a real keyboard metric has reported (or the bridge window elapsed), stop inferring
  // an inset purely from focus — otherwise dismissing the keyboard while the field keeps focus
  // would leave the sheet stuck up, since a control is still focused.
  if (mobileRailKeyboardMetricSeenVisible) return 0;
  if (Date.now() - lastMobileRailFocusAt > MOBILE_RAIL_FOCUS_FALLBACK_WINDOW_MS) return 0;
  return inferMobileRailFocusedKeyboardInset(window.innerHeight);
}

function syncMobileRailSheetViewport(): void {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  const sheet = document.querySelector<HTMLElement>('[data-mobile-rail-sheet-root]');
  if (!sheet) return;
  recordMobileRailStableViewportHeight();
  const viewport = window.visualViewport;
  const measuredKeyboardInset = Math.max(nativeKeyboardInset, virtualKeyboardInset);
  const measuredKeyboardVisible = nativeKeyboardVisible || virtualKeyboardVisible;
  const viewportHeight = viewport?.height;
  const viewportOffsetTop = viewport?.offsetTop;
  const visualKeyboardInset = currentMobileRailVisualKeyboardInset();
  const focusedControlFallbackInset = mobileRailFocusedControlFallbackInset();
  const { vvh, keyboardInset, keyboardOpen, source } = computeMobileRailViewportVars({
    viewportHeight,
    viewportOffsetTop,
    innerHeight: window.innerHeight,
    baselineInnerHeight: mobileRailStableInnerHeight || window.innerHeight,
    nativeKeyboardInset: measuredKeyboardInset,
    nativeKeyboardVisible: measuredKeyboardVisible,
    focusedControlFallbackInset,
    // On iOS the native keyboardInsetChange bridge is authoritative; the phantom visual-viewport
    // delta must not drive the sheet inset either (same iOS jitter family, --mobile-rail-* vars).
    suppressVisualViewportKeyboard: IS_IOS_APP,
  });
  // A real keyboard metric won this measurement → the focus-only fallback is no longer needed
  // and must stop firing so a later dismiss (focus retained) can settle the sheet back down.
  if (source === 'native' || source === 'visual-viewport' || source === 'layout-viewport-resize') {
    mobileRailKeyboardMetricSeenVisible = true;
  }
  sheet.style.setProperty('--mobile-rail-vvh', `${vvh}px`);
  sheet.style.setProperty('--mobile-rail-keyboard-inset', `${keyboardInset}px`);
  sheet.dataset.keyboardOpen = keyboardOpen ? 'true' : 'false';
  sheet.dataset.keyboardSource = source;
  lastMobileRailKeyboardInset = keyboardInset;
  lastMobileRailKeyboardMetricSource = source === 'native'
    ? nativeKeyboardVisible && nativeKeyboardInset > 0
      ? 'native'
      : virtualKeyboardVisible && virtualKeyboardInset > 0
        ? 'virtual-keyboard'
        : 'native'
    : source === 'visual-viewport' && visualKeyboardInset > 0
      ? 'visual-viewport'
      : source === 'layout-viewport-resize'
        ? 'layout-viewport-resize'
        : source === 'focused-control-fallback' && focusedControlFallbackInset > 0
          ? 'focused-control-fallback'
          : 'none';
}

const MOBILE_RAIL_FOCUS_VIEWPORT_SYNC_DELAYS_MS = [0, 80, 180, 320] as const;

function scheduleMobileRailViewportSyncs(): void {
  for (const delay of MOBILE_RAIL_FOCUS_VIEWPORT_SYNC_DELAYS_MS) {
    window.setTimeout(syncMobileRailSheetViewport, delay);
  }
}

// Keep the Chat composer above the on-screen keyboard. Reuses the same keyboard metrics as the
// mobile rail sheet and sets --chat-keyboard-inset: ~0 when the WebView resizes (interactive-widget,
// Android) and the keyboard height in overlay mode (iOS). The surface height subtracts
// max(dock, keyboard) in CSS.
//
// PRIMARY iOS JITTER FUSE (do not weaken — see chatRenderInvariants.test.ts):
//   1) The var is written to :root (document.documentElement), NOT the per-render .chat-surface
//      node. It inherits into the surface's calc(), so an idempotent-skipped write can never leave
//      a freshly-rendered surface node with a missing var — and the writer no longer needs to fire
//      after every render for correctness.
//   2) The write is IDEMPOTENT (shouldWriteChatKeyboardInset): an iOS visualViewport resize storm
//      that reports sub-2px jitter no longer re-writes the var → the surface height stops changing
//      → the sticky composer stops moving → no new viewport event → the feedback loop can't sustain.
//   3) resolveChatKeyboardInset forces 0 for the Android layout-viewport-resize branch and idle.
const CHAT_KEYBOARD_INSET_EPSILON_PX = 2;
let lastChatKeyboardInsetPx = -1; // -1 → first write always commits
function applyChatKeyboardInset(): void {
  if (typeof window === 'undefined' || typeof document === 'undefined') return;
  const root = document.documentElement;
  if (!root) return;
  recordMobileRailStableViewportHeight();
  const viewport = window.visualViewport;
  const vars = computeMobileRailViewportVars({
    viewportHeight: viewport?.height,
    viewportOffsetTop: viewport?.offsetTop,
    innerHeight: window.innerHeight,
    baselineInnerHeight: mobileRailStableInnerHeight || window.innerHeight,
    nativeKeyboardInset: Math.max(nativeKeyboardInset, virtualKeyboardInset),
    nativeKeyboardVisible: nativeKeyboardVisible || virtualKeyboardVisible,
    focusedControlFallbackInset: 0,
    // On iOS the native keyboardInsetChange bridge is authoritative; never let the phantom
    // visual-viewport delta write --chat-keyboard-inset (the iOS Chat jitter driver).
    suppressVisualViewportKeyboard: IS_IOS_APP,
  });
  const inset = resolveChatKeyboardInset(vars);
  if (!shouldWriteChatKeyboardInset(lastChatKeyboardInsetPx, inset, CHAT_KEYBOARD_INSET_EPSILON_PX)) return;
  lastChatKeyboardInsetPx = inset;
  root.style.setProperty('--chat-keyboard-inset', `${inset}px`);
}

// rAF-coalesced public entry for every caller (event listeners, focus-settle schedule, render
// paths, native/virtual keyboard bridges): collapse an event storm to one measure+write per frame
// so we never read-then-write layout mid-event.
let chatKeyboardInsetRaf = 0;
function syncChatKeyboardInset(): void {
  if (typeof window === 'undefined' || typeof window.requestAnimationFrame !== 'function') {
    applyChatKeyboardInset();
    return;
  }
  if (chatKeyboardInsetRaf) return;
  chatKeyboardInsetRaf = window.requestAnimationFrame(() => {
    chatKeyboardInsetRaf = 0;
    applyChatKeyboardInset();
  });
}

let chatKeyboardSyncTimers: number[] = [];
function scheduleChatKeyboardSyncs(): void {
  // Cancel any pending syncs first so rapid focus changes don't pile up overlapping
  // timers all re-measuring the same (settling) viewport.
  for (const id of chatKeyboardSyncTimers) window.clearTimeout(id);
  chatKeyboardSyncTimers = MOBILE_RAIL_FOCUS_VIEWPORT_SYNC_DELAYS_MS.map((delay) =>
    window.setTimeout(syncChatKeyboardInset, delay));
}

function blurFocusedMobileRailControl(): boolean {
  const target = focusedMobileRailTextControl();
  if (!target) return false;
  target.blur();
  scheduleMobileRailViewportSyncs();
  return true;
}

function scrollFocusedMobileRailControlIntoView(target: HTMLElement): void {
  // Skip programmatic focus restores (background re-renders): those pass preventScroll
  // deliberately and should not trigger an animated re-center.
  if (restoringMobileRailFocus) return;
  // Start a fresh focus->keyboard bridge: time-stamp it and re-arm the focus-only fallback
  // (it'll defer to the real metric the moment one arrives — see mobileRailFocusedControlFallbackInset).
  lastMobileRailFocusAt = Date.now();
  mobileRailKeyboardMetricSeenVisible = false;
  scheduleMobileRailViewportSyncs();
  // Backstop re-measure just after the bridge window: if no real metric ever appeared (or the
  // keyboard was dismissed while the field kept focus), the fallback has now expired so this
  // settles the sheet back down instead of leaving it raised.
  window.setTimeout(syncMobileRailSheetViewport, MOBILE_RAIL_FOCUS_FALLBACK_WINDOW_MS + 60);
  window.setTimeout(() => {
    syncMobileRailSheetViewport();
    try {
      target.scrollIntoView({ block: 'center', behavior: 'smooth' });
    } catch {
      target.scrollIntoView();
    }
  }, 320);
}

function bindMobileRailSheet(): void {
  bindNativeKeyboardInsets();
  recordMobileRailStableViewportHeight();
  const nestedInteractiveSelector = 'button, a, input, select, textarea, [data-mobile-rail-sheet-ignore]';
  const eventStartedOnNestedInteractive = (event: Event, trigger: HTMLElement): boolean => {
    const target = event.target;
    if (!(target instanceof Element) || target === trigger) return false;
    const interactive = target.closest(nestedInteractiveSelector);
    return Boolean(interactive && interactive !== trigger);
  };
  const openFromTrigger = (event: Event, trigger: HTMLElement) => {
    if (eventStartedOnNestedInteractive(event, trigger)) return;
    event.preventDefault();
    event.stopPropagation();
    const sheet = trigger.dataset.mobileRailSheet;
    if (!isMobileRailSheet(sheet)) return;
    if (shouldResetAiReviewSetupTabOnMobileRailOpen({
      currentSheet: state.activeMobileRailSheet,
      nextSheet: sheet,
    })) {
      state.aiReviewSetupTab = preferredAiReviewSetupTabForMobileRailOpen(sheet);
    }
    openMobileRailSheet(sheet);
  };
  for (const trigger of document.querySelectorAll<HTMLElement>('[data-mobile-rail-sheet]')) {
    bindOnce(trigger, 'click', (event) => {
      openFromTrigger(event, trigger);
    });
    if (trigger instanceof HTMLButtonElement) continue;
    bindOnce(trigger, 'keydown', (event) => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      if (eventStartedOnNestedInteractive(event, trigger)) return;
      event.preventDefault();
      openFromTrigger(event, trigger);
    });
  }

  const root = document.querySelector<HTMLElement>('[data-mobile-rail-sheet-root]');
  if (!root) return;
  mobileRailSheetController = new AbortController();
  const { signal } = mobileRailSheetController;
  root.addEventListener('pointerdown', (event) => {
    event.stopPropagation();
  }, { signal });
  root.addEventListener('click', (event) => {
    event.stopPropagation();
  }, { signal });
  syncMobileRailSheetViewport();
  window.visualViewport?.addEventListener('resize', syncMobileRailSheetViewport, { signal });
  window.visualViewport?.addEventListener('scroll', syncMobileRailSheetViewport, { signal });
  window.addEventListener('resize', syncMobileRailSheetViewport, { signal });
  // Delegated focusin (focus does not bubble, focusin does) so dynamically-mounted
  // controls — e.g. the Plan Connector pairing textarea injected after bind() — are
  // covered without re-running attachment after mount.
  root.addEventListener('focusin', (event) => {
    const target = event.target;
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      scrollFocusedMobileRailControlIntoView(target);
    }
  }, { signal });
  root.addEventListener('focusout', (event) => {
    const target = event.target;
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      window.setTimeout(syncMobileRailSheetViewport, 0);
      window.setTimeout(syncMobileRailSheetViewport, 120);
    }
  }, { signal });
  for (const closeControl of document.querySelectorAll<HTMLElement>('[data-mobile-rail-sheet-close]')) {
    closeControl.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (closeControl.classList.contains('mobile-rail-sheet-scrim') && blurFocusedMobileRailControl()) {
        return;
      }
      closeMobileRailSheet();
    }, { signal });
  }
  window.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    closeMobileRailSheet();
  }, { signal });
}

function closeMobileRailSheetInteractions(): void {
  mobileRailSheetController?.abort();
  mobileRailSheetController = null;
}

// Explicit toggle for the bottom-nav "More+" overflow menu. Replaces the native <details>
// toggle (unreliable in the Android WebView / iOS WKWebView). Re-bound on every render().
function bindMobileMoreMenu(): void {
  const trigger = document.querySelector<HTMLButtonElement>('[data-more-menu-trigger]');
  if (!trigger) {
    if (state.moreMenuOpen) state.moreMenuOpen = false;
    return;
  }
  bindOnce(trigger, 'click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    state.moreMenuOpen = !state.moreMenuOpen;
    render();
  });
  if (!state.moreMenuOpen) return;
  // Outside-tap dismiss. Bound only while open; torn down automatically on the next render()
  // because innerHTML is fully replaced (the listener removes itself on first outside tap).
  const onPointerDown = (event: PointerEvent): void => {
    const target = event.target;
    if (target instanceof Element && target.closest('[data-more-menu]')) return;
    // The LAST drop-up item (Sessions) sits at the scroll/clip edge just above the fixed dock, so a
    // tap on it can resolve to a node OUTSIDE [data-more-menu] — which would dismiss the menu before
    // the button's click fires (the "Sessions won't open" bug). Treat any pointer inside the menu's
    // bounding box as inside, so the item's click still navigates.
    const menu = document.querySelector('[data-more-menu] .workspace-bottom-more-menu');
    if (menu) {
      const rect = menu.getBoundingClientRect();
      if (
        event.clientX >= rect.left && event.clientX <= rect.right &&
        event.clientY >= rect.top && event.clientY <= rect.bottom
      ) {
        return;
      }
    }
    window.removeEventListener('pointerdown', onPointerDown, true);
    state.moreMenuOpen = false;
    render();
  };
  window.addEventListener('pointerdown', onPointerDown, true);
}

function mountPlanConnectorPairingPanel(): void {
  const container = document.querySelector<HTMLElement>('[data-plan-connector-pairing-panel]');
  if (!container) return;
  planConnectorPairingPanelCleanup = mountPhonePairingPanel(container, buildPhonePairingDeps({
    bridge: agenticAndroidBridge(),
    ...(IS_IOS_APP ? { asyncBridge: buildIosPairBridge() } : {}),
    readClipboardText,
    onPaired: (connector) => {
      void runEnablePairedBridge(connector);
    },
  }), {
    introText: IS_IOS_APP
      ? t('Point your iPhone at the QR displayed on your AI-connected computer. The computer must stay awake while planning.')
      : t('Point Android at the QR displayed on your AI-connected computer. The computer must stay awake while planning.'),
    scanLabel: t('Scan computer QR'),
    pasteLabel: t('Camera not working? Paste the pairing code from the computer page:'),
    pasteButtonLabel: t('Connect Plan Connector'),
    connectedText: t('Connected. AI now runs on your computer plan.'),
    invalidCodeText: t('That code is not valid. Copy the whole pairing code from the computer connector page.'),
  });
}

function closePlanConnectorPairingPanelInteractions(): void {
  try {
    planConnectorPairingPanelCleanup?.();
  } finally {
    planConnectorPairingPanelCleanup = null;
  }
}

function bindWalletBalanceOverlay(): void {
  const overlay = document.querySelector<HTMLElement>('#walletBalanceOverlay');
  if (!overlay || !state.walletBalance.overlayOpen) return;
  walletBalanceOverlayController = new AbortController();
  const { signal } = walletBalanceOverlayController;
  window.addEventListener('pointerdown', (event) => {
    const target = event.target;
    if (!(target instanceof Node)) return;
    if (overlay.contains(target)) return;
    if (target instanceof Element && target.closest('[data-wallet-balance-action]')) return;
    closeWalletBalanceOverlay();
  }, { signal, capture: true });
}

function closeWalletBalanceOverlayInteractions(): void {
  walletBalanceOverlayController?.abort();
  walletBalanceOverlayController = null;
}

function bindExpandNoteSheet(): void {
  for (const trigger of document.querySelectorAll<HTMLButtonElement>('[data-expand-note]')) {
    bindOnce(trigger, 'click', () => {
      const ref = expandNoteRefFromAttr(trigger.getAttribute('data-expand-note'));
      if (!ref) return;
      openExpandNoteSheet(ref);
    });
  }

  bindMobileExpandNoteSourceFields();

  const sheetRoot = document.querySelector<HTMLElement>('[data-expand-note-root]');
  if (!sheetRoot) return;

  for (const closeControl of document.querySelectorAll<HTMLElement>('[data-expand-note-close]')) {
    bindOnce(closeControl, 'click', () => closeExpandNoteSheet());
  }

  const textarea = document.querySelector<HTMLTextAreaElement>('[data-expand-note-input]');
  if (textarea) {
    bindOnce(textarea, 'input', () => {
      const ref = state.activeExpandNoteField;
      if (!ref) return;
      setExpandNoteValue(ref, textarea.value);
      syncExpandNoteSourceField(ref, textarea.value);
    });
  }

  const confirmBtn = document.querySelector<HTMLButtonElement>('[data-expand-note-confirm]');
  bindOnce(confirmBtn, 'click', () => {
    closeExpandNoteSheet();
  });

  syncExpandNoteComposerViewport();
  expandNoteViewportController = new AbortController();
  const viewportSignal = expandNoteViewportController.signal;
  window.visualViewport?.addEventListener('resize', syncExpandNoteComposerViewport, { signal: viewportSignal });
  window.visualViewport?.addEventListener('scroll', syncExpandNoteComposerViewport, { signal: viewportSignal });
  window.addEventListener('resize', syncExpandNoteComposerViewport, { signal: viewportSignal });

  expandNoteSheetController = new AbortController();
  const { signal } = expandNoteSheetController;
  window.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    closeExpandNoteSheet();
  }, { signal });
  window.addEventListener('popstate', () => {
    if (state.activeExpandNoteField) {
      closeExpandNoteSheet({ fromPopState: true });
    }
  }, { signal });
}

function closeExpandNoteSheetInteractions(): void {
  expandNoteSheetController?.abort();
  expandNoteSheetController = null;
  expandNoteViewportController?.abort();
  expandNoteViewportController = null;
}

function expandNoteRefForSourceField(source: HTMLTextAreaElement): ExpandNoteFieldRef | null {
  if (source.id === 'agentPrompt') return { kind: 'agent-prompt' };
  if (source.id === 'recurringNote') return { kind: 'recurring-note' };
  if (source.id === 'labInput') return { kind: 'lab-advanced', labId: state.activeLab };
  const fieldId = source.dataset.labField;
  const labId = source.dataset.labId || state.activeLab;
  if (fieldId && labId) return { kind: 'lab-field', labId, fieldId };
  return null;
}

function bindMobileExpandNoteSourceFields(): void {
  if (!isMobileAppViewport()) return;
  const selector = [
    '#agentPrompt',
    '#recurringNote',
    '#labInput',
    'textarea[data-lab-field][data-lab-id]',
  ].join(',');
  for (const source of document.querySelectorAll<HTMLTextAreaElement>(selector)) {
    if (source.disabled) continue;
    const ref = expandNoteRefForSourceField(source);
    if (!ref) continue;
    const openFromSource = (event: Event) => {
      if (!isMobileAppViewport() || state.activeExpandNoteField) return;
      event.preventDefault();
      event.stopPropagation();
      source.blur();
      openExpandNoteSheet(ref);
    };
    // bindOnce (not raw addEventListener): under the iOS whole-workspace morph these source nodes
    // persist across renders, so a raw listener would stack duplicates each morph. bindOnce keys per
    // (element,type) and refreshes to the newest closure.
    bindOnce(source, 'pointerdown', openFromSource);
    bindOnce(source, 'focus', openFromSource);
  }
}

function syncExpandNoteSourceField(ref: ExpandNoteFieldRef, value: string): void {
  if (typeof document === 'undefined') return;
  if (ref.kind === 'agent-prompt') {
    const source = document.querySelector<HTMLTextAreaElement>('#agentPrompt');
    if (source && source.value !== value) source.value = value;
    return;
  }
  if (ref.kind === 'recurring-note') {
    const source = document.querySelector<HTMLTextAreaElement>('#recurringNote');
    if (source && source.value !== value) source.value = value;
    return;
  }
  if (ref.kind === 'lab-advanced') {
    const source = document.querySelector<HTMLTextAreaElement>('#labInput');
    if (source && source.value !== value) source.value = value;
    return;
  }
  const escape = (input: string): string => {
    if (typeof window !== 'undefined' && typeof window.CSS?.escape === 'function') {
      return window.CSS.escape(input);
    }
    return input.replace(/(["\\])/g, '\\$1');
  };
  const selector = `[data-lab-field="${escape(ref.fieldId)}"][data-lab-id="${escape(ref.labId)}"]`;
  const source = document.querySelector<HTMLTextAreaElement | HTMLInputElement>(selector);
  if (source && source.value !== value) source.value = value;
}

function setPreferencesView(view: PreferencesView): boolean {
  const changed = state.preferencesView !== view;
  state.preferencesView = view;
  if (changed && view === 'access') state.preferencesAccessMobileTab = 'protocols';
  if (changed && view === 'rules') state.preferencesRulesMobileTab = 'recipients';
  if (changed && view === 'tokens') state.preferencesTokensMobileTab = 'labels';
  state.error = '';
  savePersistedState();
  render();
  return changed;
}

function updateSelectPickerView(picker: HTMLElement, value: string): void {
  const options = [...picker.querySelectorAll<HTMLButtonElement>('[data-select-picker-option]')];
  const selectedOption = options.find((option) => option.dataset.selectPickerOption === value);
  if (!selectedOption) return;
  for (const option of options) {
    const selected = option === selectedOption;
    option.classList.toggle('selected', selected);
    option.classList.toggle('active', selected);
    option.setAttribute('aria-selected', selected ? 'true' : 'false');
    option.tabIndex = selected ? 0 : -1;
  }
  const valueNode = picker.querySelector<HTMLElement>('[data-select-picker-value]');
  if (valueNode) {
    valueNode.textContent = selectedOption.dataset.selectPickerLabel ?? selectedOption.textContent?.trim() ?? value;
  }
  const metaNode = picker.querySelector<HTMLElement>('.select-picker-meta');
  if (metaNode) {
    const meta = selectedOption.dataset.selectPickerMeta ?? '';
    const metaSuffix = selectedOption.dataset.selectPickerMetaSuffix ?? '';
    metaNode.textContent = '';
    if (meta) {
      metaNode.append(document.createTextNode(meta));
    }
    if (metaSuffix) {
      const suffixNode = document.createElement('span');
      suffixNode.className = 'select-picker-meta-extra';
      suffixNode.textContent = metaSuffix;
      metaNode.append(suffixNode);
    }
    metaNode.hidden = meta.length === 0 && metaSuffix.length === 0;
  }
  const trigger = picker.querySelector<HTMLElement>('.select-picker-trigger, .template-picker-trigger');
  if (trigger) {
    const existingLogo = Array.from(trigger.children).find(
      (child) => child.classList.contains('select-picker-logo'),
    ) as HTMLElement | undefined;
    const optionLogo = Array.from(selectedOption.children).find(
      (child) => child.classList.contains('select-picker-logo'),
    ) as HTMLElement | undefined;
    if (optionLogo) {
      const cloned = optionLogo.cloneNode(true) as HTMLElement;
      if (existingLogo) {
        existingLogo.replaceWith(cloned);
      } else {
        trigger.prepend(cloned);
      }
    } else if (existingLogo) {
      existingLogo.remove();
    }
  }
}

function selectArtifactLab(labId: string): boolean {
  const lab = LABS.find((candidate) => candidate.id === labId);
  if (!lab || lab.id === state.activeLab) {
    return false;
  }
  state.activeLab = lab.id;
  state.error = '';
  state.labFieldErrors = {};
  render();
  return true;
}

function selectAgentTemplate(templateId: string): boolean {
  const template = templateById(templateId);
  if (template.id === state.selectedTemplateId) {
    return false;
  }
  state.selectedTemplateId = template.id;
  state.templateFields = normalizeTemplateFieldsForTemplate(template, {
    ...defaultTemplateFieldValues(template),
    ...state.templateFields,
  });
  state.templateTokenModes = defaultTemplateTokenModes(template, state.templateFields);
  state.templateTokenSelections = defaultTemplateTokenSelections(template, state.templateFields);
  state.templateFieldErrors = {};
  state.agentPlan = null;
  state.agentSignature = '';
  state.agentPreparedActionId = '';
  render();
  return true;
}

function selectConnectorForCreate(connectorId: string): void {
  const trimmed = connectorId.trim();
  if (!trimmed) {
    clearConnectorCreateSelection();
    return;
  }
  const connector = getAdapterMeta(trimmed as ConnectedDappId);
  if (!connector) return;
  const env = connectorDraftEnvironment();
  const status = connectorCreateStatus(connector, env);
  if (!status.selectable) {
    // Un-enabled but otherwise valid → connect it inline instead of dead-ending on a disabled option.
    if (connectorCreateStatusIsConnectable(status.kind)) connectProtocolConnectorThenSelect(connector);
    return;
  }
  // Under an active action, pick the connector's first form FOR that action (keeps the route
  // scoped — e.g. switching to Jupiter under "Lend" lands on its Lend form, not its first form).
  const cat = state.createActionCategory;
  const form = (cat ? firstFormForCategory(connector, cat) : undefined)
    ?? connectorActionFormsForConnector(connector)[0];
  if (!form) return;
  if (cat) applyConnectorActionFormForCategory(form, cat);
  else applyConnectorActionForm(form);
}

function connectProtocolConnectorThenSelect(connector: ProtocolConnector): void {
  // Open the in-place connect surface (popover on web, sheet on mobile) for the picked
  // connector. Keyless connectors get a one-tap "Enable" confirm; BYO-key connectors get a
  // credential form. On success the selection sticks + the action form applies; cancel only closes
  // the prompt and leaves the caller's tab/surface in place.
  const surface: ConnectorConnectSession['surface'] = state.activeTab === 'chat' && state.chatConnectorSession?.active
    ? 'chat'
    : 'create';
  openConnectorConnect(connector.id, state.createActionCategory || null, surface);
}

function openConnectorConnect(connectorId: string, category: ActionCategory | null, surface: ConnectorConnectSession['surface'] = 'create'): void {
  const nativeSheet = connectorConnectUsesNativeRailSheet();
  state.connectorConnect = {
    connectorId,
    category,
    surface,
    openerRoute: currentRoute(),
    openerTab: state.activeTab,
  };
  if (nativeSheet) {
    if (state.activeMobileRailSheet === 'connector-connect') suppressMobileRailSheetEnterAnimation = true;
    state.activeMobileRailSheet = 'connector-connect';
  }
  if (connectorNeedsCredential(connectorId)) {
    void refreshConnectorSecretsSummary({ force: Boolean(state.connectorSecrets.error), renderOnChange: true });
  }
  render();
}

function connectorConnectUsesNativeRailSheet(): boolean {
  return isNativeAppShellSurface() && isMobileAppViewport();
}

function closeConnectorConnect(): void {
  state.connectorConnect = null;
  if (state.activeMobileRailSheet === 'connector-connect') state.activeMobileRailSheet = null;
  render();
}

function reconcileConnectorConnectSession(route: AppRoute | null = currentRoute()): void {
  const session = state.connectorConnect;
  if (!session) return;
  if (route !== session.openerRoute || state.activeTab !== session.openerTab) {
    state.connectorConnect = null;
    if (state.activeMobileRailSheet === 'connector-connect') state.activeMobileRailSheet = null;
  }
}

function connectorConnectIsByo(id: string): boolean {
  return connectorNeedsCredential(id);
}

function connectorConnectEnable(connectorId: string): void {
  const updated = setConnectedDappEnabled(state.connectedDapps, connectorId as ConnectedDappId, true);
  state.connectedDapps = updated;
  saveConnectedDapps(updated);
  void syncCloudPreference('protocol-connectors');
}

// After a connector is connected, route into its form for the active action and clear the surface.
function connectorConnectFinish(connectorId: string, category: ActionCategory | null, surface: ConnectorConnectSession['surface'] = 'create'): void {
  state.connectorConnect = null;
  if (state.activeMobileRailSheet === 'connector-connect') state.activeMobileRailSheet = null;
  const connector = getAdapterMeta(connectorId as ConnectedDappId);
  const form = connector
    ? ((category ? firstFormForCategory(connector, category) : undefined) ?? connectorActionFormsForConnector(connector)[0])
    : undefined;
  if (surface === 'preferences') {
    render();
    return;
  }
  // Repeat tab: seed the recurring draft (the connector is now enabled → selectable) instead of the
  // New Request template draft. normalizeRecurringConnectorDraft keeps the category-correct form.
  if (surface === 'recurring') {
    state.recurringDraft = normalizeRecurringConnectorDraft({
      ...state.recurringDraft,
      connectorId,
      connectorOperationId: form?.id ?? state.recurringDraft.connectorOperationId,
    });
    render();
    return;
  }
  if (surface === 'chat') {
    if (!form) {
      render();
      return;
    }
    if (category) applyConnectorActionFormForCategory(form, category);
    else applyConnectorActionForm(form);
    return;
  }
  if (!form) {
    render();
    return;
  }
  if (category) applyConnectorActionFormForCategory(form, category);
  else applyConnectorActionForm(form);
}

interface ConnectorConnectSurfaceParts {
  body: string;
  connectorLogo: string;
  detail: string;
  title: string;
}

function connectorConnectSurfaceParts(): ConnectorConnectSurfaceParts | null {
  const session = state.connectorConnect;
  if (!session) return null;
  if (session.openerRoute !== currentRoute() || session.openerTab !== state.activeTab) return null;
  const connector = getAdapterMeta(session.connectorId as ConnectedDappId);
  if (!connector) return null;
  const byo = connectorConnectIsByo(session.connectorId);
  const meta = byo ? BYO_KEY_CONNECTOR_META[session.connectorId as ByoKeyConnectorId] : undefined;
  const draftApiKey = session.draftApiKey ?? '';
  const hasCredential = connectorCredentialReady(session.connectorId, draftApiKey);
  const readiness = connectorConnectReadiness(connector, session, hasCredential);
  const connectorLogo = brandLogo(protocolConnectorLogoId(connector.id), 'connector-connect-logo');
  const title = tf('Enable {name}', { name: connector.name });
  const detail = readiness.label;
  const readinessHtml = connectorReadinessSummaryHtml(readiness);
  const credentialLabel = meta?.credentialKind === 'access-code' ? t('Access code') : t('API key');
  const savedCredential = connectorHasSavedCredential(session.connectorId);
  const credentialStorageBlocked = byo && (!state.connectorSecrets.available || Boolean(state.connectorSecrets.error));
  const credentialLoading = byo && state.connectorSecrets.loading;
  const credentialNotice = !byo || savedCredential || (!credentialLoading && !credentialStorageBlocked)
    ? ''
    : `
      <div class="connector-connect-credential-status ${credentialStorageBlocked ? 'blocked' : 'ready'}">
        <strong>${escapeHtml(credentialLoading ? t('Checking saved credential') : t('Credential save needs Cloud'))}</strong>
        <p>${escapeHtml(credentialLoading ? t('You can paste the credential now while Agentic checks for a saved one.') : state.connectorSecrets.error || t('Connector key storage is unavailable. Paste the key here; save will retry Cloud storage.'))}</p>
      </div>`;
  const body = byo
    ? savedCredential
      ? `
      <p class="connector-connect-intro">${escapeHtml(readiness.detail)}</p>
      ${readinessHtml}
      <div class="connector-connect-credential-status ready">
        <strong>${escapeHtml(tf('{label} saved', { label: credentialLabel }))}</strong>
        <p>${escapeHtml(t('Agentic will use the encrypted wallet-scoped credential when preparing connector facts or transactions.'))}</p>
      </div>
      <div class="connector-connect-actions">
        <button type="button" class="connector-connect-secondary" data-connector-connect-cancel>${escapeHtml(t('Cancel'))}</button>
        <button type="button" class="connector-connect-primary primary" data-connector-connect-enable>${escapeHtml(t('Enable'))}</button>
      </div>`
      : `
      <p class="connector-connect-intro">${escapeHtml(readiness.detail)}</p>
      ${readinessHtml}
      ${credentialNotice}
      <label class="field compact connector-connect-field"><span>${escapeHtml(credentialLabel)}</span>
        <div class="ai-key-input-wrap">
          <input id="connectorConnectKey" data-connector-connect-key type="password" autocomplete="off" spellcheck="false" value="${escapeHtml(session.draftApiKey ?? '')}" placeholder="${escapeHtml(meta?.credentialKind === 'access-code' ? t('Paste access code') : t('Paste API key'))}" />
          <button type="button" class="ai-key-paste-btn" data-connector-connect-key-paste title="${escapeHtml(t('Paste your key from the clipboard'))}" aria-label="${escapeHtml(t('Paste key from clipboard'))}">${escapeHtml(t('Paste'))}</button>
        </div>
      </label>
      ${meta?.portalUrl ? `<a class="connector-connect-portal" href="${escapeHtml(meta.portalUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(t('Where to get a credential'))}</a>` : ''}
      <div class="connector-connect-actions">
        <button type="button" class="connector-connect-secondary" data-connector-connect-cancel>${escapeHtml(t('Cancel'))}</button>
        <button type="button" class="connector-connect-primary primary" data-connector-connect-save>${escapeHtml(t('Save and enable'))}</button>
      </div>`
    : readiness.canEnable
      ? `
      <p class="connector-connect-intro">${escapeHtml(readiness.detail)}</p>
      ${readinessHtml}
      <div class="connector-connect-actions">
        <button type="button" class="connector-connect-secondary" data-connector-connect-cancel>${escapeHtml(t('Cancel'))}</button>
        <button type="button" class="connector-connect-primary primary" data-connector-connect-enable>${escapeHtml(t('Enable'))}</button>
      </div>`
    : `
      <p class="connector-connect-intro">${escapeHtml(readiness.detail)}</p>
      ${readinessHtml}
      <div class="connector-connect-actions">
        <button type="button" class="connector-connect-secondary" data-connector-connect-cancel>${escapeHtml(t('Cancel'))}</button>
      </div>`;
  return { body, connectorLogo, detail, title };
}

function connectorConnectSurfaceHtml(): string {
  if (connectorConnectUsesNativeRailSheet()) return '';
  const parts = connectorConnectSurfaceParts();
  if (!parts) return '';
  const panel = `
    <div class="chat-action-popover connector-connect-popover" role="dialog" aria-modal="true" aria-labelledby="connectorConnectTitle">
      <div class="connector-connect-head">
        <div class="connector-connect-title-row">
          ${parts.connectorLogo}
          <div class="connector-connect-title-copy">
            <span>${escapeHtml(parts.detail)}</span>
            <h2 id="connectorConnectTitle">${escapeHtml(parts.title)}</h2>
          </div>
        </div>
        <button type="button" class="connector-connect-close" data-connector-connect-cancel aria-label="${escapeHtml(t('Close'))}" title="${escapeHtml(t('Close'))}">&times;</button>
      </div>
      <div class="connector-connect-body">${parts.body}</div>
    </div>`;
  return `<div class="connector-connect-overlay" data-connector-connect-overlay>${panel}</div>`;
}

function connectorConnectReadiness(
  connector: ConnectedDappAdapter,
  session: Pick<ConnectorConnectSession, 'category'>,
  hasCredential: boolean,
): ConnectorReadinessResult {
  return connectorReadiness({
    connector,
    clusterSupported: isClusterSupported(connector, state.cluster),
    walletAddress: state.address || undefined,
    hasCredential,
    actionCategory: session.category,
  });
}

function connectorReadinessSummaryHtml(readiness: ConnectorReadinessResult): string {
  const notes = readiness.notes
    .map((note) => `<li>${escapeHtml(note)}</li>`)
    .join('');
  return `
    <div class="connector-connect-readiness ${escapeHtml(readiness.kind)}">
      <span>${escapeHtml(readiness.label)}</span>
      <ul>${notes}</ul>
    </div>
  `;
}

function bindConnectorConnectSurface(): void {
  const session = state.connectorConnect;
  if (!session) return;
  const overlay = document.querySelector<HTMLElement>('[data-connector-connect-overlay]');
  bindOnce(overlay, 'click', (event) => {
    if (event.target === overlay) closeConnectorConnect();
  });
  for (const btn of document.querySelectorAll<HTMLButtonElement>('[data-connector-connect-cancel]')) {
    bindOnce(btn, 'click', () => closeConnectorConnect());
  }
  const connectorName = getAdapterMeta(session.connectorId as ConnectedDappId)?.name ?? session.connectorId;
  // Live-sync the key input into the session draft so any re-render (e.g. a toast
  // auto-dismissing, or a failed save) restores the in-progress values instead of wiping them.
  bindOnce(document.querySelector<HTMLInputElement>('[data-connector-connect-key]'), 'input', (event) => {
    if (state.connectorConnect) state.connectorConnect.draftApiKey = (event.currentTarget as HTMLInputElement).value;
  });
  bindOnce(document.querySelector<HTMLButtonElement>('[data-connector-connect-key-paste]'), 'click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    const button = event.currentTarget as HTMLButtonElement;
    void runPasteProtocolConnectorCredential(button);
  });
  bindOnce(document.querySelector<HTMLButtonElement>('[data-connector-connect-enable]'), 'click', () => {
    connectorConnectEnable(session.connectorId);
    pushToast('success', tf('{name} enabled', { name: connectorName }), t('No wallet signature was requested.'));
    connectorConnectFinish(session.connectorId, session.category, session.surface);
  });
  bindOnce(document.querySelector<HTMLButtonElement>('[data-connector-connect-save]'), 'click', () => {
    void (async () => {
      const apiKey = (document.querySelector<HTMLInputElement>('[data-connector-connect-key]')?.value ?? '').trim();
      if (!apiKey) {
        const meta = connectorNeedsCredential(session.connectorId) ? BYO_KEY_CONNECTOR_META[session.connectorId] : undefined;
        const label = meta?.credentialKind === 'access-code' ? t('Access code') : t('API key');
        pushToast('error', t('Credential required'), tf('Paste the {label} to continue.', { label }));
        render();
        return;
      }
      try {
        const summary = await saveConnectorSecret(session.connectorId as ByoKeyConnectorId, { apiKey });
        updateConnectorSecretSummary(session.connectorId as ByoKeyConnectorId, summary);
        if (connectorNeedsCredential(session.connectorId)) {
          state.protocolConnectorCredentialDrafts[session.connectorId] = { apiKey: '' };
        }
        connectorConnectEnable(session.connectorId);
        pushToast('success', tf('{name} enabled', { name: connectorName }), t('Credential saved; no wallet signature was requested.'));
        connectorConnectFinish(session.connectorId, session.category, session.surface);
      } catch (err) {
        pushToast('error', t('Could not connect'), err instanceof Error ? err.message : String(err));
        render();
      }
    })();
  });
}

function selectConnectorActionForCreate(formId: string): void {
  const form = connectorActionFormById(formId);
  if (!form) return;
  const connector = getAdapterMeta(form.connectorId);
  if (!connector || !connectorCreateStatus(connector, connectorDraftEnvironment()).selectable) return;
  applyConnectorActionForm(form);
}

function applyConnectorActionForm(form: ConnectorActionForm): void {
  const connector = getAdapterMeta(form.connectorId);
  if (!connector) return;
  const template = templateById(form.templateId);
  const previousConnectorId = selectedConnectorForDraftParameters(state.templateFields)?.id ?? '';
  const nextFields: Record<string, string> = {
    ...defaultTemplateFieldValues(template),
    ...state.templateFields,
    connectorId: connector.id,
    protocol: connector.id,
    operation: form.operationLabel,
    connectorOperationId: form.id,
  };
  if (previousConnectorId !== connector.id) {
    nextFields.memo = '';
  }
  state.selectedTemplateId = template.id;
  state.templateOutcomeFilter = templateOutcome(template);
  state.templateFields = normalizeConnectorDraftParameters(template, nextFields);
  state.templateTokenModes = defaultTemplateTokenModes(template, state.templateFields);
  state.templateTokenSelections = defaultTemplateTokenSelections(template, state.templateFields);
  state.templateFieldErrors = {};
  state.agentPlan = null;
  state.agentSignature = '';
  state.agentPreparedActionId = '';
  render();
}

function clearConnectorCreateSelection(): void {
  const fallback = templateById(selectedConnectorForCreate(selectedTemplate()) ? 'swap' : state.selectedTemplateId);
  state.selectedTemplateId = fallback.id;
  state.templateOutcomeFilter = templateOutcome(fallback);
  state.templateFields = stripConnectorDraftExtras(fallback, {
    ...defaultTemplateFieldValues(fallback),
    ...state.templateFields,
    connectorId: '',
    connectorOperationId: '',
    connectorActionSource: '',
    protocol: '',
    operation: '',
  });
  state.templateTokenModes = defaultTemplateTokenModes(fallback, state.templateFields);
  state.templateTokenSelections = defaultTemplateTokenSelections(fallback, state.templateFields);
  state.templateFieldErrors = {};
  state.agentPlan = null;
  state.agentSignature = '';
  state.agentPreparedActionId = '';
  render();
}

function normalizeTemplateFieldsForTemplate(
  template: AgentPlanTemplate,
  fields: Record<string, string>,
): Record<string, string> {
  if (!isConnectorCapableTemplate(template)) {
    const stripped = stripConnectorDraftExtras(template, fields);
    const form = connectorActionFormForTemplateFields(template, stripped);
    return form && isGenericConnectorActionForm(form)
      ? scopeTemplateFieldsToConnectorForm(stripped, form)
      : stripped;
  }
  const env = connectorDraftEnvironment();
  const templateForm = connectorActionFormForTemplate(template);
  const templateConnector = templateForm && !isGenericConnectorActionForm(templateForm)
    ? getAdapterMeta(templateForm.connectorId)
    : undefined;
  const selectable = connectorCreateConnectors(env).find((connector) => connectorCreateStatus(connector, env).selectable);
  const connector = selectedConnectorForDraftParameters(fields) ?? templateConnector ?? selectable;
  const next = connector
    ? normalizeConnectorDraftParameters(template, {
      ...fields,
      protocol: connector.id,
      connectorId: connector.id,
      ...(templateForm ? {
        operation: templateForm.operationLabel,
        connectorOperationId: templateForm.id,
      } : {}),
    })
    : normalizeConnectorDraftParameters(template, fields);
  const selected = selectedConnectorForDraftParameters(next);
  const selectedForm = selectedConnectorActionForm(next) ?? (selected ? connectorActionFormForTemplate(template, selected) : undefined);
  if (selectedForm) {
    next.operation = selectedForm.operationLabel;
    next.connectorOperationId = selectedForm.id;
  } else if (selected && !selected.supportedActions.includes(next.operation ?? '')) {
    next.operation = selected.supportedActions[0] ?? '';
  }
  return next;
}

function scopeTemplateFieldsToConnectorForm(
  fields: Record<string, string>,
  form: ConnectorActionForm,
): Record<string, string> {
  const allowed = new Set<string>();
  for (const field of formTemplateFields(form)) {
    allowed.add(field.id);
    allowed.add(`${field.id}Label`);
    allowed.add(`${field.id}Mint`);
    allowed.add(`${field.id}Decimals`);
  }
  const scoped: Record<string, string> = {};
  for (const [key, value] of Object.entries(fields)) {
    if (allowed.has(key)) scoped[key] = value;
  }
  return scoped;
}

function syncConnectorTemplateFieldChange(fieldId: string): boolean {
  const template = selectedTemplate();
  const connectorForm = connectorActionFormForTemplateFields(template, state.templateFields);
  if (!isConnectorCapableTemplate(template) && !(connectorForm && isGenericConnectorActionForm(connectorForm))) {
    return false;
  }
  if (fieldId !== 'protocol' && fieldId !== 'operation') return false;
  state.templateFields = normalizeTemplateFieldsForTemplate(template, state.templateFields);
  return fieldId === 'protocol';
}

function positionTemplatePickerMenu(trigger: HTMLElement, menu: HTMLElement): void {
  const viewport = window.visualViewport;
  const viewportTop = viewport?.offsetTop ?? 0;
  const viewportWidth = viewport?.width ?? window.innerWidth;
  const viewportHeight = viewport?.height ?? window.innerHeight;
  const triggerRect = trigger.getBoundingClientRect();
  // Bound the drop space to the scroll container (rail sheet body / desktop popover) when present, so the
  // menu is sized to what's actually visible INSIDE it and never overflows into a scroll of the whole sheet.
  const sheetBody = menu.closest<HTMLElement>('.mobile-rail-sheet-body, .chat-action-popover');
  const sheetRect = sheetBody?.getBoundingClientRect();
  const safeBottom = Math.min(viewportTop + viewportHeight - 10, sheetRect ? sheetRect.bottom - 8 : Number.POSITIVE_INFINITY);
  const safeTop = Math.max(viewportTop + 10, sheetRect ? sheetRect.top + 8 : Number.NEGATIVE_INFINITY);
  const spaceBelow = Math.max(0, Math.floor(safeBottom - triggerRect.bottom - 8));
  const spaceAbove = Math.max(0, Math.floor(triggerRect.top - safeTop - 8));
  const placement = selectPickerPlacement(trigger, menu);
  const inBottomDock = Boolean(trigger.closest('[data-layout="android-bottom-tab-dock"]'));
  // Open UPWARD when an auto down-drop can't reasonably fit below AND there's more room above — a near-bottom
  // trigger then opens over the form above it instead of scrolling the whole sheet into view.
  const shouldDropUp = placement === 'down'
    ? false
    : placement === 'up' || inBottomDock || (spaceBelow < 180 && spaceAbove > spaceBelow);
  const usableSpace = shouldDropUp ? spaceAbove : spaceBelow;
  // Cap to the available space in the chosen direction (no floor that would force it to overflow the sheet);
  // longer lists scroll inside the menu (overflow-y:auto).
  const maxHeight = sheetBody
    ? Math.max(88, Math.min(320, usableSpace))
    : Math.min(420, Math.max(160, usableSpace));
  menu.classList.toggle('drop-up', shouldDropUp);
  menu.style.setProperty('--template-menu-max-height', `${maxHeight}px`);
  menu.style.setProperty('--template-menu-max-width', `${Math.max(220, Math.floor(viewportWidth - 20))}px`);
  // Horizontal: the menu grows to fit its widest option (width:max-content), so keep it on-screen:
  // anchor to the trigger's left, but flip to right-anchored when a left-anchored menu would overflow
  // the right edge (right-aligned toolbar triggers like the Sign Approval / Done filters).
  const menuWidth = Math.min(menu.getBoundingClientRect().width || triggerRect.width, Math.floor(viewportWidth - 20));
  const overflowsRight = triggerRect.left + menuWidth > viewportWidth - 10;
  // Both connector-provider pickers — New Request (`.connector-create-picker`) and Repeat Payments
  // (`.recurring-connector-picker`), which share `.top-connector-picker` — are narrow, right-of-center
  // triggers with a wide (width:max-content) menu. The right-anchor flip in the `else` pins the menu's
  // right edge to the trigger and grows it LEFTWARD, so it opens off the left screen edge — most visibly
  // on native Android/iOS (isMobileAppViewport() === true), which the old guard wrongly excluded. For
  // these, keep the menu dropping straight DOWN from the trigger's left, nudged left only as far as
  // needed to stay on-screen. The nudge keeps BOTH edges visible because menuWidth is capped to
  // viewportWidth-20 (so overflowPx <= triggerRect.left - 10, i.e. left edge stays >= 10px). Every other
  // picker — incl. the genuinely right-aligned Sign Approval / Done toolbar filters — keeps the flip.
  if (overflowsRight && trigger.closest('.top-connector-picker')) {
    const overflowPx = Math.max(0, Math.ceil(triggerRect.left + menuWidth - (viewportWidth - 10)));
    menu.style.left = `-${overflowPx}px`;
    menu.style.right = 'auto';
  } else {
    menu.style.left = overflowsRight ? 'auto' : '0';
    menu.style.right = overflowsRight ? '0' : 'auto';
  }
}

function selectPickerPlacement(trigger: HTMLElement, menu: HTMLElement): SelectPickerPlacement {
  const picker = trigger.closest<HTMLElement>('[data-select-picker]');
  const placement = picker?.dataset.selectPickerPlacement ?? menu.dataset.selectPickerPlacement ?? 'auto';
  return placement === 'down' || placement === 'up' ? placement : 'auto';
}

function scrollForcedDownSelectPickerMenuIntoView(trigger: HTMLElement, menu: HTMLElement): void {
  if (selectPickerPlacement(trigger, menu) !== 'down') return;
  const sheetBody = menu.closest<HTMLElement>('.mobile-rail-sheet-body');
  if (!sheetBody) return;
  const triggerRect = trigger.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  const sheetRect = sheetBody.getBoundingClientRect();
  const topOverflow = Math.ceil(sheetRect.top - triggerRect.top + 8);
  const bottomOverflow = Math.ceil(menuRect.bottom - sheetRect.bottom + 12);
  // positionTemplatePickerMenu now caps the menu to fit the sheet (and drops it up when short), so a
  // down-menu normally fits — only nudge on a genuine overflow (e.g. a partially-scrolled-off trigger),
  // never for the few-px fit slack, so opening a dropdown doesn't shove the whole sheet.
  if (topOverflow > 8) {
    sheetBody.scrollTop -= topOverflow;
  } else if (bottomOverflow > 8) {
    sheetBody.scrollTop += bottomOverflow;
  }
}

function setActiveTemplateOption(
  options: HTMLButtonElement[],
  activeOption: HTMLButtonElement,
  focus: boolean,
): void {
  for (const option of options) {
    const active = option === activeOption;
    option.classList.toggle('active', active);
    option.tabIndex = active ? 0 : -1;
  }
  if (focus) {
    activeOption.focus({ preventScroll: true });
  }
  activeOption.scrollIntoView({ block: 'nearest' });
}

function focusAdjacentTemplateOption(options: HTMLButtonElement[], direction: 1 | -1): void {
  const currentIndex = options.findIndex((option) => option === document.activeElement || option.classList.contains('active'));
  const nextIndex = currentIndex < 0
    ? 0
    : (currentIndex + direction + options.length) % options.length;
  setActiveTemplateOption(options, options[nextIndex]!, true);
}

async function runFirstRunAction(action: FirstRunActionId): Promise<void> {
  switch (action) {
    case 'discover-wallets':
      if (multiPathWalletFlowAvailable()) {
        await runDesktopDiscover();
      } else {
        await runDiscover();
      }
      return;
    case 'connect-wallet':
      await runConnect();
      return;
    case 'cloud-sign-in':
      await runCloudSignIn();
      return;
    case 'open-create-plan':
      state.activeTab = 'agent';
      state.oneTimePlanView = 'create';
      state.generatedPlanAuditId = '';
      state.error = '';
      render();
      return;
    case 'open-ai-setup':
      state.activeTab = 'overview';
      state.commandCenterView = 'ai';
      state.aiSettingsPanelOpen = true;
      if (isMobileAppViewport()) {
        state.aiReviewSetupTab = preferredAiReviewSetupTabForMobileRailOpen('ai-drafting');
        state.activeMobileRailSheet = 'ai-drafting';
      }
      state.generatedPlanAuditId = '';
      state.error = '';
      render();
      if (isMobileAppViewport()) {
        maybeRefreshDeviceAgentStatusForMobileRailOpen('ai-drafting');
      }
      focusLayoutTarget('ai-setup-panel');
      return;
    case 'open-review':
      state.activeTab = 'agent';
      state.oneTimePlanView = 'review';
      selectFallbackGeneratedPlan();
      state.error = '';
      render();
      return;
    case 'open-inbox':
      state.activeTab = 'inbox';
      state.inboxFilter = 'ready';
      state.error = '';
      render();
      return;
    case 'open-completed':
      state.activeTab = 'completed';
      state.completedPlanFilter = 'receipts';
      state.error = '';
      render();
      return;
  }
}

function focusLayoutTarget(layoutName: string): void {
  window.requestAnimationFrame(() => {
    const target = document.querySelector<HTMLElement>(`[data-layout="${layoutName}"]`);
    if (!target) return;
    if (target instanceof HTMLDetailsElement) {
      target.open = true;
    }
    target.scrollIntoView({
      behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
      block: 'center',
    });
    target.focus?.({ preventScroll: true });
  });
}

interface WalletToastSnapshot {
  walletName: string;
  address: string;
  logoId?: WalletProviderLogoId;
}

function walletConnectionToastTitle(walletName: string, status: 'connected' | 'disconnected'): string {
  const name = walletName.trim();
  const walletLabel = /\bwallet$/iu.test(name) ? name : `${name} wallet`;
  if (!name || name === 'Mobile Wallet Adapter') {
    return status === 'connected' ? t('Wallet connected') : t('Wallet disconnected');
  }
  return status === 'connected'
    ? tf('{name} connected', { name: walletLabel })
    : tf('{name} disconnected', { name: walletLabel });
}

function walletConnectedToastTitle(walletName: string): string {
  return walletConnectionToastTitle(walletName, 'connected');
}

function walletDisconnectedToastTitle(walletName: string): string {
  return walletConnectionToastTitle(walletName, 'disconnected');
}

function walletToastSnapshot(): WalletToastSnapshot {
  const walletName = state.selectedWalletName?.trim() ?? '';
  const address = state.address.trim();
  const logoId = state.selectedWalletLogoId ?? walletProviderLogoIdForName(walletName);
  return {
    walletName,
    address,
    ...(logoId ? { logoId } : {}),
  };
}

function pushNativeWalletConnectedToast(): void {
  const wallet = walletToastSnapshot();
  pushToast(
    'success',
    walletConnectedToastTitle(wallet.walletName),
    wallet.address ? short(wallet.address) : '',
    wallet.logoId ? { logoId: wallet.logoId } : {},
  );
}

function pushNativeWalletDisconnectedToast(wallet: WalletToastSnapshot): void {
  pushToast(
    'success',
    walletDisconnectedToastTitle(wallet.walletName),
    wallet.address ? short(wallet.address) : '',
    wallet.logoId ? { logoId: wallet.logoId } : {},
  );
}

async function runDiscover(): Promise<void> {
  await run('discover', async () => {
    if (state.androidNativeEnvironment.isAndroidNative) {
      trackWalletConnectClick('android_native', 'discover_button');
      await connectAndroidNativeWallet(true);
      await afterWalletConnected();
      trackWalletConnectSuccess('android_native', state.cluster, 'discover_button');
      pushNativeWalletConnectedToast();
      return;
    }
    if (state.iosNativeEnvironment.isIosNative) {
      state.iosWallets = listIosNativeWalletOptions();
      await refreshIosNativeCacheState();
      state.iosNativeStatus = `${state.iosWallets.length} iOS wallet path(s) available. Cached authorizations: ${state.iosAuthCacheCount}.`;
      savePersistedState();
      pushToast('success', t('iOS wallets ready'), tf('{count} wallet path(s) available.', { count: state.iosWallets.length }));
      return;
    }
    discoverBrowserWallets();
  });
}

async function runBrowserExtensionDiscover(): Promise<void> {
  await run('discover', async () => {
    discoverBrowserWallets({ resetSelection: true });
  });
}

function discoverBrowserWallets(options: { resetSelection?: boolean } = {}): void {
  if (options.resetSelection) {
    clearPendingBrowserWalletChoice();
  }
  state.wallets = visibleBrowserWallets(listAvailableWallets());
  state.selectedWalletName = options.resetSelection
    ? ''
    : reconcileBrowserWalletSelection(state.wallets, state.selectedWalletName);
  state.selectedWalletLogoId = state.selectedWalletName
    ? walletProviderLogoIdForName(state.selectedWalletName)
    : undefined;
  state.selectedWalletIcon = undefined;
  state.browserWalletPickerOpen = state.wallets.length > 0 && !state.selectedWalletName;
  if (!browserWalletRestoreName(state.wallets, state.browserWalletSession, state.cluster)) {
    clearBrowserWalletSession();
    if (state.walletPathSession?.path === 'browser-extension' || state.walletPathSession?.path === 'desktop-browser-extension') {
      clearWalletPathSession();
    }
  }
  if (state.wallets.length === 0) {
    state.selectedWalletName = '';
    state.selectedWalletLogoId = undefined;
    state.selectedWalletIcon = undefined;
    state.browserWalletPickerOpen = false;
    clearBrowserWalletSession();
    if (state.walletPathSession?.path === 'browser-extension' || state.walletPathSession?.path === 'desktop-browser-extension') {
      clearWalletPathSession();
    }
    savePersistedState();
    throw new Error(t('No Wallet Standard Solana wallets are registered in this browser.'));
  }
  savePersistedState();
  pushToast('success', t('Wallets discovered'), tf('{count} provider(s) found.', { count: state.wallets.length }));
}

async function runConnect(
  options: {
    onError?: (message: string, err: unknown) => void | Promise<void>;
    successToast?: boolean;
  } = {},
): Promise<void> {
  const connectSurface = walletConnectSurface();
  const showSuccessToast = options.successToast !== false;
  trackWalletConnectClick(connectSurface, 'connect_button');
  await run('connect', async () => {
    if (state.androidNativeEnvironment.isAndroidNative) {
      await connectAndroidNativeWallet(true);
      state.transactionStatus = `Android MWA wallet connected on ${state.cluster}.`;
      if (state.bridgeActive) {
        await connectBridgeHost();
      }
      await afterWalletConnected();
      savePersistedState();
      trackWalletConnectSuccess(connectSurface, state.cluster, 'connect_button');
      if (showSuccessToast) {
        pushNativeWalletConnectedToast();
      }
      return;
    }
    if (state.iosNativeEnvironment.isIosNative) {
      const isJupiterIosConnect = state.selectedIosWalletId === 'jupiter';
      // Route Phantom/Solflare/Backpack through the native IWA Swift adapter when
      // the feature flag is on (default ON). Jupiter always stays on the legacy
      // WalletConnect backend. The shared post-connect flow below is identical for
      // both backends — they each expose connectSelectedWallet() + WalletBackend.
      const useNativeIwa =
        isNativeIwaWalletId(state.selectedIosWalletId) && (await refreshNativeIwaAdapterFlag());
      const iosBackend = useNativeIwa
        ? new NativeIwaWalletBackend({
            walletId: state.selectedIosWalletId as NativeIwaWalletId,
            cluster: state.cluster,
            logLevel: 'info',
          })
        : new IosNativeWalletBackend({
            walletId: state.selectedIosWalletId,
            cluster: state.cluster,
            appUrl: iosNativeAppUrl(),
            rpcUrl: activeRpcUrl(),
            logLevel: 'info',
          });
      walletBackend = iosBackend;
      client = new SolanaSigningClient({ backend: walletBackend });
      if (isJupiterIosConnect && state.jupiterReturnNotifyStatus === undefined) {
        // Request return-notification permission BEFORE the connect bounce, so the
        // native bridge's "tap to return to Agentic" notification can actually fire
        // when the user approves in Jupiter (iOS 17/18 won't auto-foreground us).
        // Requesting after connect — as we did before — left permission undetermined
        // when the first connect/sign result arrived, so the notification was dropped.
        // (Selection also requests this early in handleIosWalletSelectChange; this
        // covers a persisted/restored Jupiter selection that skipped the picker.)
        state.jupiterReturnNotifyStatus = await iosNativeEnsureReturnNotificationPermission();
      }
      if (isJupiterIosConnect) {
        // Show a pending toast during the bounce with the "Open Jupiter again"
        // re-foreground backstop. Jupiter cold-starts unreliably and can drop the
        // deep link to jup.ag; the native side auto-re-opens once on return, and
        // this button lets the user re-fire it manually if needed.
        pushToast(
          'pending',
          t('Approve in Jupiter'),
          jupiterIosManualToastMessage(t('Opening Jupiter to connect…')),
          withJupiterIosManualApprovalToast({ key: JUPITER_IOS_CONNECT_TOAST_KEY }),
        );
        render();
      }
      try {
        state.address = await iosBackend.connectSelectedWallet();
      } finally {
        if (isJupiterIosConnect) dismissToastByKey(JUPITER_IOS_CONNECT_TOAST_KEY);
      }
      state.capabilities = await client.capabilities();
      state.selectedWalletName = iosWalletLabel(state.selectedIosWalletId);
      state.selectedWalletLogoId = walletProviderLogoIdForName(state.selectedWalletName);
      state.selectedWalletIcon = undefined;
      state.iosNativeStatus = `iOS ${state.selectedWalletName} connected on ${state.cluster}.`;
      state.transactionStatus = `iOS wallet connected on ${state.cluster}.`;
      await refreshIosNativeCacheState();
      if (state.bridgeActive) {
        await connectBridgeHost();
      }
      rememberWalletPathSession({
        path: 'ios-native',
        address: state.address,
        walletName: state.selectedWalletName,
        walletBrandId: state.selectedIosWalletId,
        iosWalletId: state.selectedIosWalletId,
      });
      await afterWalletConnected();
      savePersistedState();
      trackWalletConnectSuccess(connectSurface, state.cluster, 'connect_button');
      if (showSuccessToast) {
        pushNativeWalletConnectedToast();
      }
      return;
    }
    // Ledger early-return — covers the case where `state.selectedWalletName`
    // is "Ledger" (e.g. persisted across launches via `browserWalletSession`)
    // but no Wallet Standard adapter has been registered yet because the
    // device was unplugged between sessions. Without this, `selectedWallet()`
    // throws a generic "Click Discover…" message; we want to re-open the
    // hardware-pairing overlay so the user just plugs the device in.
    if (
      state.selectedWalletName === LEDGER_WALLET_NAME
    ) {
      const hasRegisteredLedger = state.wallets.some((w) => w.name === LEDGER_WALLET_NAME);
      if (!hasRegisteredLedger) {
        openLedgerOverlay();
        return;
      }
    }
    const selected = selectedWallet();
    state.browserWalletPickerOpen = false;
    if (
      state.tauriNativeEnvironment.isTauriNative &&
      selected.name === AGENTIC_WALLET_NAME &&
      embeddedWallet.ipc
    ) {
      // Agentic Wallet has special create/unlock UX that Wallet Standard's
      // `connect()` would otherwise surface as raw error text. Route to the
      // overlay instead, then let the user re-connect once the wallet is
      // ready.
      let status: WalletStatus | null = null;
      try {
        status = await embeddedWallet.ipc.status();
      } catch (err) {
        console.warn('[runConnect] wallet_status failed', err);
      }
      embeddedWallet.status = status;
      if (status && !status.exists) {
        openEmbeddedWalletOverlay('create');
        return;
      }
      if (status && !status.unlocked) {
        openEmbeddedWalletOverlay('unlock');
        return;
      }
      // status.unlocked === true → fall through to the standard connect flow.
    }
    walletBackend = new WalletStandardWebBackend({
      wallet: selected,
      cluster: state.cluster,
      rpcUrl: activeRpcUrl(),
    });
    client = new SolanaSigningClient({ backend: walletBackend });
    const connectedAddress = await client.getAddress();
    const expectedLaunchAddress = launchParams.cliWalletAddress?.trim();
    if (expectedLaunchAddress && !sameWalletAddress(connectedAddress, expectedLaunchAddress)) {
      walletBackend = null;
      client = null;
      throw new Error(`Connected wallet ${short(connectedAddress)} does not match the requested signer ${short(expectedLaunchAddress)}.`);
    }
    state.address = connectedAddress;
    state.capabilities = await client.capabilities();
    state.transactionStatus = `Wallet connected on ${state.cluster}.`;
    state.selectedWalletName = selected.name;
    state.selectedWalletLogoId = walletProviderLogoIdForName(selected.name);
    state.selectedWalletIcon = selected.icon;
    const walletBrandId = browserWalletBrandIdForName(selected.name);
    const browserWalletPath = browserWalletPathForCurrentSurface();
    if (selected.name === LEDGER_WALLET_NAME) {
      clearBrowserWalletSession();
      rememberWalletPathSession({
        path: 'ledger',
        address: state.address,
        walletName: selected.name,
        walletBrandId: 'ledger',
      });
    } else {
      state.browserWalletSession = createBrowserWalletSession(selected.name, state.cluster, undefined, {
        address: state.address,
        walletBrandId,
        path: browserWalletPath,
      });
      rememberWalletPathSession({
        path: browserWalletPath,
        address: state.address,
        walletName: selected.name,
        walletBrandId,
      });
    }
    if (state.bridgeActive) {
      await connectBridgeHost();
    } else if (launchParams.bridgeUrl || launchParams.bridgeToken) {
      // Launched from the desktop / CLI: bridge registration is load-bearing,
      // not best-effort. If the POST 401s (token mismatch) or the bridge is
      // down, the desktop will never see this connection — show a real error
      // instead of pretending the pairing succeeded.
      try {
        await activateBridgeConnection({ refreshConfig: false, strictSync: false });
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        traceWalletCleared('bridge-connection-rejected');
        state.address = '';
        state.capabilities = null;
        state.browserWalletSession = undefined;
        clearWalletPathSession();
        state.transactionStatus = `Bridge rejected the connection: ${message}`;
        walletBackend = null;
        client = null;
        pushToast(
          'error',
          t('Bridge rejected the connection'),
          tf('{message}. Restart the local runtime and try again.', { message }),
        );
        return;
      }
    }
    await afterWalletConnected();
    savePersistedState();
    trackWalletConnectSuccess(connectSurface, state.cluster, 'connect_button');
    if (showSuccessToast) {
      pushToast('success', t('Wallet connected'), short(state.address));
    }
    // Collapse the inline Discover flow if the user reached this point via
    // the copied Browser extension / QR / Ledger rail.
    if (multiPathWalletFlowAvailable() && desktopConnect.flow.step !== 'idle') {
      dispatchDesktopConnectFlow({ type: 'reset' });
    }
  }, options);
}

async function runDisconnect(): Promise<void> {
  await run('connect', async () => {
    const browserWallet = isBrowserWalletSurface();
    const disconnectedWalletToast = walletToastSnapshot();
    const androidDisconnectSnapshot = state.androidNativeEnvironment.isAndroidNative
      ? { address: state.address, walletName: state.selectedWalletName }
      : null;
    notifyLocalWorkspaceBackupReminder('Disconnecting does not move local data to another browser.');
    if (state.bridgeActive) {
      await disconnectBridgeHost().catch(() => undefined);
    }
    await disconnectWalletBackend().catch(() => undefined);
    resetWalletConnection();
    await clearDeviceAgentForWalletBoundary();
    await signOutCloudSessionForWalletBoundary('wallet-disconnected');
    reconcileAiModeForSurface();
    if (browserWallet) {
      state.selectedWalletName = '';
      state.browserWalletPickerOpen = false;
      clearBrowserWalletSession();
    }
    await refreshAndroidNativeCacheState();
    if (state.androidNativeEnvironment.isAndroidNative) {
      if (androidDisconnectSnapshot) {
        setAndroidManualDisconnectRestoreBlock(androidDisconnectSnapshot);
      }
      state.androidNativeStatus = state.androidAuthCacheCount > 0
        ? 'Android MWA disconnected locally. Cached auto-restore disabled.'
        : 'Android MWA disconnected.';
    }
    await refreshIosNativeCacheState();
    savePersistedState();
    pushNativeWalletDisconnectedToast(disconnectedWalletToast);
  });
}

async function runReconnectAndroidCached(): Promise<void> {
  trackWalletConnectClick('android_native', 'reconnect_cached');
  await run('connect', async () => {
    assertAndroidNativeRuntime();
    const restored = await restoreAndroidNativeSession();
    if (!restored) {
      throw new Error(t('No cached Android MWA authorization found.'));
    }
    if (state.bridgeActive) {
      await connectBridgeHost();
    }
    await afterWalletConnected();
    trackWalletConnectSuccess('android_native', state.cluster, 'reconnect_cached');
    pushToast('success', t('Android MWA restored'), short(state.address));
  });
}

async function runClearAndroidTransient(): Promise<void> {
  await run('connect', async () => {
    assertAndroidNativeRuntime();
    await androidBackendOrNew().clearTransientState();
    state.androidNativeStatus = 'Android MWA transient state cleared. Cached authorization retained.';
    await refreshAndroidNativeCacheState();
    pushToast('success', t('Android state cleared'), t('Cached authorization retained.'));
  });
}

async function runClearAndroidFullReset(): Promise<void> {
  await run('connect', async () => {
    assertAndroidNativeRuntime();
    if (state.bridgeActive) {
      await disconnectBridgeHost().catch(() => undefined);
    }
    await androidBackendOrNew().clearStateFullReset();
    resetWalletConnection();
    await clearDeviceAgentForWalletBoundary();
    await refreshAndroidNativeCacheState();
    clearAndroidManualDisconnectRestoreBlock('android-full-reset');
    state.androidNativeStatus = 'Android MWA authorization reset. Discover again to authorize.';
    savePersistedState();
    pushToast('success', t('Android wallet reset'), t('Authorization cleared.'));
  });
}

async function runClearAndroidAllAccounts(): Promise<void> {
  await run('connect', async () => {
    assertAndroidNativeRuntime();
    if (state.bridgeActive) {
      await disconnectBridgeHost().catch(() => undefined);
    }
    await androidBackendOrNew().clearAllCachedAuthorizations();
    resetWalletConnection();
    await clearDeviceAgentForWalletBoundary();
    await refreshAndroidNativeCacheState();
    clearAndroidManualDisconnectRestoreBlock('android-clear-all-accounts');
    state.androidNativeStatus = 'All Android MWA cached authorizations cleared.';
    savePersistedState();
    pushToast('success', t('Android cache cleared'), t('All cached accounts removed.'));
  });
}

async function runReconnectIosCached(): Promise<void> {
  trackWalletConnectClick('ios_native', 'reconnect_cached');
  await run('connect', async () => {
    assertIosNativeRuntime();
    // Native IWA sessions live in the Keychain (per selected wallet); the legacy
    // path restores the latest across the JS cache. Pick the source that matches
    // the active backend for the currently selected wallet.
    const useNativeIwa =
      isNativeIwaWalletId(state.selectedIosWalletId) && (await refreshNativeIwaAdapterFlag());
    const restored = useNativeIwa
      ? await restoreLatestNativeIwaWallet({
          walletId: state.selectedIosWalletId as NativeIwaWalletId,
          cluster: state.cluster,
          logLevel: 'info',
        })
      : await restoreLatestIosNativeWallet({
          cluster: state.cluster,
          appUrl: iosNativeAppUrl(),
          rpcUrl: activeRpcUrl(),
          logLevel: 'info',
        });
    if (!restored) {
      throw new Error('No cached iOS wallet authorization is available. Connect once first.');
    }
    walletBackend = restored.backend;
    client = new SolanaSigningClient({ backend: walletBackend });
    state.address = restored.address;
    state.selectedIosWalletId = restored.walletId;
    state.selectedWalletName = restored.walletName;
    state.capabilities = await client.capabilities();
    state.iosAuthCacheCount = restored.cacheCount;
    state.iosNativeStatus = `Restored cached ${restored.walletName} authorization on ${state.cluster}.`;
    if (state.bridgeActive) {
      await connectBridgeHost();
    }
    await afterWalletConnected();
    savePersistedState();
    trackWalletConnectSuccess('ios_native', state.cluster, 'reconnect_cached');
    pushToast('success', t('iOS cache restored'), short(state.address));
  });
}

