const BEHAVIORAL_BASELINES_STORAGE_KEY = 'solana-agent-wallet-behavioral-baselines-v1';

function loadBehavioralBaselines(): Record<string, BehavioralBaseline> {
  try {
    const raw = window.localStorage.getItem(BEHAVIORAL_BASELINES_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    const out: Record<string, BehavioralBaseline> = {};
    for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
      const baseline = parseBehavioralBaseline(value);
      if (baseline) out[key] = baseline;
    }
    return out;
  } catch {
    return {};
  }
}

function saveBehavioralBaselines(): void {
  try {
    window.localStorage.setItem(BEHAVIORAL_BASELINES_STORAGE_KEY, JSON.stringify(state.behavioralBaselines));
  } catch {
    // Best-effort browser persistence.
  }
}

function parseBehavioralBaseline(value: unknown): BehavioralBaseline | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  if (record.schemaVersion !== 1) return null;
  if (typeof record.walletAddress !== 'string' || typeof record.cluster !== 'string') return null;
  return value as BehavioralBaseline;
}

const cloudPreferenceVersions: Partial<Record<CloudPreferenceNamespace, number>> = {};
const cloudPreferencePushes = new Map<CloudPreferenceNamespace, Promise<unknown>>();

let agentPoliciesCloudVersion = 0;
let lastCloudPoliciesPushPromise: Promise<unknown> | null = null;

async function syncAgentPoliciesToCloud(): Promise<void> {
  if (!cloudSessionMatchesWallet()) return;
  const payload = JSON.stringify({
    policies: state.agentPolicies,
    version: agentPoliciesCloudVersion + 1,
  });
  lastCloudPoliciesPushPromise = (async () => {
    try {
      const response = await cloudRequest('/api/preferences/agent-policies', {
        method: 'PUT',
        body: payload,
      });
      const data = response as { version?: number } | undefined;
      if (data && typeof data.version === 'number') {
        agentPoliciesCloudVersion = data.version;
        cloudPreferenceVersions['agent-policies'] = data.version;
      }
    } catch {
      // Best-effort: keep local state on failure.
    }
  })();
  await lastCloudPoliciesPushPromise;
}

async function syncCloudPreference(namespace: CloudPreferenceNamespace): Promise<void> {
  if (!cloudSessionMatchesWallet()) return;
  if (namespace === 'agent-policies') {
    await syncAgentPoliciesToCloud();
    return;
  }
  const payload = cloudPreferencePayload(namespace);
  const promise = (async () => {
    try {
      const response = await cloudRequest(`/api/preferences/${encodeURIComponent(namespace)}`, {
        method: 'PUT',
        body: JSON.stringify({
          payload,
          version: (cloudPreferenceVersions[namespace] ?? 0) + 1,
        }),
      });
      const record = cloudPreferenceRecordFromUnknown(response);
      if (record) {
        cloudPreferenceVersions[namespace] = record.version;
      }
    } catch {
      // Best-effort: local browser state remains authoritative on failure.
    }
  })();
  cloudPreferencePushes.set(namespace, promise);
  await promise;
}

async function hydratePreferencesFromCloud(): Promise<void> {
  if (!cloudSessionMatchesWallet()) return;
  try {
    const response = await cloudRequest('/api/preferences', { method: 'GET' });
    const records = cloudPreferenceRecordsFromResponse(response);
    const seen = new Set<CloudPreferenceNamespace>();
    let changed = false;
    for (const record of records) {
      seen.add(record.namespace);
      changed = applyCloudPreference(record) || changed;
    }
    for (const namespace of CLOUD_PREFERENCE_NAMESPACES) {
      if (!seen.has(namespace) && cloudPreferenceLocalNonEmpty(namespace)) {
        void syncCloudPreference(namespace);
      }
    }
    if (changed) render();
  } catch {
    // Keep local browser preferences if the cloud preference API is unavailable.
    await hydrateAgentPoliciesFromCloud();
  }
}

function cloudPreferencePayload(namespace: CloudPreferenceNamespace): unknown {
  switch (namespace) {
    case 'agent-policies':
      return state.agentPolicies;
    case 'protocol-connectors':
      return normalizeConnectedDapps(state.connectedDapps);
    case 'safety-rails':
      return state.safetyRails;
    case 'failure-policies':
      return state.failurePolicies;
    case 'custom-tokens':
      return state.customTokens;
    case 'ai-settings':
      return {
        mode: state.aiSettings.mode,
        provider: state.aiSettings.provider,
        apiFormat: state.aiSettings.apiFormat,
        baseUrl: state.aiSettings.baseUrl,
        model: state.aiSettings.model,
        multiReviewer: state.aiSettings.multiReviewer === true,
        autoBackgroundWatch: state.aiSettings.autoBackgroundWatch === true,
        ...(state.aiSettings.reasoningEffort ? { reasoningEffort: state.aiSettings.reasoningEffort } : {}),
        // The agent Instructions + Quick prompts ride the ai-settings namespace so they follow the
        // wallet across devices. Neither is a secret (secrets never sync). Nested under the same key
        // the planner prefs already share, so no new cloud namespace is needed.
        instructions: state.plannerPrefs.houseRules,
        quickPrompts: state.plannerPrefs.savedPrompts,
      };
    case 'recipient-rules':
      return state.recipientRules;
  }
}

function cloudPreferenceRecordsFromResponse(value: unknown): CloudPreferenceRecord[] {
  if (!isJsonObject(value) || !Array.isArray(value.preferences)) return [];
  return value.preferences
    .map(cloudPreferenceRecordFromUnknown)
    .filter((entry): entry is CloudPreferenceRecord => Boolean(entry));
}

function cloudPreferenceRecordFromUnknown(value: unknown): CloudPreferenceRecord | null {
  if (!isJsonObject(value)) return null;
  if (typeof value.namespace !== 'string' || !isCloudPreferenceNamespace(value.namespace)) return null;
  return {
    namespace: value.namespace,
    payload: value.payload,
    updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : '',
    version: typeof value.version === 'number' && Number.isFinite(value.version) ? value.version : 0,
  };
}

function isCloudPreferenceNamespace(value: string): value is CloudPreferenceNamespace {
  return (CLOUD_PREFERENCE_NAMESPACES as readonly string[]).includes(value);
}

function applyCloudPreference(record: CloudPreferenceRecord): boolean {
  cloudPreferenceVersions[record.namespace] = record.version;
  switch (record.namespace) {
    case 'agent-policies':
      return applyCloudAgentPolicies(record);
    case 'protocol-connectors': {
      state.connectedDapps = normalizeConnectedDapps(record.payload);
      saveConnectedDapps(state.connectedDapps);
      return true;
    }
    case 'safety-rails': {
      state.safetyRails = normalizeSafetyRails(record.payload);
      saveSafetyRailsAll();
      return true;
    }
    case 'failure-policies': {
      state.failurePolicies = normalizeFailurePolicies(record.payload);
      saveFailurePolicies({ sync: false });
      return true;
    }
    case 'custom-tokens': {
      state.customTokens = normalizeCustomTokens(record.payload);
      saveCustomTokens({ sync: false });
      return true;
    }
    case 'ai-settings': {
      return applyCloudAiSettings(record.payload);
    }
    case 'recipient-rules': {
      state.recipientRules = normalizeRecipientRules(record.payload);
      saveRecipientRules({ sync: false });
      return true;
    }
  }
}

function applyCloudAgentPolicies(record: CloudPreferenceRecord): boolean {
  const payload = Array.isArray(record.payload) ? record.payload : [];
  const cloudPolicies = payload
    .map(parseUserAgentPolicy)
    .filter((entry): entry is UserAgentPolicy => Boolean(entry));
  if (!cloudPolicies.length && !state.agentPolicies.length) return false;
  if (state.agentPolicies.length && cloudPolicies.length) {
    const localUpdated = state.agentPolicies.reduce(
      (acc, policy) => Math.max(acc, Date.parse(policy.updatedAt) || 0),
      0,
    );
    const cloudUpdated = cloudPolicies.reduce(
      (acc, policy) => Math.max(acc, Date.parse(policy.updatedAt) || 0),
      0,
    );
    if (localUpdated > cloudUpdated) {
      void syncAgentPoliciesToCloud();
      return false;
    }
  }
  state.agentPolicies = cloudPolicies;
  agentPoliciesCloudVersion = record.version;
  try {
    window.localStorage.setItem(AGENT_POLICIES_STORAGE_KEY, JSON.stringify(state.agentPolicies));
  } catch {
    // Best-effort persistence.
  }
  return true;
}

function applyCloudAiSettings(payload: unknown): boolean {
  if (!isJsonObject(payload)) return false;
  const previousApiKey = state.aiSettings.apiKey;
  saveCurrentSessionAiApiKey();
  const providerForMode = typeof payload.provider === 'string' && isAiProviderId(payload.provider)
    ? payload.provider
    : state.aiSettings.provider;
  if (typeof payload.mode === 'string' && isAiMode(payload.mode)) {
    aiModeSelectionExplicit = true;
    state.aiSettings.mode = normalizeAiModeForSurface(
      payload.mode,
      state.address || state.cloudSession.walletAddress,
      isMobileAiPathPolicySurface(),
      undefined,
      providerForMode,
    );
  }
  if (typeof payload.provider === 'string' && isAiProviderId(payload.provider)) {
    state.aiSettings.provider = payload.provider;
  }
  if (typeof payload.apiFormat === 'string' && isAiApiFormat(payload.apiFormat)) {
    state.aiSettings.apiFormat = payload.apiFormat;
  }
  if (typeof payload.baseUrl === 'string') {
    state.aiSettings.baseUrl = payload.baseUrl.trim();
  }
  if (typeof payload.model === 'string') {
    state.aiSettings.model = payload.model.trim();
  }
  state.aiSettings.multiReviewer = payload.multiReviewer === true;
  state.aiSettings.autoBackgroundWatch = payload.autoBackgroundWatch === true;
  if (isChatReasoningLevel(payload.reasoningEffort)) {
    state.aiSettings.reasoningEffort = payload.reasoningEffort;
  }
  ensureAiProviderAllowedForMode();
  state.aiSettings.mode = normalizeAiModeForSurface(
    state.aiSettings.mode,
    state.address || state.cloudSession.walletAddress,
    isMobileAiPathPolicySurface(),
    undefined,
    state.aiSettings.provider,
  );
  ensureAiProviderAllowedForMode();
  restoreVisibleAiKeyAfterRouteChange(previousApiKey);
  // Apply the synced Instructions + Quick prompts into plannerPrefs (their own store), guarding shape
  // and re-clamping to the local cap so a payload from a device with a higher limit can't overflow.
  if (typeof payload.instructions === 'string') {
    state.plannerPrefs.houseRules = payload.instructions.slice(0, PLANNER_HOUSE_RULES_MAX);
    // Keep the edit buffer in step with a synced value so the textarea + Saved/Unsaved state are correct.
    state.houseRulesDraft = state.plannerPrefs.houseRules;
    savePlannerPrefsLocalOnly();
  }
  if (Array.isArray(payload.quickPrompts)) {
    state.plannerPrefs.savedPrompts = payload.quickPrompts
      .map(parseSavedPrompt)
      .filter((entry): entry is SavedPrompt => entry !== null);
    savePlannerPrefsLocalOnly();
  }
  savePersistedState();
  if (state.aiSettings.autoBackgroundWatch) {
    startAgentBackgroundWatch();
  } else {
    stopAgentBackgroundWatch();
  }
  return true;
}

function cloudPreferenceLocalNonEmpty(namespace: CloudPreferenceNamespace): boolean {
  switch (namespace) {
    case 'agent-policies':
      return state.agentPolicies.length > 0;
    case 'protocol-connectors':
      return protocolConnectorsDifferFromDefaults(state.connectedDapps);
    case 'safety-rails':
      return stableJson(state.safetyRails) !== stableJson(defaultSafetyRails());
    case 'failure-policies':
      return stableJson(state.failurePolicies) !== stableJson(defaultFailurePoliciesList());
    case 'custom-tokens':
      return state.customTokens.length > 0;
    case 'ai-settings':
      return true;
    case 'recipient-rules':
      return state.recipientRules.recipients.length > 0;
  }
}

function protocolConnectorsDifferFromDefaults(value: ConnectedDappsState): boolean {
  const normalized = normalizeConnectedDapps(value);
  return PROTOCOL_CONNECTORS.some((connector) => {
    const enabled = normalized.entries[connector.id]?.enabled === true;
    return enabled !== connector.enabledByDefault;
  });
}

function normalizeSafetyRails(value: unknown): SafetyRailsState {
  const fallback = defaultSafetyRails();
  if (!isJsonObject(value)) return fallback;
  return {
    programs: normalizeProgramRules(value.programs, fallback.programs),
    tokens: normalizeTokenRules(value.tokens, fallback.tokens),
    spend: normalizeSpendCaps(value.spend, fallback.spend),
    slippage: normalizeSlippageCap(value.slippage, fallback.slippage),
  };
}

function normalizeProgramRules(value: unknown, fallback: ProgramRulesState): ProgramRulesState {
  if (!isJsonObject(value)) return fallback;
  return {
    enabled: value.enabled === true,
    mode: value.mode === 'block' ? 'block' : 'warn',
    allowlist: stringList(value.allowlist),
    blocklist: stringList(value.blocklist),
  };
}

function normalizeTokenRules(value: unknown, fallback: TokenRulesState): TokenRulesState {
  if (!isJsonObject(value)) return fallback;
  return {
    enabled: value.enabled === true,
    mode: value.mode === 'block' ? 'block' : 'warn',
    allowlist: stringList(value.allowlist),
    blocklist: stringList(value.blocklist),
  };
}

function normalizeSpendCaps(value: unknown, fallback: SpendCapsState): SpendCapsState {
  if (!isJsonObject(value)) return fallback;
  const caps = Array.isArray(value.caps)
    ? value.caps
        .map((entry): SpendCapEntry | null => {
          if (!isJsonObject(entry) || typeof entry.token !== 'string' || !entry.token.trim()) return null;
          const cap: SpendCapEntry = { token: entry.token.trim().slice(0, 64) };
          if (typeof entry.maxPerDay === 'number' && Number.isFinite(entry.maxPerDay)) cap.maxPerDay = entry.maxPerDay;
          if (typeof entry.maxPerWeek === 'number' && Number.isFinite(entry.maxPerWeek)) cap.maxPerWeek = entry.maxPerWeek;
          if (typeof entry.maxPerMonth === 'number' && Number.isFinite(entry.maxPerMonth)) cap.maxPerMonth = entry.maxPerMonth;
          return cap;
        })
        .filter((entry): entry is SpendCapEntry => Boolean(entry))
    : [];
  return {
    enabled: value.enabled === true,
    mode: value.mode === 'block' ? 'block' : 'warn',
    caps,
  };
}

function normalizeSlippageCap(value: unknown, fallback: SlippageCapState): SlippageCapState {
  if (!isJsonObject(value)) return fallback;
  const maxBps = typeof value.maxBps === 'number' && Number.isFinite(value.maxBps)
    ? Math.max(0, Math.min(10_000, Math.floor(value.maxBps)))
    : fallback.maxBps;
  return {
    enabled: value.enabled === true,
    mode: value.mode === 'block' ? 'block' : 'warn',
    maxBps,
  };
}

function normalizeFailurePolicies(value: unknown): FailureRetryPolicy[] {
  if (!Array.isArray(value)) return defaultFailurePoliciesList();
  const byKind = new Map<TransactionFailureKind, FailureRetryPolicy>();
  for (const entry of value) {
    const policy = parseFailurePolicy(entry);
    if (policy) byKind.set(policy.kind, policy);
  }
  return FAILURE_RETRY_KINDS.map((kind) =>
    byKind.get(kind) ?? { kind, mode: 'ask' as FailureRetryMode, maxAttempts: 2 },
  );
}

function normalizeCustomTokens(value: unknown): CustomToken[] {
  return Array.isArray(value)
    ? value.map(parseCustomToken).filter((entry): entry is CustomToken => Boolean(entry))
    : [];
}

function stringList(value: unknown): string[] {
  return Array.isArray(value)
    ? value.filter((entry): entry is string => typeof entry === 'string').map((entry) => entry.trim()).filter(Boolean).slice(0, 200)
    : [];
}

async function hydrateAgentPoliciesFromCloud(): Promise<void> {
  if (!cloudSessionMatchesWallet()) return;
  try {
    const response = await cloudRequest('/api/preferences/agent-policies', { method: 'GET' });
    const data = response as { policies?: unknown; version?: number } | undefined;
    if (!data || !Array.isArray(data.policies)) return;
    const cloudPolicies = data.policies
      .map(parseUserAgentPolicy)
      .filter((entry): entry is UserAgentPolicy => Boolean(entry));
    if (!cloudPolicies.length && !state.agentPolicies.length) return;
    if (state.agentPolicies.length && cloudPolicies.length) {
      const localUpdated = state.agentPolicies.reduce(
        (acc, policy) => Math.max(acc, Date.parse(policy.updatedAt) || 0),
        0,
      );
      const cloudUpdated = cloudPolicies.reduce(
        (acc, policy) => Math.max(acc, Date.parse(policy.updatedAt) || 0),
        0,
      );
      if (localUpdated > cloudUpdated) {
        // Local is newer - push it
        await syncAgentPoliciesToCloud();
        return;
      }
    }
    state.agentPolicies = cloudPolicies;
    agentPoliciesCloudVersion = typeof data.version === 'number' ? data.version : 0;
    cloudPreferenceVersions['agent-policies'] = agentPoliciesCloudVersion;
    try {
      window.localStorage.setItem(AGENT_POLICIES_STORAGE_KEY, JSON.stringify(state.agentPolicies));
    } catch {
      // Best-effort persistence.
    }
    render();
  } catch {
    // Best-effort: keep local state on failure.
  }
}

function parseUserAgentPolicy(value: unknown): UserAgentPolicy | null {
  if (!isJsonObject(value)) return null;
  if (typeof value.id !== 'string' || typeof value.label !== 'string') return null;
  if (!isAgentPolicyKind(value.kind)) return null;
  const params = isJsonObject(value.params)
    ? Object.fromEntries(
        Object.entries(value.params).filter(([, entry]) => typeof entry === 'string'),
      ) as Record<string, string>
    : undefined;
  return {
    id: value.id,
    label: value.label,
    kind: value.kind,
    enabled: value.enabled !== false,
    detail: typeof value.detail === 'string' ? value.detail : '',
    ...(params && Object.keys(params).length ? { params } : {}),
    createdAt: typeof value.createdAt === 'string' ? value.createdAt : new Date().toISOString(),
    updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : new Date().toISOString(),
  };
}

function isAgentPolicyKind(value: unknown): value is AgentPolicyKind {
  return value === 'slippage_max' ||
    value === 'amount_max' ||
    value === 'token_allow' ||
    value === 'token_block' ||
    value === 'require_known_recipient' ||
    value === 'flag_unknown_mint' ||
    value === 'custom';
}

function defaultAgentPolicyDraft(): AgentPolicyDraft {
  return {
    label: '',
    kind: 'slippage_max',
    detail: '',
    paramValue: '',
  };
}

function emptyRecipientRules(): RecipientRulesState {
  return {
    enabled: false,
    allowListEnabled: false,
    blockListEnabled: true,
    recipients: [],
  };
}

function normalizeRecipientRules(value: unknown): RecipientRulesState {
  if (!isJsonObject(value)) return emptyRecipientRules();
  const recipients = Array.isArray(value.recipients)
    ? value.recipients.map(savedRecipientFromUnknown).filter((entry): entry is SavedRecipient => Boolean(entry))
    : [];
  return {
    enabled: value.enabled === true,
    allowListEnabled: value.allowListEnabled === true,
    blockListEnabled: value.blockListEnabled !== false,
    recipients: mergeSavedRecipients(recipients),
  };
}

function savedRecipientFromUnknown(value: unknown): SavedRecipient | null {
  if (!isJsonObject(value)) return null;
  const address = typeof value.address === 'string' ? value.address.trim() : '';
  const name = typeof value.name === 'string' ? value.name.trim() : '';
  if (!name || !isSolanaPublicKeyText(address)) return null;
  const now = new Date().toISOString();
  const policy = isRecipientPolicy(value.policy) ? value.policy : 'known';
  const tags = Array.isArray(value.tags)
    ? value.tags
        .filter((entry): entry is string => typeof entry === 'string')
        .map((entry) => entry.trim())
        .filter((entry) => entry.length > 0)
        .slice(0, 8)
    : [];
  return {
    id: typeof value.id === 'string' && value.id ? value.id : newId('recipient'),
    name: name.slice(0, 48),
    address,
    policy,
    ...(typeof value.note === 'string' && value.note.trim() ? { note: value.note.trim().slice(0, 140) } : {}),
    ...(tags.length ? { tags } : {}),
    ...(value.isMine === true ? { isMine: true } : {}),
    ...(typeof value.lastUsedAt === 'string' && value.lastUsedAt ? { lastUsedAt: value.lastUsedAt } : {}),
    createdAt: typeof value.createdAt === 'string' ? value.createdAt : now,
    updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : now,
  };
}

function mergeSavedRecipients(recipients: SavedRecipient[]): SavedRecipient[] {
  const byAddress = new Map<string, SavedRecipient>();
  for (const recipient of recipients) {
    const key = recipient.address.trim();
    if (!key) continue;
    const current = byAddress.get(key);
    if (!current || recipient.updatedAt.localeCompare(current.updatedAt) >= 0) {
      const cleanTags = Array.isArray(recipient.tags)
        ? recipient.tags.map((tag) => tag.trim()).filter((tag) => tag.length > 0).slice(0, 8)
        : [];
      byAddress.set(key, {
        ...recipient,
        name: recipient.name.trim().slice(0, 48),
        address: key,
        ...(recipient.note?.trim() ? { note: recipient.note.trim().slice(0, 140) } : { note: undefined }),
        ...(cleanTags.length ? { tags: cleanTags } : { tags: undefined }),
        ...(recipient.isMine === true ? { isMine: true } : { isMine: undefined }),
        ...(recipient.lastUsedAt ? { lastUsedAt: recipient.lastUsedAt } : { lastUsedAt: undefined }),
      });
    }
  }
  return [...byAddress.values()].sort((left, right) => {
    const policyRank = recipientPolicyRank(left.policy) - recipientPolicyRank(right.policy);
    if (policyRank !== 0) return policyRank;
    const leftKey = left.lastUsedAt ?? left.createdAt;
    const rightKey = right.lastUsedAt ?? right.createdAt;
    const recencyRank = rightKey.localeCompare(leftKey);
    if (recencyRank !== 0) return recencyRank;
    return left.name.localeCompare(right.name);
  });
}

function recipientPolicyRank(policy: RecipientPolicy): number {
  switch (policy) {
    case 'allow':
      return 0;
    case 'known':
      return 1;
    case 'block':
      return 2;
  }
}

function isRecipientPolicy(value: unknown): value is RecipientPolicy {
  return value === 'known' || value === 'allow' || value === 'block';
}

function isSolanaPublicKeyText(value: string): boolean {
  try {
    new PublicKey(value.trim());
    return true;
  } catch {
    return false;
  }
}

function readCompletedCloudWorkspaceDeleteNotice(): { deletedCount: number } | null {
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.get('cloudWorkspaceDeleted') !== '1') return null;
    const rawCount = Number(params.get('deletedCount') ?? '0');
    return { deletedCount: Number.isFinite(rawCount) && rawCount > 0 ? Math.floor(rawCount) : 0 };
  } catch {
    return null;
  }
}

function readLaunchParams(): {
  bridgeUrl?: string;
  bridgeToken?: string;
  cliMode?: boolean;
  cliIntent?: CliIntentName;
  cliSurface?: CliSurfaceName;
  cliActionId?: string;
  cliRequestId?: string;
  cliWalletAddress?: string;
  walletBrand?: string;
  pairing?: string;
} {
  const params = new URLSearchParams(window.location.search);
  const bridgeUrl = params.get('bridgeUrl')?.trim();
  // Token comes from the URL fragment (CLI/desktop launches) or query (legacy /
  // QR / deeplink); fragments are never sent to a remote wallet-host origin.
  const bridgeToken = readBridgeLaunchToken(window.location.search, window.location.hash);
  if (bridgeToken) {
    saveSessionBridgeToken(bridgeToken);
  }
  const routeIntent = cliIntentFromPathname(window.location.pathname);
  const cliMode = params.get('mode')?.trim() === 'cli' || Boolean(routeIntent);
  const rawIntent = params.get('intent')?.trim() || routeIntent;
  const cliIntent: CliIntentName | undefined =
    rawIntent === 'connect' ||
    rawIntent === 'disconnect' ||
    rawIntent === 'approve' ||
    rawIntent === 'sign' ||
    rawIntent === 'sign-in' ||
    rawIntent === 'sign-out' ||
    rawIntent === 'delete-storage'
      ? rawIntent
      : undefined;
  const cliActionId = params.get('actionId')?.trim() || undefined;
  const cliRequestId = params.get('requestId')?.trim() || undefined;
  const cliWalletAddress = params.get('walletAddress')?.trim() || undefined;
  const rawSurface = params.get('surface')?.trim();
  const cliSurface: CliSurfaceName | undefined = rawSurface === 'desktop' ? 'desktop' : undefined;
  const qrConnectRoute = normalizePathname(window.location.pathname) === '/qr-connect';
  // Legacy mobile/deeplink flows can pass ?wallet=<brandId> to auto-select a
  // browser wallet on /app. Desktop CLI wallet-host routes also use it to
  // constrain /connect and /sign to the exact extension picked in the app.
  const rawWalletBrand = params.get('wallet')?.trim() || undefined;
  const walletBrand = rawWalletBrand && !qrConnectRoute && (!cliMode || cliSurface === 'desktop')
    ? rawWalletBrand
    : undefined;
  // The desktop's Phantom QR path embeds a pairing UUID. When the wallet-host
  // connects, it POSTs its address to `/api/pair/<pairing>/host` and runs an
  // inbox loop so the desktop can sign through the relay.
  const rawPairing = !cliMode && !qrConnectRoute ? params.get('pairing')?.trim() : undefined;
  const pairing =
    rawPairing && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(rawPairing)
      ? rawPairing
      : undefined;
  return {
    ...(bridgeUrl && isTrustedBridgeUrl(bridgeUrl) ? { bridgeUrl } : {}),
    ...(bridgeToken ? { bridgeToken } : {}),
    ...(cliMode ? { cliMode } : {}),
    ...(cliIntent ? { cliIntent } : {}),
    ...(cliSurface ? { cliSurface } : {}),
    ...(cliActionId ? { cliActionId } : {}),
    ...(cliRequestId ? { cliRequestId } : {}),
    ...(cliWalletAddress ? { cliWalletAddress } : {}),
    ...(walletBrand ? { walletBrand } : {}),
    ...(pairing ? { pairing } : {}),
  };
}

function cliIntentFromPathname(pathname: string): CliIntentName | undefined {
  switch (normalizePathname(pathname)) {
    case '/connect':
      return 'connect';
    case '/disconnect':
      return 'disconnect';
    case '/approve':
      return 'approve';
    case '/sign':
      return 'sign';
    case '/sign-in':
      return 'sign-in';
    case '/sign-out':
      return 'sign-out';
    case '/delete-storage':
      return 'delete-storage';
    default:
      return undefined;
  }
}

function sessionBridgeToken(): string | undefined {
  const value = window.sessionStorage.getItem(BRIDGE_TOKEN_SESSION_KEY)?.trim();
  return value || undefined;
}

// In Tauri mode the Rust side rotates the legacy `local-agent-wallet` token to
// a per-install random one (see lib.rs:1129-1130, generated_bridge_token).
// Without this mirror the webview keeps the legacy default and every
// /bridge/* request returns 401 — desktop hangs on "Waiting for browser…"
// even after the external browser POSTs /bridge/connect successfully.
function syncBridgeConfigFromTauriStatus(status: TauriBridgeStatus | null): void {
  const update = computeBridgeConfigUpdate(status);
  if (update.bridgeUrl) state.bridgeUrl = update.bridgeUrl;
  if (update.bridgeToken) {
    state.bridgeToken = update.bridgeToken;
    saveSessionBridgeToken(update.bridgeToken);
  }
}

function saveSessionBridgeToken(value: string): void {
  try {
    if (value) {
      window.sessionStorage.setItem(BRIDGE_TOKEN_SESSION_KEY, value);
    } else {
      window.sessionStorage.removeItem(BRIDGE_TOKEN_SESSION_KEY);
    }
  } catch {
    // Session-only convenience; local bridge can still be configured manually.
  }
}

function clearSensitiveLaunchParams(): void {
  const url = new URL(window.location.href);
  const had =
    url.searchParams.has('token') ||
    url.searchParams.has('intent') ||
    url.searchParams.has('actionId') ||
    url.searchParams.has('requestId') ||
    url.searchParams.has('cloudWorkspaceDeleted') ||
    url.searchParams.has('deletedCount');
  if (!had) return;
  url.searchParams.delete('token');
  url.searchParams.delete('intent');
  url.searchParams.delete('actionId');
  url.searchParams.delete('requestId');
  url.searchParams.delete('cloudWorkspaceDeleted');
  url.searchParams.delete('deletedCount');
  window.history.replaceState(window.history.state, document.title, `${url.pathname}${url.search}${url.hash}`);
}

function clearWalletBrandLaunchParam(): void {
  const url = new URL(window.location.href);
  if (!url.searchParams.has('wallet')) return;
  url.searchParams.delete('wallet');
  window.history.replaceState(window.history.state, document.title, `${url.pathname}${url.search}${url.hash}`);
}

function storageWalletKeyPart(walletAddress: string): string {
  return walletAddress.trim().toLowerCase().replace(/[^a-z0-9_-]/g, '_');
}

function walletScopedStorageKey(baseKey: string, walletAddress: string): string {
  const keyPart = storageWalletKeyPart(walletAddress);
  return keyPart ? `${baseKey}:${keyPart}` : baseKey;
}

function sameWalletAddress(left?: string, right?: string): boolean {
  const a = left?.trim().toLowerCase() ?? '';
  const b = right?.trim().toLowerCase() ?? '';
  return Boolean(a && b && a === b);
}

function recordMatchesWalletScope(record: { walletAddress?: string }, walletAddress: string): boolean {
  return !walletAddress || !record.walletAddress || sameWalletAddress(record.walletAddress, walletAddress);
}

function localStorageJsonArray(key: string): unknown[] {
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

let legacyWalletStorageMigrated = false;

function migrateLegacyWalletScopedStorage(): void {
  if (legacyWalletStorageMigrated) return;
  legacyWalletStorageMigrated = true;
  try {
    migrateGeneratedPlanStorage();
    migrateBrowserWorkflowStorage();
    migrateCompletedLedgerStorage();
  } catch {
    // Legacy storage remains readable from the base keys.
  }
}

function migrateGeneratedPlanStorage(): void {
  const legacyPlans = localStorageJsonArray(GENERATED_PLANS_STORAGE_KEY).filter(isGeneratedPlanRecord);
  const byWallet = groupByWallet(legacyPlans);
  for (const [walletAddress, records] of byWallet) {
    const key = walletScopedStorageKey(GENERATED_PLANS_STORAGE_KEY, walletAddress);
    const existing = localStorageJsonArray(key).filter(isGeneratedPlanRecord);
    window.localStorage.setItem(key, JSON.stringify(mergeGeneratedPlans(existing, records)));
  }
}

function migrateBrowserWorkflowStorage(): void {
  const legacy = parseBrowserWorkflowStorage(BROWSER_WORKFLOW_STORAGE_KEY);
  const wallets = new Set<string>();
  for (const action of legacy.preparedActions) wallets.add(action.walletAddress);
  for (const payment of legacy.recurringPayments) wallets.add(payment.walletAddress);
  for (const receipt of legacy.receipts) wallets.add(receipt.walletAddress);
  for (const walletAddress of wallets) {
    const key = walletScopedStorageKey(BROWSER_WORKFLOW_STORAGE_KEY, walletAddress);
    const existing = parseBrowserWorkflowStorage(key);
    const scoped = normalizeBrowserWorkflowState({
      preparedActions: [
        ...existing.preparedActions,
        ...legacy.preparedActions.filter((action) => recordMatchesWalletScope(action, walletAddress)),
      ],
      recurringPayments: [
        ...existing.recurringPayments,
        ...legacy.recurringPayments.filter((payment) => recordMatchesWalletScope(payment, walletAddress)),
      ],
      receipts: [
        ...existing.receipts,
        ...legacy.receipts.filter((receipt) => recordMatchesWalletScope(receipt, walletAddress)),
      ],
    }, walletAddress);
    window.localStorage.setItem(key, JSON.stringify(scoped));
  }
}

function migrateCompletedLedgerStorage(): void {
  const legacyCompleted = localStorageJsonArray(LOCAL_COMPLETED_STORAGE_KEY).filter(isCompletedPlanRecord);
  const byWallet = groupByWallet(legacyCompleted);
  for (const [walletAddress, records] of byWallet) {
    const key = walletScopedStorageKey(LOCAL_COMPLETED_STORAGE_KEY, walletAddress);
    const existing = localStorageJsonArray(key).filter(isCompletedPlanRecord);
    window.localStorage.setItem(key, JSON.stringify(mergeCompletedPlanRecords(existing, records)));
  }
}

function groupByWallet<T extends { walletAddress?: string }>(records: T[]): Map<string, T[]> {
  const byWallet = new Map<string, T[]>();
  for (const record of records) {
    const walletAddress = record.walletAddress?.trim();
    if (!walletAddress) continue;
    byWallet.set(walletAddress, [...(byWallet.get(walletAddress) ?? []), record]);
  }
  return byWallet;
}

function loadGeneratedPlans(walletAddress = ''): GeneratedPlanRecord[] {
  try {
    migrateLegacyWalletScopedStorage();
    const legacy = localStorageJsonArray(GENERATED_PLANS_STORAGE_KEY);
    const scoped = walletAddress ? localStorageJsonArray(walletScopedStorageKey(GENERATED_PLANS_STORAGE_KEY, walletAddress)) : [];
    return mergeGeneratedPlans([...legacy, ...scoped].filter(isGeneratedPlanRecord).map((record) => ({
      ...record,
      workflowSource: record.workflowSource ?? 'browser',
    }))).filter((record) => recordMatchesWalletScope(record, walletAddress));
  } catch {
    return [];
  }
}

function saveGeneratedPlans(): void {
  try {
    state.generatedPlans = mergeGeneratedPlans(state.generatedPlans);
    const localPlans = state.generatedPlans
      .filter((record) => record.workflowSource !== 'cloud')
      .filter((record) => recordMatchesWalletScope(record, state.address));
    window.localStorage.setItem(
      GENERATED_PLANS_STORAGE_KEY,
      JSON.stringify(localPlans),
    );
    if (state.address) {
      window.localStorage.setItem(
        walletScopedStorageKey(GENERATED_PLANS_STORAGE_KEY, state.address),
        JSON.stringify(localPlans),
      );
    }
    persistLocalCompletedSnapshot();
  } catch {
    // Best-effort browser persistence.
  }
}

function loadBrowserWorkflowState(walletAddress = ''): BrowserWorkflowState {
  try {
    migrateLegacyWalletScopedStorage();
    const legacy = parseBrowserWorkflowStorage(BROWSER_WORKFLOW_STORAGE_KEY);
    const scoped = walletAddress ? parseBrowserWorkflowStorage(walletScopedStorageKey(BROWSER_WORKFLOW_STORAGE_KEY, walletAddress)) : emptyBrowserWorkflowState();
    return normalizeBrowserWorkflowState({
      preparedActions: [...legacy.preparedActions, ...scoped.preparedActions],
      recurringPayments: [...legacy.recurringPayments, ...scoped.recurringPayments],
      receipts: [...legacy.receipts, ...scoped.receipts],
    }, walletAddress);
  } catch {
    return emptyBrowserWorkflowState();
  }
}

function parseBrowserWorkflowStorage(key: string): BrowserWorkflowState {
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return emptyBrowserWorkflowState();
    const parsed = JSON.parse(raw) as Partial<BrowserWorkflowState>;
    return normalizeBrowserWorkflowState(parsed);
  } catch {
    return emptyBrowserWorkflowState();
  }
}

function emptyBrowserWorkflowState(): BrowserWorkflowState {
  return {
    preparedActions: [],
    recurringPayments: [],
    receipts: [],
  };
}

function normalizeBrowserWorkflowState(input: Partial<BrowserWorkflowState>, walletAddress = ''): BrowserWorkflowState {
  return {
    preparedActions: mergePreparedActions((input.preparedActions ?? []).filter(isPreparedAction).map((action) => ({
      ...action,
      workflowSource: 'browser' as WorkflowRecordSource,
    })).filter((action) => recordMatchesWalletScope(action, walletAddress))),
    recurringPayments: mergeRecurringPayments(withRecurringPaymentSource(input.recurringPayments ?? [], 'browser')
      .filter((payment) => recordMatchesWalletScope(payment, walletAddress))),
    receipts: mergeActionReceipts((input.receipts ?? []).filter(isActionReceipt)
      .filter((receipt) => recordMatchesWalletScope(receipt, walletAddress))),
  };
}

function saveBrowserWorkflowState(): void {
  try {
    const workflow = normalizeBrowserWorkflowState({
      preparedActions: state.preparedActions.filter(isBrowserWorkflowId),
      recurringPayments: state.recurringPayments.filter((payment) => recurringPaymentWorkflowSource(payment) === 'browser'),
      receipts: state.receipts.filter((receipt) => isBrowserWorkflowId(receipt.actionId)),
    }, state.address);
    window.localStorage.setItem(BROWSER_WORKFLOW_STORAGE_KEY, JSON.stringify(workflow));
    if (state.address) {
      window.localStorage.setItem(
        walletScopedStorageKey(BROWSER_WORKFLOW_STORAGE_KEY, state.address),
        JSON.stringify(workflow),
      );
    }
    persistLocalCompletedSnapshot();
  } catch {
    // Best-effort browser workflow persistence.
  }
}

// --- Chat history persistence (browser-local, wallet-scoped) -----------------
function emptyChatHistoryState(): ChatHistoryState {
  return { schemaVersion: CHAT_HISTORY_SCHEMA_VERSION, sessions: [], activeSessionId: '' };
}

function isChatMessageRole(value: unknown): value is ChatMessageRole {
  return value === 'user' || value === 'assistant' || value === 'system';
}

function clampChatToolEvidence(input: unknown): ChatToolEvidence[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const out: ChatToolEvidence[] = [];
  for (const raw of input.slice(-MAX_CHAT_TOOL_EVIDENCE)) {
    if (!raw || typeof raw !== 'object') continue;
    const item = raw as Record<string, unknown>;
    if (typeof item.tool !== 'string') continue;
    out.push({
      tool: item.tool,
      ...(typeof item.callId === 'string' ? { callId: item.callId } : {}),
      ...(typeof item.argsSummary === 'string' ? { argsSummary: item.argsSummary.slice(0, 600) } : {}),
      ...(typeof item.resultSummary === 'string'
        ? { resultSummary: item.resultSummary.slice(0, MAX_CHAT_TOOL_RESULT_CHARS) }
        : {}),
      at: typeof item.at === 'string' ? item.at : new Date().toISOString(),
    });
  }
  return out.length ? out : undefined;
}

function normalizeChatResearchTone(value: unknown): ChatResearchTone | undefined {
  return value === 'good' || value === 'warn' || value === 'fail' || value === 'neutral' ? value : undefined;
}

function normalizeChatResearchRows(input: unknown): ChatResearchRow[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const rows = input.slice(0, 20).map((raw): ChatResearchRow | null => {
    const row = asRecord(raw);
    if (!row || typeof row.label !== 'string' || typeof row.value !== 'string') return null;
    return {
      label: row.label.slice(0, 80),
      value: row.value.slice(0, 180),
      ...(normalizeChatResearchTone(row.tone) ? { tone: normalizeChatResearchTone(row.tone) } : {}),
    };
  }).filter((row): row is ChatResearchRow => Boolean(row));
  return rows.length ? rows : undefined;
}

function normalizeChatResearchHero(input: unknown): ChatResearchHero | undefined {
  const hero = asRecord(input);
  if (!hero || typeof hero.label !== 'string' || typeof hero.value !== 'string') return undefined;
  return {
    label: hero.label.slice(0, 80),
    value: hero.value.slice(0, 100),
    ...(typeof hero.detail === 'string' ? { detail: hero.detail.slice(0, 180) } : {}),
    ...(normalizeChatResearchTone(hero.tone) ? { tone: normalizeChatResearchTone(hero.tone) } : {}),
    ...(typeof hero.meter === 'number' && Number.isFinite(hero.meter) ? { meter: Math.max(0, Math.min(100, Math.round(hero.meter))) } : {}),
  };
}

function normalizeChatResearchBadges(input: unknown): ChatResearchBadge[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const badges = input.slice(0, 12).map((raw): ChatResearchBadge | null => {
    const badge = asRecord(raw);
    if (!badge || typeof badge.label !== 'string') return null;
    return {
      label: badge.label.slice(0, 80),
      ...(typeof badge.value === 'string' ? { value: badge.value.slice(0, 80) } : {}),
      ...(normalizeChatResearchTone(badge.tone) ? { tone: normalizeChatResearchTone(badge.tone) } : {}),
    };
  }).filter((badge): badge is ChatResearchBadge => Boolean(badge));
  return badges.length ? badges : undefined;
}

function normalizeChatResearchBars(input: unknown): ChatResearchBar[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const bars = input.slice(0, 8).map((raw): ChatResearchBar | null => {
    const bar = asRecord(raw);
    if (!bar || typeof bar.label !== 'string' || typeof bar.value !== 'number' || !Number.isFinite(bar.value)) return null;
    return {
      label: bar.label.slice(0, 80),
      value: Math.max(0, Math.min(100, Math.round(bar.value))),
      ...(typeof bar.valueLabel === 'string' ? { valueLabel: bar.valueLabel.slice(0, 80) } : {}),
      ...(normalizeChatResearchTone(bar.tone) ? { tone: normalizeChatResearchTone(bar.tone) } : {}),
    };
  }).filter((bar): bar is ChatResearchBar => Boolean(bar));
  return bars.length ? bars : undefined;
}

function normalizeChatResearchChecklist(input: unknown): ChatResearchIndicator[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const items = input.slice(0, 12).map((raw): ChatResearchIndicator | null => {
    const item = asRecord(raw);
    if (!item || typeof item.label !== 'string') return null;
    return {
      label: item.label.slice(0, 90),
      ...(typeof item.detail === 'string' ? { detail: item.detail.slice(0, 100) } : {}),
      ...(normalizeChatResearchTone(item.tone) ? { tone: normalizeChatResearchTone(item.tone) } : {}),
      ...(typeof item.active === 'boolean' ? { active: item.active } : {}),
    };
  }).filter((item): item is ChatResearchIndicator => Boolean(item));
  return items.length ? items : undefined;
}

function normalizeChatResearchSwapFields(input: Record<string, unknown>): Partial<Pick<ChatResearchCard, 'swapMint' | 'swapSymbol' | 'swapDecimals' | 'swapLogoURI'>> {
  const mint = typeof input.swapMint === 'string' ? input.swapMint.trim().slice(0, 60) : '';
  if (!mint || !CHAT_BASE58_MINT.test(mint)) return {};
  const decimals = typeof input.swapDecimals === 'number' && Number.isFinite(input.swapDecimals)
    ? Math.max(0, Math.min(18, Math.floor(input.swapDecimals)))
    : undefined;
  return {
    swapMint: mint,
    ...(typeof input.swapSymbol === 'string' ? { swapSymbol: input.swapSymbol.slice(0, 40) } : {}),
    ...(decimals !== undefined ? { swapDecimals: decimals } : {}),
    ...(typeof input.swapLogoURI === 'string' ? { swapLogoURI: input.swapLogoURI.slice(0, 300) } : {}),
  };
}

function normalizeChatResearchItems(input: unknown): ChatResearchListItem[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const items = input.slice(0, 30).map((raw): ChatResearchListItem | null => {
    const item = asRecord(raw);
    if (!item || typeof item.title !== 'string') return null;
    return {
      title: item.title.slice(0, 80),
      ...(typeof item.subtitle === 'string' ? { subtitle: item.subtitle.slice(0, 140) } : {}),
      ...(typeof item.mint === 'string' ? { mint: item.mint.slice(0, 60) } : {}),
      ...normalizeChatResearchSwapFields(item),
      ...(typeof item.value === 'string' ? { value: item.value.slice(0, 80) } : {}),
      ...(typeof item.meta === 'string' ? { meta: item.meta.slice(0, 140) } : {}),
      ...(normalizeChatResearchTone(item.tone) ? { tone: normalizeChatResearchTone(item.tone) } : {}),
      ...(typeof item.rank === 'number' && Number.isFinite(item.rank) ? { rank: Math.max(1, Math.min(99, Math.floor(item.rank))) } : {}),
      ...(typeof item.price === 'string' ? { price: item.price.slice(0, 80) } : {}),
      ...(typeof item.change === 'string' ? { change: item.change.slice(0, 80) } : {}),
      ...(typeof item.liquidity === 'string' ? { liquidity: item.liquidity.slice(0, 80) } : {}),
      ...(typeof item.volume === 'string' ? { volume: item.volume.slice(0, 80) } : {}),
    };
  }).filter((item): item is ChatResearchListItem => Boolean(item));
  return items.length ? items : undefined;
}

function normalizeChatResearchChart(input: unknown): ChatResearchChart | undefined {
  const chart = asRecord(input);
  if (!chart || (chart.kind !== 'sparkline' && chart.kind !== 'bars') || !Array.isArray(chart.values)) return undefined;
  const values = chart.values
    .filter((value): value is number => typeof value === 'number' && Number.isFinite(value))
    .slice(0, 24);
  if (!values.length) return undefined;
  const labels = Array.isArray(chart.labels)
    ? chart.labels.filter((label): label is string => typeof label === 'string').slice(0, 24).map((label) => label.slice(0, 40))
    : undefined;
  return {
    kind: chart.kind,
    values,
    ...(typeof chart.label === 'string' ? { label: chart.label.slice(0, 80) } : {}),
    ...(labels?.length ? { labels } : {}),
    ...(normalizeChatResearchTone(chart.tone) ? { tone: normalizeChatResearchTone(chart.tone) } : {}),
  };
}

function normalizeChatResearchSections(input: unknown): ChatResearchSection[] | undefined {
  if (!Array.isArray(input)) return undefined;
  const sections = input.slice(0, 8).map((raw): ChatResearchSection | null => {
    const section = asRecord(raw);
    if (!section || typeof section.title !== 'string') return null;
    const bullets = Array.isArray(section.bullets)
      ? section.bullets.filter((bullet): bullet is string => typeof bullet === 'string').slice(0, 8).map((bullet) => bullet.slice(0, 180))
      : undefined;
    return {
      title: section.title.slice(0, 80),
      ...(normalizeChatResearchRows(section.rows) ? { rows: normalizeChatResearchRows(section.rows) } : {}),
      ...(bullets?.length ? { bullets } : {}),
    };
  }).filter((section): section is ChatResearchSection => Boolean(section));
  return sections.length ? sections : undefined;
}

function normalizeChatResearchCard(input: unknown): ChatResearchCard | undefined {
  const card = asRecord(input);
  if (!card || typeof card.kind !== 'string' || !chatResearchActionById(card.kind)) return undefined;
  if (typeof card.title !== 'string' || typeof card.summary !== 'string') return undefined;
  return {
    kind: card.kind as ChatResearchActionId,
    title: card.title.slice(0, 120),
    ...(typeof card.subtitle === 'string' ? { subtitle: card.subtitle.slice(0, 220) } : {}),
    ...(typeof card.target === 'string' ? { target: card.target.slice(0, 120) } : {}),
    ...normalizeChatResearchSwapFields(card),
    ...(typeof card.source === 'string' ? { source: card.source.slice(0, 80) } : {}),
    generatedAt: typeof card.generatedAt === 'string' ? card.generatedAt : new Date().toISOString(),
    summary: card.summary.slice(0, 240),
    ...(normalizeChatResearchHero(card.hero) ? { hero: normalizeChatResearchHero(card.hero) } : {}),
    ...(normalizeChatResearchRows([card.verdict]) ? { verdict: normalizeChatResearchRows([card.verdict])?.[0] } : {}),
    ...(normalizeChatResearchBadges(card.badges) ? { badges: normalizeChatResearchBadges(card.badges) } : {}),
    ...(normalizeChatResearchRows(card.highlights) ? { highlights: normalizeChatResearchRows(card.highlights) } : {}),
    ...(normalizeChatResearchBars(card.bars) ? { bars: normalizeChatResearchBars(card.bars) } : {}),
    ...(normalizeChatResearchChecklist(card.checklist) ? { checklist: normalizeChatResearchChecklist(card.checklist) } : {}),
    ...(normalizeChatResearchChart(card.chart) ? { chart: normalizeChatResearchChart(card.chart) } : {}),
    ...(normalizeChatResearchRows(card.rows) ? { rows: normalizeChatResearchRows(card.rows) } : {}),
    ...(normalizeChatResearchSections(card.sections) ? { sections: normalizeChatResearchSections(card.sections) } : {}),
    ...(normalizeChatResearchItems(card.items) ? { items: normalizeChatResearchItems(card.items) } : {}),
  };
}

function normalizeChatDecisionCheckCard(input: unknown): ChatDecisionCheckCard | undefined {
  const card = asRecord(input);
  if (!card || typeof card.prompt !== 'string') return undefined;
  const review = parseAgentPlanReviewState(card.review);
  if (!review) return undefined;
  const rawAction = asRecord(card.action);
  const action = rawAction && typeof rawAction.kind === 'string' && typeof rawAction.summary === 'string'
    ? { kind: rawAction.kind.slice(0, 40), summary: rawAction.summary.slice(0, 200) }
    : undefined;
  return {
    prompt: card.prompt.slice(0, CHAT_MAX_INPUT_CHARS),
    review,
    ...(action ? { action } : {}),
  };
}

function normalizeChatMessage(raw: unknown): ChatMessage | null {
  if (!raw || typeof raw !== 'object') return null;
  const input = raw as Record<string, unknown>;
  if (!isChatMessageRole(input.role)) return null;
  if (typeof input.content !== 'string' && typeof input.proposal !== 'object') return null;
  // Preserve unknown future fields (forward-compat), then enforce the known shape.
  const message: ChatMessage = {
    ...(input as object),
    id: typeof input.id === 'string' && input.id ? input.id : newId('chat-msg'),
    role: input.role,
    content: typeof input.content === 'string' ? input.content : '',
    createdAt: typeof input.createdAt === 'string' ? input.createdAt : new Date().toISOString(),
    // A persisted 'streaming' message means the tab closed mid-stream — finalize it.
    status: input.status === 'error' ? 'error' : 'done',
    toolEvidence: clampChatToolEvidence(input.toolEvidence),
  } as ChatMessage;
  if (input.preparedActionId && typeof input.preparedActionId === 'string') {
    message.preparedActionId = input.preparedActionId;
  }
  if (input.proposal && typeof input.proposal === 'object') {
    message.proposal = input.proposal as ChatActionProposal;
  }
  // txReceipt rides the spread above; validate it so a corrupt persisted value
  // can't break txBlock() on reload, and drop it otherwise.
  const rx = input.txReceipt as { txid?: unknown; cluster?: unknown } | undefined;
  if (rx && typeof rx === 'object' && typeof rx.txid === 'string' && typeof rx.cluster === 'string' && isCluster(rx.cluster)) {
    message.txReceipt = { txid: rx.txid, cluster: rx.cluster as Cluster };
  } else {
    delete (message as { txReceipt?: unknown }).txReceipt;
  }
  // receiveCard rides the spread above; we persist ONLY the address (the QR PNG is
  // regenerated on render via chatReceiveQrFor). Validate so a corrupt value can't break it.
  const rc = input.receiveCard as { address?: unknown } | undefined;
  if (rc && typeof rc === 'object' && typeof rc.address === 'string' && rc.address) {
    message.receiveCard = { address: rc.address };
  } else {
    delete (message as { receiveCard?: unknown }).receiveCard;
  }
  // recurringCardId is a plain id; the live card is looked up by id on render.
  if (typeof input.recurringCardId === 'string' && input.recurringCardId) {
    message.recurringCardId = input.recurringCardId;
  } else {
    delete (message as { recurringCardId?: unknown }).recurringCardId;
  }
  // positionsCard carries only a category; the cards themselves render from live positions state.
  const posCard = input.positionsCard as { category?: unknown } | undefined;
  if (posCard && typeof posCard === 'object' && typeof posCard.category === 'string') {
    message.positionsCard = { category: posCard.category as ActionCategory };
  } else {
    delete (message as { positionsCard?: unknown }).positionsCard;
  }
  const researchCard = normalizeChatResearchCard(input.researchCard);
  if (researchCard) {
    message.researchCard = researchCard;
  } else {
    delete (message as { researchCard?: unknown }).researchCard;
  }
  const decisionCheckCard = normalizeChatDecisionCheckCard(input.decisionCheckCard);
  if (decisionCheckCard) {
    message.decisionCheckCard = decisionCheckCard;
  } else {
    delete (message as { decisionCheckCard?: unknown }).decisionCheckCard;
  }
  if (typeof input.error === 'string') message.error = input.error;
  return message;
}

// Synthetic UI-only marker prepended when a session's head was trimmed to the
// per-session cap. Declared as a function (hoisted) and built from literals only so
// it is safe to call from normalizeChatSession at module init (before `t()`/`state`
// exist — the English text is translated at render time in chatMessageHtml).
function chatTruncationMarker(): ChatMessage {
  return {
    id: 'chat-trim-marker',
    role: 'system',
    content: 'Earlier messages were trimmed to keep this chat fast.',
    createdAt: new Date().toISOString(),
    status: 'done',
    ephemeral: true,
  };
}

function normalizeChatSession(raw: unknown, walletAddress: string): ChatSession | null {
  if (!raw || typeof raw !== 'object') return null;
  const input = raw as Record<string, unknown>;
  if (typeof input.id !== 'string' || !input.id) return null;
  if (!recordMatchesWalletScope(input as { walletAddress?: string }, walletAddress)) return null;
  const messages = Array.isArray(input.messages)
    ? input.messages
      .map(normalizeChatMessage)
      .filter((m): m is ChatMessage => Boolean(m))
      // Drop empty assistant placeholders (e.g. tab closed mid-stream) so reloads
      // don't show a blank bubble; keep anything carrying a proposal or a card.
      .filter((m) => !(m.role === 'assistant' && !m.content.trim() && !m.proposal && !m.preparedActionId && !m.researchCard && !m.decisionCheckCard && m.status !== 'error'))
    : [];
  // Cap per-session messages but always keep any message anchored to a promoted
  // action. Count REAL messages only — a prior synthetic trim marker is stripped
  // first so it never accumulates or counts toward the cap.
  const hadMarker = messages.some((m) => m.ephemeral);
  const real = messages.filter((m) => !m.ephemeral);
  let capped = real;
  let truncated = false;
  if (real.length > MAX_CHAT_MESSAGES_PER_SESSION) {
    truncated = true;
    const anchored = real.filter((m) => m.preparedActionId);
    const tail = real.slice(-MAX_CHAT_MESSAGES_PER_SESSION);
    const tailIds = new Set(tail.map((m) => m.id));
    capped = [...anchored.filter((m) => !tailIds.has(m.id)), ...tail];
  }
  // Surface the otherwise-silent head-drop with a single UI-only marker that
  // persists across reloads (once trimmed the dropped head never returns). It is
  // excluded from cloud sync + message counts — see serializeChatSessionMessages
  // and chatSessionCloudBody.
  if (truncated || hadMarker) {
    capped = [chatTruncationMarker(), ...capped];
  }
  const now = new Date().toISOString();
  // NOTE: this runs at module init (loadChatHistoryState) BEFORE `state` exists,
  // so it must not reference `state` or `t()` (both would throw a TDZ error).
  // Use plain fallbacks; persisted sessions always carry their own title/cluster.
  return {
    ...(input as object),
    id: input.id,
    title: typeof input.title === 'string' && input.title ? input.title : 'New chat',
    createdAt: typeof input.createdAt === 'string' ? input.createdAt : now,
    updatedAt: typeof input.updatedAt === 'string' ? input.updatedAt : now,
    walletAddress: typeof input.walletAddress === 'string' ? input.walletAddress : walletAddress,
    cluster: (typeof input.cluster === 'string' ? input.cluster : 'mainnet-beta') as Cluster,
    messages: capped,
  } as ChatSession;
}

function normalizeChatHistoryState(input: Partial<ChatHistoryState>, walletAddress = ''): ChatHistoryState {
  const sessions = (Array.isArray(input.sessions) ? input.sessions : [])
    .map((session) => normalizeChatSession(session, walletAddress))
    .filter((s): s is ChatSession => Boolean(s))
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
    .slice(0, MAX_CHAT_SESSIONS);
  const activeSessionId = sessions.some((s) => s.id === input.activeSessionId)
    ? String(input.activeSessionId)
    : (sessions[0]?.id ?? '');
  return { schemaVersion: CHAT_HISTORY_SCHEMA_VERSION, sessions, activeSessionId };
}

function serializeChatHistory(history: ChatHistoryState): string {
  return CHAT_COMPRESS_PREFIX + LZString.compressToUTF16(JSON.stringify(history));
}

// Cloud sync stores ONLY the messages array per session (metadata travels as
// plaintext columns), compressed with the same LZString scheme as localStorage.
// The server treats this string as an opaque blob. See chatCloudSync.ts.
function serializeChatSessionMessages(session: ChatSession): string {
  // Strip UI-only synthetic markers (e.g. the trim notice) — they are regenerated
  // locally and must never round-trip through the shared cloud blob.
  return compressChatMessages(session.messages.filter((m) => !m.ephemeral));
}

function deserializeChatSessionMessages(messagesLz: string): ChatMessage[] {
  return decompressChatMessages(messagesLz)
    .map(normalizeChatMessage)
    .filter((m): m is ChatMessage => Boolean(m));
}

function parseChatHistoryStorage(key: string): ChatHistoryState {
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return emptyChatHistoryState();
    let json: string;
    if (raw.startsWith(CHAT_COMPRESS_PREFIX)) {
      const decompressed = LZString.decompressFromUTF16(raw.slice(CHAT_COMPRESS_PREFIX.length));
      if (!decompressed) return emptyChatHistoryState();
      json = decompressed;
    } else {
      // Legacy uncompressed v1 record.
      json = raw;
    }
    const parsed = JSON.parse(json) as Partial<ChatHistoryState> & { schemaVersion?: number };
    if (typeof parsed.schemaVersion === 'number' && parsed.schemaVersion > CHAT_HISTORY_SCHEMA_VERSION) {
      // Newer build wrote this — read best-effort but never overwrite it.
      chatHistorySaveLocked = true;
    }
    return normalizeChatHistoryState(parsed);
  } catch {
    return emptyChatHistoryState();
  }
}

function loadChatHistoryState(walletAddress = ''): ChatHistoryState {
  try {
    const key = walletAddress
      ? walletScopedStorageKey(CHAT_HISTORY_STORAGE_KEY, walletAddress)
      : CHAT_HISTORY_STORAGE_KEY;
    return normalizeChatHistoryState(parseChatHistoryStorage(key), walletAddress);
  } catch {
    return emptyChatHistoryState();
  }
}

function writeChatHistoryWithEviction(key: string, history: ChatHistoryState): void {
  let working: ChatHistoryState = history;
  for (let attempt = 0; attempt < MAX_CHAT_SESSIONS + 1; attempt += 1) {
    const serialized = serializeChatHistory(working);
    const overBudget = serialized.length > MAX_CHAT_HISTORY_BYTES;
    if (!overBudget) {
      try {
        window.localStorage.setItem(key, serialized);
        return;
      } catch {
        // QuotaExceededError (or similar) — fall through to evict and retry.
      }
    }
    // Evict the oldest non-active session and retry.
    const evictable = working.sessions
      .filter((s) => s.id !== working.activeSessionId)
      .sort((a, b) => a.updatedAt.localeCompare(b.updatedAt));
    const drop = evictable[0];
    if (!drop) {
      // Only the active session remains; best-effort final write, then give up.
      try { window.localStorage.setItem(key, serializeChatHistory(working)); } catch { /* drop */ }
      return;
    }
    // Storage-pressure eviction is real chat loss — tell the user once instead of dropping silently.
    notifyChatHistoryEvictedOnce();
    working = { ...working, sessions: working.sessions.filter((s) => s.id !== drop.id) };
  }
}

// Probe once whether localStorage actually accepts writes. In private/incognito
// windows setItem throws on every call, which would make writeChatHistoryWithEviction
// pointlessly evict every non-active session before giving up — so we detect it up
// front, skip the destructive write entirely, and keep chat in memory for the session.
function chatLocalStorageWritable(): boolean {
  if (chatLocalStorageWritableCache !== null) return chatLocalStorageWritableCache;
  let ok = false;
  try {
    const probe = '__agentic_chat_probe__';
    window.localStorage.setItem(probe, '1');
    window.localStorage.removeItem(probe);
    ok = true;
  } catch {
    ok = false;
  }
  chatLocalStorageWritableCache = ok;
  return ok;
}

// A newer app build wrote this wallet's chat history (higher schemaVersion); we keep
// it read-only so we don't clobber the newer format. Tell the user ONCE rather than
// silently dropping every chat write for the rest of the session.
function notifyChatHistorySaveLockedOnce(): void {
  if (chatHistorySaveLockedNotified || typeof window === 'undefined') return;
  chatHistorySaveLockedNotified = true;
  pushToast('error', t('Chat history is read-only here'), t('A newer version of the app saved this chat history. Update the app to save new chats on this device.'));
}

function notifyChatStorageUnavailableOnce(): void {
  if (chatStorageUnavailableNotified || typeof window === 'undefined') return;
  chatStorageUnavailableNotified = true;
  pushToast('info', t('Chat is not being saved'), t('This browser is blocking local storage (e.g. private mode), so chats will be lost when you close the tab.'));
}

// Surface the byte-budget eviction so storage-pressure chat loss is never silent (the count
// limit is enforced separately at "New chat"). Once per session to avoid toast spam.
function notifyChatHistoryEvictedOnce(): void {
  if (chatHistoryEvictedNotified || typeof window === 'undefined') return;
  chatHistoryEvictedNotified = true;
  pushToast('info', t('Chat storage is full'), t('The oldest chats were removed to free space. Delete chats you no longer need to keep new ones.'));
}

function saveChatHistoryState(): void {
  if (chatHistorySaveLocked) { notifyChatHistorySaveLockedOnce(); return; }
  if (!chatLocalStorageWritable()) { notifyChatStorageUnavailableOnce(); return; }
  try {
    // Persist a normalized SNAPSHOT to disk, but do NOT replace state.chat with
    // fresh objects — the streaming loop holds a live reference to the assistant
    // message and mutates it across token/proposal events. Reassigning here would
    // detach that reference and lose tokens that arrive after a mid-stream save.
    // Caps/sort are enforced on load and on the disk snapshot, which is enough.
    // Don't persist cloud metadata stubs (unloaded cloud-only sessions): they're
    // re-hydrated from the server on sign-in and would otherwise linger on disk as
    // empty sessions after sign-out. Loaded sessions persist normally (local cache).
    const persistable: ChatHistoryState = {
      ...state.chat,
      sessions: state.chat.sessions.filter((s) => !chatSessionIsCloudStub(s)),
    };
    const snapshot = normalizeChatHistoryState(persistable, state.address);
    const key = state.address
      ? walletScopedStorageKey(CHAT_HISTORY_STORAGE_KEY, state.address)
      : CHAT_HISTORY_STORAGE_KEY;
    writeChatHistoryWithEviction(key, snapshot);
  } catch {
    // Best-effort browser chat persistence.
  }
}

function activeChatSession(): ChatSession | null {
  return state.chat.sessions.find((s) => s.id === state.chat.activeSessionId) ?? null;
}

// Re-read the wallet's chat history written by another tab and merge it in. This
// tab's active and streaming sessions are preserved as-is (never clobber an
// in-progress turn); every other session is taken from the other tab's snapshot, so
// a delete/rename/new-message in tab B propagates to tab A without data loss.
function mergeChatSessionsFromOtherTab(): void {
  if (chatHistorySaveLocked) return;
  const incoming = loadChatHistoryState(state.address);
  const protectedIds = new Set<string>(
    [state.chat.activeSessionId, chatStreamSessionId].filter((id): id is string => Boolean(id)),
  );
  const merged = new Map<string, ChatSession>();
  for (const s of incoming.sessions) merged.set(s.id, s);
  // This tab's protected sessions win over the other tab's copy.
  for (const s of state.chat.sessions) {
    if (protectedIds.has(s.id)) merged.set(s.id, s);
  }
  state.chat = {
    ...state.chat,
    sessions: [...merged.values()].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)),
  };
  if (state.activeTab === 'chat') render();
}

// Load this wallet's on-disk chat history and merge the in-memory sessions OVER it so a
// workflow refresh never DROPS chats. Two cases this fixes:
//   - same-wallet refresh: keep in-memory sessions not yet flushed to disk (no destructive
//     reload clobbering a just-created card/message).
//   - first connect ('' -> address): ADOPT the unscoped sessions the user built before
//     connecting — otherwise the scoped reload returns empty and they appear deleted.
// Sessions belonging to a DIFFERENT wallet are NOT carried (no cross-wallet leak on a switch;
// teardownChatRuntimeForWalletBoundary already ran). recordMatchesWalletScope = same-wallet OR
// unscoped. Cloud stubs are excluded (re-hydrated from the server on sign-in).
function loadChatHistoryMergingMemory(): ChatHistoryState {
  const addr = state.address;
  const disk = loadChatHistoryState(addr);
  const carry = state.chat.sessions.filter(
    (s) => !chatSessionIsCloudStub(s) && recordMatchesWalletScope(s, addr),
  );
  const merged = new Map<string, ChatSession>();
  for (const s of disk.sessions) merged.set(s.id, s);
  for (const s of carry) {
    // Stamp adopted unscoped sessions with the now-connected wallet so they persist scoped.
    const stamped = addr && !s.walletAddress ? { ...s, walletAddress: addr } : s;
    const existing = merged.get(stamped.id);
    if (!existing || stamped.updatedAt.localeCompare(existing.updatedAt) >= 0) merged.set(stamped.id, stamped);
  }
  const sorted = [...merged.values()].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  // Resolve the active session BEFORE capping. Switching to an older chat doesn't bump its
  // updatedAt, so a naive slice(0, MAX) could prune the currently-open session and silently
  // jump the user to sessions[0] — the exact "my chat changed by itself" bug this merge guards
  // against. So pin the active session into the capped list (dropping the least-recent instead).
  const activeSessionId = sorted.some((s) => s.id === state.chat.activeSessionId)
    ? state.chat.activeSessionId
    : sorted.some((s) => s.id === disk.activeSessionId)
      ? disk.activeSessionId
      : (sorted[0]?.id ?? '');
  let sessions = sorted.slice(0, MAX_CHAT_SESSIONS);
  if (activeSessionId && !sessions.some((s) => s.id === activeSessionId)) {
    const active = sorted.find((s) => s.id === activeSessionId);
    if (active) sessions = [...sorted.slice(0, MAX_CHAT_SESSIONS - 1), active];
  }
  return { schemaVersion: CHAT_HISTORY_SCHEMA_VERSION, sessions, activeSessionId };
}

function createChatSession(): ChatSession {
  const now = new Date().toISOString();
  const session: ChatSession = {
    id: newId('chat-session'),
    title: t('New chat'),
    createdAt: now,
    updatedAt: now,
    walletAddress: state.address,
    cluster: state.cluster,
    messages: [],
  };
  state.chat.sessions = [session, ...state.chat.sessions];
  state.chat.activeSessionId = session.id;
  saveChatHistoryState();
  return session;
}

function ensureActiveChatSession(): ChatSession {
  return activeChatSession() ?? createChatSession();
}

function chatSessionTitleFromText(text: string): string {
  const trimmed = text.trim().replace(/\s+/g, ' ');
  if (!trimmed) return t('New chat');
  return trimmed.length > 48 ? `${trimmed.slice(0, 47)}…` : trimmed;
}

function appendChatMessage(sessionId: string, message: ChatMessage): void {
  const session = state.chat.sessions.find((s) => s.id === sessionId);
  if (!session) return;
  session.messages.push(message);
  session.updatedAt = new Date().toISOString();
  // First user line names the session.
  if (message.role === 'user' && (session.title === t('New chat') || !session.title)) {
    session.title = chatSessionTitleFromText(message.content);
  }
  saveChatHistoryState();
  // Mirror the user turn to the cloud (status 'done'). Skip 'streaming'
  // placeholders (synced from runChatStream's finally once complete) and 'error'
  // bubbles (device/locale-specific readiness errors shouldn't rehydrate cross-device).
  if (message.status === 'done') void syncChatSessionToCloud(sessionId);
}

function deleteChatSession(sessionId: string): void {
  const removed = state.chat.sessions.find((s) => s.id === sessionId);
  if (removed) dropOrphanedChatPreparedActions(removed.messages);
  state.chat.sessions = state.chat.sessions.filter((s) => s.id !== sessionId);
  if (state.chat.activeSessionId === sessionId) {
    state.chat.activeSessionId = state.chat.sessions[0]?.id ?? '';
  }
  saveChatHistoryState();
  if (cloudSessionMatchesWallet() && !chatTabHidden()) {
    void (async () => {
      try {
        await ensureChatCloudTokenReady();
        await cloudRequest(`/api/chat/sessions/${encodeURIComponent(sessionId)}`, { method: 'DELETE' });
      } catch (err) {
        if (isCloudUnreachableError(err)) enqueuePendingCloudSync({ id: sessionId, kind: 'chat-delete' });
      }
    })();
  }
}

function clearAllChatSessions(): void {
  state.chat = emptyChatHistoryState();
  try {
    const key = state.address
      ? walletScopedStorageKey(CHAT_HISTORY_STORAGE_KEY, state.address)
      : CHAT_HISTORY_STORAGE_KEY;
    window.localStorage.removeItem(key);
  } catch { /* best effort */ }
  if (cloudSessionMatchesWallet() && !chatTabHidden()) {
    void (async () => {
      try {
        await ensureChatCloudTokenReady();
        await cloudRequest('/api/chat/sessions', { method: 'DELETE' });
      } catch (err) {
        if (isCloudUnreachableError(err)) enqueuePendingCloudSync({ id: 'all', kind: 'chat-clear' });
      }
    })();
  }
}

// ── Chat history cloud sync (signed-in only) ─────────────────────────────────
interface ChatSessionMetaWire {
  sessionId: string;
  title: string;
  cluster: string;
  messageCount: number;
  version: number;
  schemaVersion: number;
  createdAt: string;
  updatedAt: string;
}
interface ChatSessionWire extends ChatSessionMetaWire {
  messagesLz: string;
}

function chatCloudSyncEnabled(): boolean {
  return cloudSessionMatchesWallet() && !chatTabHidden() && !chatHistorySaveLocked;
}

// On native (iOS/Android/Tauri) the cloud Bearer token hydrates asynchronously
// after a cold launch; await it before any chat-storage cloud call so the first
// request doesn't 401 before the Keychain/secure-store token lands (mirrors the
// chat-stream path which already awaits ensureNativeCloudTokenReady()).
async function ensureChatCloudTokenReady(): Promise<void> {
  if (nativeCloudApiSurfaceActive()) await ensureNativeCloudTokenReady();
}

// A chat-storage request failed because the session no longer exists on the
// cloud (deleted on another device) — distinct from a transient/unreachable
// error, so the caller can stop treating it as a loadable stub.
function isChatSessionNotFoundError(err: unknown): boolean {
  const msg = err instanceof Error ? err.message : String(err);
  return /\b404\b|not found/i.test(msg);
}

// A PUT was rejected because another device advanced this session's version (the
// server's optimistic-concurrency guard) — reconcile by refetch + merge.
function isChatConflictError(err: unknown): boolean {
  const msg = err instanceof Error ? err.message : String(err);
  return /\b409\b|conflict/i.test(msg);
}

// chatSessionIsCloudStub() lives in chatCloudSync.ts (pure + unit-tested).

function chatSessionCloudBody(session: ChatSession): string {
  return JSON.stringify({
    title: session.title,
    cluster: session.cluster,
    messageCount: session.messages.filter((m) => !m.ephemeral).length,
    schemaVersion: CHAT_HISTORY_SCHEMA_VERSION,
    // Optimistic-concurrency base version the server checks; on a stale value it
    // replies 409 and we reconcileChatConflict() instead of clobbering the newer copy.
    version: session.cloudVersion ?? 0,
    createdAt: session.createdAt,
    updatedAt: session.updatedAt,
    messagesLz: serializeChatSessionMessages(session),
  });
}

// Resolve a 409 conflict: pull the server's authoritative thread, union it with the
// local messages by id (so neither device's turns are lost), then re-PUT the merged
// copy on top of the latest version. Guarded against running twice for one session.
async function reconcileChatConflict(sessionId: string): Promise<void> {
  if (!chatCloudSyncEnabled()) return;
  if (chatConflictReconcilesInFlight.has(sessionId)) return;
  chatConflictReconcilesInFlight.add(sessionId);
  try {
    await ensureChatCloudTokenReady();
    const full = await cloudRequest<ChatSessionWire>(`/api/chat/sessions/${encodeURIComponent(sessionId)}`, { method: 'GET' });
    const session = state.chat.sessions.find((s) => s.id === sessionId);
    if (!session || chatSessionIsCloudStub(session)) return; // gone or not yet loaded
    const serverMessages = full?.messagesLz ? deserializeChatSessionMessages(full.messagesLz) : [];
    session.messages = mergeChatMessagesById(serverMessages, session.messages.filter((m) => !m.ephemeral));
    session.cloudVersion = full?.version ?? session.cloudVersion;
    session.updatedAt = new Date().toISOString(); // merged copy is the newest
    saveChatHistoryState();
    if (state.activeTab === 'chat') render();
    const saved = await cloudRequest<{ version?: number }>(`/api/chat/sessions/${encodeURIComponent(sessionId)}`, {
      method: 'PUT',
      body: chatSessionCloudBody(session),
    });
    session.cloudVersion = saved?.version ?? session.cloudVersion;
  } catch (err) {
    if (isCloudUnreachableError(err)) enqueuePendingCloudSync({ id: sessionId, kind: 'chat-put' });
    // A second 409 (another concurrent write) or other error → drop; the next user
    // turn re-attempts the sync, and localStorage still holds the local copy.
  } finally {
    chatConflictReconcilesInFlight.delete(sessionId);
  }
}

// Best-effort upsert of one session to the cloud. Skips metadata stubs (cloud
// already holds the authoritative copy) and empty 'New chat' sessions.
async function syncChatSessionToCloud(sessionId: string): Promise<void> {
  if (!chatCloudSyncEnabled()) return;
  const session = state.chat.sessions.find((s) => s.id === sessionId);
  if (!session || session.messages.length === 0) return;
  if (chatSessionIsCloudStub(session)) return; // cloud holds the authoritative copy
  await ensureChatCloudTokenReady();
  try {
    const saved = await cloudRequest<{ version?: number }>(`/api/chat/sessions/${encodeURIComponent(sessionId)}`, {
      method: 'PUT',
      body: chatSessionCloudBody(session),
    });
    session.cloudVersion = saved?.version ?? session.cloudVersion;
  } catch (err) {
    if (isChatConflictError(err)) { void reconcileChatConflict(sessionId); return; }
    if (isCloudUnreachableError(err)) enqueuePendingCloudSync({ id: sessionId, kind: 'chat-put' });
    // Other errors (validation/auth) → drop; localStorage still has the copy.
  }
}

// Pull the per-wallet session metadata list and merge it into state.chat. Cloud
// sessions not present locally (or newer than the local copy) become metadata
// stubs whose messages load lazily on open; local-newer sessions are kept and
// pushed up by pushLocalChatSessionsToCloud().
async function hydrateChatHistoryFromCloud(): Promise<void> {
  if (!cloudSessionMatchesWallet() || chatTabHidden() || chatHistorySaveLocked) return;
  let metas: ChatSessionMetaWire[];
  try {
    await ensureChatCloudTokenReady();
    const payload = await cloudRequest<{ sessions?: ChatSessionMetaWire[] }>('/api/chat/sessions', { method: 'GET' });
    metas = Array.isArray(payload?.sessions) ? payload.sessions : [];
  } catch {
    return; // Cloud unreachable — keep the local history as-is.
  }
  const now = new Date().toISOString();
  const byId = new Map(state.chat.sessions.map((s) => [s.id, s] as const));
  for (const meta of metas) {
    if (!meta || typeof meta.sessionId !== 'string' || !meta.sessionId) continue;
    const local = byId.get(meta.sessionId);
    const metaCluster = (typeof meta.cluster === 'string' ? meta.cluster : state.cluster) as Cluster;
    switch (decideCloudChatMeta(local, meta)) {
      case 'create-stub':
        // Cloud-only session → metadata stub; messages load lazily on open.
        byId.set(meta.sessionId, {
          id: meta.sessionId,
          title: meta.title || t('New chat'),
          createdAt: meta.createdAt || now,
          updatedAt: meta.updatedAt || now,
          walletAddress: state.address,
          cluster: metaCluster,
          messages: [],
          cloudMessageCount: stubMessageCount(meta.messageCount),
          cloudVersion: meta.version ?? 0,
        });
        break;
      case 'restub':
        // Cloud is newer — re-stub so the fresh thread is fetched on open. H7-C: but if a
        // chat stream is actively writing to THIS session, clearing local.messages would
        // orphan the streamed message object (token loss + nothing persisted). Skip the
        // restub for the active session; it re-stubs on the next hydrate after the stream
        // settles. (Mirrors the chatStreamSessionId guard in ensureChatSessionMessagesLoaded.)
        if (chatStreamSessionId === meta.sessionId) break;
        local!.title = meta.title || local!.title;
        local!.updatedAt = meta.updatedAt || local!.updatedAt;
        local!.cluster = metaCluster;
        local!.messages = [];
        local!.cloudMessageCount = stubMessageCount(meta.messageCount);
        local!.cloudVersion = meta.version ?? 0;
        break;
      case 'mark-stub':
        // Local copy has no loaded messages (e.g. a stub restored from localStorage
        // after reload) — keep it a stub so opening fetches the thread.
        local!.cloudMessageCount = stubMessageCount(meta.messageCount);
        local!.cloudVersion = meta.version ?? local!.cloudVersion;
        break;
      case 'keep':
        // Local has content and is newer/equal — keep it (pushed up later).
        local!.cloudVersion = meta.version ?? local!.cloudVersion;
        break;
    }
  }
  state.chat.sessions = [...byId.values()].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  if (!state.chat.sessions.some((s) => s.id === state.chat.activeSessionId)) {
    state.chat.activeSessionId = state.chat.sessions[0]?.id ?? '';
  }
  chatCloudHydrated = true;
  saveChatHistoryState();
  // Eagerly load the open session so the transcript isn't blank after sign-in.
  const active = activeChatSession();
  if (active && chatSessionIsCloudStub(active)) {
    await ensureChatSessionMessagesLoaded(active.id);
  }
  if (state.activeTab === 'chat') render();
}

// Fetch + decompress one stub session's messages on demand. Distinguishes a
// genuine deletion (404) from a decompression/empty-blob failure (data loss) and
// a transient network/server error, so a failed open surfaces a retry affordance
// instead of silently blanking the thread or spinning "Loading…" forever.
async function ensureChatSessionMessagesLoaded(sessionId: string): Promise<void> {
  const session = state.chat.sessions.find((s) => s.id === sessionId);
  if (!session || !chatSessionIsCloudStub(session)) return;
  if (!cloudSessionMatchesWallet()) { delete session.cloudMessageCount; return; }
  if (chatSessionLoadsInFlight.has(sessionId)) return; // a load is already running
  chatSessionLoadsInFlight.add(sessionId);
  delete session.cloudLoadError; // a fresh attempt clears any prior error state
  // Identity/state snapshot: bail on completion if the wallet changed mid-GET
  // (sign-out/switch) so a late response can't mutate the wrong wallet's state;
  // detect a concurrent local append; remember the advertised count for the
  // empty-blob = data-loss check.
  const loadAddress = state.address;
  const expectedCount = session.cloudMessageCount ?? 0;
  const messagesBefore = session.messages.length;
  try {
    await ensureChatCloudTokenReady();
    const full = await cloudRequest<ChatSessionWire>(`/api/chat/sessions/${encodeURIComponent(sessionId)}`, { method: 'GET' });
    // Wallet changed during the GET — discard this response entirely.
    if (state.address !== loadAddress || !cloudSessionMatchesWallet()) return;
    // A live stream is mutating a message ref inside session.messages (or the user
    // appended a turn): never replace the array under it — keep the local content
    // and stop treating this as a stub.
    if (session.messages.length !== messagesBefore || chatStreamSessionId === sessionId) {
      delete session.cloudMessageCount;
      saveChatHistoryState();
      return;
    }
    // The decompressed blob is the source of truth — trust its length over the
    // server's unverified messageCount. The cloud never stores an empty thread
    // (syncChatSessionToCloud skips empty sessions; the server rejects an empty
    // blob), so a stub that claimed messages but decodes to nothing is corruption
    // / a missing blob = data loss, not an empty chat. Keep the stub + show retry.
    const decoded = full?.messagesLz ? deserializeChatSessionMessages(full.messagesLz) : [];
    if (decoded.length === 0 && expectedCount > 0) {
      session.cloudLoadError = 'failed';
      pushToast('error', t('Could not load this conversation'), t('Something went wrong reading it. Try again.'));
      if (state.activeTab === 'chat') render();
      return;
    }
    session.messages = decoded;
    session.cloudVersion = full?.version ?? session.cloudVersion;
    delete session.cloudMessageCount; // no longer a stub
    saveChatHistoryState();
  } catch (err) {
    if (state.address !== loadAddress) return; // wallet changed — ignore the late failure
    if (isChatSessionNotFoundError(err)) {
      // Deleted on another device — stop treating it as a loadable stub so it
      // doesn't loop on 404 (it drops out of the history list once empty).
      delete session.cloudMessageCount;
      saveChatHistoryState();
      return;
    }
    // Offline/unreachable keeps the stub but shows an offline state (with Retry);
    // 5xx/auth/other show a generic failed state — both beat an endless spinner.
    session.cloudLoadError = isCloudUnreachableError(err) ? 'offline' : 'failed';
    if (state.activeTab === 'chat') render();
  } finally {
    chatSessionLoadsInFlight.delete(sessionId);
  }
}

// On sign-in, push local-only / local-newer sessions up to the cloud (idempotent
// per-session PUT). Stubs are skipped (cloud copy is authoritative). Returns the
// number of local sessions queued for upload so the sign-in summary can reassure
// the user their chat history is moving to storage.
function pushLocalChatSessionsToCloud(): number {
  if (!chatCloudSyncEnabled()) return 0;
  let queued = 0;
  for (const session of state.chat.sessions) {
    if (chatSessionIsCloudStub(session)) continue;
    if (session.messages.length === 0) continue;
    void syncChatSessionToCloud(session.id);
    queued += 1;
  }
  return queued;
}

function loadLocalCompletedPlans(walletAddress = ''): CompletedPlanRecord[] {
  try {
    migrateLegacyWalletScopedStorage();
    const legacy = localStorageJsonArray(LOCAL_COMPLETED_STORAGE_KEY);
    const scoped = walletAddress ? localStorageJsonArray(walletScopedStorageKey(LOCAL_COMPLETED_STORAGE_KEY, walletAddress)) : [];
    return mergeCompletedPlanRecords(
      [...legacy, ...scoped]
        .filter(isCompletedPlanRecord)
        .filter((record) => recordMatchesWalletScope(record, walletAddress)),
    );
  } catch {
    return [];
  }
}

function saveLocalCompletedPlans(): void {
  try {
    state.localCompletedPlans = mergeCompletedPlanRecords(
      state.localCompletedPlans.filter((record) => recordMatchesWalletScope(record, state.address)),
    );
    window.localStorage.setItem(LOCAL_COMPLETED_STORAGE_KEY, JSON.stringify(state.localCompletedPlans));
    if (state.address) {
      window.localStorage.setItem(
        walletScopedStorageKey(LOCAL_COMPLETED_STORAGE_KEY, state.address),
        JSON.stringify(state.localCompletedPlans),
      );
    }
  } catch {
    // Best-effort completed history persistence.
  }
}

function isPositionRecord(value: unknown): value is PositionRecord {
  if (!value || typeof value !== 'object') return false;
  const v = value as Record<string, unknown>;
  return (
    typeof v.id === 'string' &&
    typeof v.category === 'string' &&
    typeof v.kind === 'string' &&
    (v.status === 'open' || v.status === 'closed')
  );
}

// Records written before `manage` existed carry a bare `manageRequestedAt`. That flag could ONLY be
// cleared by a successful live read, so a failing or permanently-partial section left it set forever
// and the card sat on "Updating…" indefinitely — the bug this lifecycle exists to kill. One still
// inside its settle window becomes a real intent (deadline and all) so it can resolve; one already
// past it is simply dropped: its txid and amount can't be reconstructed, and a stale flag has no
// business surviving a reload.
function migrateLegacyManageFlag(p: PositionRecord): PositionRecord {
  if (p.manageRequestedAt && !p.manage) {
    const requestedAt = new Date(p.manageRequestedAt).getTime();
    if (Number.isFinite(requestedAt) && Date.now() - requestedAt < POSITION_SETTLE_MS) {
      p.manage = {
        actionId: '',
        kind: positionSeedManage(p)?.kind ?? p.kind,
        requestedAt: p.manageRequestedAt,
        settleDeadlineAt: new Date(requestedAt + POSITION_SETTLE_MS).toISOString(),
        phase: 'pending',
      };
    }
  }
  delete p.manageRequestedAt;
  return p;
}

function loadPositions(walletAddress = ''): PositionRecord[] {
  try {
    const legacy = localStorageJsonArray(POSITIONS_STORAGE_KEY);
    const scoped = walletAddress
      ? localStorageJsonArray(walletScopedStorageKey(POSITIONS_STORAGE_KEY, walletAddress))
      : [];
    const byId = new Map<string, PositionRecord>();
    for (const value of [...legacy, ...scoped]) {
      if (!isPositionRecord(value)) continue;
      if (walletAddress && value.walletAddress && value.walletAddress !== walletAddress) continue;
      byId.set(value.id, migrateLegacyManageFlag(value));
    }
    return [...byId.values()];
  } catch {
    return [];
  }
}

function savePositions(): void {
  try {
    window.localStorage.setItem(POSITIONS_STORAGE_KEY, JSON.stringify(state.positions));
    if (state.address) {
      window.localStorage.setItem(
        walletScopedStorageKey(POSITIONS_STORAGE_KEY, state.address),
        JSON.stringify(state.positions),
      );
    }
  } catch {
    // Best-effort positions persistence.
  }
}

function loadPositionsClosed(walletAddress = ''): Record<string, { kind: string; metrics: PositionClosedMetrics }> {
  try {
    const scoped = walletAddress ? window.localStorage.getItem(walletScopedStorageKey(POSITIONS_CLOSED_STORAGE_KEY, walletAddress)) : null;
    const raw = scoped ?? window.localStorage.getItem(POSITIONS_CLOSED_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function savePositionsClosed(): void {
  try {
    // Cap growth: keep the ~300 most recently captured (insertion order), prune the rest.
    const keys = Object.keys(state.positionsClosed);
    if (keys.length > 300) {
      const trimmed: typeof state.positionsClosed = {};
      for (const k of keys.slice(keys.length - 300)) {
        const v = state.positionsClosed[k];
        if (v) trimmed[k] = v;
      }
      state.positionsClosed = trimmed;
    }
    window.localStorage.setItem(POSITIONS_CLOSED_STORAGE_KEY, JSON.stringify(state.positionsClosed));
    if (state.address) {
      window.localStorage.setItem(
        walletScopedStorageKey(POSITIONS_CLOSED_STORAGE_KEY, state.address),
        JSON.stringify(state.positionsClosed),
      );
    }
  } catch {
    // Best-effort closed-metrics persistence.
  }
}

let persistingLocalCompletedSnapshot = false;

function persistLocalCompletedSnapshot(): void {
  if (persistingLocalCompletedSnapshot || !state.address) return;
  persistingLocalCompletedSnapshot = true;
  try {
    const snapshot = completedPlanRecords({ includeLocalLedger: false })
      .filter((record) => record.workflowSource !== 'cloud')
      .filter((record) => recordMatchesWalletScope(record, state.address));
    if (!snapshot.length) return;
    state.localCompletedPlans = mergeCompletedPlanRecords(state.localCompletedPlans, snapshot);
    saveLocalCompletedPlans();
  } finally {
    persistingLocalCompletedSnapshot = false;
  }
}

function mergeCompletedPlanRecords(...groups: CompletedPlanRecord[][]): CompletedPlanRecord[] {
  const byId = new Map<string, CompletedPlanRecord>();
  for (const records of groups) {
    for (const record of records) {
      const current = byId.get(record.id);
      if (!current || record.completedAt.localeCompare(current.completedAt) >= 0) {
        byId.set(record.id, record);
      }
    }
  }
  return [...byId.values()].sort((left, right) => right.completedAt.localeCompare(left.completedAt));
}

function isCompletedPlanRecord(value: unknown): value is CompletedPlanRecord {
  if (!value || typeof value !== 'object') return false;
  const record = value as Partial<CompletedPlanRecord>;
  return (
    typeof record.id === 'string' &&
    (record.kind === 'one-time' || record.kind === 'recurring') &&
    typeof record.status === 'string' &&
    typeof record.tone === 'string' &&
    typeof record.title === 'string' &&
    typeof record.summary === 'string' &&
    typeof record.completedAt === 'string' &&
    typeof record.createdAt === 'string' &&
    typeof record.walletAddress === 'string' &&
    isCluster(record.cluster ?? '') &&
    typeof record.copyPayload === 'string' &&
    Array.isArray(record.detailRows) &&
    record.detailRows.every(isDetailRow)
  );
}

function mergePreparedActions(...groups: PreparedAction[][]): PreparedAction[] {
  const byId = new Map<string, PreparedAction>();
  for (const actions of groups) {
    for (const action of actions) {
      const current = byId.get(action.id);
      if (!current || action.updatedAt.localeCompare(current.updatedAt) >= 0) {
        byId.set(action.id, action);
      }
    }
  }
  return [...byId.values()].sort((left, right) => right.createdAt.localeCompare(left.createdAt));
}

function withPreparedActionSource(actions: PreparedAction[], workflowSource: WorkflowRecordSource): PreparedAction[] {
  return actions.filter(isPreparedAction).map((action) => ({ ...action, workflowSource }));
}

function withRecurringPaymentSource(payments: RecurringPayment[], workflowSource: WorkflowRecordSource): RecurringPayment[] {
  return payments.filter(isRecurringPayment).map((payment) => ({ ...payment, workflowSource }));
}

function mergeRecurringPayments(...groups: RecurringPayment[][]): RecurringPayment[] {
  const byId = new Map<string, RecurringPayment>();
  for (const payments of groups) {
    for (const payment of payments) {
      const current = byId.get(payment.id);
      if (!current || payment.updatedAt.localeCompare(current.updatedAt) >= 0) {
        byId.set(payment.id, payment);
      }
    }
  }
  return [...byId.values()].sort((left, right) => right.createdAt.localeCompare(left.createdAt));
}

function mergeActionReceipts(...groups: ActionReceipt[][]): ActionReceipt[] {
  const byId = new Map<string, ActionReceipt>();
  for (const receipts of groups) {
    for (const receipt of receipts) {
      const current = byId.get(receipt.actionId);
      if (!current || receipt.completedAt.localeCompare(current.completedAt) >= 0) {
        byId.set(receipt.actionId, receipt);
      }
    }
  }
  return [...byId.values()].sort((left, right) => right.completedAt.localeCompare(left.completedAt));
}

function isPreparedAction(value: unknown): value is PreparedAction {
  if (!value || typeof value !== 'object') return false;
  const action = value as Partial<PreparedAction>;
  return (
    typeof action.id === 'string' &&
    isPreparedActionKind(action.kind) &&
    isPreparedActionStatus(action.status) &&
    typeof action.walletAddress === 'string' &&
    isCluster(action.cluster ?? '') &&
    typeof action.summary === 'string' &&
    Boolean(action.params) &&
    typeof action.params === 'object' &&
    !Array.isArray(action.params) &&
    typeof action.dueAt === 'string' &&
    typeof action.createdAt === 'string' &&
    typeof action.updatedAt === 'string'
  );
}

function isPreparedActionKind(value: unknown): value is PreparedActionKind {
  return typeof value === 'string' && BASE_PREPARED_ACTION_KINDS.has(value);
}

function isRecurringPayment(value: unknown): value is RecurringPayment {
  if (!value || typeof value !== 'object') return false;
  const payment = value as Partial<RecurringPayment>;
  return (
    typeof payment.id === 'string' &&
    (payment.status === 'active' || payment.status === 'paused') &&
    typeof payment.walletAddress === 'string' &&
    isCluster(payment.cluster ?? '') &&
    typeof payment.token === 'string' &&
    typeof payment.recipient === 'string' &&
    typeof payment.amount === 'string' &&
    isRecurringCadence(payment.cadence) &&
    typeof payment.createdAt === 'string' &&
    typeof payment.updatedAt === 'string'
  );
}

function isActionReceipt(value: unknown): value is ActionReceipt {
  if (!value || typeof value !== 'object') return false;
  const receipt = value as Partial<ActionReceipt>;
  return (
    typeof receipt.actionId === 'string' &&
    isPreparedActionStatus(receipt.status) &&
    typeof receipt.summary === 'string' &&
    typeof receipt.walletAddress === 'string' &&
    isCluster(receipt.cluster ?? '') &&
    typeof receipt.createdAt === 'string' &&
    typeof receipt.completedAt === 'string' &&
    (receipt.proofSignature === undefined || typeof receipt.proofSignature === 'string') &&
    (receipt.proofMessage === undefined || typeof receipt.proofMessage === 'string') &&
    (receipt.proofEncoding === undefined || receipt.proofEncoding === 'utf8-message' || receipt.proofEncoding === 'tx-memo-proof') &&
    (receipt.proofTxBase64 === undefined || typeof receipt.proofTxBase64 === 'string') &&
    (receipt.proofMemoText === undefined || typeof receipt.proofMemoText === 'string')
  );
}

function isPreparedActionStatus(value: unknown): value is PreparedActionStatus {
  return (
    value === 'scheduled' ||
    value === 'ready' ||
    value === 'overdue' ||
    value === 'approval_pending' ||
    value === 'approved' ||
    value === 'rejected' ||
    value === 'cancelled' ||
    value === 'blocked' ||
    value === 'failed' ||
    value === 'expired'
  );
}

function isRecurringCadence(value: unknown): value is RecurringCadence {
  return (
    value === 'weekly' ||
    value === 'monthly' ||
    value === 'interval_days' ||
    value === 'interval_hours' ||
    value === 'interval_minutes'
  );
}

function isBrowserWorkflowId(value: { id: string } | string): boolean {
  const id = typeof value === 'string' ? value : value.id;
  return id.startsWith('browser-');
}

function recurringPaymentWorkflowSource(payment: RecurringPayment): WorkflowRecordSource {
  if (payment.workflowSource) return payment.workflowSource;
  return isBrowserWorkflowId(payment.id) ? 'browser' : 'local-bridge';
}

function mergeGeneratedPlans(...planGroups: unknown[][]): GeneratedPlanRecord[] {
  const byId = new Map<string, GeneratedPlanRecord>();
  for (const plans of planGroups) {
    for (const plan of plans) {
      if (!isGeneratedPlanRecord(plan)) continue;
      const current = byId.get(plan.id);
      if (!current || plan.updatedAt.localeCompare(current.updatedAt) >= 0) {
        byId.set(plan.id, plan);
      }
    }
  }
  return [...byId.values()]
    .sort((left, right) => right.createdAt.localeCompare(left.createdAt))
    .slice(0, GENERATED_PLANS_LIMIT);
}

function isGeneratedPlanRecord(value: unknown): value is GeneratedPlanRecord {
  if (!value || typeof value !== 'object') return false;
  const record = value as Partial<GeneratedPlanRecord>;
  return (
    typeof record.id === 'string' &&
    isAgentPlan(record.plan) &&
    typeof record.createdAt === 'string' &&
    typeof record.updatedAt === 'string' &&
    (record.source === 'template' || record.source === 'ai') &&
    typeof record.templateId === 'string' &&
    typeof record.templateTitle === 'string' &&
    typeof record.prompt === 'string' &&
    typeof record.walletAddress === 'string' &&
    isCluster(record.cluster ?? '') &&
    isGeneratedPlanStatus(record.status) &&
    (record.signature === undefined || typeof record.signature === 'string') &&
    (record.preparedActionId === undefined || typeof record.preparedActionId === 'string') &&
    (record.error === undefined || typeof record.error === 'string') &&
    (record.failureLabel === undefined || typeof record.failureLabel === 'string') &&
    (record.agentReview === undefined || Boolean(parseAgentPlanReviewState(record.agentReview))) &&
    (record.agentOverride === undefined || Boolean(parseAgentReviewOverride(record.agentOverride))) &&
    (record.metadata === undefined || isJsonObject(record.metadata)) &&
    (record.cloudSyncStatus === undefined || isCloudSyncStatus(record.cloudSyncStatus)) &&
    (record.cloudSyncError === undefined || typeof record.cloudSyncError === 'string')
  );
}

function isCloudSyncStatus(value: unknown): value is CloudSyncStatus {
  return value === 'synced' || value === 'pending' || value === 'error';
}

function parseAgentPlanReviewState(value: unknown): AgentPlanReviewState | undefined {
  if (!isJsonObject(value)) return undefined;
  if (!isAgentPlanReviewStatus(value.status)) return undefined;
  const status: AgentPlanReviewStatus = value.status === 'needs_input' && isWalletRequiredAgentReviewEvidence(
    isJsonObject(value.evidence) ? value.evidence : undefined,
  )
    ? 'wallet_required'
    : value.status;
  const decision = value.decision === 'approve' || value.decision === 'deny' || value.decision === 'needs_input'
    ? value.decision
    : undefined;
  const questions = parseAgentReviewQuestions(value.questions);
  const answers = parseAgentReviewAnswers(value.answers);
  const staleness = parseAgentReviewStaleness(value.staleness);
  const reviewers = parseAgentReviewerEntries(value.reviewers);
  const policies = parseAgentReviewPolicySnapshots(value.policies);
  const history = parseAgentReviewAttempts(value.history);
  const facts = parseAgentReviewFactSet(value.facts);
  const checks = parseAgentReviewChecks(value.checks);
  const conversation = parseAgentAskConversation(value.conversation);
  const localized = normalizeAgentReviewLocalizedCopy(value.localized);
  const evidenceRequirements = parseAgentEvidenceRequirements(value.evidenceRequirements);
  const evidenceFacts = parseAgentEvidenceFacts(value.evidenceFacts);
  const evidenceGate = parseAgentEvidenceGateResult(value.evidenceGate);
  const decisionContract = parseAgentDecisionContract(value.decisionContract);
  const auditReceipt = parseAgentDecisionAuditReceipt(value.auditReceipt);
  const decisionViolations = parseAgentReviewStringArray(value.decisionViolations, 12);
  const appliedUserPolicyIds = Array.isArray(value.appliedUserPolicyIds)
    ? value.appliedUserPolicyIds.filter((entry): entry is string => typeof entry === 'string')
    : undefined;
  return {
    schemaVersion: AGENT_REVIEW_SCHEMA_VERSION,
    required: value.required !== false,
    status,
    ...(decision ? { decision } : {}),
    reason: typeof value.reason === 'string' ? value.reason : '',
    ...(typeof value.summary === 'string' && { summary: value.summary }),
    ...(typeof value.checkedAt === 'string' && { checkedAt: value.checkedAt }),
    ...(typeof value.provider === 'string' && { provider: value.provider }),
    ...(typeof value.model === 'string' && { model: value.model }),
    ...(isAgentReviewSource(value.source) ? { source: value.source } : {}),
    ...(isAgentReviewDisplayPath(value.path) ? { path: value.path } : {}),
    ...(isJsonObject(value.evidence) && { evidence: value.evidence }),
    ...(localized && { localized }),
    ...(checks && { checks }),
    ...(questions && { questions }),
    ...(answers && { answers }),
    ...(staleness && { staleness }),
    ...(reviewers && { reviewers }),
    ...(policies && { policies }),
    ...(history && { history }),
    ...(facts && { facts }),
    ...(conversation && { conversation }),
    ...(evidenceRequirements && { evidenceRequirements }),
    ...(evidenceFacts && { evidenceFacts }),
    ...(evidenceGate && { evidenceGate }),
    ...(decisionContract && { decisionContract }),
    ...(auditReceipt && { auditReceipt }),
    ...(decisionViolations && { decisionViolations }),
    ...(typeof value.reviewedPlanFingerprint === 'string' && { reviewedPlanFingerprint: value.reviewedPlanFingerprint }),
    ...(appliedUserPolicyIds && appliedUserPolicyIds.length ? { appliedUserPolicyIds } : {}),
  };
}

function parseAgentReviewStringArray(value: unknown, limit = 24): string[] | undefined {
  const entries = parseAgentReviewStringArrayValue(value, limit);
  return entries && entries.length ? entries : undefined;
}

function parseAgentReviewStringArrayValue(value: unknown, limit = 24): string[] | undefined {
  if (!Array.isArray(value)) return undefined;
  return value
    .filter((entry): entry is string => typeof entry === 'string' && Boolean(entry.trim()))
    .map((entry) => entry.trim())
    .slice(0, limit);
}

function parseAgentEvidenceRequirements(value: unknown): AgentEvidenceRequirement[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const requirements: AgentEvidenceRequirement[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    const status = entry.status === 'optional' ? 'optional' : entry.status === 'required' ? 'required' : undefined;
    if (
      typeof entry.id !== 'string' ||
      typeof entry.routeId !== 'string' ||
      typeof entry.need !== 'string' ||
      typeof entry.provider !== 'string' ||
      typeof entry.endpoint !== 'string' ||
      !status ||
      typeof entry.ttlMs !== 'number' ||
      !Number.isFinite(entry.ttlMs) ||
      typeof entry.blocking !== 'boolean' ||
      typeof entry.reason !== 'string'
    ) {
      continue;
    }
    requirements.push({
      id: entry.id,
      routeId: entry.routeId,
      need: entry.need as AgentEvidenceRequirement['need'],
      provider: entry.provider as AgentEvidenceRequirement['provider'],
      endpoint: entry.endpoint,
      status,
      ttlMs: entry.ttlMs,
      blocking: entry.blocking,
      reason: entry.reason,
      ...(typeof entry.connectorProfile === 'string' ? { connectorProfile: entry.connectorProfile as AgentEvidenceRequirement['connectorProfile'] } : {}),
      ...(typeof entry.connectorId === 'string' ? { connectorId: entry.connectorId } : {}),
      ...(typeof entry.capability === 'string' ? { capability: entry.capability } : {}),
    });
    if (requirements.length >= 64) break;
  }
  return requirements.length ? requirements : undefined;
}

function parseAgentEvidenceFacts(value: unknown): AgentEvidenceFact[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const facts: AgentEvidenceFact[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    const tone = entry.tone === 'good' || entry.tone === 'neutral' || entry.tone === 'warn' || entry.tone === 'fail'
      ? entry.tone
      : undefined;
    const freshness = entry.freshness === 'fresh' || entry.freshness === 'stale' || entry.freshness === 'missing'
      ? entry.freshness
      : undefined;
    const severity = entry.severity === 'info' || entry.severity === 'warn' || entry.severity === 'block'
      ? entry.severity
      : undefined;
    if (
      typeof entry.id !== 'string' ||
      typeof entry.label !== 'string' ||
      typeof entry.value !== 'string' ||
      !tone ||
      typeof entry.source !== 'string' ||
      typeof entry.checkedAt !== 'string' ||
      !freshness ||
      !severity
    ) {
      continue;
    }
    facts.push({
      id: entry.id,
      ...(typeof entry.requirementId === 'string' ? { requirementId: entry.requirementId } : {}),
      ...(typeof entry.routeId === 'string' ? { routeId: entry.routeId } : {}),
      label: entry.label,
      value: entry.value,
      tone,
      source: entry.source as AgentEvidenceFact['source'],
      checkedAt: entry.checkedAt,
      ...(typeof entry.expiresAt === 'string' ? { expiresAt: entry.expiresAt } : {}),
      freshness,
      severity,
      ...(isJsonObject(entry.detail) ? { detail: entry.detail } : {}),
      ...(typeof entry.usd === 'number' && Number.isFinite(entry.usd) ? { usd: entry.usd } : {}),
    });
    if (facts.length >= 96) break;
  }
  return facts.length ? facts : undefined;
}

function parseAgentEvidenceGateResult(value: unknown): AgentEvidenceGateResult | undefined {
  if (!isJsonObject(value)) return undefined;
  if (value.decision !== 'pass' && value.decision !== 'block' && value.decision !== 'needs_input') return undefined;
  if (typeof value.checkedAt !== 'string' || typeof value.reason !== 'string') return undefined;
  return {
    decision: value.decision,
    checkedAt: value.checkedAt,
    requirements: parseAgentEvidenceRequirements(value.requirements) ?? [],
    facts: parseAgentEvidenceFacts(value.facts) ?? [],
    missingRequired: parseAgentEvidenceRequirements(value.missingRequired) ?? [],
    staleRequired: parseAgentEvidenceRequirements(value.staleRequired) ?? [],
    blockingFacts: parseAgentEvidenceFacts(value.blockingFacts) ?? [],
    warnings: parseAgentEvidenceFacts(value.warnings) ?? [],
    reason: value.reason,
  };
}

function parseAgentDecisionContract(value: unknown): AgentDecisionContract | undefined {
  if (!isJsonObject(value)) return undefined;
  if (value.decision !== 'approve' && value.decision !== 'deny' && value.decision !== 'needs_input') return undefined;
  if (typeof value.reason !== 'string' || typeof value.summary !== 'string') return undefined;
  const evidenceFactIds = parseAgentReviewStringArrayValue(value.evidenceFactIds, 96);
  if (!evidenceFactIds) return undefined;
  const confidence = value.confidence === 'high' || value.confidence === 'medium' || value.confidence === 'low'
    ? value.confidence
    : undefined;
  const confidenceFactors = Array.isArray(value.confidenceFactors)
    ? value.confidenceFactors.filter(isJsonObject).filter((entry) => (
      typeof entry.id === 'string' &&
      typeof entry.label === 'string' &&
      typeof entry.delta === 'number' &&
      Number.isFinite(entry.delta)
    )).slice(0, 12) as unknown as AgentDecisionContract['confidenceFactors']
    : undefined;
  const counterfactuals = Array.isArray(value.counterfactuals)
    ? value.counterfactuals.filter(isJsonObject).slice(0, 12) as unknown as AgentDecisionContract['counterfactuals']
    : undefined;
  const missingFactIds = parseAgentReviewStringArray(value.missingFactIds, 96);
  const blockingFactIds = parseAgentReviewStringArray(value.blockingFactIds, 96);
  const warnings = parseAgentReviewStringArray(value.warnings, 24);
  const questions = parseAgentReviewQuestions(value.questions);
  return {
    decision: value.decision,
    ...(confidence ? { confidence } : {}),
    ...(typeof value.confidenceScore === 'number' && Number.isFinite(value.confidenceScore) ? { confidenceScore: value.confidenceScore } : {}),
    ...(confidenceFactors?.length ? { confidenceFactors } : {}),
    ...(counterfactuals?.length ? { counterfactuals } : {}),
    reason: value.reason,
    summary: value.summary,
    evidenceFactIds,
    ...(missingFactIds ? { missingFactIds } : {}),
    ...(blockingFactIds ? { blockingFactIds } : {}),
    ...(warnings ? { warnings } : {}),
    ...(questions ? { questions } : {}),
  };
}

function parseAgentDecisionAuditReceipt(value: unknown): AgentDecisionAuditReceipt | undefined {
  if (!isJsonObject(value)) return undefined;
  if (value.schemaVersion !== 1) return undefined;
  if (value.finalDecision !== 'approve' && value.finalDecision !== 'deny' && value.finalDecision !== 'needs_input') return undefined;
  if (value.gateDecision !== 'pass' && value.gateDecision !== 'block' && value.gateDecision !== 'needs_input') return undefined;
  const providerRoutes = parseAgentReviewStringArrayValue(value.providerRoutes, 64);
  const evidenceFactIds = parseAgentReviewStringArrayValue(value.evidenceFactIds, 96);
  const blockingFactIds = parseAgentReviewStringArrayValue(value.blockingFactIds, 96);
  const missingRequirementIds = parseAgentReviewStringArrayValue(value.missingRequirementIds, 96);
  if (
    typeof value.receiptId !== 'string' ||
    typeof value.planFingerprint !== 'string' ||
    typeof value.walletAddress !== 'string' ||
    typeof value.cluster !== 'string' ||
    typeof value.routePlanHash !== 'string' ||
    typeof value.evidenceHash !== 'string' ||
    typeof value.aiDecisionHash !== 'string' ||
    typeof value.checkedAt !== 'string' ||
    !providerRoutes ||
    !evidenceFactIds ||
    !blockingFactIds ||
    !missingRequirementIds
  ) {
    return undefined;
  }
  const confidenceBand = value.confidenceBand === 'high' || value.confidenceBand === 'medium' || value.confidenceBand === 'low'
    ? value.confidenceBand
    : undefined;
  return {
    schemaVersion: 1,
    receiptId: value.receiptId,
    planFingerprint: value.planFingerprint,
    walletAddress: value.walletAddress,
    cluster: value.cluster,
    ...(typeof value.connectorId === 'string' ? { connectorId: value.connectorId } : {}),
    ...(typeof value.connectorProfile === 'string' ? { connectorProfile: value.connectorProfile as AgentDecisionAuditReceipt['connectorProfile'] } : {}),
    routePlanHash: value.routePlanHash,
    evidenceHash: value.evidenceHash,
    aiDecisionHash: value.aiDecisionHash,
    finalDecision: value.finalDecision,
    gateDecision: value.gateDecision,
    checkedAt: value.checkedAt,
    providerRoutes,
    evidenceFactIds,
    blockingFactIds,
    missingRequirementIds,
    ...(typeof value.confidenceScore === 'number' && Number.isFinite(value.confidenceScore) ? { confidenceScore: value.confidenceScore } : {}),
    ...(confidenceBand ? { confidenceBand } : {}),
    ...(Array.isArray(value.counterfactualSummary)
      ? { counterfactualSummary: value.counterfactualSummary.filter(isJsonObject).slice(0, 12) as AgentDecisionAuditReceipt['counterfactualSummary'] }
      : {}),
    ...(isJsonObject(value.spotPrices) ? { spotPrices: value.spotPrices as AgentDecisionAuditReceipt['spotPrices'] } : {}),
    ...(typeof value.totalUsdAtRisk === 'number' && Number.isFinite(value.totalUsdAtRisk) ? { totalUsdAtRisk: value.totalUsdAtRisk } : {}),
  };
}

function parseAgentReviewChecks(value: unknown): AgentReviewCheck[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const rows: AgentReviewCheck[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    const label = typeof entry.label === 'string' ? entry.label.trim() : '';
    const rowValue = typeof entry.value === 'string' ? entry.value.trim() : '';
    if (!label || !rowValue) continue;
    const tone = entry.tone === 'good' || entry.tone === 'warn' || entry.tone === 'neutral' || entry.tone === 'fail'
      ? entry.tone
      : undefined;
    const source = entry.source === 'deterministic' || entry.source === 'ai' || entry.source === 'connector' || entry.source === 'user'
      ? entry.source
      : undefined;
    rows.push({
      label: compactSentence(label, 80),
      value: compactSentence(rowValue, 360),
      ...(tone ? { tone } : {}),
      ...(source ? { source } : {}),
      ...(isJsonObject(entry.detail) ? { detail: entry.detail } : {}),
    });
    if (rows.length >= 24) break;
  }
  return rows.length ? rows : undefined;
}

function parseAgentAskConversation(value: unknown): AgentAskExchange[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const exchanges: AgentAskExchange[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    if (typeof entry.id !== 'string' || typeof entry.question !== 'string' || typeof entry.askedAt !== 'string') continue;
    exchanges.push({
      id: entry.id,
      question: entry.question,
      askedAt: entry.askedAt,
      ...(typeof entry.answer === 'string' ? { answer: entry.answer } : {}),
      ...(Array.isArray(entry.citations) ? {
        citations: entry.citations.filter((citation): citation is { kind: string; ref: string; title?: string } => (
          isJsonObject(citation) &&
          typeof citation.kind === 'string' &&
          typeof citation.ref === 'string'
        )).slice(0, 8),
      } : {}),
      ...(typeof entry.error === 'string' ? { error: entry.error } : {}),
      ...(typeof entry.answeredAt === 'string' ? { answeredAt: entry.answeredAt } : {}),
      ...(entry.pending === true ? { pending: true } : {}),
      ...(isAgentReviewSource(entry.source) ? { source: entry.source } : {}),
      ...(typeof entry.provider === 'string' ? { provider: entry.provider } : {}),
      ...(typeof entry.model === 'string' ? { model: entry.model } : {}),
    });
    if (exchanges.length >= 6) break;
  }
  return exchanges.length ? exchanges : undefined;
}

function parseAgentReviewOverride(value: unknown): AgentReviewOverride | undefined {
  if (!isJsonObject(value)) return undefined;
  if (typeof value.overriddenAt !== 'string') return undefined;
  if (typeof value.agentReason !== 'string') return undefined;
  const status = value.agentStatus;
  if (!isAgentPlanReviewStatus(status)) return undefined;
  const decision = value.agentDecision === 'approve' || value.agentDecision === 'deny' || value.agentDecision === 'needs_input'
    ? value.agentDecision
    : undefined;
  return {
    overriddenAt: value.overriddenAt,
    agentStatus: status,
    agentReason: value.agentReason,
    ...(decision ? { agentDecision: decision } : {}),
    ...(typeof value.agentSummary === 'string' && { agentSummary: value.agentSummary }),
    ...(typeof value.userReason === 'string' && value.userReason.trim() && { userReason: value.userReason }),
    ...(typeof value.provider === 'string' && { provider: value.provider }),
    ...(typeof value.model === 'string' && { model: value.model }),
    ...(isAgentReviewSource(value.source) ? { source: value.source } : {}),
    ...(isAgentReviewDisplayPath(value.path) ? { path: value.path } : {}),
  };
}

function parseAgentReviewQuestions(value: unknown): AgentReviewQuestion[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const questions: AgentReviewQuestion[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    const prompt = typeof entry.prompt === 'string' ? entry.prompt.trim() : '';
    if (!prompt) continue;
    const id = typeof entry.id === 'string' && entry.id.trim()
      ? entry.id.trim()
      : `q${questions.length + 1}`;
    const inputKind = entry.inputKind === 'select' || entry.inputKind === 'number'
      ? (entry.inputKind as AgentReviewQuestion['inputKind'])
      : 'text';
    const options = Array.isArray(entry.options)
      ? entry.options.filter((value): value is string => typeof value === 'string' && value.trim().length > 0).slice(0, 8)
      : undefined;
    const hint = typeof entry.hint === 'string' && entry.hint.trim() ? entry.hint.trim() : undefined;
    questions.push({
      id,
      prompt,
      inputKind,
      required: entry.required !== false,
      ...(options?.length ? { options } : {}),
      ...(hint ? { hint } : {}),
    });
    if (questions.length >= 3) break;
  }
  return questions.length ? questions : undefined;
}

function parseAgentReviewAnswers(value: unknown): Record<string, string> | undefined {
  if (!isJsonObject(value)) return undefined;
  const answers: Record<string, string> = {};
  for (const [key, raw] of Object.entries(value)) {
    if (typeof key === 'string' && typeof raw === 'string') {
      answers[key] = raw;
    }
  }
  return Object.keys(answers).length ? answers : undefined;
}

function parseAgentReviewStaleness(value: unknown): AgentReviewStaleness | undefined {
  if (!isJsonObject(value)) return undefined;
  if (typeof value.staleSince !== 'string') return undefined;
  if (!Array.isArray(value.triggers)) return undefined;
  const triggers: AgentReviewStalenessTrigger[] = [];
  for (const entry of value.triggers) {
    if (!isJsonObject(entry)) continue;
    if (typeof entry.field !== 'string' || typeof entry.changedAt !== 'string') continue;
    triggers.push({
      field: entry.field,
      changedAt: entry.changedAt,
      ...(typeof entry.before === 'string' ? { before: entry.before } : {}),
      ...(typeof entry.after === 'string' ? { after: entry.after } : {}),
    });
  }
  return triggers.length ? { staleSince: value.staleSince, triggers } : undefined;
}

function parseAgentReviewerEntries(value: unknown): AgentReviewerEntry[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const entries: AgentReviewerEntry[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    if (typeof entry.id !== 'string' || typeof entry.label !== 'string') continue;
    if (entry.decision !== 'approve' && entry.decision !== 'deny' && entry.decision !== 'needs_input') continue;
    if (typeof entry.reason !== 'string' || typeof entry.checkedAt !== 'string') continue;
    entries.push({
      id: entry.id,
      label: entry.label,
      decision: entry.decision,
      reason: entry.reason,
      checkedAt: entry.checkedAt,
      ...(typeof entry.summary === 'string' ? { summary: entry.summary } : {}),
      ...(isJsonObject(entry.errored) && typeof entry.errored.message === 'string'
        ? { errored: { message: entry.errored.message } }
        : {}),
    });
    if (entries.length >= 4) break;
  }
  return entries.length ? entries : undefined;
}

function parseAgentReviewPolicySnapshots(value: unknown): AgentReviewPolicySnapshot[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const snapshots: AgentReviewPolicySnapshot[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    if (typeof entry.id !== 'string' || typeof entry.label !== 'string' || typeof entry.ruleText !== 'string') continue;
    if (entry.outcome !== 'pass' && entry.outcome !== 'warn' && entry.outcome !== 'block' && entry.outcome !== 'not_applicable') continue;
    snapshots.push({ id: entry.id, label: entry.label, ruleText: entry.ruleText, outcome: entry.outcome });
  }
  return snapshots.length ? snapshots : undefined;
}

function parseAgentReviewAttempts(value: unknown): AgentReviewAttempt[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const attempts: AgentReviewAttempt[] = [];
  for (const entry of value) {
    if (!isJsonObject(entry)) continue;
    if (typeof entry.attemptId !== 'string' || typeof entry.startedAt !== 'string') continue;
    const decision = entry.decision === 'approve' || entry.decision === 'deny' || entry.decision === 'needs_input'
      ? entry.decision
      : undefined;
    const followUpQuestionIds = Array.isArray(entry.followUpQuestionIds)
      ? entry.followUpQuestionIds.filter((value): value is string => typeof value === 'string')
      : undefined;
    const answersSnapshot = parseAgentReviewAnswers(entry.answersSnapshot);
    attempts.push({
      attemptId: entry.attemptId,
      startedAt: entry.startedAt,
      ...(typeof entry.finishedAt === 'string' ? { finishedAt: entry.finishedAt } : {}),
      ...(decision ? { decision } : {}),
      ...(typeof entry.reason === 'string' ? { reason: entry.reason } : {}),
      ...(followUpQuestionIds?.length ? { followUpQuestionIds } : {}),
      ...(answersSnapshot ? { answersSnapshot } : {}),
    });
    if (attempts.length >= 5) break;
  }
  return attempts.length ? attempts : undefined;
}

function parseAgentReviewFact(value: unknown): AgentReviewFact | undefined {
  if (!isJsonObject(value)) return undefined;
  if (
    value.state !== 'checked' &&
    value.state !== 'missing' &&
    value.state !== 'warn' &&
    value.state !== 'ok' &&
    value.state !== 'fail'
  ) {
    return undefined;
  }
  if (value.source !== 'deterministic' && value.source !== 'ai' && value.source !== 'connector') return undefined;
  if (typeof value.checkedAt !== 'string') return undefined;
  return {
    state: value.state,
    source: value.source,
    checkedAt: value.checkedAt,
    ...(typeof value.message === 'string' ? { message: value.message } : {}),
    ...(isJsonObject(value.detail) ? { detail: value.detail } : {}),
  };
}

function parseAgentReviewFactSet(value: unknown): AgentReviewFactSet | undefined {
  if (!isJsonObject(value)) return undefined;
  const slots: Array<keyof AgentReviewFactSet> = ['evidenceRoutes', 'research', 'quote', 'route', 'policy', 'simulation', 'protocol', 'protocolConnector', 'connectorRead', 'blinkAction', 'blinkClassification', 'tokenMint', 'recipient', 'limits', 'schedule', 'walletActivity', 'walletHoldings', 'marketSentiment', 'marketConditions'];
  const facts: AgentReviewFactSet = {};
  for (const slot of slots) {
    const fact = parseAgentReviewFact(value[slot]);
    if (fact) facts[slot] = fact;
  }
  return Object.keys(facts).length ? facts : undefined;
}

function isAgentPlan(value: unknown): value is AgentPlan {
  if (!value || typeof value !== 'object') return false;
  const plan = value as Partial<AgentPlan>;
  return (
    typeof plan.intent === 'string' &&
    typeof plan.route === 'string' &&
    typeof plan.risk === 'string' &&
    typeof plan.approval === 'string' &&
    (plan.source === 'template' || plan.source === 'ai') &&
    typeof plan.category === 'string' &&
    typeof plan.actionType === 'string' &&
    typeof plan.templateTitle === 'string' &&
    (plan.userNotes === undefined || typeof plan.userNotes === 'string') &&
    Boolean(plan.parameters) &&
    typeof plan.parameters === 'object' &&
    !Array.isArray(plan.parameters) &&
    Object.values(plan.parameters).every((entry) => typeof entry === 'string') &&
    Array.isArray(plan.fields) &&
    plan.fields.every(isAgentPlanField) &&
    Array.isArray(plan.safeguards) &&
    plan.safeguards.every((entry) => typeof entry === 'string')
  );
}

function isAgentPlanField(value: unknown): value is AgentPlan['fields'][number] {
  if (!value || typeof value !== 'object') return false;
  const field = value as Partial<AgentPlan['fields'][number]>;
  return typeof field.label === 'string' && typeof field.value === 'string';
}

function isGeneratedPlanStatus(value: unknown): value is GeneratedPlanStatus {
  return value === 'draft' || value === 'signed' || value === 'queued' || value === 'archived' || value === 'failed';
}

function loadLabArtifacts(): LabArtifact[] {
  try {
    const raw = window.localStorage.getItem(LAB_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? mergeLabArtifacts(parsed.filter(isLabArtifact)) : [];
  } catch {
    return [];
  }
}

async function hydrateLabArtifactArchive(): Promise<void> {
  const legacy = loadLabArtifacts();
  const indexed = await loadIndexedLabArtifacts().catch(() => []);
  const mode = activeWorkflowMode();
  const cloud = mode === 'agentic-cloud'
    ? await loadCloudEvidenceArtifacts().catch((err) => {
        state.cloudEvidenceStatus = tf('Cloud evidence archive unavailable: {message}', { message: err instanceof Error ? err.message : String(err) });
        return [] as LabArtifact[];
      })
    : [];
  state.labArtifacts = mergeLabArtifacts(state.labArtifacts, legacy, indexed, cloud);
  if (mode === 'agentic-cloud') {
    state.cloudEvidenceLastSyncAt = Date.now();
    state.cloudEvidenceStatus = cloud.length > 0
      ? cloudEvidenceSyncedStatus(cloud.length)
      : 'Cloud evidence archive ready (no receipts yet).';
  } else if (mode === 'local-bridge') {
    state.cloudEvidenceStatus = 'Private local mode: receipts stay off Agentic Cloud.';
  } else {
    state.cloudEvidenceStatus = 'Cloud evidence archive: sign in to also store receipts in Agentic Cloud.';
  }
  await requestPersistentLabArtifactStorage();
  await saveLabArtifacts();
}

async function saveLabArtifacts(): Promise<void> {
  state.labArtifacts = mergeLabArtifacts(state.labArtifacts);
  await saveIndexedLabArtifacts(state.labArtifacts).catch(() => undefined);
  try {
    window.localStorage.setItem(LAB_STORAGE_KEY, JSON.stringify(state.labArtifacts));
  } catch {
    // Best-effort browser persistence.
  }
}

function mergeLabArtifacts(...artifactGroups: unknown[][]): LabArtifact[] {
  const byId = new Map<string, LabArtifact>();
  for (const artifacts of artifactGroups) {
    for (const artifact of artifacts) {
      if (!isLabArtifact(artifact)) continue;
      const current = byId.get(artifact.id);
      if (!current || artifact.createdAt.localeCompare(current.createdAt) >= 0) {
        byId.set(artifact.id, artifact);
      }
    }
  }
  return [...byId.values()].sort((left, right) => right.createdAt.localeCompare(left.createdAt));
}

function isLabArtifact(value: unknown): value is LabArtifact {
  if (!value || typeof value !== 'object') return false;
  const artifact = value as Partial<LabArtifact>;
  if (artifact.cloudReceiptId !== undefined && (typeof artifact.cloudReceiptId !== 'string' || artifact.cloudReceiptId.length === 0)) return false;
  if (artifact.bridgeArchived !== undefined && typeof artifact.bridgeArchived !== 'boolean') return false;
  if (artifact.metadata !== undefined && !isJsonObject(artifact.metadata)) return false;
  return (
    typeof artifact.id === 'string' &&
    typeof artifact.labId === 'string' &&
    typeof artifact.title === 'string' &&
    typeof artifact.kind === 'string' &&
    typeof artifact.createdAt === 'string' &&
    typeof artifact.walletAddress === 'string' &&
    isCluster(artifact.cluster ?? '') &&
    typeof artifact.input === 'string' &&
    typeof artifact.preSignatureHash === 'string' &&
    typeof artifact.signingMessage === 'string' &&
    typeof artifact.signature === 'string' &&
    typeof artifact.verified === 'boolean' &&
    typeof artifact.artifactHash === 'string' &&
    isLabPayload(artifact.payload)
  );
}

function isLabPayload(value: unknown): value is LabPayload {
  if (!value || typeof value !== 'object') return false;
  const payload = value as Partial<LabPayload>;
  return (
    (payload.status === 'approved' || payload.status === 'blocked' || payload.status === 'warn' || payload.status === 'observed') &&
    typeof payload.thesis === 'string' &&
    typeof payload.nextSignatureGate === 'string' &&
    Array.isArray(payload.metrics) &&
    Array.isArray(payload.evidence)
  );
}

async function requestPersistentLabArtifactStorage(): Promise<void> {
  try {
    if (!navigator.storage?.persist) {
      state.labArchiveStatus = 'Browser archive ready.';
      return;
    }
    const alreadyPersistent = await navigator.storage.persisted?.();
    if (alreadyPersistent) {
      state.labArchiveStatus = 'Persistent browser archive ready.';
      return;
    }
    const granted = await navigator.storage.persist();
    state.labArchiveStatus = granted ? 'Persistent browser archive ready.' : 'Browser archive ready.';
  } catch {
    state.labArchiveStatus = 'Browser archive ready.';
  }
}

async function loadIndexedLabArtifacts(): Promise<LabArtifact[]> {
  const db = await openLabArchiveDb();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(LAB_ARCHIVE_STORE_NAME, 'readonly');
    const store = transaction.objectStore(LAB_ARCHIVE_STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(mergeLabArtifacts((request.result as unknown[]).filter(isLabArtifact)));
    request.onerror = () => reject(request.error ?? new Error(t('Unable to load lab artifact archive.')));
    transaction.oncomplete = () => db.close();
    transaction.onerror = () => {
      db.close();
      reject(transaction.error ?? new Error(t('Unable to load lab artifact archive.')));
    };
  });
}

async function saveIndexedLabArtifacts(artifacts: LabArtifact[]): Promise<void> {
  const db = await openLabArchiveDb();
  await new Promise<void>((resolve, reject) => {
    const transaction = db.transaction(LAB_ARCHIVE_STORE_NAME, 'readwrite');
    const store = transaction.objectStore(LAB_ARCHIVE_STORE_NAME);
    const clearRequest = store.clear();
    clearRequest.onsuccess = () => {
      for (const artifact of mergeLabArtifacts(artifacts)) {
        store.put(artifact);
      }
    };
    clearRequest.onerror = () => reject(clearRequest.error ?? new Error(t('Unable to clear lab artifact archive.')));
    transaction.oncomplete = () => {
      db.close();
      resolve();
    };
    transaction.onerror = () => {
      db.close();
      reject(transaction.error ?? new Error(t('Unable to save lab artifact archive.')));
    };
  });
}

function openLabArchiveDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) {
      reject(new Error(t('IndexedDB is unavailable.')));
      return;
    }
    const request = window.indexedDB.open(LAB_ARCHIVE_DB_NAME, LAB_ARCHIVE_DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(LAB_ARCHIVE_STORE_NAME)) {
        const store = db.createObjectStore(LAB_ARCHIVE_STORE_NAME, { keyPath: 'id' });
        store.createIndex('createdAt', 'createdAt');
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error(t('Unable to open lab artifact archive.')));
  });
}

// The agent's standing rules/memory — the important, always-visible half. Explicit Save (the draft +
// Saved/Unsaved pill) so it never silently auto-saves, and kept separate from Quick prompts below.
function agentRulesCard(scope: string): string {
  const draft = state.houseRulesDraft;
  const remaining = PLANNER_HOUSE_RULES_MAX - draft.length;
  const dirty = houseRulesDirty();
  return `
    <section class="agent-rules-card" aria-label="${escapeHtml(t('Agent rules & memory'))}">
      <div class="agent-rules-head">
        <div>
          <strong>${escapeHtml(t('Agent rules & memory'))}</strong>
          <p>${escapeHtml(t('Standing rules the agent remembers for every request and every chat. Wallet approval and signing stay separate.'))}</p>
        </div>
        <span class="agent-rules-status${dirty ? ' is-dirty' : ''}" data-house-rules-status>${escapeHtml(dirty ? t('Unsaved changes') : t('Saved'))}</span>
      </div>
      <textarea
        id="plannerHouseRules-${escapeHtml(scope)}"
        class="agent-rules-textarea"
        data-planner-pref="houseRules"
        rows="5"
        maxlength="${PLANNER_HOUSE_RULES_MAX}"
        placeholder="${escapeHtml(t("e.g. Never propose meme coins. Prefer USDC for stables. Always memo as 'work expense'."))}"
        ${state.busy ? 'disabled' : ''}
      >${escapeHtml(draft)}</textarea>
      <div class="agent-rules-foot">
        <em class="agent-rules-counter" data-house-rules-counter>${escapeHtml(tf('The agent keeps these in mind for every request and every chat. {remaining} characters left.', { remaining }))}</em>
        <button type="button" class="primary agent-rules-save" data-house-rules-action="save" ${!dirty || state.busy ? 'disabled' : ''}>${escapeHtml(t('Save rules'))}</button>
      </div>
    </section>
  `;
}

// Quick prompts — reusable request shortcuts. A DISTINCT card with its own Save, so it's clear these
// are not rules and the "Save quick prompt" button only saves a prompt.
function quickPromptsCard(): string {
  const prompts = state.plannerPrefs.savedPrompts;
  const draft = state.savedPromptDraft;
  const errors = state.savedPromptErrors;
  return `
    <section class="quick-prompts-card" aria-label="${escapeHtml(t('Quick prompts'))}">
      <div class="quick-prompts-head">
        <div>
          <strong>${escapeHtml(t('Quick prompts'))}</strong>
          <p>${escapeHtml(t('Reusable requests you can drop into a new request. Shortcuts only - they do not change how the agent behaves.'))}</p>
        </div>
        <em>${escapeHtml(savedPromptCountLabel(prompts.length))}</em>
      </div>
      <div class="planner-prompts-form">
        <label class="field compact">
          <span>${escapeHtml(t('Quick prompt name'))}</span>
          <input data-saved-prompt-field="label" value="${escapeHtml(draft.label)}" placeholder="${escapeHtml(t('Weekly rebalance'))}" autocomplete="off" ${state.busy ? 'disabled' : ''} />
          ${errors.label ? `<em class="error-text">${escapeHtml(t(errors.label))}</em>` : ''}
        </label>
        <label class="field compact planner-prompt-body-field">
          <span>${escapeHtml(t('Prompt'))}</span>
          <textarea data-saved-prompt-field="prompt" rows="2" placeholder="${escapeHtml(t('Rebalance to 50% SOL / 30% USDC / 20% JUP'))}" ${state.busy ? 'disabled' : ''}>${escapeHtml(draft.prompt)}</textarea>
          ${errors.prompt ? `<em class="error-text">${escapeHtml(t(errors.prompt))}</em>` : ''}
        </label>
        <div class="planner-prompts-actions">
          <button type="button" class="primary" data-saved-prompt-action="save" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Save quick prompt'))}</button>
          <button type="button" class="utility" data-saved-prompt-action="reset" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Clear'))}</button>
        </div>
      </div>
      ${prompts.length ? `<ul class="planner-prompts-list">${prompts.map(savedPromptRow).join('')}</ul>` : `<div class="planner-prompts-empty">${escapeHtml(t('No quick prompts yet.'))}</div>`}
    </section>
  `;
}

function savedPromptRow(prompt: SavedPrompt): string {
  return `
    <li class="planner-prompt-row" data-saved-prompt-id="${escapeHtml(prompt.id)}">
      <div>
        <strong>${escapeHtml(prompt.label)}</strong>
        <p>${escapeHtml(prompt.prompt)}</p>
      </div>
      <div class="planner-prompt-actions">
        <button type="button" data-saved-prompt-action="use" data-saved-prompt-id="${escapeHtml(prompt.id)}" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Use'))}</button>
        <button type="button" class="utility danger" data-saved-prompt-action="delete" data-saved-prompt-id="${escapeHtml(prompt.id)}" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Delete'))}</button>
      </div>
    </li>
  `;
}

// Typing edits the draft only (explicit Save commits it). Reflect Saved/Unsaved + the counter + the
// Save button's enabled state directly in the DOM so we don't re-render mid-keystroke and lose the caret.
function updateHouseRules(value: string): void {
  state.houseRulesDraft = value.slice(0, PLANNER_HOUSE_RULES_MAX);
  const dirty = houseRulesDirty();
  const remaining = PLANNER_HOUSE_RULES_MAX - state.houseRulesDraft.length;
  const status = document.querySelector('[data-house-rules-status]');
  if (status) {
    status.textContent = dirty ? t('Unsaved changes') : t('Saved');
    status.classList.toggle('is-dirty', dirty);
  }
  const saveBtn = document.querySelector<HTMLButtonElement>('[data-house-rules-action="save"]');
  if (saveBtn) saveBtn.disabled = !dirty || state.busy;
  const counter = document.querySelector('[data-house-rules-counter]');
  if (counter) {
    counter.textContent = tf('The agent keeps these in mind for every request and every chat. {remaining} characters left.', { remaining });
  }
}

function houseRulesDirty(): boolean {
  return state.houseRulesDraft !== state.plannerPrefs.houseRules;
}

function saveHouseRules(): void {
  if (!houseRulesDirty()) return;
  state.plannerPrefs.houseRules = state.houseRulesDraft.slice(0, PLANNER_HOUSE_RULES_MAX);
  savePlannerPrefs();
  pushToast('success', t('Rules saved'), t('The agent will use these for every request and chat.'));
  render();
}

function updateSavedPromptDraftField(field: HTMLInputElement | HTMLTextAreaElement): void {
  const key = field.dataset.savedPromptField;
  if (key === 'label' || key === 'prompt') {
    state.savedPromptDraft[key] = field.value;
    delete state.savedPromptErrors[key];
  }
}

function handleSavedPromptAction(button: HTMLButtonElement): void {
  const action = button.dataset.savedPromptAction;
  if (action === 'save') {
    saveSavedPromptDraft();
    return;
  }
  if (action === 'reset') {
    state.savedPromptDraft = defaultSavedPromptDraft();
    state.savedPromptErrors = {};
    render();
    return;
  }
  const promptId = button.dataset.savedPromptId;
  if (!promptId) return;
  if (action === 'delete') {
    deleteSavedPrompt(promptId);
    return;
  }
  if (action === 'use') {
    useSavedPrompt(promptId);
  }
}

function saveSavedPromptDraft(): void {
  const label = state.savedPromptDraft.label.trim();
  const prompt = state.savedPromptDraft.prompt.trim();
  const errors: Record<string, string> = {};
  if (!label) errors.label = 'Label is required.';
  if (!prompt) errors.prompt = 'Prompt body is required.';
  state.savedPromptErrors = errors;
  if (Object.keys(errors).length > 0) {
    render();
    return;
  }
  const now = new Date().toISOString();
  const entry: SavedPrompt = {
    id: newId('saved-prompt'),
    label: label.slice(0, 48),
    prompt: prompt.slice(0, 2000),
    createdAt: now,
    updatedAt: now,
  };
  state.plannerPrefs.savedPrompts = [entry, ...state.plannerPrefs.savedPrompts];
  state.savedPromptDraft = defaultSavedPromptDraft();
  state.savedPromptErrors = {};
  savePlannerPrefs();
  pushToast('success', t('Prompt saved'), entry.label);
  render();
}

function deleteSavedPrompt(promptId: string): void {
  const prompt = state.plannerPrefs.savedPrompts.find((entry) => entry.id === promptId);
  state.plannerPrefs.savedPrompts = state.plannerPrefs.savedPrompts.filter((entry) => entry.id !== promptId);
  savePlannerPrefs();
  pushToast('success', t('Prompt removed'), prompt?.label ?? promptId);
  render();
}

function useSavedPrompt(promptId: string): void {
  const prompt = state.plannerPrefs.savedPrompts.find((entry) => entry.id === promptId);
  if (!prompt) return;
  state.agentPrompt = prompt.prompt;
  pushToast('success', t('Prompt loaded'), prompt.label);
  render();
}

// === Phase 3 helpers: diagnostics, notifications, attach-tx ===

const DEBUG_LOG_LIMIT = 200;

function logDebug(event: Omit<DebugLogEvent, 'ts'>): void {
  const entry: DebugLogEvent = { ...event, ts: new Date().toISOString() };
  state.debugLog = [entry, ...state.debugLog].slice(0, DEBUG_LOG_LIMIT);
}

function buildDiagnosticBundle(options: { actionId?: string } = {}): string {
  const filtered = options.actionId
    ? state.debugLog.filter((event) => event.actionId === options.actionId)
    : state.debugLog;
  const bundle = {
    capturedAt: new Date().toISOString(),
    app: { name: 'Agentic Browser', cluster: state.cluster, bridgeActive: state.bridgeActive },
    rpcHost: rpcHostFromUrl(activeRpcUrl()),
    walletAddress: state.address ? short(state.address) : null,
    aiMode: state.aiSettings.mode,
    aiDiagnostics: state.aiDiagnostics,
    systemHealth: state.systemHealth,
    notificationSettings: state.notificationSettings,
    pendingLedger: state.pendingTransactions
      .filter((record) => !options.actionId || record.actionId === options.actionId)
      .map((record) => ({
        id: record.id,
        actionId: record.actionId,
        cluster: record.cluster,
        kind: record.kind,
        phase: record.phase,
        txid: record.txid,
        failureKind: record.failureKind,
        attemptCount: record.attemptCount,
        signedAt: record.signedAt,
        submittedAt: record.submittedAt,
        confirmedAt: record.confirmedAt,
        failedAt: record.failedAt,
        lastError: record.lastError,
        explorerUrl: record.explorerUrl,
      })),
    debugLog: filtered.slice(0, 60),
  };
  return redactSecrets(JSON.stringify(bundle, null, 2), state.aiSettings.apiKey);
}

async function copyDiagnosticBundle(actionId?: string): Promise<void> {
  try {
    const text = buildDiagnosticBundle({ actionId });
    await navigator.clipboard.writeText(text);
    pushToast('success', t('Debug log copied'), t('Safe to share. No keys, signed bytes, or secrets included.'));
  } catch (err) {
    const message = err instanceof Error ? err.message : t('Could not copy debug log.');
    pushToast('error', t('Copy failed'), message);
  }
}

async function resolveTransactionBySignature(cluster: Cluster, txid: string): Promise<TxResolution> {
  const connection = browserActionConnection(cluster);
  const tx = await connection.getTransaction(txid, {
    commitment: 'confirmed',
    maxSupportedTransactionVersion: 0,
  });
  if (!tx) {
    return { found: false, confirmed: false, failed: false, txid, signers: [], programIds: [] };
  }
  const message = tx.transaction.message;
  const accountKeys = message.getAccountKeys ? message.getAccountKeys().staticAccountKeys : [];
  const keys = accountKeys.map((key) => key.toBase58());
  const numSigners = message.header.numRequiredSignatures || 0;
  const signers = keys.slice(0, numSigners);
  const compiledInstructions = 'compiledInstructions' in message
    ? message.compiledInstructions
    : (message as unknown as { instructions: Array<{ programIdIndex: number }> }).instructions;
  const programIds = Array.from(new Set(
    compiledInstructions.map((ix) => keys[ix.programIdIndex]).filter((value): value is string => Boolean(value)),
  ));
  const failed = Boolean(tx.meta?.err);
  return {
    found: true,
    confirmed: !failed,
    failed,
    txid,
    slot: tx.slot,
    blockTime: tx.blockTime ?? undefined,
    signers,
    programIds,
    error: tx.meta?.err ? stringifySimulationError(tx.meta.err) : undefined,
  };
}

function validateTxMatchesAction(resolution: TxResolution, action: PreparedAction): AttachTxValidation {
  const warnings: string[] = [];
  if (!resolution.found) {
    warnings.push('Transaction not found on-chain yet.');
    return { match: false, warnings };
  }
  if (action.walletAddress && !resolution.signers.includes(action.walletAddress)) {
    warnings.push(`Wallet ${short(action.walletAddress)} did not sign this transaction.`);
  }
  if (action.kind === 'swap') {
    const touchesJupiter = resolution.programIds.some((id) => id.startsWith('JUP'));
    if (!touchesJupiter) warnings.push('Transaction does not touch a Jupiter program - expected for a swap.');
  }
  return { match: warnings.length === 0, warnings };
}

async function handleAttachTxAction(op: string, dataset: DOMStringMap): Promise<void> {
  switch (op) {
    case 'open':
      state.attachTxModal = { actionId: dataset.actionId, txidInput: '', busy: false };
      render();
      return;
    case 'cancel':
      state.attachTxModal = null;
      render();
      return;
    case 'lookup': {
      const modal = state.attachTxModal;
      if (!modal || !modal.txidInput.trim()) return;
      await runAttachTxLookup(modal.txidInput.trim());
      return;
    }
    case 'confirm':
      await runAttachTxConfirm();
      return;
  }
}

async function runAttachTxLookup(txid: string): Promise<void> {
  const modal = state.attachTxModal;
  if (!modal) return;
  const action = modal.actionId
    ? state.preparedActions.find((candidate) => candidate.id === modal.actionId)
    : undefined;
  const cluster = action?.cluster ?? state.cluster;
  state.attachTxModal = { ...modal, txidInput: txid, busy: true, error: undefined };
  render();
  try {
    const resolution = await resolveTransactionBySignature(cluster, txid);
    const validation = action ? validateTxMatchesAction(resolution, action) : { match: resolution.found, warnings: [] };
    state.attachTxModal = { ...modal, txidInput: txid, resolution, validation, busy: false };
    render();
  } catch (err) {
    const message = err instanceof Error ? err.message : t('Lookup failed.');
    state.attachTxModal = { ...modal, txidInput: txid, busy: false, error: message };
    logDebug({ level: 'error', source: 'rpc', message: `attach-tx lookup failed: ${message}`, txid });
    render();
  }
}

async function runAttachTxConfirm(): Promise<void> {
  const modal = state.attachTxModal;
  if (!modal || !modal.resolution) return;
  const action = modal.actionId
    ? state.preparedActions.find((candidate) => candidate.id === modal.actionId)
    : undefined;
  state.attachTxModal = { ...modal, busy: true };
  render();
  try {
    const resolution = modal.resolution;
    if (action) {
      upsertPendingTransaction({
        actionId: action.id,
        cluster: action.cluster,
        workflowSource: (action.workflowSource ?? 'browser') as LedgerWorkflowSource,
        kind: action.kind,
        phase: resolution.failed ? 'failed' : 'confirmed',
        walletAddress: action.walletAddress,
        txid: resolution.txid,
        confirmedAt: resolution.failed ? undefined : new Date().toISOString(),
        failedAt: resolution.failed ? new Date().toISOString() : undefined,
        explorerUrl: explorerUrl(resolution.txid, action.cluster),
      });
      const next: PreparedAction = {
        ...action,
        txid: resolution.txid,
        txStatus: resolution.failed ? 'failed' : 'confirmed',
        confirmedAt: resolution.failed ? undefined : new Date().toISOString(),
        txError: resolution.error,
        status: resolution.failed ? 'failed' : 'approved',
        updatedAt: new Date().toISOString(),
      };
      state.preparedActions = state.preparedActions.map((candidate) => candidate.id === action.id ? next : candidate);
      state.materializedActions = state.preparedActions;
      saveBrowserWorkflowState();
      syncPendingTransactionsFromLedger();
    }
    state.attachTxModal = null;
    pushToast(
      resolution.failed ? 'error' : 'success',
      resolution.failed ? t('Attached as failed') : t('Transaction attached'),
      tf('{tx} resolved on-chain.', { tx: short(resolution.txid) }),
      { linkHref: explorerUrl(resolution.txid, action?.cluster ?? state.cluster), linkLabel: t('Open Solscan') },
    );
    render();
  } catch (err) {
    const message = err instanceof Error ? err.message : t('Attach failed.');
    state.attachTxModal = { ...modal, busy: false, error: message };
    logDebug({ level: 'error', source: 'ledger', message: `attach-tx confirm failed: ${message}`, actionId: action?.id });
    render();
  }
}

function attachTxModalRender(): string {
  const modal = state.attachTxModal;
  if (!modal) return '';
  const resolution = modal.resolution;
  const validation = modal.validation;
  return `
    <div class="attach-tx-modal-scrim" data-attach-tx-action="cancel" aria-hidden="true"></div>
    <aside class="attach-tx-modal" role="dialog" aria-label="${escapeHtml(t('Attach existing transaction'))}">
      <header>
        <h3>${escapeHtml(t('Attach existing transaction'))}</h3>
        <button type="button" class="attach-tx-modal-close" data-attach-tx-action="cancel" aria-label="${escapeHtml(t('Cancel'))}">&times;</button>
      </header>
      <p>${escapeHtml(t('Paste a transaction signature to reconcile a pending or ambiguous approval.'))}</p>
      <div class="attach-tx-input-row">
        <input
          type="text"
          placeholder="${escapeHtml(t('Transaction signature'))}"
          value="${escapeHtml(modal.txidInput)}"
          data-attach-tx-input
          ${modal.busy ? 'disabled' : ''}
          spellcheck="false"
          autocomplete="off"
        />
        <button type="button" class="primary" data-attach-tx-action="lookup" ${modal.busy || !modal.txidInput.trim() ? 'disabled' : ''}>${modal.busy && !resolution ? escapeHtml(t('Looking up...')) : escapeHtml(t('Verify on-chain'))}</button>
      </div>
      ${modal.error ? `<p class="attach-tx-error">${escapeHtml(modal.error)}</p>` : ''}
      ${resolution ? `
        <div class="attach-tx-resolution ${resolution.failed ? 'failed' : resolution.confirmed ? 'confirmed' : 'pending'}">
          <div class="attach-tx-resolution-head">
            <strong>${resolution.failed ? escapeHtml(t('Found on-chain - transaction failed')) : resolution.confirmed ? escapeHtml(t('Found on-chain - confirmed')) : escapeHtml(t('Not yet confirmed'))}</strong>
            ${resolution.slot ? `<small>${tf('slot {slot}', { slot: resolution.slot })}</small>` : ''}
          </div>
          ${resolution.signers.length > 0 ? `<p>${tf('Signers: {signers}', { signers: `${resolution.signers.slice(0, 3).map((s) => escapeHtml(short(s))).join(', ')}${resolution.signers.length > 3 ? '...' : ''}` })}</p>` : ''}
          ${resolution.programIds.length > 0 ? `<p>${tf('Programs: {programs}', { programs: `${resolution.programIds.slice(0, 4).map((s) => escapeHtml(short(s))).join(', ')}${resolution.programIds.length > 4 ? '...' : ''}` })}</p>` : ''}
          ${resolution.error ? `<p class="attach-tx-error">${escapeHtml(resolution.error)}</p>` : ''}
          ${validation && validation.warnings.length > 0 ? `
            <ul class="attach-tx-warnings">
              ${validation.warnings.map((w) => `<li>${escapeHtml(w)}</li>`).join('')}
            </ul>
          ` : ''}
        </div>
      ` : ''}
      <footer>
        <button type="button" class="utility" data-attach-tx-action="cancel" ${modal.busy ? 'disabled' : ''}>${escapeHtml(t('Cancel'))}</button>
        <button type="button" class="primary" data-attach-tx-action="confirm" ${!resolution || modal.busy ? 'disabled' : ''}>
          ${modal.busy ? escapeHtml(t('Attaching...')) : validation && !validation.match ? escapeHtml(t('Attach anyway')) : escapeHtml(t('Attach to approval'))}
        </button>
      </footer>
    </aside>
  `;
}

let notificationTickerTimer: number | null = null;
const NOTIFICATION_TICKER_INTERVAL_MS = 30_000;

function startNotificationTicker(): void {
  stopNotificationTicker();
  notificationTickerTimer = window.setInterval(runNotificationTick, NOTIFICATION_TICKER_INTERVAL_MS);
}

function stopNotificationTicker(): void {
  if (notificationTickerTimer !== null) {
    window.clearInterval(notificationTickerTimer);
    notificationTickerTimer = null;
  }
}

function runNotificationTick(): void {
  if (!state.notificationSettings.browser) return;
  if (typeof Notification === 'undefined') return;
  if (Notification.permission !== 'granted') return;
  if (document.visibilityState === 'visible') return;
  for (const record of state.pendingTransactions) {
    if (state.notificationSettings.pending && (record.phase === 'submitted' || record.phase === 'ambiguous')) {
      const reference = record.submittedAt ?? record.lastAttemptAt;
      if (reference && Date.now() - new Date(reference).getTime() > 60_000) {
        fireNotificationOnce(
          'pending',
          record.id,
          t('Transaction still pending'),
          tf('Awaiting confirmation for {tx}.', { tx: short(record.txid ?? record.id) }),
        );
      }
    }
    if (state.notificationSettings.confirmed && record.phase === 'confirmed') {
      fireNotificationOnce('confirmed', record.id, t('Transaction confirmed'), short(record.txid ?? record.id));
    }
    if (state.notificationSettings.failed && record.phase === 'failed') {
      fireNotificationOnce('failed', record.id, t('Transaction failed'), record.lastError ?? short(record.id));
    }
  }
  if (state.notificationSettings.due) {
    const now = Date.now();
    for (const schedule of state.recurringPayments) {
      if (schedule.status !== 'active') continue;
      const next = schedule.startAt ? new Date(schedule.startAt).getTime() : NaN;
      if (!Number.isNaN(next) && next <= now + 5 * 60 * 1000 && next >= now - 5 * 60 * 1000) {
        fireNotificationOnce(
          'due',
          schedule.id,
          t('Repeat payment due'),
          tf('{amount} {token} to {recipient}', {
            amount: schedule.amount,
            token: schedule.token,
            recipient: short(schedule.recipient),
          }),
        );
      }
    }
  }
}

function fireNotificationOnce(category: string, recordId: string, title: string, body: string): void {
  const key = `${category}:${recordId}`;
  if (state.notifiedRecords[key]) return;
  state.notifiedRecords[key] = new Date().toISOString();
  saveNotifiedRecords();
  try {
    // Route to whichever notification surface exists: the native bridge on the app shells (the
    // WebView has no `Notification`), the Web Notification API in a browser.
    if (IS_IOS_APP) {
      void iosNativeShowNotification({ title, body, tag: key });
    } else if (IS_ANDROID_APP) {
      androidShowNotification({ title, body, tag: key });
    } else {
      new Notification(title, { body, tag: key });
    }
  } catch (err) {
    logDebug({ level: 'warn', source: 'ui', message: `notification failed: ${err instanceof Error ? err.message : String(err)}` });
  }
}

function loadNotifiedRecords(): Record<string, string> {
  try {
    const raw = window.localStorage.getItem(NOTIFIED_RECORDS_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
    const out: Record<string, string> = {};
    for (const [key, value] of Object.entries(parsed)) if (typeof value === 'string') out[key] = value;
    return out;
  } catch {
    return {};
  }
}

function saveNotifiedRecords(): void {
  try {
    let entries = Object.entries(state.notifiedRecords);
    if (entries.length > NOTIFIED_RECORDS_MAX) {
      // Evict oldest by timestamp; the values are ISO strings so lexical sort is chronological.
      entries = entries.sort((a, b) => (a[1] < b[1] ? 1 : -1)).slice(0, NOTIFIED_RECORDS_MAX);
      state.notifiedRecords = Object.fromEntries(entries);
    }
    window.localStorage.setItem(NOTIFIED_RECORDS_STORAGE_KEY, JSON.stringify(state.notifiedRecords));
  } catch {
    /* Best-effort browser persistence. */
  }
}

// Operator kill-switch for the whole push path (server-sent, closed-app). A build constant rather
// than remote config: flipping it is a Render redeploy that reaches every surface's live bundle, and
// it's the "server" half of the two-flags-must-agree gate (the other half is the binary bridge probe).
const PUSH_NOTIFICATIONS_ENABLED = true;

function notificationSurfaceNow(): NotificationSurface {
  return notificationSurface({ isIosApp: IS_IOS_APP, isAndroidApp: IS_ANDROID_APP });
}

/** Does THIS binary expose the native push bridge? iOS Capacitor builds always do; Android needs the
 *  capability bit an old APK lacks. */
function notificationBridgeAvailable(): boolean {
  if (IS_IOS_APP) return true;
  if (IS_ANDROID_APP) return androidNotificationsBridgeAvailable();
  return false;
}

function notificationPushAvailability(): ReturnType<typeof pushAvailability> {
  return pushAvailability({
    surface: notificationSurfaceNow(),
    serverEnabled: PUSH_NOTIFICATIONS_ENABLED,
    bridgeAvailable: notificationBridgeAvailable(),
    signedIn: state.cloudSession.status === 'signed-in' && cloudSessionMatchesWallet(),
  });
}

// The category ids match the NotificationSettingsState field names 1:1 (minus the `browser` master),
// so a category id indexes settings directly.
function currentNotificationCategoryMap(): NotificationCategoryMap {
  const s = state.notificationSettings;
  return {
    due: s.due,
    confirmed: s.confirmed,
    failed: s.failed,
    limitFilled: s.limitFilled,
    dcaFilled: s.dcaFilled,
    borrowAtRisk: s.borrowAtRisk,
    pending: s.pending,
  };
}

let pushRegisterInFlight = false;

/**
 * Reconcile this device's push registration with the current toggles. Registers (fetching the native
 * token) when push is available and any push-capable category is on; unregisters when none are. Called
 * on every relevant toggle and on sign-in. Best-effort — a failure leaves local alerts working.
 */
async function syncPushDeviceRegistration(): Promise<void> {
  const availability = notificationPushAvailability();
  if (!availability.available || pushRegisterInFlight) return;
  const categoryMap = currentNotificationCategoryMap();
  pushRegisterInFlight = true;
  try {
    if (!hasAnyPushCategory(categoryMap)) {
      await unregisterPushDevice();
      return;
    }
    const registration = IS_IOS_APP ? await iosNativeRegisterForPush() : await androidRequestNotificationPermission();
    if (!registration.ok || !registration.token) {
      if (registration.status === 'denied') {
        pushToast('info', t('Notifications off'), t('Enable notifications in system settings to receive alerts.'));
      }
      return;
    }
    state.notificationSettings.permission = registration.status === 'denied' ? 'denied' : 'granted';
    savePersistedState();
    await cloudRequest('/api/push/register-device', {
      method: 'POST',
      body: JSON.stringify({
        platform: IS_IOS_APP ? 'ios' : 'android',
        token: registration.token,
        categories: pushCategoryMapForRegistration(categoryMap),
      }),
    });
    rememberPushDeviceToken(IS_IOS_APP ? 'ios' : 'android', registration.token);
  } catch (err) {
    logDebug({ level: 'warn', source: 'ui', message: `push register failed: ${err instanceof Error ? err.message : String(err)}` });
  } finally {
    pushRegisterInFlight = false;
    render();
  }
}

// The registered token, kept so we can unregister the exact device later (the server keys on it).
const PUSH_DEVICE_TOKEN_KEY = 'solana-agent-wallet-push-device-v1';
function rememberPushDeviceToken(platform: 'ios' | 'android', token: string): void {
  try {
    window.localStorage.setItem(PUSH_DEVICE_TOKEN_KEY, JSON.stringify({ platform, token }));
  } catch {
    /* best-effort */
  }
}
function rememberedPushDevice(): { platform: 'ios' | 'android'; token: string } | null {
  try {
    const raw = window.localStorage.getItem(PUSH_DEVICE_TOKEN_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    if (parsed && (parsed.platform === 'ios' || parsed.platform === 'android') && typeof parsed.token === 'string') {
      return parsed;
    }
    return null;
  } catch {
    return null;
  }
}

async function unregisterPushDevice(): Promise<void> {
  const device = rememberedPushDevice();
  if (!device) return;
  try {
    await cloudRequest('/api/push/unregister-device', { method: 'POST', body: JSON.stringify(device) });
    window.localStorage.removeItem(PUSH_DEVICE_TOKEN_KEY);
  } catch {
    /* best-effort — server also reaps dead tokens on 410 */
  }
}

/**
 * A tapped notification carries a routing hint the server set ({ tab, section, … }). Navigate to it.
 * Tolerant of unknown tabs: an old binary tapping a route for a tab it doesn't have just no-ops.
 */
function handlePushTapRoute(route: Record<string, string>): void {
  const tab = route.tab;
  if (!tab) return;
  const known = new Set(['positions', 'completed', 'inbox', 'chat', 'overview']);
  if (known.has(tab)) {
    state.activeTab = tab as typeof state.activeTab;
    if (tab === 'positions' && route.section) state.positionsCategory = route.section as PositionsFilterId;
    render();
  }
}

let pushTapWired = false;
/** Wire notification-tap routing + drain any cold-launch tap the native side buffered. */
function initPushTapRouting(): void {
  if (pushTapWired || !surfaceIsNativeApp(notificationSurfaceNow())) return;
  pushTapWired = true;
  if (IS_IOS_APP) {
    void iosNativeOnPushTap(handlePushTapRoute);
  } else if (IS_ANDROID_APP) {
    onAndroidPushTap(handlePushTapRoute);
    const coldRoute = consumeAndroidPushRoute();
    if (coldRoute) handlePushTapRoute(coldRoute);
    // A token FCM rotated to while closed (couldn't register then) → re-register now.
    const pendingToken = consumeAndroidPendingPushToken();
    if (pendingToken) void syncPushDeviceRegistration();
  }
}

async function handleNotificationAction(op: string): Promise<void> {
  if (op === 'request-permission') {
    if (surfaceIsNativeApp(notificationSurfaceNow())) {
      // Native: prompt + register for push in one step. On iOS the plugin self-prompts; on Android
      // this is the POST_NOTIFICATIONS runtime request that never existed before.
      state.notificationSettings.browser = true;
      // Turn on the always-useful defaults so a fresh grant actually delivers something.
      if (!hasAnyPushCategory(currentNotificationCategoryMap())) {
        state.notificationSettings.confirmed = true;
        state.notificationSettings.due = true;
      }
      savePersistedState();
      render();
      await syncPushDeviceRegistration();
      return;
    }
    if (typeof Notification === 'undefined') {
      pushToast('error', t('Not supported'), t('This browser does not expose the Notification API.'));
      return;
    }
    try {
      const permission = await Notification.requestPermission();
      state.notificationSettings.permission = permission;
      if (permission === 'granted') state.notificationSettings.browser = true;
      savePersistedState();
      render();
    } catch (err) {
      const message = err instanceof Error ? err.message : t('Permission request failed.');
      pushToast('error', t('Permission failed'), message);
    }
    return;
  }

  // Only the boolean fields (never `permission`), so the indexed assignment below stays a boolean.
  type NotificationToggleField = Exclude<keyof NotificationSettingsState, 'permission'>;
  const toggleField: Partial<Record<string, NotificationToggleField>> = {
    'toggle-browser': 'browser',
    'toggle-due': 'due',
    'toggle-pending': 'pending',
    'toggle-confirmed': 'confirmed',
    'toggle-failed': 'failed',
    'toggle-limitFilled': 'limitFilled',
    'toggle-dcaFilled': 'dcaFilled',
    'toggle-borrowAtRisk': 'borrowAtRisk',
  };
  const field = toggleField[op];
  if (!field) return;
  state.notificationSettings[field] = !state.notificationSettings[field];
  savePersistedState();
  render();
  // A push-category toggle changes what this device should receive — re-sync the registration. `pending`
  // is a web-only client timer (no device registration); `browser` is the master switch, so toggling it
  // off/on must re-sync so the device stops/starts receiving push.
  if (field !== 'pending') void syncPushDeviceRegistration();
}

function notificationPreferencesPanel(): string {
  const settings = state.notificationSettings;
  const surface = notificationSurfaceNow();
  const native = surfaceIsNativeApp(surface);
  const push = notificationPushAvailability();
  // 'unsupported' now genuinely means "nowhere to notify" — native surfaces always have the bridge, so
  // only a browser with no Notification API lands here.
  const supported = native || settings.permission !== 'unsupported';

  const blurb = t(notificationCardBlurbKey(surface, push));
  // The primary CTA: on native it enables device notifications (permission + push register); on web it
  // requests the browser permission. Shown until granted.
  const needsCta = native ? !settings.browser : settings.permission !== 'granted';
  const ctaLabel = native ? t('Turn on notifications') : t('Request permission');

  // The push-capable categories the user can toggle. `pending` is web-only (a client-side timer with no
  // server event), so it's hidden on native where push is the delivery model.
  const rows: string[] = [
    notificationToggleRow('toggle-confirmed', t('Transaction confirmed'), settings.confirmed),
    notificationToggleRow('toggle-failed', t('Transaction failed'), settings.failed),
    notificationToggleRow('toggle-due', t('Repeat payment due'), settings.due),
  ];
  // limitFilled/dcaFilled/borrowAtRisk are delivered ONLY by server push (native). The web ticker
  // (runNotificationTick) never fires them, so on web they'd be dead toggles that just persist — show
  // them on native only, mirroring how `pending` (a web-only client timer) is hidden on native.
  if (native) {
    rows.push(
      notificationToggleRow('toggle-limitFilled', t('Limit order filled'), settings.limitFilled),
      notificationToggleRow('toggle-dcaFilled', t('DCA order filled'), settings.dcaFilled),
      notificationToggleRow('toggle-borrowAtRisk', t('Borrow position at risk'), settings.borrowAtRisk),
    );
  } else {
    rows.unshift(notificationToggleRow('toggle-pending', t('Pending transactions (>60s)'), settings.pending));
  }
  // Master on/off. `browser` gates the web ticker (runNotificationTick returns early when false) and the
  // native enabled-state, but nothing let the user turn it back off without revoking OS permission.
  // Show it once notifications are active so they can mute everything without losing the grant.
  if (!needsCta) {
    rows.unshift(notificationToggleRow('toggle-browser', t('All notifications'), settings.browser));
  }

  return `
    <section class="notification-prefs-panel" aria-label="${escapeHtml(t('Notifications'))}">
      <div class="notification-prefs-head">
        <strong>${escapeHtml(t('Notifications'))}</strong>
        <p>${escapeHtml(blurb)}</p>
      </div>
      ${supported ? `
        ${needsCta ? `<div class="notification-prefs-permission">
          <button type="button" class="primary" data-notification-action="request-permission">${escapeHtml(ctaLabel)}</button>
        </div>` : ''}
        <ul class="notification-prefs-list">
          ${rows.join('\n          ')}
        </ul>
      ` : `<p>${escapeHtml(t('This browser does not expose the Notification API.'))}</p>`}
    </section>
  `;
}

function notificationToggleRow(action: string, label: string, value: boolean): string {
  return `
    <li>
      <span>${escapeHtml(label)}</span>
      <button type="button" class="safety-rails-toggle ${value ? 'active' : ''}" data-notification-action="${escapeHtml(action)}">${value ? 'on' : 'off'}</button>
    </li>
  `;
}

function updateTabTitleBadge(): void {
  const current = document.title.replace(/^\(\d+\)\s*/, '');
  const pending = state.pendingTransactions.filter((record) =>
    record.phase === 'submitted' || record.phase === 'ambiguous' || record.phase === 'confirming',
  ).length;
  const approvals = state.preparedActions.filter((action) => !isTerminalPreparedAction(action)).length;
  const count = pending + approvals;
  document.title = count > 0 ? `(${count}) ${current}` : current;
}

function defaultFailurePoliciesList(): FailureRetryPolicy[] {
  return FAILURE_RETRY_KINDS.map((kind) => ({ kind, mode: 'ask' as FailureRetryMode, maxAttempts: 2 }));
}

function loadFailurePolicies(): FailureRetryPolicy[] {
  try {
    const raw = window.localStorage.getItem(FAILURE_POLICIES_STORAGE_KEY);
    if (!raw) return defaultFailurePoliciesList();
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return defaultFailurePoliciesList();
    const byKind = new Map<TransactionFailureKind, FailureRetryPolicy>();
    for (const entry of parsed) {
      const policy = parseFailurePolicy(entry);
      if (policy) byKind.set(policy.kind, policy);
    }
    return FAILURE_RETRY_KINDS.map((kind) =>
      byKind.get(kind) ?? { kind, mode: 'ask' as FailureRetryMode, maxAttempts: 2 },
    );
  } catch {
    return defaultFailurePoliciesList();
  }
}

function saveFailurePolicies(options: { sync?: boolean } = {}): void {
  try {
    window.localStorage.setItem(FAILURE_POLICIES_STORAGE_KEY, JSON.stringify(state.failurePolicies));
  } catch {
    // Best-effort.
  }
  if (options.sync !== false) {
    void syncCloudPreference('failure-policies');
  }
}

function parseFailurePolicy(value: unknown): FailureRetryPolicy | null {
  if (!value || typeof value !== 'object') return null;
  const raw = value as Partial<FailureRetryPolicy>;
  if (!isTransactionFailureKind(raw.kind)) return null;
  const mode: FailureRetryMode =
    raw.mode === 'auto' || raw.mode === 'ask' || raw.mode === 'disabled' ? raw.mode : 'ask';
  const maxAttempts = typeof raw.maxAttempts === 'number' && Number.isFinite(raw.maxAttempts)
    ? Math.max(0, Math.min(10, Math.floor(raw.maxAttempts)))
    : 2;
  return { kind: raw.kind, mode, maxAttempts };
}

function isTransactionFailureKind(value: unknown): value is TransactionFailureKind {
  return typeof value === 'string' && (FAILURE_RETRY_KINDS as readonly string[]).includes(value);
}

function policyForFailure(kind: TransactionFailureKind): FailureRetryPolicy {
  return state.failurePolicies.find((policy) => policy.kind === kind) ?? { ...DEFAULT_FAILURE_POLICY, kind };
}

function resetFailurePoliciesToRecommended(): void {
  state.failurePolicies = FAILURE_RETRY_KINDS.map((kind) => ({
    kind,
    mode: (FAILURE_RECOMMENDED_AUTO.has(kind) ? 'auto' : 'ask') as FailureRetryMode,
    maxAttempts: 2,
  }));
  saveFailurePolicies();
  pushToast('success', t('Defaults restored'), t('Recommended auto-retry policies set.'));
  render();
}

function setFailurePolicyMode(kind: TransactionFailureKind, mode: FailureRetryMode): void {
  state.failurePolicies = state.failurePolicies.map((policy) =>
    policy.kind === kind ? { ...policy, mode } : policy,
  );
  saveFailurePolicies();
  render();
}

function setFailurePolicyMaxAttempts(kind: TransactionFailureKind, value: string): void {
  const num = Number(value);
  const clamped = Number.isFinite(num) ? Math.max(0, Math.min(10, Math.floor(num))) : 2;
  state.failurePolicies = state.failurePolicies.map((policy) =>
    policy.kind === kind ? { ...policy, maxAttempts: clamped } : policy,
  );
  saveFailurePolicies();
}

// Count only kinds that can actually auto-retry — a stale mode:'auto' persisted for a non-retryable
// kind (e.g. from the old recommended defaults that flipped expired_blockhash on) must not inflate the
// "N auto" summaries now that those kinds render as always-stops.
function autoRetryEnabledCount(policies: ReadonlyArray<FailureRetryPolicy>): number {
  return policies.filter((p) => p.mode === 'auto' && isAutoRetryableSignedBroadcastKind(p.kind)).length;
}

function failurePoliciesPanel(): string {
  const policies = state.failurePolicies;
  const autoCount = autoRetryEnabledCount(policies);
  const mobile = isMobileAppViewport();
  const open = mobile || autoCount > 0 ? 'open' : '';
  return `
    <details class="failure-policies-panel rail-details" data-layout="failure-policies-panel" ${open}>
      <summary>
        <span class="failure-policies-summary-copy">
          <span>${escapeHtml(t('Failure auto-retry'))}</span>
          <em>${escapeHtml(autoCount === 0 ? t('All ask') : tf('{count} kinds auto', { count: autoCount }))}</em>
        </span>
        <strong>${autoCount === 0 ? t('off') : `${autoCount}`}</strong>
      </summary>
      <section class="failure-policies-card" aria-label="${escapeHtml(t('Failure retry preferences'))}">
        <p class="failure-policies-intro">${escapeHtml(t('Most failures should stop and ask. Use auto-retry only for network conditions you are comfortable replaying up to the cap.'))}</p>
        <div class="failure-policies-actions">
          <button type="button" class="utility" data-failure-policy-action="reset">${escapeHtml(t('Use recommended defaults'))}</button>
        </div>
        ${failurePolicyGroupedList(policies)}
      </section>
    </details>
  `;
}

function failurePolicyGroupedList(policies: FailureRetryPolicy[]): string {
  const policiesByKind = new Map(policies.map((policy) => [policy.kind, policy]));
  const groups = groupedFailureRetryKinds(FAILURE_RETRY_KINDS);
  // Desktop has the room to show the whole matrix at once, so groups open by
  // default there and only act as section headers. Mobile collapses the ones
  // that are all-ask to keep the list scannable.
  const collapsible = isMobileAppViewport();
  return `
    <div class="failure-policy-group-list">
      ${groups.map((group) => {
        const groupPolicies = group.kinds
          .map((kind) => isTransactionFailureKind(kind) ? policiesByKind.get(kind) : undefined)
          .filter((policy): policy is FailureRetryPolicy => Boolean(policy));
        const autoCount = autoRetryEnabledCount(groupPolicies);
        return `
          <details class="failure-policy-group" ${!collapsible || autoCount > 0 ? 'open' : ''}>
            <summary>
              <span>
                <strong>${escapeHtml(group.title)}</strong>
                <em>${escapeHtml(group.detail)}</em>
              </span>
              <b>${autoCount > 0 ? tf('{count} auto', { count: autoCount }) : t('ask')}</b>
            </summary>
            <div class="failure-policy-list">
              ${groupPolicies.map(failurePolicyRow).join('')}
            </div>
          </details>
        `;
      }).join('')}
    </div>
  `;
}

function failurePolicyRow(policy: FailureRetryPolicy): string {
  const label = FAILURE_KIND_LABEL[policy.kind] ? t(FAILURE_KIND_LABEL[policy.kind]) : policy.kind;
  const help = FAILURE_KIND_HELP[policy.kind] ? t(FAILURE_KIND_HELP[policy.kind]) : t('Choose whether this failure should retry.');
  // Only same-bytes-rebroadcastable kinds get the Auto/Ask/Off + cap controls. For every other class a
  // replay of the identical signed bytes can't help (needs a re-sign, a fix, or a real stop), so
  // offering an Auto toggle would be the dishonest "dead knob" this panel used to have. Show an
  // informational chip instead — it also matches the intro's "most failures should stop and ask".
  if (!isAutoRetryableSignedBroadcastKind(policy.kind)) {
    return `
      <article class="failure-policy-row is-always-stop" data-failure-policy-kind="${escapeHtml(policy.kind)}">
        <div>
          <strong>${escapeHtml(label)}</strong>
          <em>${escapeHtml(help)}</em>
        </div>
        <span class="failure-policy-always-stop" title="${escapeHtml(t('This failure is never safe to auto-replay with the same signed transaction. The app always stops and hands it back to you.'))}">${escapeHtml(t('Always stops · asks you'))}</span>
      </article>
    `;
  }
  const showAttempts = !isMobileAppViewport() || policy.mode === 'auto';
  return `
    <article class="failure-policy-row mode-${escapeHtml(policy.mode)}" data-failure-policy-kind="${escapeHtml(policy.kind)}">
      <div>
        <strong>${escapeHtml(label)}</strong>
        <em>${escapeHtml(help)}</em>
      </div>
      <div class="failure-policy-mode-controls" role="group" aria-label="${escapeHtml(t('Mode'))}">
        ${failurePolicyModeButton(policy, 'auto', t('Auto'))}
        ${failurePolicyModeButton(policy, 'ask', t('Ask'))}
        ${failurePolicyModeButton(policy, 'disabled', t('Off'))}
      </div>
      ${showAttempts ? `<label class="failure-policy-max-attempts">
        <span>${escapeHtml(t('Max retries'))}</span>
        <input type="number" inputmode="numeric" min="0" max="10" step="1" value="${policy.maxAttempts}" data-failure-policy-field="maxAttempts" data-failure-policy-kind="${escapeHtml(policy.kind)}" ${state.busy ? 'disabled' : ''} />
      </label>` : ''}
    </article>
  `;
}

function failurePolicyModeButton(policy: FailureRetryPolicy, mode: FailureRetryMode, label: string): string {
  const active = policy.mode === mode;
  return `
    <button
      type="button"
      data-failure-policy-action="mode"
      data-failure-policy-kind="${escapeHtml(policy.kind)}"
      data-failure-policy-mode="${escapeHtml(mode)}"
      class="${active ? 'active' : ''}"
      aria-pressed="${active ? 'true' : 'false'}"
      ${state.busy ? 'disabled' : ''}
    >${escapeHtml(label)}</button>
  `;
}

function handleFailurePolicyAction(button: HTMLButtonElement): void {
  const action = button.dataset.failurePolicyAction;
  if (action === 'reset') {
    resetFailurePoliciesToRecommended();
    return;
  }
  if (action === 'mode') {
    const kind = button.dataset.failurePolicyKind;
    const mode = button.dataset.failurePolicyMode;
    if (isTransactionFailureKind(kind) && (mode === 'auto' || mode === 'ask' || mode === 'disabled')) {
      setFailurePolicyMode(kind, mode);
    }
  }
}

function handleFailurePolicyFieldChange(field: HTMLInputElement): void {
  const fieldKey = field.dataset.failurePolicyField;
  const kind = field.dataset.failurePolicyKind;
  if (fieldKey !== 'maxAttempts' || !isTransactionFailureKind(kind)) return;
  setFailurePolicyMaxAttempts(kind, field.value);
}

function planTemplatesStrip(embedded: boolean): string {
  const templates = templateGeneratedPlans(embedded);
  if (!templates.length) return '';
  return `
    <div class="plan-templates-strip" aria-label="${escapeHtml(t('Plan templates'))}">
      <header>
        <strong>${escapeHtml(t('Templates'))}</strong>
        <em>${escapeHtml(tf('{count} saved · click Use to clone into a new draft', { count: templates.length }))}</em>
      </header>
      <ul class="plan-templates-list">
        ${templates.map(planTemplateRow).join('')}
      </ul>
    </div>
  `;
}

function planTemplateRow(record: GeneratedPlanRecord): string {
  const label = record.templateLabel?.trim() || record.templateTitle || record.plan.intent || t('Template');
  return `
    <li class="plan-template-row" data-generated-plan-id="${escapeHtml(record.id)}">
      <div>
        <strong>${escapeHtml(label)}</strong>
        <em>${escapeHtml(record.plan.actionType || record.source)}</em>
        <p>${escapeHtml(record.plan.intent || '')}</p>
      </div>
      <div class="plan-template-actions">
        <button type="button" class="primary" data-template-action="use" data-generated-plan-id="${escapeHtml(record.id)}" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Use'))}</button>
        <button type="button" class="utility" data-template-action="unmark" data-generated-plan-id="${escapeHtml(record.id)}" ${state.busy ? 'disabled' : ''} title="${escapeHtml(t('Stop treating this draft as a template'))}">${escapeHtml(t('Unmark'))}</button>
        <button type="button" class="utility danger" data-template-action="delete" data-generated-plan-id="${escapeHtml(record.id)}" ${state.busy ? 'disabled' : ''}>${escapeHtml(t('Delete'))}</button>
      </div>
    </li>
  `;
}

function handleTemplateAction(button: HTMLButtonElement): void {
  const action = button.dataset.templateAction;
  const planId = button.dataset.generatedPlanId;
  if (!action || !planId) return;
  if (action === 'save-as') {
    saveGeneratedPlanAsTemplate(planId);
    return;
  }
  if (action === 'use') {
    cloneTemplateAsDraft(planId);
    return;
  }
  if (action === 'unmark') {
    unmarkPlanTemplate(planId);
    return;
  }
  if (action === 'delete') {
    deleteGeneratedPlanTemplate(planId);
  }
}

function saveGeneratedPlanAsTemplate(planId: string): void {
  const record = generatedPlanById(planId);
  if (!record) return;
  const defaultLabel = record.templateLabel || record.templateTitle || record.plan.intent.slice(0, 48);
  const label = (window.prompt(t('Save as template - label?'), defaultLabel) ?? '').trim();
  if (!label) return;
  const now = new Date().toISOString();
  state.generatedPlans = state.generatedPlans.map((entry) =>
    entry.id === planId ? { ...entry, template: true, templateLabel: label.slice(0, 64), updatedAt: now } : entry,
  );
  saveGeneratedPlans();
  pushToast('success', t('Template saved'), label);
  render();
}

function cloneTemplateAsDraft(planId: string): void {
  const template = generatedPlanById(planId);
  if (!template || !template.template) return;
  const now = new Date().toISOString();
  const cloned: GeneratedPlanRecord = {
    ...template,
    id: newId('plan'),
    createdAt: now,
    updatedAt: now,
    status: 'draft',
    template: false,
    ...(template.templateLabel ? { templateLabel: undefined } : {}),
    signature: undefined,
    preparedActionId: undefined,
    error: undefined,
    failureLabel: undefined,
    agentReview: undefined,
    agentOverride: undefined,
  };
  state.generatedPlans = [cloned, ...state.generatedPlans];
  state.selectedGeneratedPlanId = cloned.id;
  saveGeneratedPlans();
  pushToast('success', t('Template used'), tf('Created draft from {template}', { template: template.templateLabel ?? t('template') }));
  render();
}

function unmarkPlanTemplate(planId: string): void {
  const now = new Date().toISOString();
  let touched = false;
  state.generatedPlans = state.generatedPlans.map((entry) => {
    if (entry.id !== planId || entry.template !== true) return entry;
    touched = true;
    return { ...entry, template: false, templateLabel: undefined, updatedAt: now };
  });
  if (!touched) return;
  saveGeneratedPlans();
  pushToast('success', t('Template unmarked'), t('The draft is now a regular plan.'));
  render();
}

function deleteGeneratedPlanTemplate(planId: string): void {
  const record = generatedPlanById(planId);
  if (!record) return;
  state.generatedPlans = state.generatedPlans.filter((entry) => entry.id !== planId);
  saveGeneratedPlans();
  pushToast('success', t('Template removed'), record.templateLabel ?? t('Template'));
  render();
}

void startApp();
